bool dxfRW::write3dface(DRW_3Dface *ent){
    if (!preflightEntity(ent))
        return false;
    if (ent->invisibleflag < DRW_3Dface::NoEdge
        || ent->invisibleflag > DRW_3Dface::AllEdges) {
        m_writeError = true;
        return false;
    }
    EntityRecordScope scope(*this, ent);
    writer->writeString(0, "3DFACE");
    if (!writeEntity(ent))
        return false;
    if (version > DRW::AC1009) {
        writer->writeString(100, "AcDbFace");
    }
    writer->writeDouble(10, ent->basePoint.x);
    writer->writeDouble(20, ent->basePoint.y);
    writer->writeDouble(30, ent->basePoint.z);
    writer->writeDouble(11, ent->secPoint.x);
    writer->writeDouble(21, ent->secPoint.y);
    writer->writeDouble(31, ent->secPoint.z);
    writer->writeDouble(12, ent->thirdPoint.x);
    writer->writeDouble(22, ent->thirdPoint.y);
    writer->writeDouble(32, ent->thirdPoint.z);
    writer->writeDouble(13, ent->fourPoint.x);
    writer->writeDouble(23, ent->fourPoint.y);
    writer->writeDouble(33, ent->fourPoint.z);
    writer->writeInt16(70, ent->invisibleflag);
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeLWPolyline(DRW_LWPolyline *ent){
    if (!preflightDxfWrite())
        return false;
    if (version <= DRW::AC1009)
        return rejectUnsupportedDxfWrite("LWPOLYLINE");
    if (writer == nullptr || ent == nullptr || !ent->validatePayloadFields()) {
        m_writeError = true;
        return false;
    }

    {
        EntityRecordScope scope(*this, ent);
        writer->writeString(0, "LWPOLYLINE");
        if (!writeEntity(ent))
            return false;
        writer->writeString(100, "AcDbPolyline");
        const int vertexCount = static_cast<int>(ent->vertlist.size());
        writer->writeInt32(90, vertexCount);
        writer->writeInt16(70, ent->flags);
        writer->writeDouble(43, ent->width);
        if (ent->elevation != 0)
            writer->writeDouble(38, ent->elevation);
        if (ent->thickness != 0)
            writer->writeDouble(39, ent->thickness);
        for (const auto& v : ent->vertlist) {
            writer->writeDouble(10, v->x);
            writer->writeDouble(20, v->y);
            if (v->stawidth != 0)
                writer->writeDouble(40, v->stawidth);
            if (v->endwidth != 0)
                writer->writeDouble(41, v->endwidth);
            if (v->bulge != 0)
                writer->writeDouble(42, v->bulge);
            if (version > DRW::AC1021 && v->identifier != 0)
                writer->writeInt32(91, v->identifier);
        }
        // extrusion(210/220/230) — UCS/extruded plines flatten to WCS without it
        // (reader reads it, DWG encoder preserves it). Default 0,0,1.
        DRW_Coord crd = ent->extPoint;
        if (crd.x != 0 || crd.y != 0 || crd.z != 1) {
            writer->writeDouble(210, crd.x);
            writer->writeDouble(220, crd.y);
            writer->writeDouble(230, crd.z);
        }
        if (!ent->extData.empty() && !writeExtData(ent->extData))
            return false;
    }
    return !writer->hasWriteError();
}

bool dxfRW::writePolyline(DRW_Polyline *ent) {
    if (!preflightDxfWrite())
        return false;
    if (writer == nullptr || ent == nullptr || !ent->validatePayloadFields()
        || !ent->validatePolyfaceDxf()
        || std::any_of(ent->vertlist.cbegin(), ent->vertlist.cend(),
                       [](const auto& vertex) {
                           return vertex == nullptr
                               || !vertex->validatePayloadFields();
                       })) {
        m_writeError = true;
        return false;
    }
    // Nonzero classic VERTEX identifiers are implemented for AC1024+ output.
    // Older primary tables omit this field; do not silently lose it or infer
    // an earlier legal version from peers that emit it without a version gate.
    // This is an output-support policy, not a claim of older-format invalidity.
    if (version < DRW::AC1024
        && std::any_of(ent->vertlist.cbegin(), ent->vertlist.cend(),
                       [](const auto& vertex) { return vertex->identifier != 0; }))
        return rejectUnsupportedDxfWrite("POLYLINE");
    RecordStateScope state(*this, ent);
    DxfWriterRecordScope record(*writer);
    // Child records share this parent transaction. Keep the existing minted
    // handle assignment on success, but restore every emitted prefix when a
    // later child (including its trailing XDATA) rejects the compound record.
    struct VertexHandleRollback {
        std::vector<std::pair<DRW_Vertex*, std::uint32_t>> handles;
        bool committed {false};
        ~VertexHandleRollback() {
            if (!committed) {
                for (auto saved = handles.rbegin(); saved != handles.rend(); ++saved)
                    saved->first->handle = saved->second;
            }
        }
    } vertexState;
    vertexState.handles.reserve(ent->vertlist.size());
    writer->writeString(0, "POLYLINE");
    if (!writeEntity(ent))
        return false;
    if (version > DRW::AC1009) {
        if (ent->flags & 64)
            writer->writeString(100, "AcDbPolyFaceMesh");
        else if (ent->flags & 8)
            writer->writeString(100, "AcDb3dPolyline");
        else if (ent->flags & 16)
            writer->writeString(100, "AcDbPolygonMesh");
        else
            writer->writeString(100, "AcDb2dPolyline");
    } else
        writer->writeInt16(66, 1);
    writer->writeDouble(10, 0.0);
    writer->writeDouble(20, 0.0);
    writer->writeDouble(30, ent->basePoint.z);
    if (ent->thickness != 0) {
        writer->writeDouble(39, ent->thickness);
        }
    writer->writeInt16(70, ent->flags);
    if (ent->defstawidth != 0) {
        writer->writeDouble(40, ent->defstawidth);
        }
    if (ent->defendwidth != 0) {
        writer->writeDouble(41, ent->defendwidth);
    }
    if (ent->flags & 16 || ent->flags & 32 || ent->flags & 64) {
        writer->writeInt16(71, ent->vertexcount);
        writer->writeInt16(72, ent->facecount);
    }
    if (ent->smoothM != 0) {
        writer->writeInt16(73, ent->smoothM);
    }
    if (ent->smoothN != 0) {
        writer->writeInt16(74, ent->smoothN);
    }
    if (ent->curvetype != 0) {
        writer->writeInt16(75, ent->curvetype);
    }
    DRW_Coord crd  = ent->extPoint;
    // Classic 3D polylines, polygon meshes, and polyface meshes use WCS
    // vertices; Autodesk's OCS rules do not define them as extrudable. DWG
    // readers leave this unused field zero-initialized, which must not become
    // an explicit zero-length DXF extrusion vector. Preserve extrusion only
    // for the planar OCS polyline form.
    constexpr int wcsPolylineFlags = 8 | 16 | 64;
    const bool usesWcsVertices = (ent->flags & wcsPolylineFlags) != 0;
    if (!usesWcsVertices && (crd.x != 0 || crd.y != 0 || crd.z != 1)) {
        writer->writeDouble(210, crd.x);
        writer->writeDouble(220, crd.y);
        writer->writeDouble(230, crd.z);
    }
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;

    const std::uint32_t parentHandle = ent->handle;
    const bool isPolyface = (ent->flags & 64) != 0;
    const auto emitVertex = [&](const std::shared_ptr<DRW_Vertex>& vertex) {
        DRW_Vertex *v = vertex.get();
        vertexState.handles.emplace_back(v, v->handle);
        const bool polyfaceFace = isPolyface
            && DRW_Polyline::polyfaceVertexRole(*v)
                == DRW_Polyline::PolyfaceVertexRole::Face;
        // DWG VERTEX_PFACE_FACE has four indices but no flags field. The
        // public typed subtype must supply DXF's required face-record bit.
        const int dxfVertexFlags = polyfaceFace ? 128
            : isPolyface ? v->flags | 192 : v->flags;
        writer->writeString(0, "VERTEX");
        if (!writeEntity(v, /*captureSourceHandle=*/true, parentHandle))
            return false;
        if (version > DRW::AC1009) {
            // R2000+ requires a type-specific second subclass marker after
            // AcDbVertex (a face record uses ONLY AcDbFaceRecord). Mirrors
            // ezdxf polyline.py vertex classification; without it AutoCAD/ezdxf
            // mis-type 3D/mesh/polyface vertices.
            if (polyfaceFace) {
                writer->writeString(100, "AcDbFaceRecord");
            } else {
                writer->writeString(100, "AcDbVertex");
                if (dxfVertexFlags & 128)
                    writer->writeString(100, "AcDbPolyFaceMeshVertex");
                else if (ent->flags & 16)
                    writer->writeString(100, "AcDbPolygonMeshVertex");
                else if (ent->flags & 32)
                    writer->writeString(100, "AcDbPolygonMeshVertex");
                else if (ent->flags & 8)
                    writer->writeString(100, "AcDb3dPolylineVertex");
                else
                    writer->writeString(100, "AcDb2dVertex");
            }
        }
        if (polyfaceFace) {
            writer->writeDouble(10, 0);
            writer->writeDouble(20, 0);
            writer->writeDouble(30, 0);
        } else {
            writer->writeDouble(10, v->basePoint.x);
            writer->writeDouble(20, v->basePoint.y);
            // The DWG reader folds a 2D POLYLINE's parent elevation into each
            // typed Vertex2D for the public model. In DXF the parent POLYLINE
            // owns that elevation; 2D VERTEX coordinates remain at OCS z=0.
            // See ODA DWG spec §20.4.11/§20.4.16 and avoid duplicating it.
            const double vertexZ =
                v->dwgSubtype() == DRW_Vertex::DwgSubtype::Vertex2D
                    ? 0.0
                    : v->basePoint.z;
            writer->writeDouble(30, vertexZ);
        }
        if (v->stawidth != 0)
            writer->writeDouble(40, v->stawidth);
        if (v->endwidth != 0)
            writer->writeDouble(41, v->endwidth);
        if (v->bulge != 0)
            writer->writeDouble(42, v->bulge);
        if (dxfVertexFlags != 0) {
            writer->writeInt16(70, dxfVertexFlags);
        }
        if (dxfVertexFlags & 2) {
            writer->writeDouble(50, v->tgdir);
        }
        if (dxfVertexFlags & 128) {
            const std::array<int, 4> indices {{v->vindex1, v->vindex2,
                                              v->vindex3, v->vindex4}};
            for (std::size_t i = 0; i != indices.size(); ++i) {
                if (polyfaceFace && indices[i] == 0)
                    break;
                if (indices[i] != 0)
                    writer->writeInt16(static_cast<int>(71 + i), indices[i]);
            }
        }
        // Identifier is an independent I32 field, not a face index or a
        // POLYFACE coordinate-pool position. Zero/absence share the API default.
        if (version >= DRW::AC1024 && v->identifier != 0)
            writer->writeInt32(91, v->identifier);
        if (!v->extData.empty() && !writeExtData(v->extData))
            return false;
        return true;
    };
    // Keep each coordinate/face pool stable, preserving IDs, winding and
    // per-face metadata without reordering the caller-owned vertex vector.
    for (int pass = 0; pass != (isPolyface ? 2 : 1); ++pass) {
        for (const auto& vertex : ent->vertlist) {
            const bool face = isPolyface
                && DRW_Polyline::polyfaceVertexRole(*vertex)
                    == DRW_Polyline::PolyfaceVertexRole::Face;
            if ((!isPolyface || face == (pass == 1)) && !emitVertex(vertex))
                return false;
        }
    }
    if (!writeSequenceEnd(ent->seqEndEntity.get(), parentHandle))
        return false;
    if (!preflightDxfWrite() || !record.commit()) {
        m_writeError = true;
        return false;
    }
    state.commit();
    vertexState.committed = true;
    return true;
}

bool dxfRW::writeSpline(DRW_Spline *ent){
    if (!preflightDxfWrite())
        return false;
    if (version > DRW::AC1009) {
        if (writer == nullptr || ent == nullptr
            || !ent->validateDxf()
            || ent->knotslist.size()
                   > static_cast<std::size_t>(std::numeric_limits<std::int16_t>::max())
            || ent->controllist.size()
                   > static_cast<std::size_t>(std::numeric_limits<std::int16_t>::max())
            || ent->fitlist.size()
                   > static_cast<std::size_t>(std::numeric_limits<std::int16_t>::max())) {
            m_writeError = true;
            return false;
        }
        EntityRecordScope scope(*this, ent);
        writer->writeString(0, "SPLINE");
        if (!writeEntity(ent))
            return false;
        writer->writeString(100, "AcDbSpline");
        writeDxfSplineBody(writer.get(), ent);
        if (!ent->extData.empty() && !writeExtData(ent->extData))
            return false;
    } else {
        // R12 has no SPLINE record and this writer does not approximate it.
        return rejectUnsupportedDxfWrite("SPLINE");
    }
    return !writer->hasWriteError();
}

bool dxfRW::writeHelix(DRW_Helix *ent){
    if (!preflightDxfWrite())
        return false;
    if (version <= DRW::AC1009)
        return rejectUnsupportedDxfWrite("HELIX");
    if (version > DRW::AC1009) {
        if (writer == nullptr || ent == nullptr
            || !ent->validateDxf()
            || ent->knotslist.size()
                   > static_cast<std::size_t>(std::numeric_limits<std::int16_t>::max())
            || ent->controllist.size()
                   > static_cast<std::size_t>(std::numeric_limits<std::int16_t>::max())
            || ent->fitlist.size()
                   > static_cast<std::size_t>(std::numeric_limits<std::int16_t>::max())
            || !std::isfinite(ent->axisBasePt.x)
            || !std::isfinite(ent->axisBasePt.y)
            || !std::isfinite(ent->axisBasePt.z)
            || !std::isfinite(ent->startPt.x)
            || !std::isfinite(ent->startPt.y)
            || !std::isfinite(ent->startPt.z)
            || !std::isfinite(ent->axisVector.x)
            || !std::isfinite(ent->axisVector.y)
            || !std::isfinite(ent->axisVector.z)
            || !std::isfinite(ent->radius)
            || !std::isfinite(ent->turns)
            || !std::isfinite(ent->turnHeight)
            || ent->constraintType > 2) {
            m_writeError = true;
            return false;
        }
        EntityRecordScope scope(*this, ent);
        writer->writeString(0, "HELIX");
        if (!writeEntity(ent))
            return false;
        writer->writeString(100, "AcDbSpline");
        writeDxfSplineBody(writer.get(), ent);
        writer->writeString(100, "AcDbHelix");
        writer->writeInt32(90, ent->m_majorVersion);
        writer->writeInt32(91, ent->m_maintVersion);
        writer->writeDouble(10, ent->axisBasePt.x);
        writer->writeDouble(20, ent->axisBasePt.y);
        writer->writeDouble(30, ent->axisBasePt.z);
        writer->writeDouble(11, ent->startPt.x);
        writer->writeDouble(21, ent->startPt.y);
        writer->writeDouble(31, ent->startPt.z);
        writer->writeDouble(12, ent->axisVector.x);
        writer->writeDouble(22, ent->axisVector.y);
        writer->writeDouble(32, ent->axisVector.z);
        writer->writeDouble(40, ent->radius);
        writer->writeDouble(41, ent->turns);
        writer->writeDouble(42, ent->turnHeight);
        writer->writeBool(290, ent->handedness);
        writer->writeInt16(280, static_cast<int>(ent->constraintType));
        if (!ent->extData.empty() && !writeExtData(ent->extData))
            return false;
    }
    return !writer->hasWriteError();
}

bool dxfRW::writeHatch(DRW_Hatch *ent){
    if (version > DRW::AC1009) {
        if (!preflightEntity(ent) || !validateHatchPayload(ent)) {
            m_writeError = true;
            return false;
        }
        const auto writeBoundaryHandles = [this](const DRW_HatchLoop& loop) {
            if (!writer->writeInt32(97, static_cast<int>(loop.m_boundaryHandles.size())))
                return failDxfWrite();
            for (const std::uint32_t source : loop.m_boundaryHandles) {
                // A consumer resolver returns final output identity. Applying
                // the source map again can redirect a numeric handle alias.
                const std::uint32_t emitted = m_referenceResolver
                    ? resolveReference(source) : remapObjectHandle(source);
                if (emitted == 0 || !writer->writeString(330, toHexStr(emitted)))
                    return failDxfWrite();
            }
            return true;
        };
        EntityRecordScope scope(*this, ent);
        writer->writeString(0, "HATCH");
        if (!writeEntity(ent))
            return false;
        writer->writeString(100, "AcDbHatch");
        writer->writeDouble(10, 0.0);
        writer->writeDouble(20, 0.0);
        writer->writeDouble(30, ent->basePoint.z);
        writer->writeDouble(210, ent->extPoint.x);
        writer->writeDouble(220, ent->extPoint.y);
        writer->writeDouble(230, ent->extPoint.z);
        writer->writeUtf8String(2, ent->name);
        writer->writeInt16(70, ent->solid);
        writer->writeInt16(71, ent->associative);
        const int loopCount = static_cast<int>(ent->looplist.size());
        writer->writeInt32(91, loopCount);
        //write paths data
        for (int i = 0; i < loopCount; i++){
            DRW_HatchLoop *loop = ent->looplist.at(i).get();
            writer->writeInt32(92, loop->type);
            if ((loop->type & 2) == 2) {
                // Polyline boundary path
                DRW_LWPolyline *pl = nullptr;
                if (!loop->objlist.empty())
                    pl = dynamic_cast<DRW_LWPolyline*>(loop->objlist.at(0).get());
                const bool hasBulge = pl && std::any_of(
                    pl->vertlist.begin(), pl->vertlist.end(),
                    [](const std::shared_ptr<DRW_Vertex2D>& v){ return v && v->bulge != 0.0; });
                writer->writeInt16(72, hasBulge ? 1 : 0);
                writer->writeInt16(73, pl ? (pl->flags & 1) : 0); // is-closed
                const int nv = pl ? static_cast<int>(pl->vertlist.size()) : 0;
                writer->writeInt32(93, nv);
                for (int v = 0; v < nv; ++v) {
                    const auto &vtx = pl->vertlist.at(v);
                    writer->writeDouble(10, vtx->x);
                    writer->writeDouble(20, vtx->y);
                    if (hasBulge)
                        writer->writeDouble(42, vtx->bulge);
                }
                if (!writeBoundaryHandles(*loop))
                    return false;
            } else {
                //boundary path
                const int edgeCount = static_cast<int>(loop->objlist.size());
                writer->writeInt32(93, edgeCount);
                for (int j = 0; j < edgeCount; ++j) {
                    switch ((loop->objlist.at(j))->eType) {
                        case DRW::LINE: {
                        writer->writeInt16(72, 1);
                        DRW_Line* l = (DRW_Line*)loop->objlist.at(j).get();
                        writer->writeDouble(10, l->basePoint.x);
                        writer->writeDouble(20, l->basePoint.y);
                        writer->writeDouble(11, l->secPoint.x);
                        writer->writeDouble(21, l->secPoint.y);
                            break;
                        }
                        case DRW::ARC: {
                        writer->writeInt16(72, 2);
                        DRW_Arc* a = (DRW_Arc*)loop->objlist.at(j).get();
                        writer->writeDouble(10, a->basePoint.x);
                        writer->writeDouble(20, a->basePoint.y);
                        writer->writeDouble(40, a->radious);
                        writer->writeDouble(50, a->staangle*ARAD);
                        writer->writeDouble(51, a->endangle*ARAD);
                        writer->writeInt16(73, a->isccw);
                            break;
                        }
                        case DRW::ELLIPSE: {
                        writer->writeInt16(72, 3);
                        DRW_Ellipse* a = (DRW_Ellipse*)loop->objlist.at(j).get();
                        DRW_Ellipse normalized = *a;
                        normalized.correctAxis();
                        writer->writeDouble(10, normalized.basePoint.x);
                        writer->writeDouble(20, normalized.basePoint.y);
                        writer->writeDouble(11, normalized.secPoint.x);
                        writer->writeDouble(21, normalized.secPoint.y);
                        writer->writeDouble(40, normalized.ratio);
                        writer->writeDouble(50, normalized.staparam*ARAD);
                        writer->writeDouble(51, normalized.endparam*ARAD);
                        writer->writeInt16(73, normalized.isccw);
                            break;
                        }
                        case DRW::SPLINE:{
                        writer->writeInt16(72, 4);
                            DRW_Spline* sp = (DRW_Spline*)loop->objlist.at(j).get();
                        writer->writeInt32(94, sp->degree);
                            // Unlike standalone SPLINE, HATCH emits weights
                            // only when its rational flag is set. Infer that
                            // wire flag for every supplied complete array so
                            // even a nearly-unit weight is never discarded.
                            const bool rational = (sp->flags & 0x4) != 0
                                || !sp->weightlist.empty();
                            const bool periodic = (sp->flags & 0x2) != 0;
                        writer->writeInt16(73, rational ? 1 : 0);
                        writer->writeInt16(74, periodic ? 1 : 0);
                        writer->writeInt32(95, static_cast<int>(sp->knotslist.size()));
                        writer->writeInt32(96, static_cast<int>(sp->controllist.size()));
                            for (double k : sp->knotslist) {
                            writer->writeDouble(40, k);
                            }
                        for (size_t k = 0; k < sp->controllist.size(); ++k) {
                                const auto& cp = sp->controllist[k];
                                if (!cp) continue;
                            writer->writeDouble(10, cp->x);
                            writer->writeDouble(20, cp->y);
                                if (!sp->weightlist.empty()) {
                                writer->writeDouble(42, sp->weightlist[k]);
                                }
                            }
                        writer->writeInt32(97, static_cast<int>(sp->fitlist.size()));
                            for (const auto& fp : sp->fitlist) {
                                if (!fp) continue;
                            writer->writeDouble(11, fp->x);
                            writer->writeDouble(21, fp->y);
                            }
                        // start/end tangents (codes 12/22, 13/23)
                        if (sp->tgStart.x != 0.0 || sp->tgStart.y != 0.0) {
                            writer->writeDouble(12, sp->tgStart.x);
                            writer->writeDouble(22, sp->tgStart.y);
                        }
                        if (sp->tgEnd.x != 0.0 || sp->tgEnd.y != 0.0) {
                            writer->writeDouble(13, sp->tgEnd.x);
                            writer->writeDouble(23, sp->tgEnd.y);
                        }
                            break;
                        }
                        default:
                            break;
                    }
                }
                if (!writeBoundaryHandles(*loop))
                    return false;
            }
        }
        writer->writeInt16(75, ent->hstyle);
        writer->writeInt16(76, ent->hpattern);
        if (!ent->solid){
            writer->writeDouble(52, ent->angle);
            writer->writeDouble(41, ent->scale);
            writer->writeInt16(77, ent->doubleflag);
        }
        // code 78 (def-line count) is written for both solid and pattern fills
        const int nDefLines = static_cast<int>(ent->patternLines.size());
        writer->writeInt16(78, nDefLines);
        for (const DRW_Hatch::PatternLine &pl : ent->patternLines) {
            writer->writeDouble(53, pl.angle);
            writer->writeDouble(43, pl.baseX);
            writer->writeDouble(44, pl.baseY);
            writer->writeDouble(45, pl.offsetX);
            writer->writeDouble(46, pl.offsetY);
            writer->writeInt16(79, static_cast<int>(pl.dashList.size()));
            for (double d : pl.dashList)
                writer->writeDouble(49, d);
        }
        const bool hasDerivedBoundary = std::any_of(
            ent->looplist.begin(), ent->looplist.end(),
            [](const std::shared_ptr<DRW_HatchLoop>& loop) {
                return loop && (loop->type & 4) != 0;
            });
        if (ent->pixelSize != 0.0 || hasDerivedBoundary)
            writer->writeDouble(47, ent->pixelSize);
        // Seed points (group 98 = count, then 10/20 pairs).
        const int seedCount = static_cast<int>(ent->seedPoints.size());
        writer->writeInt32(98, seedCount);
        for (const DRW_Coord &pt : ent->seedPoints) {
            writer->writeDouble(10, pt.x);
            writer->writeDouble(20, pt.y);
        }
        // Gradient block (R2004+ DXF; codes 450-470 + 463/421/63 per stop).
        if (ent->isGradient) {
            writer->writeInt32(450, ent->isGradient);
            writer->writeInt32(451, ent->gradReserved);
            writer->writeDouble(460, ent->gradAngle);
            writer->writeDouble(461, ent->gradShift);
            writer->writeInt32(452, ent->singleColor);
            writer->writeDouble(462, ent->gradTint);
            writer->writeInt32(453, static_cast<int>(ent->gradColors.size()));
            for (const DRW_Hatch::GradientStop &stop : ent->gradColors) {
                writer->writeDouble(463, stop.value);
                if (stop.aciColor != 0 || stop.colorMethod == 0xC1u)
                    writer->writeInt16(63, stop.aciColor);
                if (stop.rgb >= 0)
                    writer->writeInt32(421, stop.rgb);
                if (!stop.colorName.empty())
                    writer->writeUtf8String(432, stop.colorName);
                if (!stop.colorBookName.empty())
                    writer->writeUtf8String(433, stop.colorBookName);
            }
            writer->writeUtf8String(470, ent->gradName);
        }
        if (!ent->extData.empty() && !writeExtData(ent->extData))
            return false;
    } else {
        return rejectUnsupportedDxfWrite("HATCH");
    }
    return !writer->hasWriteError();
}

bool dxfRW::writeMPolygon(DRW_MPolygon *ent){
    if (version <= DRW::AC1009)
        return rejectUnsupportedDxfWrite("MPOLYGON");
    if (ent != nullptr && ent->dxfVersion != 1)
        return rejectUnsupportedDxfWrite();
    if (version > DRW::AC1009) {
        if (!preflightEntity(ent) || !ent->validateDxf()
            || !validateHatchPayload(ent)) {
            m_writeError = true;
            return false;
        }
        EntityRecordScope scope(*this, ent);
        const auto writeBoundaryHandles = [this](const DRW_HatchLoop& loop) {
            if (!writer->writeInt32(97,
                                    static_cast<int>(loop.m_boundaryHandles.size())))
                return failDxfWrite();
            for (const std::uint32_t source : loop.m_boundaryHandles) {
                const std::uint32_t emitted = m_referenceResolver
                    ? resolveReference(source) : remapObjectHandle(source);
                if (emitted == 0
                    || !writer->writeString(330, toHexStr(emitted)))
                    return failDxfWrite();
            }
            return true;
        };
        writer->writeString(0, "MPOLYGON");
        if (!writeEntity(ent))
            return false;
        writer->writeString(100, "AcDbMPolygon");
        writer->writeInt16(70, ent->dxfVersion);
        writer->writeDouble(10, 0.0);
        writer->writeDouble(20, 0.0);
        writer->writeDouble(30, ent->basePoint.z);
        writer->writeDouble(210, ent->extPoint.x);
        writer->writeDouble(220, ent->extPoint.y);
        writer->writeDouble(230, ent->extPoint.z);
        writer->writeUtf8String(2, ent->name);
        writer->writeInt16(71, ent->solid);
        const int loopCount = static_cast<int>(ent->looplist.size());
        writer->writeInt32(91, loopCount);
        for (int i = 0; i < loopCount; ++i) {
            DRW_HatchLoop *loop = ent->looplist.at(i).get();
            writer->writeInt32(92, loop->type);
            if ((loop->type & 2) == 2) {
                DRW_LWPolyline *pl = nullptr;
                if (!loop->objlist.empty())
                    pl = dynamic_cast<DRW_LWPolyline*>(loop->objlist.at(0).get());
                const bool hasBulge = pl && std::any_of(
                    pl->vertlist.begin(), pl->vertlist.end(),
                    [](const std::shared_ptr<DRW_Vertex2D>& v){ return v && v->bulge != 0.0; });
                writer->writeInt16(72, hasBulge ? 1 : 0);
                writer->writeInt16(73, pl ? (pl->flags & 1) : 0);
                const int nv = pl ? static_cast<int>(pl->vertlist.size()) : 0;
                writer->writeInt32(93, nv);
                for (int v = 0; v < nv; ++v) {
                    const auto &vtx = pl->vertlist.at(v);
                    writer->writeDouble(10, vtx->x);
                    writer->writeDouble(20, vtx->y);
                    if (hasBulge)
                        writer->writeDouble(42, vtx->bulge);
                }
                if (!writeBoundaryHandles(*loop))
                    return false;
            } else {
                const int edgeCount = static_cast<int>(loop->objlist.size());
                writer->writeInt32(93, edgeCount);
                for (int j = 0; j < edgeCount; ++j) {
                    switch ((loop->objlist.at(j))->eType) {
                    case DRW::LINE: {
                        writer->writeInt16(72, 1);
                        DRW_Line* l = (DRW_Line*)loop->objlist.at(j).get();
                        writer->writeDouble(10, l->basePoint.x);
                        writer->writeDouble(20, l->basePoint.y);
                        writer->writeDouble(11, l->secPoint.x);
                        writer->writeDouble(21, l->secPoint.y);
                        break; }
                    case DRW::ARC: {
                        writer->writeInt16(72, 2);
                        DRW_Arc* a = (DRW_Arc*)loop->objlist.at(j).get();
                        writer->writeDouble(10, a->basePoint.x);
                        writer->writeDouble(20, a->basePoint.y);
                        writer->writeDouble(40, a->radious);
                        writer->writeDouble(50, a->staangle*ARAD);
                        writer->writeDouble(51, a->endangle*ARAD);
                        writer->writeInt16(73, a->isccw);
                        break; }
                    case DRW::ELLIPSE: {
                        writer->writeInt16(72, 3);
                        DRW_Ellipse* a = (DRW_Ellipse*)loop->objlist.at(j).get();
                        DRW_Ellipse normalized = *a;
                        normalized.correctAxis();
                        writer->writeDouble(10, normalized.basePoint.x);
                        writer->writeDouble(20, normalized.basePoint.y);
                        writer->writeDouble(11, normalized.secPoint.x);
                        writer->writeDouble(21, normalized.secPoint.y);
                        writer->writeDouble(40, normalized.ratio);
                        writer->writeDouble(50, normalized.staparam*ARAD);
                        writer->writeDouble(51, normalized.endparam*ARAD);
                        writer->writeInt16(73, normalized.isccw);
                        break; }
                    case DRW::SPLINE: {
                        writer->writeInt16(72, 4);
                        DRW_Spline* sp = (DRW_Spline*)loop->objlist.at(j).get();
                        writer->writeInt32(94, sp->degree);
                        // MPOLYGON uses the same boundary spline grammar and
                        // must not drop supplied weights when flag 4 is clear.
                        const bool rational = (sp->flags & 0x4) != 0
                            || !sp->weightlist.empty();
                        const bool periodic = (sp->flags & 0x2) != 0;
                        writer->writeInt16(73, rational ? 1 : 0);
                        writer->writeInt16(74, periodic ? 1 : 0);
                        writer->writeInt32(95, static_cast<int>(sp->knotslist.size()));
                        writer->writeInt32(96, static_cast<int>(sp->controllist.size()));
                        for (double k : sp->knotslist)
                            writer->writeDouble(40, k);
                        for (size_t k = 0; k < sp->controllist.size(); ++k) {
                            const auto& cp = sp->controllist[k];
                            if (!cp) continue;
                            writer->writeDouble(10, cp->x);
                            writer->writeDouble(20, cp->y);
                            if (!sp->weightlist.empty()) {
                                writer->writeDouble(42, sp->weightlist[k]);
                            }
                        }
                        writer->writeInt32(97, static_cast<int>(sp->fitlist.size()));
                        for (const auto& fp : sp->fitlist) {
                            if (!fp) continue;
                            writer->writeDouble(11, fp->x);
                            writer->writeDouble(21, fp->y);
                        }
                        if (sp->tgStart.x != 0.0 || sp->tgStart.y != 0.0) {
                            writer->writeDouble(12, sp->tgStart.x);
                            writer->writeDouble(22, sp->tgStart.y);
                        }
                        if (sp->tgEnd.x != 0.0 || sp->tgEnd.y != 0.0) {
                            writer->writeDouble(13, sp->tgEnd.x);
                            writer->writeDouble(23, sp->tgEnd.y);
                        }
                        break; }
                    default:
                        break;
                    }
                }
                if (!writeBoundaryHandles(*loop))
                    return false;
            }
        }
        writer->writeInt16(75, ent->hstyle);
        writer->writeInt16(76, ent->hpattern);
        if (!ent->solid) {
            writer->writeDouble(52, ent->angle);
            writer->writeDouble(41, ent->scale);
            writer->writeInt16(77, ent->doubleflag);
        }
        if (ent->annotatedBoundary != 0)
            writer->writeInt16(73, ent->annotatedBoundary);
        const int nDefLines = static_cast<int>(ent->patternLines.size());
        writer->writeInt16(78, nDefLines);
        for (const DRW_Hatch::PatternLine &pl : ent->patternLines) {
            writer->writeDouble(53, pl.angle);
            writer->writeDouble(43, pl.baseX);
            writer->writeDouble(44, pl.baseY);
            writer->writeDouble(45, pl.offsetX);
            writer->writeDouble(46, pl.offsetY);
            writer->writeInt16(79, static_cast<int>(pl.dashList.size()));
            for (double d : pl.dashList)
                writer->writeDouble(49, d);
        }
        if (ent->pixelSize != 0.0)
            writer->writeDouble(47, ent->pixelSize);
        if (ent->fillColorAci != 0)
            writer->writeInt16(63, ent->fillColorAci);
        if (ent->fillColorRgb >= 0)
            writer->writeInt32(421, ent->fillColorRgb);
        if (!ent->fillColorName.empty())
            writer->writeUtf8String(430, ent->fillColorName);
        writer->writeInt32(98, static_cast<int>(ent->seedPoints.size()));
        for (const DRW_Coord& point : ent->seedPoints) {
            writer->writeDouble(10, point.x);
            writer->writeDouble(20, point.y);
        }
        writer->writeDouble(11, ent->xDirX);
        writer->writeDouble(21, ent->xDirY);
        writer->writeInt32(99, ent->degenerateLoops);
        if (ent->isGradient) {
            writer->writeInt32(450, ent->isGradient);
            writer->writeInt32(451, ent->gradReserved);
            writer->writeDouble(460, ent->gradAngle);
            writer->writeDouble(461, ent->gradShift);
            writer->writeInt32(452, ent->singleColor);
            writer->writeDouble(462, ent->gradTint);
            writer->writeInt32(453, static_cast<int>(ent->gradColors.size()));
            for (const DRW_Hatch::GradientStop &stop : ent->gradColors) {
                writer->writeDouble(463, stop.value);
                if (stop.aciColor != 0 || stop.colorMethod == 0xC1u)
                    writer->writeInt16(63, stop.aciColor);
                if (stop.rgb >= 0)
                    writer->writeInt32(421, stop.rgb);
                if (!stop.colorName.empty())
                    writer->writeUtf8String(432, stop.colorName);
                if (!stop.colorBookName.empty())
                    writer->writeUtf8String(433, stop.colorBookName);
            }
            writer->writeUtf8String(470, ent->gradName);
        }
        if (!ent->extData.empty() && !writeExtData(ent->extData))
            return false;
    }
    return !writer->hasWriteError();
}

bool dxfRW::writeLeader(DRW_Leader *ent){
    if (!preflightDxfWrite())
        return false;
    if (version <= DRW::AC1009)
        return rejectUnsupportedDxfWrite("LEADER");
    if (writer == nullptr || ent == nullptr || !ent->validatePayloadFields()
        || ent->vertexlist.size()
               > static_cast<std::size_t>(std::numeric_limits<std::int16_t>::max())) {
        m_writeError = true;
        return false;
    }

    {
        EntityRecordScope scope(*this, ent);
        writer->writeString(0, "LEADER");
        if (!writeEntity(ent))
            return false;
        writer->writeString(100, "AcDbLeader");
        writer->writeUtf8String(3, ent->style);
        writer->writeInt16(71, ent->arrow);
        writer->writeInt16(72, ent->leadertype);
        writer->writeInt16(73, ent->flag);
        writer->writeInt16(74, ent->hookline);
        writer->writeInt16(75, ent->hookflag);
        writer->writeDouble(40, ent->textheight);
        writer->writeDouble(41, ent->textwidth);
        writer->writeInt16(76, static_cast<int>(ent->vertexlist.size()));
        for (const auto& vert : ent->vertexlist) {
            writer->writeDouble(10, vert->x);
            writer->writeDouble(20, vert->y);
            writer->writeDouble(30, vert->z);
        }
        // block_color (77): color used when the leader annotation color is
        // BYBLOCK; ezdxf acdb_leader emits it unconditionally (default 7).
        writer->writeInt16(77, ent->coloruse);
        // annotation_handle (340): hard ref to the associated annotation,
        // resolved through the source->minted map. The adapter preplans this
        // typed target before streaming so forward references remain valid;
        // refuse an unresolved/ambiguous edge rather than silently dropping it.
        if (ent->annotHandle != 0) {
            if (m_writingContext.ambiguousSourceHandles.count(
                    ent->annotHandle) != 0)
                return rejectUnsupportedDxfWrite(
                    "LEADER annotation reference");
            auto it = m_writingContext.sourceHandleToMintedMap.find(ent->annotHandle);
            if (it == m_writingContext.sourceHandleToMintedMap.end())
                return rejectUnsupportedDxfWrite(
                    "LEADER annotation reference");
            writer->writeString(340, toHexStr(it->second));
        }
        if (ent->extrusionPoint.x != 0.0 || ent->extrusionPoint.y != 0.0 ||
            ent->extrusionPoint.z != 1.0) {
            writer->writeDouble(210, ent->extrusionPoint.x);
            writer->writeDouble(220, ent->extrusionPoint.y);
            writer->writeDouble(230, ent->extrusionPoint.z);
        }
        // horizontal_direction (211), offset-from-block (212), offset-from-
        // annotation (213) — emitted after 210 per ezdxf order, when non-default.
        if (ent->horizdir.x != 1.0 || ent->horizdir.y != 0.0 || ent->horizdir.z != 0.0) {
            writer->writeDouble(211, ent->horizdir.x);
            writer->writeDouble(221, ent->horizdir.y);
            writer->writeDouble(231, ent->horizdir.z);
        }
        if (ent->offsetblock.x != 0.0 || ent->offsetblock.y != 0.0 || ent->offsetblock.z != 0.0) {
            writer->writeDouble(212, ent->offsetblock.x);
            writer->writeDouble(222, ent->offsetblock.y);
            writer->writeDouble(232, ent->offsetblock.z);
        }
        if (ent->offsettext.x != 0.0 || ent->offsettext.y != 0.0 || ent->offsettext.z != 0.0) {
            writer->writeDouble(213, ent->offsettext.x);
            writer->writeDouble(223, ent->offsettext.y);
            writer->writeDouble(233, ent->offsettext.z);
        }
        if (!ent->extData.empty() && !writeExtData(ent->extData))
            return false;
    }
    return !writer->hasWriteError();
}
bool dxfRW::writeArcDimension(DRW_DimArc *d) {
    if (version <= DRW::AC1009)
        return rejectUnsupportedDxfWrite("ARC_DIMENSION");
    if (!preflightEntity(d) || !preflightDimensionStyle(d)
        || !preflightDimensionPictureBlock(d))
        return false;
    std::vector<std::shared_ptr<DRW_Variant>> dimensionXdata;
    if (!buildDimensionDstyleXdata(*d, dimensionXdata))
        return false;
    EntityRecordScope scope(*this, d);
    writer->writeString(0, "ARC_DIMENSION");
    if (!writeEntity(d))
        return false;
    writer->writeString(100, "AcDbDimension");
    if (version >= DRW::AC1024)
        writer->writeInt16(280, 0);   // AcDbDimension version, 0 = R2010+
    if (!d->getName().empty())
        writer->writeUtf8String(2, d->getName());
    writer->writeDouble(10, d->getArcDefPoint().x);
    writer->writeDouble(20, d->getArcDefPoint().y);
    writer->writeDouble(30, d->getArcDefPoint().z);
    writer->writeDouble(11, d->getTextPoint().x);
    writer->writeDouble(21, d->getTextPoint().y);
    writer->writeDouble(31, d->getTextPoint().z);
    // ARC_DIMENSION: subtype 5 in low 3 bits (same as angular3p); preserve high bits.
    const int dimType = (d->type & ~0x07) | 5 | 32;
    writer->writeInt16(70, dimType);
    if (!d->getText().empty())
        writer->writeUtf8String(1, d->getText());
    writer->writeInt16(71, d->getAlign());
    if (d->getTextLineStyle() != 1)
        writer->writeInt16(72, d->getTextLineStyle());
    if (d->getTextLineFactor() != 1)
        writer->writeDouble(41, d->getTextLineFactor());
    writer->writeUtf8String(3, d->getStyle());
    if (d->getDir() != 0)
        writer->writeDouble(53, d->getDir());
    writer->writeDouble(210, d->getExtrusion().x);
    writer->writeDouble(220, d->getExtrusion().y);
    writer->writeDouble(230, d->getExtrusion().z);
    writer->writeString(100, "AcDbArcDimension");
    writer->writeDouble(13, d->getExtLine1().x);
    writer->writeDouble(23, d->getExtLine1().y);
    writer->writeDouble(33, d->getExtLine1().z);
    writer->writeDouble(14, d->getExtLine2().x);
    writer->writeDouble(24, d->getExtLine2().y);
    writer->writeDouble(34, d->getExtLine2().z);
    writer->writeDouble(15, d->getArcCenter().x);
    writer->writeDouble(25, d->getArcCenter().y);
    writer->writeDouble(35, d->getArcCenter().z);
    writer->writeInt16(70, d->isPartial ? 1 : 0);
    writer->writeDouble(40, d->arcStartAngle);
    writer->writeDouble(41, d->arcEndAngle);
    writer->writeInt16(71, d->hasLeader ? 1 : 0);
    // The presence flag controls display, not the stored point values. Keep
    // inactive leader points as well; do not replace them with extension points.
    const DRW_Coord lp1 = d->getLeaderPt1();
    const DRW_Coord lp2 = d->leaderPt2;
    writer->writeDouble(16, lp1.x); writer->writeDouble(26, lp1.y); writer->writeDouble(36, lp1.z);
    writer->writeDouble(17, lp2.x); writer->writeDouble(27, lp2.y); writer->writeDouble(37, lp2.z);
    if (!dimensionXdata.empty() && !writeExtData(dimensionXdata))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeLargeRadialDimension(DRW_DimLargeRadial *d) {
    if (version <= DRW::AC1009)
        return rejectUnsupportedDxfWrite("LARGE_RADIAL_DIMENSION");
    if (!preflightEntity(d) || !preflightDimensionStyle(d)
        || !preflightDimensionPictureBlock(d))
        return false;
    std::vector<std::shared_ptr<DRW_Variant>> dimensionXdata;
    if (!buildDimensionDstyleXdata(*d, dimensionXdata))
        return false;
    EntityRecordScope scope(*this, d);
    writer->writeString(0, "LARGE_RADIAL_DIMENSION");
    if (!writeEntity(d))
        return false;
    writer->writeString(100, "AcDbDimension");
    if (version >= DRW::AC1024)
        writer->writeInt16(280, 0);
    if (!d->getName().empty())
        writer->writeUtf8String(2, d->getName());
    writer->writeDouble(10, d->getCenterPoint().x);
    writer->writeDouble(20, d->getCenterPoint().y);
    writer->writeDouble(30, d->getCenterPoint().z);
    writer->writeDouble(11, d->getTextPoint().x);
    writer->writeDouble(21, d->getTextPoint().y);
    writer->writeDouble(31, d->getTextPoint().z);
    int dimType = (d->type & ~0x07) | 4;
    if (!(dimType & 32))
        dimType += 32;
    writer->writeInt16(70, dimType);
    if (!d->getText().empty())
        writer->writeUtf8String(1, d->getText());
    writer->writeInt16(71, d->getAlign());
    if (d->getTextLineStyle() != 1)
        writer->writeInt16(72, d->getTextLineStyle());
    if (d->getTextLineFactor() != 1)
        writer->writeDouble(41, d->getTextLineFactor());
    writer->writeUtf8String(3, d->getStyle());
    if (d->measureValue != 0)
        writer->writeDouble(42, d->measureValue);
    if (d->getDir() != 0)
        writer->writeDouble(53, d->getDir());
    if (d->hdir != 0)
        writer->writeDouble(51, d->hdir);
    if (d->getFlipArrow1())
        writer->writeInt16(74, 1);
    if (d->getFlipArrow2())
        writer->writeInt16(75, 1);
    writer->writeDouble(210, d->getExtrusion().x);
    writer->writeDouble(220, d->getExtrusion().y);
    writer->writeDouble(230, d->getExtrusion().z);
    writer->writeString(100, "AcDbRadialDimensionLarge");
    writer->writeDouble(13, d->getChordPoint().x);
    writer->writeDouble(23, d->getChordPoint().y);
    writer->writeDouble(33, d->getChordPoint().z);
    writer->writeDouble(14, d->overrideCenterPoint.x);
    writer->writeDouble(24, d->overrideCenterPoint.y);
    writer->writeDouble(34, d->overrideCenterPoint.z);
    writer->writeDouble(15, d->jogPoint.x);
    writer->writeDouble(25, d->jogPoint.y);
    writer->writeDouble(35, d->jogPoint.z);
    writer->writeDouble(40, d->jogAngle);
    if (!dimensionXdata.empty() && !writeExtData(dimensionXdata))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::preflightDimensionPictureBlock(
    const DRW_Dimension *dimension) {
    // This is only a strict-converter admission check for an explicit DXF
    // group-2 target. An empty name may be a constraint-only or otherwise
    // unclassified record; do not infer its semantics here. Also keep legacy
    // standalone writers unchanged unless the caller opted into resolved
    // block-owner validation.
    if (!m_requireResolvedBlockOwners || version <= DRW::AC1009
        || dimension == nullptr || dimension->name.empty())
        return true;

    const std::string key = dxfSymbolNameKey(dimension->name);
    const bool fixedSpace = key == "*MODEL_SPACE"
        || key == "*PAPER_SPACE";
    if (key.empty() || (!fixedSpace && blockMap.count(key) == 0)) {
        recordOperationDiagnostic(writingBlock ? DRW::OperationPhase::Blocks
                                               : DRW::OperationPhase::Entities,
            DRW::OperationCause::ValidationFailure,
            "unresolved-dimension-picture-block",
            "DIMENSION picture block has no planned BLOCK_RECORD", 0, false,
            dimension->handle, dimension->handle != DRW::NoHandle);
        return failDxfWrite();
    }

    if (m_dxfBlockSectionActive) {
        if (m_pendingDxfDimensionPictureBlocks.count(key) == 0) {
            const std::size_t mutationCheckpoint =
                m_dxfWriteMutations.size();
            try {
                if (m_recordStateScopeDepth != 0) {
                    m_dxfWriteMutations.push_back({
                        DxfWriteMutationKind::
                            PendingDxfDimensionPictureBlockInsert,
                        key, 0, 0, false});
                }
                const auto inserted =
                    m_pendingDxfDimensionPictureBlocks.emplace(
                        key, dimension->handle);
                if (!inserted.second) {
                    m_dxfWriteMutations.resize(mutationCheckpoint);
                    m_writeError = true;
                    return false;
                }
            } catch (...) {
                m_pendingDxfDimensionPictureBlocks.erase(key);
                m_dxfWriteMutations.resize(mutationCheckpoint);
                m_writeError = true;
                return false;
            }
        }
        return true;
    }

    if (m_dxfBlockSectionComplete
        && m_emittedDxfBlockBodyNames.count(key) == 0) {
        recordOperationDiagnostic(DRW::OperationPhase::Entities,
            DRW::OperationCause::ValidationFailure,
            "incomplete-dimension-picture-block",
            "DIMENSION picture BLOCK_RECORD has no emitted BLOCK body", 0,
            false, dimension->handle, dimension->handle != DRW::NoHandle);
        return failDxfWrite();
    }

    // A direct standalone writeDimension() call outside the BLOCKS phase has
    // only the historical planned-name contract; the full writer performs
    // body closure once BLOCKS is structurally complete.
    return true;
}

bool dxfRW::preflightDimensionStyle(const DRW_Dimension *dimension) {
    // DIMENSION group 3 names a DIMSTYLE table record. Resolve it only during
    // strict full conversion, after TABLES has been emitted; standalone writer
    // calls retain their historical behavior.
    if (!m_requireResolvedBlockOwners || version <= DRW::AC1009
        || dimension == nullptr || dimension->getStyle().empty()
        || (!m_dxfBlockSectionActive && !m_dxfBlockSectionComplete))
        return true;

    const std::string key = dxfSymbolNameKey(dimension->getStyle());
    if (key.empty() || m_emittedDxfDimStyleNames.count(key) == 0) {
        recordOperationDiagnostic(writingBlock ? DRW::OperationPhase::Blocks
                                               : DRW::OperationPhase::Entities,
            DRW::OperationCause::ValidationFailure,
            "unresolved-dimension-style",
            "DIMENSION group-3 style has no emitted DIMSTYLE record", 0,
            false, dimension->handle,
            dimension->handle != DRW::NoHandle);
        return failDxfWrite();
    }
    return true;
}

bool dxfRW::preflightInsertTargetBody(const DRW_Insert *insert) {
    if (!m_requireResolvedBlockOwners || version <= DRW::AC1009
        || insert == nullptr || insert->name.empty())
        return true;

    const std::string key = dxfSymbolNameKey(insert->name);
    if (key.empty()) {
        m_writeError = true;
        return false;
    }

    if (m_dxfBlockSectionActive) {
        if (m_emittedDxfBlockBodyNames.count(key) != 0
            || m_pendingDxfInsertBodyTargets.count(key) != 0)
            return true;

        const std::size_t mutationCheckpoint = m_dxfWriteMutations.size();
        try {
            if (m_recordStateScopeDepth != 0) {
                m_dxfWriteMutations.push_back({
                    DxfWriteMutationKind::PendingDxfInsertBodyTargetInsert,
                    key, 0, 0, false});
            }
            const auto inserted = m_pendingDxfInsertBodyTargets.emplace(
                key, insert->handle);
            if (!inserted.second) {
                m_dxfWriteMutations.resize(mutationCheckpoint);
                m_writeError = true;
                return false;
            }
        } catch (...) {
            m_pendingDxfInsertBodyTargets.erase(key);
            m_dxfWriteMutations.resize(mutationCheckpoint);
            m_writeError = true;
            return false;
        }
        return true;
    }

    if (m_dxfBlockSectionComplete
        && m_emittedDxfBlockBodyNames.count(key) == 0) {
        recordOperationDiagnostic(DRW::OperationPhase::Entities,
            DRW::OperationCause::ValidationFailure,
            "incomplete-insert-target-block",
            "INSERT BLOCK_RECORD has no emitted BLOCK body", 0, false,
            insert->handle, insert->handle != DRW::NoHandle);
        return failDxfWrite();
    }

    // A direct standalone writeInsert() call before BLOCKS has completed can
    // establish only the historical planned-name contract. The full writer
    // performs body closure at the end of the BLOCKS section.
    return true;
}

bool dxfRW::recordEmittedDxfBlockBody(const std::string& name) {
    const std::string key = dxfSymbolNameKey(name);
    if (key.empty() || m_emittedDxfBlockBodyNames.count(key) != 0) {
        m_writeError = true;
        return false;
    }
    const std::size_t mutationCheckpoint = m_dxfWriteMutations.size();
    try {
        if (m_recordStateScopeDepth != 0) {
            m_dxfWriteMutations.push_back({
                DxfWriteMutationKind::EmittedDxfBlockBodyInsert,
                key, 0, 0, false});
        }
        const auto inserted = m_emittedDxfBlockBodyNames.insert(key);
        if (!inserted.second) {
            m_dxfWriteMutations.resize(mutationCheckpoint);
            m_writeError = true;
            return false;
        }
    } catch (...) {
        m_emittedDxfBlockBodyNames.erase(key);
        m_dxfWriteMutations.resize(mutationCheckpoint);
        m_writeError = true;
        return false;
    }
    return true;
}

bool dxfRW::recordEmittedDxfDimStyleName(const std::string& name) {
    if (!m_requireResolvedBlockOwners || version <= DRW::AC1009)
        return true;

    const std::string key = dxfSymbolNameKey(name);
    if (key.empty() || m_emittedDxfDimStyleNames.count(key) != 0) {
        m_writeError = true;
        return false;
    }
    const std::size_t mutationCheckpoint = m_dxfWriteMutations.size();
    try {
        if (m_recordStateScopeDepth != 0) {
            m_dxfWriteMutations.push_back({
                DxfWriteMutationKind::EmittedDxfDimStyleNameInsert,
                key, 0, 0, false});
        }
        const auto inserted = m_emittedDxfDimStyleNames.insert(key);
        if (!inserted.second) {
            m_dxfWriteMutations.resize(mutationCheckpoint);
            m_writeError = true;
            return false;
        }
    } catch (...) {
        m_emittedDxfDimStyleNames.erase(key);
        m_dxfWriteMutations.resize(mutationCheckpoint);
        m_writeError = true;
        return false;
    }
    return true;
}

bool dxfRW::recordSourceLinetypeTarget(std::uint32_t sourceHandle,
                                      const std::string& name,
                                      std::uint32_t emittedHandle) {
    if (sourceHandle == 0 || sourceHandle == DRW::NoHandle)
        return true;
    if (name.empty() || emittedHandle == 0) {
        m_writeError = true;
        return false;
    }
    const auto existing = m_sourceLinetypeTargetsByHandle.find(sourceHandle);
    if (existing != m_sourceLinetypeTargetsByHandle.end()) {
        const bool sameTarget = existing->second.name == name
            && existing->second.emittedHandle == emittedHandle;
        if (!sameTarget)
            m_writeError = true;
        return sameTarget;
    }

    const std::size_t mutationCheckpoint = m_dxfWriteMutations.size();
    try {
        if (m_recordStateScopeDepth != 0) {
            m_dxfWriteMutations.push_back({
                DxfWriteMutationKind::SourceLinetypeTargetInsert, {},
                sourceHandle, 0, false});
        }
        const auto inserted = m_sourceLinetypeTargetsByHandle.emplace(
            sourceHandle, SourceLinetypeTarget{name, emittedHandle});
        if (!inserted.second) {
            m_dxfWriteMutations.resize(mutationCheckpoint);
            m_writeError = true;
            return false;
        }
    } catch (...) {
        m_sourceLinetypeTargetsByHandle.erase(sourceHandle);
        m_dxfWriteMutations.resize(mutationCheckpoint);
        m_writeError = true;
        return false;
    }
    return true;
}

bool dxfRW::recordPendingDxfDimstyleBlockResource(
    const std::string& name, std::uint32_t sourceDimstyleHandle) {
    if (!m_requireResolvedBlockOwners || version <= DRW::AC1009)
        return true;
    const std::string key = dxfSymbolNameKey(name);
    if (key.empty()) {
        m_writeError = true;
        return false;
    }
    if (m_pendingDxfDimstyleBlockResources.count(key) != 0)
        return true;

    const std::size_t mutationCheckpoint = m_dxfWriteMutations.size();
    try {
        if (m_recordStateScopeDepth != 0) {
            m_dxfWriteMutations.push_back({
                DxfWriteMutationKind::PendingDxfDimstyleBlockResourceInsert,
                key, 0, 0, false});
        }
        const auto inserted = m_pendingDxfDimstyleBlockResources.emplace(
            key, sourceDimstyleHandle);
        if (!inserted.second) {
            m_dxfWriteMutations.resize(mutationCheckpoint);
            m_writeError = true;
            return false;
        }
    } catch (...) {
        m_pendingDxfDimstyleBlockResources.erase(key);
        m_dxfWriteMutations.resize(mutationCheckpoint);
        m_writeError = true;
        return false;
    }
    return true;
}

bool dxfRW::writeDimension(DRW_Dimension *ent) {
    if (!preflightEntity(ent))
        return false;
    if (ent->eType == DRW::DIMARC)
        return writeArcDimension(static_cast<DRW_DimArc*>(ent));
    if (auto *largeRadial = dynamic_cast<DRW_DimLargeRadial*>(ent))
        return writeLargeRadialDimension(largeRadial);
    if (!preflightDimensionStyle(ent)
        || !preflightDimensionPictureBlock(ent))
        return false;
    if (version > DRW::AC1009) {
        std::vector<std::shared_ptr<DRW_Variant>> dimensionXdata;
        if (!buildDimensionDstyleXdata(*ent, dimensionXdata))
            return false;
        EntityRecordScope scope(*this, ent);
        writer->writeString(0, "DIMENSION");
        if (!writeEntity(ent))
            return false;
        writer->writeString(100, "AcDbDimension");
        if (version >= DRW::AC1024)
            writer->writeInt16(280, 0);   // AcDbDimension version, 0 = R2010+
        if (!ent->getName().empty()){
            writer->writeUtf8String(2, ent->getName());
        }
        writer->writeDouble(10, ent->getDefPoint().x);
        writer->writeDouble(20, ent->getDefPoint().y);
        writer->writeDouble(30, ent->getDefPoint().z);
        writer->writeDouble(11, ent->getTextPoint().x);
        writer->writeDouble(21, ent->getTextPoint().y);
        writer->writeDouble(31, ent->getTextPoint().z);
        // DRW_Dimension::type carries DXF flags, while the concrete C++
        // subtype is represented by eType.  Callers historically assigned
        // DRW::DIMENSION to type (the entity enum value) when constructing a
        // DRW_DimLinear/DRW_DimAligned; trusting that low nibble emitted a
        // different subtype (often DIAMETRIC) and made AutoCAD reject the
        // record.  Derive the subtype bits from the concrete subtype and
        // preserve all other flags supplied by the caller.
        int subtype = ent->type & 0x07;
        switch (ent->eType) {
        case DRW::DIMLINEAR:
            subtype = 0;
            break;
        case DRW::DIMALIGNED:
            subtype = 1;
            break;
        case DRW::DIMANGULAR:
            subtype = 2;
            break;
        case DRW::DIMDIAMETRIC:
            subtype = 3;
            break;
        case DRW::DIMRADIAL:
            subtype = 4;
            break;
        case DRW::DIMANGULAR3P:
            subtype = 5;
            break;
        case DRW::DIMORDINATE:
            subtype = 6;
            break;
        default:
            break;
        }
        // Bits 0..3 are the DXF subtype nibble.  Clear all four bits so an
        // accidental assignment of DRW::DIMENSION (the entity enum value 8)
        // cannot leak into the emitted subtype; preserve the documented
        // high flags (associativity, ordinate axis, and anonymous-block bit).
        const int dimType = (ent->type & ~0x0F) | subtype | 32;
        writer->writeInt16(70, dimType);
        if ( !(ent->getText().empty()) )
            writer->writeUtf8String(1, ent->getText());
        writer->writeInt16(71, ent->getAlign());
        if ( ent->getTextLineStyle() != 1)
            writer->writeInt16(72, ent->getTextLineStyle());
        if ( ent->getTextLineFactor() != 1)
            writer->writeDouble(41, ent->getTextLineFactor());
        writer->writeUtf8String(3, ent->getStyle());
        // Measurement(42), horizontal direction(51) and flip-arrow flags(74/75)
        // — the DXF reader consumes all four (drw_entities.cpp parseCode) and the
        // DWG encoder writes hdir/flipArrow1/flipArrow2; emit them for symmetry.
        if (ent->measureValue != 0)
            writer->writeDouble(42, ent->measureValue);
        if (ent->getDir() != 0)
            writer->writeDouble(53, ent->getDir());
        if (ent->hdir != 0)
            writer->writeDouble(51, ent->hdir);
        if (ent->getFlipArrow1())
            writer->writeInt16(74, 1);
        if (ent->getFlipArrow2())
            writer->writeInt16(75, 1);
        writer->writeDouble(210, ent->getExtrusion().x);
        writer->writeDouble(220, ent->getExtrusion().y);
        writer->writeDouble(230, ent->getExtrusion().z);

        switch (ent->eType) {
            case DRW::DIMALIGNED:
            case DRW::DIMLINEAR: {
            DRW_DimAligned * dd = (DRW_DimAligned*)ent;
            writer->writeString(100, "AcDbAlignedDimension");
                DRW_Coord crd = dd->getClonepoint();
                if (crd.x != 0 || crd.y != 0 || crd.z != 0) {
                writer->writeDouble(12, crd.x);
                writer->writeDouble(22, crd.y);
                writer->writeDouble(32, crd.z);
                }
            writer->writeDouble(13, dd->getDef1Point().x);
            writer->writeDouble(23, dd->getDef1Point().y);
            writer->writeDouble(33, dd->getDef1Point().z);
            writer->writeDouble(14, dd->getDef2Point().x);
            writer->writeDouble(24, dd->getDef2Point().y);
            writer->writeDouble(34, dd->getDef2Point().z);
                if (ent->eType == DRW::DIMLINEAR) {
                DRW_DimLinear * dl = (DRW_DimLinear*)ent;
                if (dl->getAngle() != 0)
                    writer->writeDouble(50, dl->getAngle());
                if (dl->getOblique() != 0)
                    writer->writeDouble(52, dl->getOblique());
                writer->writeString(100, "AcDbRotatedDimension");
                }
                break;
            }
            case DRW::DIMRADIAL: {
            DRW_DimRadial * dd = (DRW_DimRadial*)ent;
            writer->writeString(100, "AcDbRadialDimension");
            writer->writeDouble(15, dd->getDiameterPoint().x);
            writer->writeDouble(25, dd->getDiameterPoint().y);
            writer->writeDouble(35, dd->getDiameterPoint().z);
            writer->writeDouble(40, dd->getLeaderLength());
                break;
            }
            case DRW::DIMDIAMETRIC: {
            DRW_DimDiametric * dd = (DRW_DimDiametric*)ent;
            writer->writeString(100, "AcDbDiametricDimension");
            writer->writeDouble(15, dd->getDiameter1Point().x);
            writer->writeDouble(25, dd->getDiameter1Point().y);
            writer->writeDouble(35, dd->getDiameter1Point().z);
            writer->writeDouble(40, dd->getLeaderLength());
                break;
            }
            case DRW::DIMANGULAR: {
            DRW_DimAngular * dd = (DRW_DimAngular*)ent;
            writer->writeString(100, "AcDb2LineAngularDimension");
            writer->writeDouble(13, dd->getFirstLine1().x);
            writer->writeDouble(23, dd->getFirstLine1().y);
            writer->writeDouble(33, dd->getFirstLine1().z);
            writer->writeDouble(14, dd->getFirstLine2().x);
            writer->writeDouble(24, dd->getFirstLine2().y);
            writer->writeDouble(34, dd->getFirstLine2().z);
            writer->writeDouble(15, dd->getSecondLine1().x);
            writer->writeDouble(25, dd->getSecondLine1().y);
            writer->writeDouble(35, dd->getSecondLine1().z);
            writer->writeDouble(16, dd->getDimPoint().x);
            writer->writeDouble(26, dd->getDimPoint().y);
            writer->writeDouble(36, dd->getDimPoint().z);
            break; }
            case DRW::DIMANGULAR3P: {
            DRW_DimAngular3p * dd = (DRW_DimAngular3p*)ent;
            writer->writeString(100, "AcDb3PointAngularDimension");
            writer->writeDouble(13, dd->getFirstLine().x);
            writer->writeDouble(23, dd->getFirstLine().y);
            writer->writeDouble(33, dd->getFirstLine().z);
            writer->writeDouble(14, dd->getSecondLine().x);
            writer->writeDouble(24, dd->getSecondLine().y);
            writer->writeDouble(34, dd->getSecondLine().z);
            writer->writeDouble(15, dd->getVertexPoint().x);
            writer->writeDouble(25, dd->getVertexPoint().y);
            writer->writeDouble(35, dd->getVertexPoint().z);
            break; }
            case DRW::DIMORDINATE: {
            DRW_DimOrdinate * dd = (DRW_DimOrdinate*)ent;
            writer->writeString(100, "AcDbOrdinateDimension");
            writer->writeDouble(13, dd->getFirstLine().x);
            writer->writeDouble(23, dd->getFirstLine().y);
            writer->writeDouble(33, dd->getFirstLine().z);
            writer->writeDouble(14, dd->getSecondLine().x);
            writer->writeDouble(24, dd->getSecondLine().y);
            writer->writeDouble(34, dd->getSecondLine().z);
            break; }
            default:
                break;
        }
        if (!dimensionXdata.empty() && !writeExtData(dimensionXdata))
            return false;
    } else  {
        return rejectUnsupportedDxfWrite("DIMENSION");
    }
    return !writer->hasWriteError();
}

bool dxfRW::writeInsert(DRW_Insert *ent){
    if (!preflightEntity(ent)
        || (ent->seqEndEntity != nullptr
            && !preflightEntity(ent->seqEndEntity.get()))
        || ent->name.empty()
        || !isSafeDxfRecordText(ent->name)
        || ent->colcount <= 0
        || ent->rowcount <= 0
        || ent->colcount > std::numeric_limits<std::int16_t>::max()
        || ent->rowcount > std::numeric_limits<std::int16_t>::max()
        || std::any_of(ent->attlist.cbegin(), ent->attlist.cend(),
                       [](const auto& attribute) {
                           return attribute == nullptr
                               || !isValidDxfEntityFields(*attribute)
                               || !isSafeDxfRecordText(attribute->tag)
                               // DXF currently has no route for the separate
                               // R2018 DWG outer annotative byte block and
                               // APPID hard pointer. Refuse the compound
                               // INSERT before publishing any child records.
                               || !attribute->m_r2018OuterAnnotativeData.empty()
                               || attribute->m_r2018OuterAnnotativeUnknown != 0
                               || attribute->m_r2018OuterAnnotativeAppHandle != 0
                               || !attribute->m_r2018OuterAnnotativeAppIdName.empty();
                       }))
    {
        m_writeError = true;
        return false;
    }
    // Strict converter closure applies to the referenced definition as well
    // as this entity's owner. TABLES has already planned all BLOCK_RECORDs,
    // including forward/nested references; reuse that index, not a new walk.
    // R12 has no BLOCK_RECORD table and keeps its existing fallback contract.
    if (m_requireResolvedBlockOwners && version > DRW::AC1009
        && getBlockRecordHandleToWrite(ent->name) == DRW::NoHandle) {
        recordOperationDiagnostic(writingBlock ? DRW::OperationPhase::Blocks
                                               : DRW::OperationPhase::Entities,
            DRW::OperationCause::ValidationFailure, "unresolved-insert-target",
            "INSERT target has no emitted BLOCK_RECORD", 0, false,
            ent->handle, ent->handle != DRW::NoHandle);
        return failDxfWrite();
    }
    RecordStateScope state(*this, ent);
    if (!preflightInsertTargetBody(ent))
        return false;
    DxfWriterRecordScope record(*writer);
    // Successful child scopes still belong to this compound transaction.
    // Reverse the emitted prefix on failure, including intermediate handles
    // when the caller's attribute list contains the same pointer more than once.
    struct AttributeHandleRollback {
        std::vector<std::pair<DRW_Attrib*, std::uint32_t>> handles;
        bool committed {false};
        ~AttributeHandleRollback() {
            if (!committed) {
                for (auto saved = handles.rbegin(); saved != handles.rend(); ++saved)
                    saved->first->handle = saved->second;
            }
        }
    } attributeState;
    attributeState.handles.reserve(ent->attlist.size());
    const bool hasAttribs = !ent->attlist.empty();
    const bool hasSequenceEnd = hasAttribs || ent->seqEndEntity != nullptr;
    const bool isMInsert = ent->isMInsert();
    // DXF represents a multiple insert as an INSERT record with the
    // AcDbMInsertBlock subclass and grid groups.  MINSERT is the distinct DWG
    // object type, not the standard DXF group-0 entity name.
    writer->writeString(0, "INSERT");
    if (!writeEntity(ent))
        return false;
    if (version > DRW::AC1009) {
        writer->writeString(100, isMInsert ? "AcDbMInsertBlock" : "AcDbBlockReference");
        if (hasSequenceEnd)
            writer->writeInt16(66, 1); //attributes-follow flag
        writer->writeUtf8String(2, ent->name);
    } else {
        if (hasSequenceEnd)
            writer->writeInt16(66, 1);
        writer->writeUtf8Caps(2, ent->name);
    }
    writer->writeDouble(10, ent->basePoint.x);
    writer->writeDouble(20, ent->basePoint.y);
    writer->writeDouble(30, ent->basePoint.z);
    writer->writeDouble(41, ent->xscale);
    writer->writeDouble(42, ent->yscale);
    writer->writeDouble(43, ent->zscale);
    writer->writeDouble(50, (ent->angle)*ARAD); //in dxf angle is writed in degrees
    writer->writeInt16(70, ent->colcount);
    writer->writeInt16(71, ent->rowcount);
    writer->writeDouble(44, ent->colspace);
    writer->writeDouble(45, ent->rowspace);
    // extrusion(210/220/230) — OCS inserts re-import in the wrong plane without
    // it (reader reads it, DWG encoder preserves it). Default 0,0,1.
    if (ent->extPoint.x != 0 || ent->extPoint.y != 0 || ent->extPoint.z != 1) {
        writer->writeDouble(210, ent->extPoint.x);
        writer->writeDouble(220, ent->extPoint.y);
        writer->writeDouble(230, ent->extPoint.z);
    }
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    //Trailing block attributes + terminating SEQEND (mirrors writePolyline).
    if (hasSequenceEnd) {
        const std::uint32_t insertHandle = ent->handle;
        for (const auto &att : ent->attlist) {
            if (att) {
                attributeState.handles.emplace_back(att.get(), att->handle);
                if (!writeAttrib(att.get(), insertHandle))
                    return false;
            }
        }
        if (!writeSequenceEnd(ent->seqEndEntity.get(), insertHandle))
            return false;
    }
    if (!preflightDxfWrite() || !record.commit()) {
        m_writeError = true;
        return false;
    }
    state.commit();
    attributeState.committed = true;
    return true;
}

bool dxfRW::writeTable(DRW_Table *ent){
    if (!preflightEntity(ent)
        || (ent != nullptr && ent->seqEndEntity != nullptr
            && !preflightEntity(ent->seqEndEntity.get())))
        return false;

    constexpr std::size_t maxRows = 10000u;
    constexpr std::size_t maxColumns = 1000u;
    constexpr std::size_t maxCells = 200000u;
    constexpr std::size_t maxCellAttributes = 10000u;
    constexpr std::size_t maxTextBytes = 16u * 1024u * 1024u;
    const std::size_t rows = ent->m_content.m_rows.size();
    const std::size_t columns = tableColumnCount(*ent);
    if (version < DRW::AC1018
        || !ent->m_hasSemanticContent || !ent->m_semanticContentComplete
        || rows == 0u || columns == 0u || rows > maxRows
        || columns > maxColumns || rows > maxCells / columns
        || ent->m_content.m_columns.size() != columns
        || ent->m_tableStyleHandle != ent->m_content.m_tableStyleHandle
        || (ent->m_tableStyleHandle != 0u
            && std::find(m_resolvedTableStyleHandles.begin(),
                         m_resolvedTableStyleHandles.end(),
                         ent->m_tableStyleHandle)
                == m_resolvedTableStyleHandles.end())
        || ent->m_content.m_name.size() != 0u
        || ent->m_content.m_description.size() != 0u
        || ent->m_content.m_overrideStyleType != 4
        || !ent->m_content.m_fieldHandles.empty()
        || !ent->m_content.m_subrecordRanges.empty()) {
        return failDxfWrite();
    }

    std::size_t mergedCellCount = 0;
    for (std::size_t rowIndex = 0; rowIndex < rows; ++rowIndex) {
        const DRW_TableRow& row = ent->m_content.m_rows[rowIndex];
        // TABLECONTENT base-style IDs are carried by DWG, but Autodesk's
        // published TABLE DXF group-code schema has no row-ID slot.
        if (row.m_styleId != 0 || row.m_overrideStyleType != 2
            || row.m_cells.size() != columns
            || !std::isfinite(row.m_height)
            || row.m_height < 0.0)
            return failDxfWrite();
        for (const DRW_TableCell& cell : row.m_cells) {
            const bool textCell = cell.m_type == 1;
            const bool blockCell = cell.m_type == 2;
            const bool cellContentMatches = cell.m_contents.size() == 1u
                && ((textCell && cell.m_contents.front().m_type == 1)
                    || (blockCell && cell.m_contents.front().m_type == 4
                        && cell.m_contents.front().m_handle
                            == cell.m_blockHandle));
            if ((!textCell && !blockCell) || !cellContentMatches
                || cell.m_attributes.size() > maxCellAttributes
                || (!blockCell && !cell.m_attributes.empty())
                || cell.m_hasLinkedData || cell.m_dataLinkHandle != 0u
                || cell.m_linkedDataRowCount != 0
                || cell.m_linkedDataColumnCount != 0
                || cell.m_linkedDataUnknown != 0
                || !cell.m_toolTip.empty()
                // DXF TABLE has no serialized cell base-style ID field.
                || cell.m_styleId != 0 || cell.m_overrideStyleType != 1
                || cell.m_valueHandle != 0u
                || cell.m_textStyleHandle != 0u
                || cell.m_textStyleOverrideHandle != 0u
                || (textCell && (cell.m_blockHandle != 0u
                                 || cell.m_blockScale != 1.0))
                || (blockCell
                    && (cell.m_blockHandle == 0u
                        || cell.m_blockHandle == DRW::NoHandle
                        || !std::isfinite(cell.m_blockScale)
                        || cell.m_blockScale <= 0.0))
                || cell.m_width != 0.0 || cell.m_height != 0.0
                || cell.m_geometryFlags != 0u || cell.m_geometryHandle != 0u
                || cell.m_geometryRecordFlags != 0u
                || cell.m_geometryTopLeft.x != 0.0
                || cell.m_geometryTopLeft.y != 0.0
                || cell.m_geometryTopLeft.z != 0.0
                || cell.m_geometryCenter.x != 0.0
                || cell.m_geometryCenter.y != 0.0
                || cell.m_geometryCenter.z != 0.0
                || cell.m_contentWidth != 0.0 || cell.m_contentHeight != 0.0
                || cell.m_geometryWidth != 0.0 || cell.m_geometryHeight != 0.0
                || cell.m_textColorMethod != 0u
                || cell.m_fillColorMethod != 0u
                || (!cell.m_textStyleName.empty()
                    && getTextStyleHandle(cell.m_textStyleName)
                        == DRW::NoHandle)
                || !std::isfinite(cell.m_rotation)
                || !std::isfinite(cell.m_textHeight) || cell.m_textHeight < 0.0
                || cell.m_flags < 0 || cell.m_edgeFlags < 0
                || cell.m_edgeFlags > 32767
                || cell.m_textAlignment < 0 || cell.m_textAlignment > 32767
                || cell.m_textColorRgb > 32767 || cell.m_fillColorRgb > 32767
                || cell.m_overrideFlags > static_cast<std::uint32_t>(INT_MAX)
                || cell.m_virtualEdgeFlags < 0 || cell.m_virtualEdgeFlags > 0xFF
                || (version < DRW::AC1021
                    && (cell.m_overrideFlags != 0u
                        || cell.m_virtualEdgeFlags != 0 || cell.m_flags != 0
                        || !cell.m_textStyleName.empty()
                        || cell.m_textHeight != 0.0
                        || cell.m_textAlignment != 0
                        || cell.m_textColorRgb >= 0
                        || cell.m_fillColorRgb >= 0
                        || cell.m_backgroundEnabled))
                || (!cell.m_isMerged
                    && (cell.m_mergedWidth > 1 || cell.m_mergedHeight > 1))
                || (cell.m_isMerged
                    && (cell.m_mergedWidth <= 0 || cell.m_mergedHeight <= 0
                        || cell.m_mergedWidth > static_cast<int>(columns)
                        || cell.m_mergedHeight > static_cast<int>(rows)
                        || rowIndex + static_cast<std::size_t>(cell.m_mergedHeight) > rows))
                || (!cell.m_isMerged
                    && (!ent->m_content.m_mergedRanges.empty()
                        && cell.m_mergedWidth > 1))) {
                return failDxfWrite();
            }
            if (textCell) {
                const UTF8STRING text = tableCellText(cell);
                if (text.size() > maxTextBytes
                    || (cell.m_contents.front().m_value.m_dataType != 0
                        && cell.m_contents.front().m_value.m_dataType != 4))
                    return failDxfWrite();
            } else {
                const auto blockRecord = m_sourceBlockRecordHandles.find(
                    cell.m_blockHandle);
                if (blockRecord == m_sourceBlockRecordHandles.end()
                    || blockRecord->second == 0u
                    || cell.m_contents.front().m_value.m_dataType != 0)
                    return failDxfWrite();
                std::unordered_set<std::uint32_t> seenAttributeDefinitions;
                for (std::size_t attributeIndex = 0;
                     attributeIndex < cell.m_attributes.size();
                     ++attributeIndex) {
                    const DRW_TableCellAttribute& attribute =
                        cell.m_attributes[attributeIndex];
                    const auto emitted =
                        m_writingContext.sourceHandleToMintedMap.find(
                            attribute.m_attdefHandle);
                    const bool invalidAttribute = attribute.m_contentIndex != 0u
                        || attribute.m_index
                            != static_cast<int>(attributeIndex)
                        || attribute.m_attdefHandle == 0u
                        || attribute.m_attdefHandle == DRW::NoHandle
                        || attribute.m_text.size() > maxTextBytes
                        || !isSafeDxfRecordText(attribute.m_text)
                        || !seenAttributeDefinitions.insert(
                            attribute.m_attdefHandle).second
                        || emitted
                            == m_writingContext.sourceHandleToMintedMap.end()
                        || m_writingContext.ambiguousSourceHandles.count(
                               attribute.m_attdefHandle) != 0u
                        || m_writingContext.writtenSourceEntityHandles.count(
                               attribute.m_attdefHandle) != 1u
                        || remapObjectHandle(attribute.m_attdefHandle)
                            != emitted->second;
                    if (invalidAttribute) {
                        recordOperationDiagnostic(
                            DRW::OperationPhase::Entities,
                            DRW::OperationCause::ValidationFailure,
                            "table-cell-attribute-reference",
                            "TABLE block-cell ATTDEF handle is not uniquely emitted",
                            0, false, attribute.m_attdefHandle, true);
                        return failDxfWrite();
                    }
                }
            }
            if (cell.m_isMerged)
                ++mergedCellCount;
            for (std::size_t borderIndex = 0;
                 borderIndex < cell.m_borders.size(); ++borderIndex) {
                const DRW_TableBorder& border = cell.m_borders[borderIndex];
                if (border.m_colorMethod != 0u || border.m_lineWeight < 0
                    || border.m_lineWeight > 32767
                    || border.m_colorRgb < -1 || border.m_colorRgb > 32767
                    || (version < DRW::AC1021
                        && (border.m_colorRgb >= 0
                            || border.m_lineWeight != 0 || !border.m_visible))
                    || (borderIndex >= 4u
                        && (border.m_lineWeight != 0 || !border.m_visible
                            || border.m_colorRgb != -1)))
                    return failDxfWrite();
            }
        }
    }
    if (mergedCellCount != ent->m_content.m_mergedRanges.size())
        return failDxfWrite();
    for (std::size_t rowIndex = 0; rowIndex < rows; ++rowIndex) {
        for (std::size_t columnIndex = 0; columnIndex < columns; ++columnIndex) {
            const DRW_TableCell& cell =
                ent->m_content.m_rows[rowIndex].m_cells[columnIndex];
            if (!cell.m_isMerged)
                continue;
            const int bottom = static_cast<int>(rowIndex)
                + cell.m_mergedHeight - 1;
            const int right = static_cast<int>(columnIndex)
                + cell.m_mergedWidth - 1;
            const auto matches = std::count_if(
                ent->m_content.m_mergedRanges.begin(),
                ent->m_content.m_mergedRanges.end(),
                [rowIndex, columnIndex, bottom, right](
                    const DRW_TableMergedRange& range) {
                    return range.m_topRow == static_cast<int>(rowIndex)
                        && range.m_leftColumn == static_cast<int>(columnIndex)
                        && range.m_bottomRow == bottom
                        && range.m_rightColumn == right;
                });
            if (matches != 1)
                return failDxfWrite();
        }
    }
    for (std::size_t column = 0; column < columns; ++column) {
        const DRW_TableColumn& tableColumn = ent->m_content.m_columns[column];
        // As with row and cell base-style IDs, DXF has no column-ID field.
        if (tableColumn.m_styleId != 0 || tableColumn.m_overrideStyleType != 3
            || !tableColumn.m_name.empty()
            || !std::isfinite(tableColumn.m_width)
            || tableColumn.m_width < 0.0)
            return failDxfWrite();
    }
    if (ent->m_dataVersion < 0 || ent->m_dataVersion > 32767
        || (version < DRW::AC1024 && ent->m_dataVersion != 0)
        || ent->m_flowDirection < 0 || ent->m_flowDirection > 32767
        || ent->m_tableOverrideFlags > static_cast<std::uint32_t>(INT_MAX)
        || ent->m_borderColorOverrideFlags > static_cast<std::uint32_t>(INT_MAX)
        || ent->m_borderLineweightOverrideFlags > static_cast<std::uint32_t>(INT_MAX)
        || ent->m_borderVisibilityOverrideFlags > static_cast<std::uint32_t>(INT_MAX)
        || !std::isfinite(ent->m_horizontalCellMargin)
        || !std::isfinite(ent->m_verticalCellMargin)
        || ent->m_horizontalCellMargin < 0.0
        || ent->m_verticalCellMargin < 0.0)
        return failDxfWrite();
    const std::uint32_t emittedOwnerBlockRecord =
        remapObjectHandle(ent->m_ownerBlockRecordHandle);
    if (ent->m_ownerBlockRecordHandle != 0u
        && emittedOwnerBlockRecord == 0u)
        return failDxfWrite();

    if (std::any_of(ent->attlist.cbegin(), ent->attlist.cend(),
            [](const auto& attribute) {
                return attribute == nullptr
                    || !isValidDxfEntityFields(*attribute)
                    || !isSafeDxfRecordText(attribute->tag)
                    || !attribute->m_r2018OuterAnnotativeData.empty()
                    || attribute->m_r2018OuterAnnotativeUnknown != 0
                    || attribute->m_r2018OuterAnnotativeAppHandle != 0
                    || !attribute->m_r2018OuterAnnotativeAppIdName.empty();
            }))
        return failDxfWrite();

    EntityRecordScope scope(*this, ent);
    struct AttributeHandleRollback {
        std::vector<std::pair<DRW_Attrib*, std::uint32_t>> handles;
        bool committed {false};
        ~AttributeHandleRollback() {
            if (!committed) {
                for (auto saved = handles.rbegin(); saved != handles.rend(); ++saved)
                    saved->first->handle = saved->second;
            }
        }
    } attributeState;
    attributeState.handles.reserve(ent->attlist.size());
    const bool hasAttribs = !ent->attlist.empty();
    const bool hasSequenceEnd = hasAttribs || ent->seqEndEntity != nullptr;
    writer->writeString(0, "ACAD_TABLE");
    if (!writeEntity(ent))
        return false;
    if (version > DRW::AC1009) {
        writer->writeString(100, "AcDbBlockReference");
        if (hasSequenceEnd)
            writer->writeInt16(66, 1);
    }

    const UTF8STRING blockName = ent->name.empty() ? UTF8STRING("*T1") : ent->name;
    writer->writeUtf8String(2, blockName);
    writer->writeDouble(10, ent->basePoint.x);
    writer->writeDouble(20, ent->basePoint.y);
    writer->writeDouble(30, ent->basePoint.z);
    if (ent->xscale != 1.0)
        writer->writeDouble(41, ent->xscale);
    if (ent->yscale != 1.0)
        writer->writeDouble(42, ent->yscale);
    if (ent->zscale != 1.0)
        writer->writeDouble(43, ent->zscale);
    if (ent->angle != 0.0)
        writer->writeDouble(50, ent->angle * ARAD);
    if (ent->extPoint.x != 0 || ent->extPoint.y != 0 || ent->extPoint.z != 1) {
        writer->writeDouble(210, ent->extPoint.x);
        writer->writeDouble(220, ent->extPoint.y);
        writer->writeDouble(230, ent->extPoint.z);
    }

    writer->writeString(100, "AcDbTable");
    if (ent->m_tableStyleHandle != 0u)
        writer->writeString(342,
            toHexStr(remapObjectHandle(ent->m_tableStyleHandle)));
    if (version >= DRW::AC1024)
        writer->writeInt16(280, ent->m_dataVersion);
    if (ent->m_ownerBlockRecordHandle != 0u)
        writer->writeString(343, toHexStr(emittedOwnerBlockRecord));

    DRW_Coord horizontal = ent->m_horizontalDirection;
    if (horizontal.x == 0.0 && horizontal.y == 0.0 && horizontal.z == 0.0)
        horizontal.x = 1.0;
    writer->writeDouble(11, horizontal.x);
    writer->writeDouble(21, horizontal.y);
    writer->writeDouble(31, horizontal.z);

    writer->writeInt32(90, ent->m_valueFlag);
    writer->writeInt32(91, static_cast<int>(rows));
    writer->writeInt32(92, static_cast<int>(columns));
    writer->writeInt32(93, static_cast<int>(ent->m_tableOverrideFlags));
    writer->writeInt32(94, static_cast<int>(ent->m_borderColorOverrideFlags));
    writer->writeInt32(95, static_cast<int>(ent->m_borderLineweightOverrideFlags));
    writer->writeInt32(96, static_cast<int>(ent->m_borderVisibilityOverrideFlags));

    for (const auto& row : ent->m_content.m_rows)
        writer->writeDouble(141, row.m_height);
    for (std::size_t column = 0; column < columns; ++column) {
        const double width = column < ent->m_content.m_columns.size()
            ? ent->m_content.m_columns[column].m_width
            : 0.0;
        writer->writeDouble(142, width);
    }

    for (std::size_t row = 0; row < rows; ++row) {
        for (std::size_t column = 0; column < columns; ++column) {
            const DRW_TableCell *cell = nullptr;
            cell = &ent->m_content.m_rows[row].m_cells[column];
            writer->writeInt16(171, cell->m_type);
            writer->writeInt16(172, cell->m_edgeFlags);
            writer->writeInt16(173, cell->m_isMerged ? 1 : 0);
            writer->writeInt16(174, cell->m_autoFit ? 1 : 0);
            writer->writeInt16(175, cell->m_isMerged ? cell->m_mergedWidth : 1);
            writer->writeInt16(176, cell->m_isMerged ? cell->m_mergedHeight : 1);
            if (version >= DRW::AC1021) {
                writer->writeInt32(91, static_cast<int>(cell->m_overrideFlags));
                writer->writeInt16(178, cell->m_virtualEdgeFlags);
                writer->writeInt32(92, cell->m_flags);
            }
            writer->writeDouble(145, cell->m_rotation);

            if (version >= DRW::AC1021) {
                if (!cell->m_textStyleName.empty())
                    writer->writeUtf8String(7, cell->m_textStyleName);
                if (cell->m_textHeight != 0.0)
                    writer->writeDouble(140, cell->m_textHeight);
                if (cell->m_textAlignment != 0)
                    writer->writeInt16(170, cell->m_textAlignment);
                if (cell->m_textColorRgb >= 0)
                    writer->writeInt16(64, cell->m_textColorRgb);
                if (cell->m_fillColorRgb >= 0)
                    writer->writeInt16(63, cell->m_fillColorRgb);
                if (cell->m_backgroundEnabled)
                    writer->writeInt16(283, 1);
            }

            static const int borderColorCodes[] = {69, 65, 66, 68};
            static const int borderWeightCodes[] = {279, 275, 276, 278};
            static const int borderVisibleCodes[] = {289, 285, 286, 288};
            for (std::size_t border = 0; border < 4u; ++border) {
                const DRW_TableBorder& value = cell->m_borders[border];
                if (version >= DRW::AC1021 && value.m_colorRgb >= 0)
                    writer->writeInt16(borderColorCodes[border],
                                       value.m_colorRgb);
                if (version >= DRW::AC1021 && value.m_lineWeight != 0)
                    writer->writeInt16(borderWeightCodes[border],
                                       value.m_lineWeight);
                if (version >= DRW::AC1021 && !value.m_visible)
                    writer->writeInt16(borderVisibleCodes[border], 0);
            }

            if (cell->m_type == 2) {
                const std::uint32_t blockHandle =
                    remapObjectHandle(cell->m_blockHandle);
                if (blockHandle == 0u)
                    return failDxfWrite();
                writer->writeString(340, toHexStr(blockHandle));
                if (cell->m_blockScale != 1.0)
                    writer->writeDouble(144, cell->m_blockScale);
                if (!cell->m_attributes.empty()) {
                    writer->writeInt16(179,
                        static_cast<int>(cell->m_attributes.size()));
                    for (const DRW_TableCellAttribute& attribute :
                         cell->m_attributes) {
                        writer->writeString(331, toHexStr(
                            remapObjectHandle(attribute.m_attdefHandle)));
                        writer->writeUtf8String(300, attribute.m_text);
                    }
                }
                continue;
            }

            const UTF8STRING text = tableCellText(*cell);
            if (version >= DRW::AC1021) {
                writer->writeUtf8String(301, "CELL_VALUE");
                writer->writeInt32(90, 4);
                if (!writer->writeUtf8Chunks(text, 303, 302, 250u))
                    return false;
                writer->writeUtf8String(304, "ACVALUE_END");
            } else if (!writer->writeUtf8Chunks(text, 2, 1, 250u)) {
                return false;
            }
        }
    }

    if (ent->m_flowDirection != 0)
        writer->writeInt16(70, ent->m_flowDirection);
    if (ent->m_horizontalCellMargin != 0.0)
        writer->writeDouble(40, ent->m_horizontalCellMargin);
    if (ent->m_verticalCellMargin != 0.0)
        writer->writeDouble(41, ent->m_verticalCellMargin);
    if (ent->m_titleSuppressed)
        writer->writeInt16(280, 1);
    if (ent->m_headerSuppressed)
        writer->writeInt16(281, 1);

    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    if (hasSequenceEnd) {
        const std::uint32_t tableHandle = ent->handle;
        for (const auto& attribute : ent->attlist) {
            attributeState.handles.emplace_back(attribute.get(),
                                                attribute->handle);
            if (!writeAttrib(attribute.get(), tableHandle))
                return false;
        }
        if (!writeSequenceEnd(ent->seqEndEntity.get(), tableHandle))
            return false;
    }
    if (writer->hasWriteError())
        return false;
    attributeState.committed = true;
    return true;
}

bool dxfRW::writeTableStyle(
    DRW_TableStyle *ent, const std::list<DRW_Textstyle>& textStyles) {
    const auto reject = [this](const char *message) {
        recordOperationDiagnostic(
            DRW::OperationPhase::Validation,
            DRW::OperationCause::ValidationFailure,
            "tablestyle-unsupported-profile", message);
        return failDxfWrite();
    };
    const auto scalarColorIsDxfRepresentable = [](
            int color, const DRW_TableStyleCmcColor& cmc) {
        const std::uint8_t canonical = color == 0 ? 0xC1u
            : color >= 1 && color <= 255 ? 0xC3u : 0u;
        return cmc.m_rgb == -1 && cmc.m_name.empty()
            && cmc.m_bookName.empty() && cmc.m_reservedIndex == 0
            && cmc.m_flags == 0
            && (cmc.m_method == 0 || cmc.m_method == canonical);
    };
    const auto contentFormatColorIsDxfRepresentable =
        [&scalarColorIsDxfRepresentable](
            const DRW_TableStyleContentFormat& format) {
            return scalarColorIsDxfRepresentable(
                format.m_contentColor, format.m_contentColorCmc);
        };
    const auto validValueDataType = [](int value) {
        switch (value) {
        case 0: case 1: case 2: case 4: case 8: case 16:
        case 32: case 64: case 128: case 256: case 512:
            return true;
        default:
            return false;
        }
    };
    const auto validValueUnitType = [](int value) {
        return value == 0 || value == 1 || value == 2
            || value == 4 || value == 8 || value == 0x10
            || value == 0x20 || value == 0x10000;
    };
    if (!preflightDxfWrite() || ent == nullptr || version < DRW::AC1021
        || ent->handle == 0 || ent->handle == DRW::NoHandle
        || ent->parentHandle == 0 || ent->parentHandle == DRW::NoHandle
        || ent->m_name.size() > 255u || !isSafeDxfRecordText(ent->m_name)
        || ent->m_flowDirection < 0 || ent->m_flowDirection > 1
        || ent->m_flags < 0
        || ent->m_flags > std::numeric_limits<std::uint16_t>::max()
        || !std::isfinite(ent->m_horizontalCellMargin)
        || ent->m_horizontalCellMargin < 0.0
        || !std::isfinite(ent->m_verticalCellMargin)
        || ent->m_verticalCellMargin < 0.0
        || ent->m_rowStyles.size() != 3u || !ent->m_cellStyles.empty()
        || ent->m_tableCellStyle.m_hasData || ent->m_unknownHandle != 0u)
        return reject("TABLESTYLE is outside the bounded typed profile");

    const DRW_TableStyleCellStyle& cellStyle = ent->m_tableCellStyle;
    const DRW_TableStyleContentFormat& contentFormat =
        cellStyle.m_contentFormat;
    if (cellStyle.m_type != 0 || cellStyle.m_propertyOverrideFlags != 0u
        || cellStyle.m_mergeFlags != 0u || cellStyle.m_backgroundColor != 0
        || cellStyle.m_contentLayout != 0u
        || contentFormat.m_propertyOverrideFlags != 0u
        || contentFormat.m_propertyFlags != 0u
        || contentFormat.m_valueDataType != 0
        || contentFormat.m_valueUnitType != 0
        || !contentFormat.m_valueFormatString.empty()
        || contentFormat.m_rotation != 0.0
        || contentFormat.m_blockScale != 1.0
        || contentFormat.m_cellAlignment != 0
        || contentFormat.m_contentColor != 0
        || !contentFormatColorIsDxfRepresentable(contentFormat)
        || contentFormat.m_textStyleHandle != 0u
        || contentFormat.m_textHeight != 0.0
        || cellStyle.m_marginOverrideFlags != 0
        || cellStyle.m_verticalMargin != 0.0
        || cellStyle.m_horizontalMargin != 0.0
        || cellStyle.m_bottomMargin != 0.0
        || cellStyle.m_rightMargin != 0.0
        || cellStyle.m_marginHorizontalSpacing != 0.0
        || cellStyle.m_marginVerticalSpacing != 0.0
        || cellStyle.m_id != 0 || cellStyle.m_styleClass != 0
        || !cellStyle.m_name.empty() || !cellStyle.m_borders.empty())
        return reject("TABLESTYLE contains an unmodeled custom cell style");

    std::vector<std::string> textStyleNames;
    try {
        textStyleNames.reserve(ent->m_rowStyles.size());
        for (const DRW_TableStyleRowStyle& row : ent->m_rowStyles) {
            if (!std::isfinite(row.m_textHeight) || row.m_textHeight < 0.0
                || row.m_textAlignment < 0
                || row.m_textAlignment
                    > std::numeric_limits<std::uint16_t>::max()
                || row.m_textColor < 0 || row.m_textColor > 255
                || row.m_fillColor < 0 || row.m_fillColor > 255
                || !scalarColorIsDxfRepresentable(
                    row.m_textColor, row.m_textColorCmc)
                || !scalarColorIsDxfRepresentable(
                    row.m_fillColor, row.m_fillColorCmc)
                || !validValueDataType(row.m_valueDataType)
                || !validValueUnitType(row.m_valueUnitType)
                || !row.m_valueFormatString.empty()
                || row.m_borders.size() != 6u)
                return reject("TABLESTYLE row has unsupported or ambiguous fields");

            if (row.m_textStyleHandle == 0u
                || row.m_textStyleHandle == DRW::NoHandle)
                return reject("TABLESTYLE row has no resolved text style");
            std::size_t sourceTextStyleMatches = 0;
            std::string textStyleName;
            for (const DRW_Textstyle& textStyle : textStyles) {
                if (textStyle.handle != row.m_textStyleHandle)
                    continue;
                textStyleName = textStyle.name;
                ++sourceTextStyleMatches;
            }
            const std::string textStyleKey = dxfSymbolNameKey(textStyleName);
            const std::size_t emittedTextStyleMatches = textStyleKey.empty()
                ? 0u : textStyleMap.count(textStyleKey);
            if (sourceTextStyleMatches != 1u
                || emittedTextStyleMatches != 1u || textStyleName.empty()
                || !isSafeDxfRecordText(textStyleName))
                return reject("TABLESTYLE row text style is not uniquely emitted");
            textStyleNames.push_back(std::move(textStyleName));

            for (std::size_t index = 0; index < row.m_borders.size(); ++index) {
                const DRW_TableStyleBorder& border = row.m_borders[index];
                if (border.m_edgeFlags != (1 << index)
                    || border.m_propertyOverrideFlags != 0
                    || border.m_borderType != 0
                    || border.m_lineWeight
                        < std::numeric_limits<std::int16_t>::min()
                    || border.m_lineWeight
                        > std::numeric_limits<std::int16_t>::max()
                    || border.m_color < 0 || border.m_color > 255
                    || !scalarColorIsDxfRepresentable(
                        border.m_color, border.m_colorCmc)
                    || border.m_visible < 0 || border.m_visible > 1
                    || !std::isfinite(border.m_doubleLineSpacing)
                    || border.m_doubleLineSpacing != 0.0)
                    return reject("TABLESTYLE border properties are not losslessly representable");
            }
        }
    } catch (...) {
        return reject("TABLESTYLE profile validation allocation failed");
    }

    const std::uint32_t handle = remapObjectHandle(ent->handle);
    if (handle == 0 || isDxfFixedOutputHandle(handle) || !reserveHandle(handle))
        return reject("TABLESTYLE identity is not uniquely writable");

    RecordStateScope state(*this, ent);
    DxfWriterRecordScope record(*writer);
    bool written = writer->writeString(0, "TABLESTYLE")
        && writer->writeString(5, toHexStr(handle))
        && writeTableEntryAppData(*ent);
    if (!written)
        return failDxfWrite();
    writeObjectOwner(static_cast<std::uint32_t>(ent->parentHandle));
    written = writer->writeString(100, "AcDbTableStyle")
        && writer->writeInt16(280, 0)
        && writer->writeUtf8String(3, ent->m_name)
        && writer->writeInt16(70, ent->m_flowDirection)
        && writer->writeInt16(71, ent->m_flags)
        && writer->writeDouble(40, ent->m_horizontalCellMargin)
        && writer->writeDouble(41, ent->m_verticalCellMargin)
        && writer->writeInt16(280, ent->m_titleSuppressed ? 1 : 0)
        && writer->writeInt16(281, ent->m_headerSuppressed ? 1 : 0);

    for (std::size_t index = 0; written && index < ent->m_rowStyles.size(); ++index) {
        const DRW_TableStyleRowStyle& row = ent->m_rowStyles[index];
        written = writer->writeUtf8String(7, textStyleNames[index])
            && writer->writeDouble(140, row.m_textHeight)
            && writer->writeInt16(170, row.m_textAlignment)
            && writer->writeInt16(62, row.m_textColor)
            && writer->writeInt16(63, row.m_fillColor)
            && writer->writeInt16(283, row.m_hasBackgroundColor ? 1 : 0);
        for (int border = 0; written && border < 6; ++border)
            written = writer->writeInt16(
                274 + border,
                row.m_borders[static_cast<std::size_t>(border)].m_lineWeight);
        for (int border = 0; written && border < 6; ++border)
            written = writer->writeInt16(
                284 + border,
                row.m_borders[static_cast<std::size_t>(border)].m_visible);
        for (int border = 0; written && border < 6; ++border)
            written = writer->writeInt16(
                64 + border,
                row.m_borders[static_cast<std::size_t>(border)].m_color);
        written = written
            && writer->writeInt32(90, row.m_valueDataType)
            && writer->writeInt32(91, row.m_valueUnitType);
    }
    if (!written || (!ent->extData.empty() && !writeExtData(ent->extData))
        || writer->hasWriteError() || !preflightDxfWrite() || !record.commit())
        return failDxfWrite();
    state.commit();
    return true;
}

bool dxfRW::writeCellStyleMap(DRW_CellStyleMap *ent) {
    const auto reject = [this](const char *message) {
        recordOperationDiagnostic(
            DRW::OperationPhase::Validation,
            DRW::OperationCause::ValidationFailure,
            "cellstylemap-unsupported-profile", message);
        return failDxfWrite();
    };
    const auto safeText = [](const std::string& value) {
        return value.size() <= 1024u * 1024u
            && isSafeDxfRecordText(value);
    };
    const auto validColor = [&safeText](
            int index, const DRW_TableStyleCmcColor& cmc) {
        if (index < 0 || index > 256 || cmc.m_rgb < -1
            || cmc.m_rgb > 0xFFFFFF || cmc.m_flags != 0u
            || cmc.m_reservedIndex != 0u || !safeText(cmc.m_name)
            || !safeText(cmc.m_bookName))
            return false;
        switch (cmc.m_method) {
        case 0:
            return true;
        case 0xC1:
            return cmc.m_rgb < 0 && cmc.m_name.empty()
                && cmc.m_bookName.empty() && index == 0;
        case 0xC2:
            return cmc.m_rgb >= 0;
        case 0xC3:
            return cmc.m_rgb < 0 && cmc.m_name.empty()
                && cmc.m_bookName.empty() && index > 0 && index < 256;
        default:
            return false;
        }
    };
    const auto colorIsDefault = [](
            const DRW_TableStyleCmcColor& color) {
        return color.m_rgb == -1 && color.m_name.empty()
            && color.m_bookName.empty() && color.m_method == 0u
            && color.m_flags == 0u && color.m_reservedIndex == 0u;
    };
    const auto validDataType = [](int value) {
        switch (value) {
        case 0: case 1: case 2: case 4: case 8: case 16:
        case 32: case 64: case 128: case 256: case 512:
            return true;
        default:
            return false;
        }
    };
    const auto validUnitType = [](int value) {
        return value == 0 || value == 1 || value == 2 || value == 4
            || value == 8 || value == 0x10 || value == 0x20
            || value == 0x10000;
    };
    const auto resolve = [this](std::uint32_t source,
                                std::uint32_t& emitted) {
        // NoHandle is represented by zero in this API. Optional text-style
        // and linetype references therefore serialize as a null handle.
        emitted = source == 0 ? 0
            : m_referenceResolver ? resolveReference(source)
                                  : remapObjectHandle(source);
        return source == 0 || emitted != 0;
    };
    const auto validContent = [&safeText, &validColor, &validDataType,
                               &validUnitType](
            const DRW_TableStyleContentFormat& format) {
        return (format.m_propertyOverrideFlags & ~std::uint32_t{0x7FFFFu})
                == 0u
            && (format.m_propertyFlags & ~std::uint32_t{0x100u}) == 0u
            && validDataType(format.m_valueDataType)
            && validUnitType(format.m_valueUnitType)
            && safeText(format.m_valueFormatString)
            && std::isfinite(format.m_rotation)
            && std::isfinite(format.m_blockScale)
            && format.m_cellAlignment >= 1 && format.m_cellAlignment <= 9
            && validColor(format.m_contentColor,
                          format.m_contentColorCmc)
            && format.m_textStyleHandle != DRW::NoHandle
            && std::isfinite(format.m_textHeight);
    };
    const auto invalidStyleReason = [
            &colorIsDefault, &validColor, &validContent](
            const DRW_TableStyleCellStyle& style) -> const char* {
        if (style.m_type < 1 || style.m_type > 5)
            return "CELLSTYLEMAP cell-style type is outside 1-5";
        if (!style.m_hasData) {
            const DRW_TableStyleContentFormat& format = style.m_contentFormat;
            const bool noDataIsDefault = style.m_propertyOverrideFlags == 0u
                && style.m_mergeFlags == 0u
                && style.m_backgroundColor == 0
                && colorIsDefault(style.m_backgroundColorCmc)
                && style.m_contentLayout == 0u
                && format.m_propertyOverrideFlags == 0u
                && format.m_propertyFlags == 0u
                && format.m_valueDataType == 0
                && format.m_valueUnitType == 0
                && format.m_valueFormatString.empty()
                && format.m_rotation == 0.0
                && format.m_blockScale == 1.0
                && format.m_cellAlignment == 0
                && format.m_contentColor == 0
                && colorIsDefault(format.m_contentColorCmc)
                && format.m_textStyleHandle == 0u
                && format.m_textHeight == 0.0
                && style.m_marginOverrideFlags == 0
                && style.m_verticalMargin == 0.0
                && style.m_horizontalMargin == 0.0
                && style.m_bottomMargin == 0.0
                && style.m_rightMargin == 0.0
                && style.m_marginHorizontalSpacing == 0.0
                && style.m_marginVerticalSpacing == 0.0
                && style.m_borders.empty();
            return noDataIsDefault ? nullptr
                : "CELLSTYLEMAP absent cell-style data has non-default payload";
        }
        if ((style.m_propertyOverrideFlags & ~std::uint32_t{0x7FFFFu})
                != 0u
            || (style.m_mergeFlags & ~std::uint32_t{0x18000u}) != 0u
            || (style.m_contentLayout & ~std::uint32_t{0x7u}) != 0u
            || !validColor(style.m_backgroundColor,
                           style.m_backgroundColorCmc)
            )
            return "CELLSTYLEMAP cell-style flags or background color invalid";
        if (!validContent(style.m_contentFormat))
            return "CELLSTYLEMAP content-format fields are invalid";
        if (style.m_marginOverrideFlags < 0
            || (style.m_marginOverrideFlags & ~0x1) != 0
            || style.m_borders.size() > 6u)
            return "CELLSTYLEMAP margin flags or border count invalid";
        if (style.m_marginOverrideFlags == 0
            && (style.m_verticalMargin != 0.0
                || style.m_horizontalMargin != 0.0
                || style.m_bottomMargin != 0.0
                || style.m_rightMargin != 0.0
                || style.m_marginHorizontalSpacing != 0.0
                || style.m_marginVerticalSpacing != 0.0))
            return "CELLSTYLEMAP unflagged margins contain data";
        const auto finite = [](double value) { return std::isfinite(value); };
        if (!finite(style.m_verticalMargin)
            || !finite(style.m_horizontalMargin)
            || !finite(style.m_bottomMargin) || !finite(style.m_rightMargin)
            || !finite(style.m_marginHorizontalSpacing)
            || !finite(style.m_marginVerticalSpacing))
            return "CELLSTYLEMAP margin contains a non-finite value";
        for (const DRW_TableStyleBorder& border : style.m_borders) {
            if (border.m_edgeFlags < 0 || border.m_edgeFlags > 0x3F
                || (border.m_propertyOverrideFlags & ~0x3F) != 0)
                return "CELLSTYLEMAP border flags are invalid";
            if ((border.m_propertyOverrideFlags & 0x1) != 0
                    ? border.m_borderType < 1 || border.m_borderType > 2
                    : border.m_borderType < 0 || border.m_borderType > 2)
                return "CELLSTYLEMAP border type is invalid";
            if (!validColor(border.m_color, border.m_colorCmc))
                return "CELLSTYLEMAP border color is invalid";
            if (border.m_visible < 0 || border.m_visible > 1
                || !finite(border.m_doubleLineSpacing))
                return "CELLSTYLEMAP border visibility or spacing is invalid";
            if (border.m_edgeFlags == 0
                && (border.m_propertyOverrideFlags != 0
                    || border.m_borderType != 0 || border.m_color != 0
                    || !colorIsDefault(border.m_colorCmc)
                    || border.m_lineWeight != 0
                    || border.m_lineTypeHandle != 0
                    || border.m_visible != 0
                    || border.m_doubleLineSpacing != 0.0))
                return "CELLSTYLEMAP empty border contains payload";
        }
        return nullptr;
    };

    if (!preflightDxfWrite() || ent == nullptr || version < DRW::AC1021
        || ent->handle == 0 || ent->handle == DRW::NoHandle
        || ent->parentHandle == 0 || ent->parentHandle == DRW::NoHandle
        || ent->m_cellStyles.size() > 100000u
        || ent->m_cellStyles.size()
            > static_cast<std::size_t>(std::numeric_limits<std::int32_t>::max()))
        return reject("CELLSTYLEMAP identity or count is not writable");

    std::unordered_set<int> styleIds;
    try {
        styleIds.reserve(ent->m_cellStyles.size());
    } catch (...) {
        return reject("CELLSTYLEMAP identity validation allocation failed");
    }
    for (const DRW_TableStyleCellStyle& style : ent->m_cellStyles) {
        if (const char* reason = invalidStyleReason(style))
            return reject(reason);
        if (style.m_id < 1 || (style.m_id == 4 && version < DRW::AC1024)
            || (style.m_id > 4 && style.m_id < 101)
            || style.m_styleClass < 0 || style.m_styleClass > 2
            || !safeText(style.m_name)
            || !styleIds.insert(style.m_id).second)
            return reject("CELLSTYLEMAP contains an unsupported cell style");
        std::uint32_t ignored = 0;
        if (!resolve(style.m_contentFormat.m_textStyleHandle, ignored))
            return reject("CELLSTYLEMAP content style handle is unresolved");
        for (const DRW_TableStyleBorder& border : style.m_borders) {
            if (!resolve(border.m_lineTypeHandle, ignored))
                return reject("CELLSTYLEMAP border linetype handle is unresolved");
        }
    }

    const std::uint32_t handle = remapObjectHandle(ent->handle);
    if (handle == 0 || isDxfFixedOutputHandle(handle) || !reserveHandle(handle))
        return reject("CELLSTYLEMAP identity is not uniquely writable");

    RecordStateScope state(*this, ent);
    DxfWriterRecordScope record(*writer);
    bool written = writer->writeString(0, "CELLSTYLEMAP")
        && writer->writeString(5, toHexStr(handle))
        && writeTableEntryAppData(*ent);
    if (!written)
        return failDxfWrite();
    writeObjectOwner(static_cast<std::uint32_t>(ent->parentHandle));
    written = writer->writeString(100, "AcDbCellStyleMap")
        && writer->writeInt32(90,
            static_cast<std::int32_t>(ent->m_cellStyles.size()));

    const auto writeColor = [this](int index,
            const DRW_TableStyleCmcColor& cmc) {
        if (!writer->writeInt16(62, static_cast<std::int16_t>(index)))
            return false;
        return (cmc.m_rgb < 0 || writer->writeInt32(420, cmc.m_rgb))
            && (cmc.m_name.empty()
                || writer->writeUtf8String(430, cmc.m_name))
            && (cmc.m_bookName.empty()
                || writer->writeUtf8String(431, cmc.m_bookName));
    };
    const auto writeContent = [this, &writeColor, &resolve](
            const DRW_TableStyleContentFormat& format) {
        std::uint32_t textStyleHandle = 0;
        if (!resolve(format.m_textStyleHandle, textStyleHandle))
            return false;
        return writer->writeString(300, "CONTENTFORMAT")
            && writer->writeString(1, "CONTENTFORMAT_BEGIN")
            && writer->writeInt32(90,
                static_cast<std::int32_t>(format.m_propertyOverrideFlags))
            && writer->writeInt32(91,
                static_cast<std::int32_t>(format.m_propertyFlags))
            && writer->writeInt32(92, format.m_valueDataType)
            && writer->writeInt32(93, format.m_valueUnitType)
            && writer->writeUtf8String(300, format.m_valueFormatString)
            && writer->writeDouble(40, format.m_rotation)
            && writer->writeDouble(140, format.m_blockScale)
            && writer->writeInt32(94, format.m_cellAlignment)
            && writeColor(format.m_contentColor,
                          format.m_contentColorCmc)
            && writer->writeString(340, toHexStr(textStyleHandle))
            && writer->writeDouble(144, format.m_textHeight)
            && writer->writeString(309, "CONTENTFORMAT_END");
    };

    for (const DRW_TableStyleCellStyle& style : ent->m_cellStyles) {
        written = written && writer->writeUtf8String(300, "CELLSTYLE")
            && writer->writeString(1, "TABLEFORMAT_BEGIN")
            && writer->writeInt32(90, style.m_type)
            && writer->writeInt16(170, style.m_hasData ? 1 : 0);
        if (style.m_hasData) {
            written = written
                && writer->writeInt32(91,
                    static_cast<std::int32_t>(style.m_propertyOverrideFlags))
                && writer->writeInt32(92,
                    static_cast<std::int32_t>(style.m_mergeFlags))
                && writeColor(style.m_backgroundColor,
                              style.m_backgroundColorCmc)
                && writer->writeInt32(93,
                    static_cast<std::int32_t>(style.m_contentLayout))
                && writeContent(style.m_contentFormat)
                && writer->writeInt16(171,
                    static_cast<std::int16_t>(style.m_marginOverrideFlags));
            if (style.m_marginOverrideFlags != 0) {
                written = written && writer->writeString(301, "MARGIN")
                    && writer->writeString(1, "CELLMARGIN_BEGIN")
                    && writer->writeDouble(40, style.m_verticalMargin)
                    && writer->writeDouble(40, style.m_horizontalMargin)
                    && writer->writeDouble(40, style.m_bottomMargin)
                    && writer->writeDouble(40, style.m_rightMargin)
                    && writer->writeDouble(40,
                        style.m_marginHorizontalSpacing)
                    && writer->writeDouble(40,
                        style.m_marginVerticalSpacing)
                    && writer->writeString(309, "CELLMARGIN_END");
            }
            written = written && writer->writeInt32(94,
                static_cast<std::int32_t>(style.m_borders.size()));
            for (const DRW_TableStyleBorder& border : style.m_borders) {
                if (border.m_edgeFlags == 0) {
                    written = written && writer->writeInt32(95, 0)
                        && writer->writeString(309, "GRIDFORMAT_END");
                    continue;
                }
                std::uint32_t lineTypeHandle = 0;
                if (!resolve(border.m_lineTypeHandle, lineTypeHandle)) {
                    written = false;
                    break;
                }
                written = written && writer->writeInt32(95, border.m_edgeFlags)
                    && writer->writeString(302, "GRIDFORMAT")
                    && writer->writeString(1, "GRIDFORMAT_BEGIN")
                    && writer->writeInt32(90,
                        border.m_propertyOverrideFlags)
                    && writer->writeInt32(91, border.m_borderType)
                    && writeColor(border.m_color, border.m_colorCmc)
                    && writer->writeInt32(92, border.m_lineWeight)
                    && writer->writeString(340, toHexStr(lineTypeHandle))
                    && writer->writeInt32(93, border.m_visible)
                    && writer->writeDouble(40,
                        border.m_doubleLineSpacing)
                    && writer->writeString(309, "GRIDFORMAT_END");
            }
        }
        written = written && writer->writeString(309, "TABLEFORMAT_END")
            && writer->writeString(1, "CELLSTYLE_BEGIN")
            && writer->writeInt32(90, style.m_id)
            && writer->writeInt32(91, style.m_styleClass)
            && writer->writeUtf8String(300, style.m_name)
            && writer->writeString(309, "CELLSTYLE_END");
        if (!written)
            return failDxfWrite();
    }
    if ((!ent->extData.empty() && !writeExtData(ent->extData))
        || writer->hasWriteError() || !preflightDxfWrite() || !record.commit())
        return failDxfWrite();
    state.commit();
    return true;
}

/**
 * The background-fill groups of an MTEXT, for both writers that emit them.
 *
 * Group 90 says which background mode is in use; 45 and 63 describe a colour
 * fill and belong only to the mode that has one. Writing them for every
 * non-zero flag turns "absent" into "present and zero": a text-frame-only
 * MTEXT (flag 16) came out carrying a zero box scale, where the convention is
 * that the tag is absent and the scale is 1.5.
 *
 * R2007 is the floor for all of them. 421, 431 and 441 are optional and go out
 * only when set, so an MTEXT that asks for none of this keeps its byte stream.
 */
bool dxfRW::writeMTextBackground(DRW_MText *ent) {
    if (ent == nullptr || version < DRW::AC1021 || ent->m_backgroundFlags == 0)
        return true;

    const bool hasColourFill = (ent->m_backgroundFlags & 0x01) != 0;
    if (hasColourFill)
        writer->writeDouble(45, ent->m_backgroundScale);
    writer->writeInt32(90, ent->m_backgroundFlags);
    if (hasColourFill) {
        // 63 is required even when the colour is given as a true colour or by
        // name, so within this mode it goes out unconditionally.
        writer->writeInt16(63, ent->m_backgroundColor);
        if (ent->m_backgroundColorTrue >= 0)
            writer->writeInt32(421, ent->m_backgroundColorTrue);
        if (!ent->m_backgroundColorName.empty())
            writer->writeUtf8String(431, ent->m_backgroundColorName);
    }
    if (ent->m_backgroundTransparency != 0)
        writer->writeInt32(441, ent->m_backgroundTransparency);
    return !writer->hasWriteError();
}

bool dxfRW::writeEmbeddedMText(DRW_MText *ent) {
    if (ent == nullptr)
        return false;
    // ATTRIB/ATTDEF and GEOLOCATIONMARKER use an ordinary embedded-MTEXT
    // body, not the standalone R2018 MTEXT column-object schema.
    if (hasR2018MTextColumns(*ent))
        return rejectUnsupportedDxfWrite("embedded MTEXT columns");

    // ODA's canonical R2018 attribute grammar uses the embedded-object marker
    // (101), not a subclass marker (100). The reader still accepts legacy 100.
    writer->writeString(101, "Embedded Object");
    writer->writeDouble(10, ent->basePoint.x);
    writer->writeDouble(20, ent->basePoint.y);
    writer->writeDouble(30, ent->basePoint.z);
    writer->writeDouble(40, ent->height);
    writer->writeDouble(41, ent->widthscale);
    // Main MTEXT group 46 is separate from the R2018 context's group 41.
    // The presence bit keeps a source-supplied zero distinct from absence;
    // nonzero direct assignments remain compatible with existing callers.
    if (ent->m_definedHeightPresent || ent->m_definedHeight != 0.0)
        writer->writeDouble(46, ent->m_definedHeight);
    writer->writeInt16(71, ent->textgen);
    writer->writeInt16(72, ent->alignH);
    if (!writer->writeUtf8MTextChunks(ent->text, 3, 1, 250u, 250u))
        return false;
    if (!ent->style.empty())
        writer->writeUtf8String(7, ent->style);
    if (ent->extPoint.x != 0.0 || ent->extPoint.y != 0.0
        || ent->extPoint.z != 1.0) {
        writer->writeDouble(210, ent->extPoint.x);
        writer->writeDouble(220, ent->extPoint.y);
        writer->writeDouble(230, ent->extPoint.z);
    }
    const auto orientation = ent->dxfOrientationForOutput();
    const bool legacyOrientation = orientation == DRW_MText::DxfOrientationMode::LegacyApi;
    if (orientation == DRW_MText::DxfOrientationMode::Direction
        || (legacyOrientation && (ent->secPoint.x != 0.0 || ent->secPoint.y != 0.0
                                   || ent->secPoint.z != 0.0))) {
        writer->writeDouble(11, ent->secPoint.x);
        writer->writeDouble(21, ent->secPoint.y);
        writer->writeDouble(31, ent->secPoint.z);
    }
    if (ent->m_r2018ExtentsWidth != 0.0)
        writer->writeDouble(42, ent->m_r2018ExtentsWidth);
    if (ent->m_r2018ExtentsHeight != 0.0)
        writer->writeDouble(43, ent->m_r2018ExtentsHeight);
    if (orientation == DRW_MText::DxfOrientationMode::Rotation
        || (legacyOrientation && ent->angle != 0.0))
        writer->writeDouble(50, ent->angle);
    writer->writeInt16(73, ent->linespacingStyle);
    writer->writeDouble(44, ent->interlin);
    if (!writeMTextBackground(ent))
        return false;
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeAttributeR2018Features(DRW_Attrib *ent) {
    if (ent == nullptr || !ent->mtext)
        return true;
    // ATTRIB/ATTDEF carry their multiline body in the R2018 embedded-object
    // profile. Earlier DXF versions would otherwise emit only the fallback
    // single-line value and silently discard the attached MTEXT semantics.
    if (version < DRW::AC1032)
        return rejectUnsupportedDxfWrite("multiline attribute");
    // DXF does not provide a qualified boundary here that distinguishes XDATA
    // owned by the embedded MTEXT from trailing XDATA owned by ATTRIB/ATTDEF.
    // Do not merge the nested payload into the host or silently lose its scope.
    if (!ent->mtext->extData.empty())
        return rejectDxfWriteWithReason(
            "embedded MTEXT XDATA", "scope not qualified");
    std::uint8_t attributeType = ent->m_attributeType;
    if (attributeType == 1)
        attributeType = ent->eType == DRW::ATTDEF ? 4 : 2;
    writer->writeInt16(71, attributeType);
    writer->writeInt16(72, 0); // R2018 keep-duplicate-records placeholder.
    writer->writeDouble(11, ent->mtext->basePoint.x);
    writer->writeDouble(21, ent->mtext->basePoint.y);
    writer->writeDouble(31, ent->mtext->basePoint.z);
    return writeEmbeddedMText(ent->mtext.get());
}

bool dxfRW::writeAttrib(DRW_Attrib *ent,
                        std::uint32_t ownerOverride){
    if (!preflightEntity(ent)
        || !isSafeDxfRecordText(ent->tag)
        || !ent->m_r2018OuterAnnotativeData.empty()
        || ent->m_r2018OuterAnnotativeUnknown != 0
        || ent->m_r2018OuterAnnotativeAppHandle != 0
        || !ent->m_r2018OuterAnnotativeAppIdName.empty()
        || ent->m_fieldLength < std::numeric_limits<std::int16_t>::min()
        || ent->m_fieldLength > std::numeric_limits<std::uint16_t>::max()
        || (ent->mtext != nullptr
            && (!isValidDxfEntityFields(*ent->mtext)
                || !isSafeDxfMTextContent(ent->mtext->text))))
    {
        m_writeError = true;
        return false;
    }
    if (ent->eType == DRW::ATTDEF) {
        if (auto *attdef = dynamic_cast<DRW_Attdef *>(ent))
            return writeAttdef(attdef, ownerOverride);
    }

    EntityRecordScope scope(*this, ent);
    writer->writeString(0, "ATTRIB");
    if (!writeEntity(ent, true, ownerOverride))
        return false;
    if (version > DRW::AC1009)
        writer->writeString(100, "AcDbText");
    if (ent->thickness != 0)  // reader + DWG encoder preserve thickness(39)
        writer->writeDouble(39, ent->thickness);
    writer->writeDouble(10, ent->basePoint.x);
    writer->writeDouble(20, ent->basePoint.y);
    writer->writeDouble(30, ent->basePoint.z);
    writer->writeDouble(40, ent->height);
    writer->writeUtf8String(1, ent->text);
    writer->writeDouble(50, ent->angle);
    writer->writeDouble(41, ent->widthscale);
    writer->writeDouble(51, ent->oblique);
    if (version > DRW::AC1009)
        writer->writeUtf8String(7, ent->style);
    else
        writer->writeUtf8Caps(7, ent->style);
    writer->writeInt16(71, ent->textgen);
    if (ent->alignH != DRW_Text::HLeft)
        writer->writeInt16(72, ent->alignH);
    if (ent->alignH != DRW_Text::HLeft || ent->alignV != DRW_Text::VBaseLine) {
        writer->writeDouble(11, ent->secPoint.x);
        writer->writeDouble(21, ent->secPoint.y);
        writer->writeDouble(31, ent->secPoint.z);
    }
    writer->writeDouble(210, ent->extPoint.x);
    writer->writeDouble(220, ent->extPoint.y);
    writer->writeDouble(230, ent->extPoint.z);
    if (version > DRW::AC1009)
        writer->writeString(100, "AcDbAttribute");
    writer->writeUtf8String(2, ent->tag);
    writer->writeInt16(70, ent->attribFlags);
    writer->writeInt16(73, ent->m_fieldLength);
    if (ent->alignV != DRW_Text::VBaseLine)
        writer->writeInt16(74, ent->alignV);
    if (version > DRW::AC1014)
        writer->writeInt16(280, ent->lockPosition ? 1 : 0);
    if (!writeAttributeR2018Features(ent))
        return false;
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeAttdef(DRW_Attdef *ent,
                        std::uint32_t ownerOverride){
    if (!preflightEntity(ent)
        || !isSafeDxfRecordText(ent->tag)
        || !isSafeDxfRecordText(ent->prompt)
        || !ent->m_r2018OuterAnnotativeData.empty()
        || ent->m_r2018OuterAnnotativeUnknown != 0
        || ent->m_r2018OuterAnnotativeAppHandle != 0
        || !ent->m_r2018OuterAnnotativeAppIdName.empty()
        || ent->m_fieldLength < std::numeric_limits<std::int16_t>::min()
        || ent->m_fieldLength > std::numeric_limits<std::uint16_t>::max()
        || (ent->mtext != nullptr
            && (!isValidDxfEntityFields(*ent->mtext)
                || !isSafeDxfMTextContent(ent->mtext->text))))
    {
        m_writeError = true;
        return false;
    }
    EntityRecordScope scope(*this, ent);
    writer->writeString(0, "ATTDEF");
    if (!writeEntity(ent, true, ownerOverride))
        return false;
    if (version > DRW::AC1009)
        writer->writeString(100, "AcDbText");
    if (ent->thickness != 0)
        writer->writeDouble(39, ent->thickness);
    writer->writeDouble(10, ent->basePoint.x);
    writer->writeDouble(20, ent->basePoint.y);
    writer->writeDouble(30, ent->basePoint.z);
    writer->writeDouble(40, ent->height);
    writer->writeUtf8String(1, ent->text);
    writer->writeDouble(50, ent->angle);
    writer->writeDouble(41, ent->widthscale);
    writer->writeDouble(51, ent->oblique);
    if (version > DRW::AC1009)
        writer->writeUtf8String(7, ent->style);
    else
        writer->writeUtf8Caps(7, ent->style);
    writer->writeInt16(71, ent->textgen);
    if (ent->alignH != DRW_Text::HLeft)
        writer->writeInt16(72, ent->alignH);
    if (ent->alignH != DRW_Text::HLeft || ent->alignV != DRW_Text::VBaseLine) {
        writer->writeDouble(11, ent->secPoint.x);
        writer->writeDouble(21, ent->secPoint.y);
        writer->writeDouble(31, ent->secPoint.z);
    }
    writer->writeDouble(210, ent->extPoint.x);
    writer->writeDouble(220, ent->extPoint.y);
    writer->writeDouble(230, ent->extPoint.z);
    if (version > DRW::AC1009)
        writer->writeString(100, "AcDbAttributeDefinition");
    writer->writeUtf8String(2, ent->tag);
    writer->writeUtf8String(3, ent->prompt);
    writer->writeInt16(70, ent->attribFlags);
    writer->writeInt16(73, ent->m_fieldLength);
    if (ent->alignV != DRW_Text::VBaseLine)
        writer->writeInt16(74, ent->alignV);
    if (version > DRW::AC1014)
        writer->writeInt16(280, ent->lockPosition ? 1 : 0);
    if (!writeAttributeR2018Features(ent))
        return false;
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeText(DRW_Text *ent) {
    if (!preflightEntity(ent))
        return false;
    EntityRecordScope scope(*this, ent);
    writer->writeString(0, "TEXT");
    if (!writeEntity(ent))
        return false;
    if (version > DRW::AC1009) {
        writer->writeString(100, "AcDbText");
    }
    if (ent->thickness != 0)  // reader + DWG encoder preserve thickness(39)
        writer->writeDouble(39, ent->thickness);
    writer->writeDouble(10, ent->basePoint.x);
    writer->writeDouble(20, ent->basePoint.y);
    writer->writeDouble(30, ent->basePoint.z);
    writer->writeDouble(40, ent->height);
    writer->writeUtf8String(1, ent->text);
    writer->writeDouble(50, ent->angle);
    writer->writeDouble(41, ent->widthscale);
    writer->writeDouble(51, ent->oblique);
    if (version > DRW::AC1009)
        writer->writeUtf8String(7, ent->style);
    else
        writer->writeUtf8Caps(7, ent->style);
    writer->writeInt16(71, ent->textgen);
    if (ent->alignH != DRW_Text::HLeft) {
        writer->writeInt16(72, ent->alignH);
    }
    if (ent->alignH != DRW_Text::HLeft || ent->alignV != DRW_Text::VBaseLine) {
        writer->writeDouble(11, ent->secPoint.x);
        writer->writeDouble(21, ent->secPoint.y);
        writer->writeDouble(31, ent->secPoint.z);
    }
    writer->writeDouble(210, ent->extPoint.x);
    writer->writeDouble(220, ent->extPoint.y);
    writer->writeDouble(230, ent->extPoint.z);
    if (version > DRW::AC1009) {
        writer->writeString(100, "AcDbText");
    }
    if (ent->alignV != DRW_Text::VBaseLine) {
        writer->writeInt16(73, ent->alignV);
    }
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

static double arcAlignedDxfValue(const UTF8STRING& value, double fallback) {
    if (value.empty())
        return fallback;
    double parsed = 0.0;
    return DxfNumeric::parsePrefix(value, parsed) ? parsed : fallback;
}

bool dxfRW::writeRText(DRW_RText *ent) {
    if (version <= DRW::AC1009)
        return rejectUnsupportedDxfWrite("RTEXT");
    if (!preflightEntity(ent))
        return false;
    EntityRecordScope scope(*this, ent);
    writer->writeString(0, "RTEXT");
    if (!writeEntity(ent))
        return false;
    writer->writeString(100, "RText");
    writer->writeUtf8String(7, ent->style.empty() ? "Standard" : ent->style);
    writer->writeDouble(10, ent->basePoint.x);
    writer->writeDouble(20, ent->basePoint.y);
    writer->writeDouble(30, ent->basePoint.z);
    writer->writeDouble(40, ent->height);
    writer->writeDouble(50, ent->angle);
    writer->writeInt16(70, ent->m_rTextFlags);
    writer->writeUtf8String(1, ent->text);
    writer->writeDouble(210, ent->extPoint.x);
    writer->writeDouble(220, ent->extPoint.y);
    writer->writeDouble(230, ent->extPoint.z);
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeArcAlignedText(DRW_ArcAlignedText *ent) {
    if (version <= DRW::AC1009)
        return rejectUnsupportedDxfWrite("ARCALIGNEDTEXT");
    if (!preflightEntity(ent))
        return false;
    EntityRecordScope scope(*this, ent);
    writer->writeString(0, "ARCALIGNEDTEXT");
    if (!writeEntity(ent))
        return false;
    writer->writeString(100, "AcDbArcAlignedText");
    writer->writeUtf8String(1, ent->text);
    if (!ent->m_fontName.empty())
        writer->writeUtf8String(2, ent->m_fontName);
    if (!ent->m_bigFontName.empty())
        writer->writeUtf8String(3, ent->m_bigFontName);
    writer->writeUtf8String(7, ent->style.empty() ? "Standard" : ent->style);
    writer->writeDouble(10, ent->m_center.x);
    writer->writeDouble(20, ent->m_center.y);
    writer->writeDouble(30, ent->m_center.z);
    writer->writeDouble(40, ent->m_radius);
    writer->writeDouble(41, arcAlignedDxfValue(
        ent->m_xScale, ent->widthscale > 0.0 ? ent->widthscale : 1.0));
    writer->writeDouble(42, arcAlignedDxfValue(
        ent->m_textSize, ent->height > 0.0 ? ent->height : 0.0));
    writer->writeDouble(43, arcAlignedDxfValue(ent->m_charSpacing, 1.0));
    writer->writeDouble(44, arcAlignedDxfValue(ent->m_offsetFromArc, 0.0));
    writer->writeDouble(45, arcAlignedDxfValue(ent->m_rightOffset, 0.0));
    writer->writeDouble(46, arcAlignedDxfValue(ent->m_leftOffset, 0.0));
    writer->writeDouble(50, ent->m_startAngle * ARAD);
    writer->writeDouble(51, ent->m_endAngle * ARAD);
    writer->writeInt32(90, ent->m_rawColor);
    writer->writeInt16(77, ent->m_characterSet);
    writer->writeInt16(78, ent->m_pitchAndFamily);
    writer->writeInt16(79, ent->m_isShx);
    writer->writeInt16(74, ent->m_isBold);
    writer->writeInt16(75, ent->m_isItalic);
    writer->writeInt16(76, ent->m_isUnderlined);
    writer->writeInt16(72, ent->m_alignment);
    writer->writeInt16(70, ent->m_isReverse);
    writer->writeInt16(280, ent->m_wizardFlag);
    writer->writeInt16(73, ent->m_textPosition);
    writer->writeInt16(71, ent->m_textDirection);
    writer->writeDouble(210, ent->extPoint.x);
    writer->writeDouble(220, ent->extPoint.y);
    writer->writeDouble(230, ent->extPoint.z);
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeTolerance(DRW_Tolerance *ent){
    if (!preflightEntity(ent))
        return false;
    EntityRecordScope scope(*this, ent);
    writer->writeString(0, "TOLERANCE");
    if (!writeEntity(ent))
        return false;
    if (version > DRW::AC1009)
        writer->writeString(100, "AcDbFcf");
    writer->writeUtf8String(3, ent->dimStyleName);
    writer->writeDouble(10, ent->insertionPoint.x);
    writer->writeDouble(20, ent->insertionPoint.y);
    writer->writeDouble(30, ent->insertionPoint.z);
    writer->writeUtf8String(1, ent->text);
    writer->writeDouble(210, ent->extPoint.x);
    writer->writeDouble(220, ent->extPoint.y);
    writer->writeDouble(230, ent->extPoint.z);
    writer->writeDouble(11, ent->xAxisDirectionVector.x);
    writer->writeDouble(21, ent->xAxisDirectionVector.y);
    writer->writeDouble(31, ent->xAxisDirectionVector.z);
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeMLine(DRW_MLine *ent) {
    if (!preflightDxfWrite())
        return false;
    if (version <= DRW::AC1009) return rejectUnsupportedDxfWrite("MLINE");
    if (ent == nullptr || writer == nullptr || !ent->validatePayloadFields()) {
        m_writeError = true;
        return false;
    }
    const std::uint32_t emittedStyleHandle = ent->styleHandle == 0
        ? 0 : remapObjectHandle(ent->styleHandle);
    if (ent->styleHandle == DRW::NoHandle
        || emittedStyleHandle == DRW::NoHandle)
        return failDxfWrite();
    EntityRecordScope scope(*this, ent);
    writer->writeString(0, "MLINE");
    if (!writeEntity(ent))
        return false;
    writer->writeString(100, "AcDbMline");
    writer->writeUtf8String(2, ent->styleName);
    if (ent->styleHandle != 0) {
        writer->writeString(340, toHexStr(emittedStyleHandle));
    }
    writer->writeDouble(40, ent->scale);
    writer->writeInt16(70, ent->justification);
    writer->writeInt16(71, ent->openClosed);
    writer->writeInt16(72, static_cast<int>(ent->vertlist.size()));
    writer->writeInt16(73, static_cast<int>(ent->numLines));
    writer->writeDouble(10, ent->basePoint.x);
    writer->writeDouble(20, ent->basePoint.y);
    writer->writeDouble(30, ent->basePoint.z);
    if (ent->extPoint.x != 0.0 || ent->extPoint.y != 0.0 || ent->extPoint.z != 1.0) {
        writer->writeDouble(210, ent->extPoint.x);
        writer->writeDouble(220, ent->extPoint.y);
        writer->writeDouble(230, ent->extPoint.z);
    }
    for (const auto& v : ent->vertlist) {
        writer->writeDouble(11, v.position.x);
        writer->writeDouble(21, v.position.y);
        writer->writeDouble(31, v.position.z);
        writer->writeDouble(12, v.vertexDir.x);
        writer->writeDouble(22, v.vertexDir.y);
        writer->writeDouble(32, v.vertexDir.z);
        writer->writeDouble(13, v.miterDir.x);
        writer->writeDouble(23, v.miterDir.y);
        writer->writeDouble(33, v.miterDir.z);
        for (int li = 0; li < ent->numLines; ++li) {
            const auto& seg = (li < static_cast<int>(v.segParms.size()))
                                  ? v.segParms[li] : std::vector<double>{};
            const auto& fill = (li < static_cast<int>(v.areaFillParms.size()))
                                   ? v.areaFillParms[li] : std::vector<double>{};
            writer->writeInt16(74, static_cast<int>(seg.size()));
            for (double p : seg) writer->writeDouble(41, p);
            writer->writeInt16(75, static_cast<int>(fill.size()));
            for (double p : fill) writer->writeDouble(42, p);
        }
    }
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeUnderlay(DRW_Underlay *ent) {
    if (!preflightDxfWrite())
        return false;
    if (version <= DRW::AC1009) return rejectUnsupportedDxfWrite("UNDERLAY");
    if (ent == nullptr || writer == nullptr || !ent->validatePayloadFields()
        || ent->clipBoundary.size() > DRW_Underlay::kMaxClipVertices
        || ent->inverseClipBoundary.size() > DRW_Underlay::kMaxClipVertices
        || (version <= DRW::AC1021
            && (!ent->inverseClipBoundary.empty() || (ent->flags & 0x10) != 0))) {
        m_writeError = true;
        return false;
    }
    EntityRecordScope scope(*this, ent);
    const bool hasInverseClip = !ent->inverseClipBoundary.empty()
                                || (ent->flags & 0x10) != 0;
    const std::uint8_t wireFlags =
        hasInverseClip ? static_cast<std::uint8_t>(ent->flags | 0x10) : ent->flags;
    const char* tag = (ent->kind == DRW_Underlay::DGN) ? "DGNUNDERLAY"
                    : (ent->kind == DRW_Underlay::DWF) ? "DWFUNDERLAY"
                    : "PDFUNDERLAY";
    writer->writeString(0, tag);
    if (!writeEntity(ent))
        return false;
    writer->writeString(100, "AcDbUnderlayReference");
    if (ent->definitionHandle != 0) {
        writer->writeString(340, toHexStr(ent->definitionHandle));
    }
    writer->writeDouble(10, ent->position.x);
    writer->writeDouble(20, ent->position.y);
    writer->writeDouble(30, ent->position.z);
    if (ent->scale.x != 1.0 || ent->scale.y != 1.0 || ent->scale.z != 1.0) {
        writer->writeDouble(41, ent->scale.x);
        writer->writeDouble(42, ent->scale.y);
        writer->writeDouble(43, ent->scale.z);
    }
    writer->writeDouble(50, ent->rotation);
    if (ent->extPoint.x != 0.0 || ent->extPoint.y != 0.0 || ent->extPoint.z != 1.0) {
        writer->writeDouble(210, ent->extPoint.x);
        writer->writeDouble(220, ent->extPoint.y);
        writer->writeDouble(230, ent->extPoint.z);
    }
    writer->writeInt16(280, wireFlags);
    writer->writeInt16(281, ent->contrast);
    writer->writeInt16(282, ent->fade);
    for (const auto& v : ent->clipBoundary) {
        writer->writeDouble(11, v.x);
        writer->writeDouble(21, v.y);
    }
    if (hasInverseClip) {
        writer->writeInt16(170, static_cast<int>(ent->inverseClipBoundary.size()));
        for (const auto& v : ent->inverseClipBoundary) {
            writer->writeDouble(12, v.x);
            writer->writeDouble(22, v.y);
        }
    }
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeUnderlayDefinition(DRW_UnderlayDefinition *ent) {
    if (version <= DRW::AC1009)
        return rejectUnsupportedDxfWrite("UNDERLAY definition");
    if (!preflightTableEntry(ent))
        return false;
    const char* tag = (ent->kind == DRW_UnderlayDefinition::DGN) ? "DGNDEFINITION"
                    : (ent->kind == DRW_UnderlayDefinition::DWF) ? "DWFDEFINITION"
                    : "PDFDEFINITION";
    EntityRecordScope scope(*this, ent);
    writer->writeString(0, tag);
    writer->writeString(5, toHexStr(ent->handle));
    if (!writeTableEntryAppData(*ent))
        return false;
    writeObjectOwner(static_cast<std::uint32_t>(ent->parentHandle));
    writer->writeString(100, "AcDbUnderlayDefinition");
    writer->writeUtf8String(1, ent->filename);
    writer->writeUtf8String(2, ent->sheetName);
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeMText(DRW_MText *ent){
    if (version > DRW::AC1009) {
        if (!preflightEntity(ent))
            return false;
        const bool hasColumns = hasR2018MTextColumns(*ent);
        if (hasColumns
            && (version < DRW::AC1032
                || !isValidR2018MTextColumnState(*ent)))
            return rejectUnsupportedDxfWrite("MTEXT column profile");
        EntityRecordScope scope(*this, ent);
        writer->writeString(0, "MTEXT");
        if (!writeEntity(ent))
            return false;
        writer->writeString(100, "AcDbMText");
        writer->writeDouble(10, ent->basePoint.x);
        writer->writeDouble(20, ent->basePoint.y);
        writer->writeDouble(30, ent->basePoint.z);
        writer->writeDouble(40, ent->height);
        writer->writeDouble(41, ent->widthscale);
        // Defined height, R2007+. Read by DRW_MText and never written, so a
        // DXF-to-DXF pass dropped it.
        if (version >= DRW::AC1021
            && (ent->m_definedHeightPresent || ent->m_definedHeight != 0.0))
            writer->writeDouble(46, ent->m_definedHeight);
        writer->writeInt16(71, ent->textgen);
        writer->writeInt16(72, ent->alignH);
        // Keep the documented character chunk budget distinct from the
        // target-encoded byte ceiling. The shared helper preserves complete
        // encoded scalars and emits a short final group 1 when continuations
        // are required, for both the strict and compatibility writer paths.
        if (!writer->writeUtf8MTextChunks(ent->text, 3, 1, 250u, 250u))
            return false;
        writer->writeUtf8String(7, ent->style);
        writer->writeDouble(210, ent->extPoint.x);
        writer->writeDouble(220, ent->extPoint.y);
        writer->writeDouble(230, ent->extPoint.z);
        const auto orientation = ent->dxfOrientationForOutput();
        const bool legacyOrientation = orientation == DRW_MText::DxfOrientationMode::LegacyApi;
        if (orientation != DRW_MText::DxfOrientationMode::Direction)
            writer->writeDouble(50, ent->angle);
        // MTEXT may carry an explicit WCS x-axis direction (groups 11/21/31)
        // instead of deriving its rotation from group 50. Preserve it when
        // present; a zero vector means the optional field was absent.
        if (orientation == DRW_MText::DxfOrientationMode::Direction
            || (legacyOrientation && (ent->secPoint.x != 0.0 || ent->secPoint.y != 0.0
                                       || ent->secPoint.z != 0.0))) {
            writer->writeDouble(11, ent->secPoint.x);
            writer->writeDouble(21, ent->secPoint.y);
            writer->writeDouble(31, ent->secPoint.z);
        }
        writer->writeInt16(73, ent->linespacingStyle);  // linespacing style (was: alignV)
        writer->writeDouble(44, ent->interlin);
//RLZ ... 11, 21, 31 needed?
        // Background fill. DRW_MText has always read 45, 63, 90, 421 and 441
        // and this writer emitted none of them, so every MTEXT with a filled
        // background came out of a DXF-to-DXF pass with the fill gone --
        // silently, in a file that still held the text.
        //
        // 45, 90 and 63 travel together: the reference calls all three
        // required once any of them is used, and 63 required even when the
        // colour is given as a true colour or by name. The optional two are
        // written only when set, so a plain MTEXT's byte stream is unchanged.
        //
        // R2007 is where background fill arrives; writing it into an older
        // revision would produce groups that revision has no meaning for.
        if (!writeMTextBackground(ent))
            return false;
        if (hasColumns) {
            writer->writeString(101, "Embedded Object");
            const bool hasNestedContext =
                ent->m_r2018DxfColumnContextPresent
                || ent->m_r2018IsNotAnnotative;
            const DRW_Coord direction = hasNestedContext
                ? ent->m_r2018XAxisDir
                : (ent->secPoint.x != 0.0 || ent->secPoint.y != 0.0
                   || ent->secPoint.z != 0.0)
                    ? ent->secPoint
                    : DRW_Coord(
                        std::cos(ent->angle * std::acos(-1.0) / 180.0),
                        std::sin(ent->angle * std::acos(-1.0) / 180.0), 0.0);
            const DRW_Coord insertion = hasNestedContext
                ? ent->m_r2018InsertionPoint : ent->basePoint;
            const double referenceWidth = hasNestedContext
                ? ent->m_r2018RectWidth : ent->widthscale;
            const double definedHeight = hasNestedContext
                ? ent->m_r2018RectHeight : ent->m_definedHeight;
            const double totalWidth = hasNestedContext
                ? ent->m_r2018ExtentsWidth
                : ent->m_r2018ColumnCount > 0
                    ? ent->m_r2018ColumnCount * ent->m_r2018ColumnWidth
                        + (ent->m_r2018ColumnCount - 1)
                            * ent->m_r2018ColumnGutter
                    : 0.0;
            double totalHeight = hasNestedContext
                ? ent->m_r2018ExtentsHeight : definedHeight;
            if (!hasNestedContext
                && ent->m_r2018ColumnType == 2
                && !ent->m_r2018ColumnAutoHeight
                && !ent->m_r2018ColumnHeights.empty())
                totalHeight = *std::max_element(
                    ent->m_r2018ColumnHeights.begin(),
                    ent->m_r2018ColumnHeights.end());

            writer->writeInt16(70, hasNestedContext
                ? ent->m_r2018Attachment : ent->textgen);
            writer->writeDouble(10, direction.x);
            writer->writeDouble(20, direction.y);
            writer->writeDouble(30, direction.z);
            writer->writeDouble(11, insertion.x);
            writer->writeDouble(21, insertion.y);
            writer->writeDouble(31, insertion.z);
            writer->writeDouble(40, referenceWidth);
            writer->writeDouble(41, definedHeight);
            writer->writeDouble(42, totalWidth);
            writer->writeDouble(43, totalHeight);
            writer->writeInt16(71, ent->m_r2018ColumnType);
            const std::int32_t columnCount =
                ent->m_r2018ColumnType == 2
                    && ent->m_r2018ColumnAutoHeight
                ? 0 : ent->m_r2018ColumnCount;
            writer->writeInt16(72, static_cast<int>(columnCount));
            writer->writeDouble(44, ent->m_r2018ColumnWidth);
            writer->writeDouble(45, ent->m_r2018ColumnGutter);
            writer->writeInt16(73,
                ent->m_r2018ColumnAutoHeight ? 1 : 0);
            writer->writeInt16(74,
                ent->m_r2018ColumnFlowReversed ? 1 : 0);
            for (const double heightValue : ent->m_r2018ColumnHeights)
                writer->writeDouble(46, heightValue);
        }
        if (!ent->extData.empty() && !writeExtData(ent->extData))
            return false;
    } else {
        return rejectUnsupportedDxfWrite("MTEXT");
    }
    return !writer->hasWriteError();
}

bool dxfRW::writeLight(DRW_Light *ent) {
    // AcDbLight is an R2007+ (AC1021+) entity; pre-R2007 DXF has no LIGHT entity,
    // so skip rather than emit something AutoCAD/ezdxf would reject. Lights read
    // from a DWG are carried on LibreCAD's metadata shelf and would otherwise be
    // dropped on DWG->DXF export; this re-emits them (D4 write-path preservation).
    if (version < DRW::AC1021)
        return rejectUnsupportedDxfWrite("LIGHT");
    if (!preflightEntity(ent))
        return false;
    EntityRecordScope scope(*this, ent);
    writer->writeString(0, "LIGHT");
    if (!writeEntity(ent))
        return false;
    writer->writeString(100, "AcDbLight");
    writer->writeInt32(90, static_cast<int>(ent->m_classVersion));
    writer->writeUtf8String(1, ent->m_name);
    writer->writeInt16(70, static_cast<int>(ent->m_type));
    writer->writeBool(290, ent->m_status);
    // ACI index in 63; a packed true-color value goes in 421 instead.
    if (ent->m_color < 256)
        writer->writeInt16(63, static_cast<int>(ent->m_color));
    else
        writer->writeInt32(421, static_cast<int>(ent->m_color));
    writer->writeBool(291, ent->m_plotGlyph);
    writer->writeDouble(40, ent->m_intensity);
    writer->writeDouble(10, ent->m_position.x);
    writer->writeDouble(20, ent->m_position.y);
    writer->writeDouble(30, ent->m_position.z);
    writer->writeDouble(11, ent->m_target.x);
    writer->writeDouble(21, ent->m_target.y);
    writer->writeDouble(31, ent->m_target.z);
    writer->writeInt16(72, static_cast<int>(ent->m_attenuationType));
    writer->writeBool(292, ent->m_useAttenuationLimits);
    writer->writeDouble(41, ent->m_attenuationStartLimit);
    writer->writeDouble(42, ent->m_attenuationEndLimit);
    writer->writeDouble(50, ent->m_hotspotAngle);
    writer->writeDouble(51, ent->m_falloffAngle);
    writer->writeBool(293, ent->m_castShadows);
    writer->writeInt16(73, static_cast<int>(ent->m_shadowType));
    writer->writeInt32(91, static_cast<int>(ent->m_shadowMapSize));
    writer->writeInt16(280, static_cast<int>(ent->m_shadowMapSoftness));
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeCamera(DRW_Camera *ent) {
    if (!preflightEntity(ent))
        return false;
    if (version < DRW::AC1015)
        return rejectUnsupportedDxfWrite("CAMERA");
    EntityRecordScope scope(*this, ent);
    writer->writeString(0, "CAMERA");
    if (!writeEntity(ent))
        return false;
    writer->writeString(100, "AcDbCamera");
    if (ent->m_viewHandle != 0)
        writer->writeString(340, toHexStr(ent->m_viewHandle));
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeGeoPositionMarker(DRW_GeoPositionMarker *ent) {
    if (!preflightEntity(ent))
        return false;
    if (version < DRW::AC1027)
        return rejectUnsupportedDxfWrite("GEOPOSITIONMARKER");
    if (ent->m_enableFrameText && ent->mtext == nullptr) {
        m_writeError = true;
        return false;
    }

    EntityRecordScope scope(*this, ent);
    writer->writeString(0, "GEOPOSITIONMARKER");
    if (!writeEntity(ent))
        return false;
    writer->writeString(100, "AcDbGeoPositionMarker");
    writer->writeInt32(90, static_cast<int>(ent->m_classVersion));
    writer->writeDouble(10, ent->m_position.x);
    writer->writeDouble(20, ent->m_position.y);
    writer->writeDouble(30, ent->m_position.z);
    writer->writeDouble(40, ent->m_radius);
    writer->writeUtf8String(1, ent->m_notes);
    writer->writeDouble(40, ent->m_landingGap);
    writer->writeBool(290, ent->m_mtextVisible);
    writer->writeInt16(280, ent->m_textAlignment);
    writer->writeBool(290, ent->m_enableFrameText);
    if (ent->m_enableFrameText) {
        // The DXF form stores the embedded object's insertion point separately
        // before the standard Embedded Object MTEXT subclass.
        writer->writeDouble(11, ent->m_position.x);
        writer->writeDouble(21, ent->m_position.y);
        writer->writeDouble(31, ent->m_position.z);
        DRW_MText embedded(*ent->mtext);
        embedded.extData.clear();
        if (!writeEmbeddedMText(&embedded))
            return false;
    }
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeSectionObject(DRW_SectionObject *ent) {
    if (!preflightEntity(ent))
        return false;
    if (version < DRW::AC1021)
        return rejectUnsupportedDxfWrite("SECTIONOBJECT");
    if (ent->m_indicatorColorRgb != -1
        || !ent->m_indicatorColorName.empty()
        || !ent->m_indicatorColorBookName.empty()) {
        recordOperationDiagnostic(
            DRW::OperationPhase::Entities,
            DRW::OperationCause::ValidationFailure,
            "unrepresentable-sectionobject-dxf-cmc-color",
            "SECTIONOBJECT DXF defines scalar indicator color group 63 only; retained RGB, color-name, or color-book CMC data cannot be preserved",
            0, false, ent->handle, ent->handle != DRW::NoHandle);
        return failDxfWrite();
    }
    if (ent->m_indicatorColor > std::numeric_limits<std::uint16_t>::max()
        || ent->m_verts.size() > DRW_SectionObject::kMaxVertices
        || ent->m_blVerts.size() > DRW_SectionObject::kMaxVertices) {
        m_writeError = true;
        return false;
    }
    EntityRecordScope scope(*this, ent);
    writer->writeString(0, "SECTIONOBJECT");
    if (!writeEntity(ent))
        return false;
    writer->writeString(100, "AcDbSection");
    writer->writeInt32(90, static_cast<int>(ent->m_state));
    writer->writeInt32(91, static_cast<int>(ent->m_flags));
    writer->writeUtf8String(1, ent->m_name);
    writer->writeDouble(10, ent->m_vertDir.x);
    writer->writeDouble(20, ent->m_vertDir.y);
    writer->writeDouble(30, ent->m_vertDir.z);
    writer->writeDouble(40, ent->m_topHeight);
    writer->writeDouble(41, ent->m_bottomHeight);
    writer->writeInt16(70, static_cast<int>(ent->m_indicatorAlpha));
    writer->writeInt16(63, static_cast<int>(ent->m_indicatorColor));
    writer->writeInt32(92, static_cast<int>(ent->m_verts.size()));
    for (const DRW_Coord& point : ent->m_verts) {
        writer->writeDouble(11, point.x);
        writer->writeDouble(21, point.y);
        writer->writeDouble(31, point.z);
    }
    writer->writeInt32(93, static_cast<int>(ent->m_blVerts.size()));
    for (const DRW_Coord& point : ent->m_blVerts) {
        writer->writeDouble(12, point.x);
        writer->writeDouble(22, point.y);
        writer->writeDouble(32, point.z);
    }
    if (ent->m_sectionSettingsHandle != 0)
        writer->writeString(360, toHexStr(ent->m_sectionSettingsHandle));
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeMesh(DRW_Mesh *ent) {
    if (!preflightDxfWrite())
        return false;
    if (version <= DRW::AC1009)
        return rejectUnsupportedDxfWrite("MESH");
    const char* recordName = dxfMeshRecordNameForVersion(version);
    if (recordName == nullptr)
        return rejectUnsupportedDxfWrite("MESH");
    if (ent == nullptr || writer == nullptr || !ent->validateDxfOutput()) {
        m_writeError = true;
        return false;
    }
    EntityRecordScope scope(*this, ent);
    writer->writeString(0, recordName);
    if (!writeEntity(ent))
        return false;
    writer->writeString(100, "AcDbSubDMesh");
    writer->writeInt16(71, static_cast<int>(ent->version));
    writer->writeInt16(72, ent->blendCrease ? 1 : 0);
    writer->writeInt32(91, ent->subdivisionLevel);
    writer->writeInt32(92, static_cast<int>(ent->vertices.size()));
    for (const DRW_Coord& vertex : ent->vertices) {
        writer->writeDouble(10, vertex.x);
        writer->writeDouble(20, vertex.y);
        writer->writeDouble(30, vertex.z);
    }

    std::int32_t faceStreamCount = 0;
    for (const auto& face : ent->faces)
        faceStreamCount += static_cast<std::int32_t>(face.size() + 1);
    writer->writeInt32(93, faceStreamCount);
    for (const auto& face : ent->faces) {
        writer->writeInt32(90, static_cast<int>(face.size()));
        for (std::int32_t index : face)
            writer->writeInt32(90, index);
    }

    writer->writeInt32(94, static_cast<int>(ent->edges.size()));
    for (const auto& edge : ent->edges) {
        writer->writeInt32(90, edge.first);
        writer->writeInt32(90, edge.second);
    }

    writer->writeInt32(95, static_cast<int>(ent->creases.size()));
    for (double crease : ent->creases)
        writer->writeDouble(140, crease);
    writer->writeInt32(90, static_cast<int>(ent->propertyOverrides.size()));
    for (const auto& overrideData : ent->propertyOverrides) {
        writer->writeInt32(91, overrideData.subEntityMarker);
        writer->writeInt32(92, static_cast<int>(overrideData.propertyTypes.size()));
        for (std::int32_t propertyType : overrideData.propertyTypes)
            writer->writeInt32(90, propertyType);
    }
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeShape(DRW_Shape *ent) {
    if (!preflightEntity(ent))
        return false;
    // DXF SHAPE (AcDbShape). The DWG stores only a glyph index; the glyph name
    // lives in the external .shx and is unrecoverable, so group 2 carries the
    // SHAPEFILE/STYLE record name (resolved on read), matching libredwg/ACadSharp.
    // m_rotation/m_oblique are radians (DRW_Shape::parseDwg keeps them un-scaled,
    // unlike DRW_Text) -> convert to DXF degrees.
    const auto finite = [](const DRW_Coord& point) {
        return std::isfinite(point.x) && std::isfinite(point.y)
               && std::isfinite(point.z);
    };
    if (!finite(ent->m_insertionPoint) || !finite(ent->m_extrusion)
        || !std::isfinite(ent->m_scale) || !std::isfinite(ent->m_rotation)
        || !std::isfinite(ent->m_widthFactor) || !std::isfinite(ent->m_oblique)
        || !std::isfinite(ent->m_thickness)) {
        m_writeError = true;
        return false;
    }
    EntityRecordScope scope(*this, ent);
    writer->writeString(0, "SHAPE");
    if (!writeEntity(ent))
        return false;
    if (version > DRW::AC1009)
        writer->writeString(100, "AcDbShape");
    if (ent->m_thickness != 0.0)
        writer->writeDouble(39, ent->m_thickness);
    writer->writeDouble(10, ent->m_insertionPoint.x);
    writer->writeDouble(20, ent->m_insertionPoint.y);
    writer->writeDouble(30, ent->m_insertionPoint.z);
    writer->writeDouble(40, ent->m_scale);            // size
    if (!ent->m_styleName.empty())
        writer->writeUtf8String(2, ent->m_styleName); // shape (style) name
    writer->writeDouble(50, ent->m_rotation * ARAD);  // radians -> degrees
    if (ent->m_widthFactor != 1.0)
        writer->writeDouble(41, ent->m_widthFactor);
    if (ent->m_oblique != 0.0)
        writer->writeDouble(51, ent->m_oblique * ARAD);
    if (ent->m_extrusion.x != 0.0 || ent->m_extrusion.y != 0.0 || ent->m_extrusion.z != 1.0) {
        writer->writeDouble(210, ent->m_extrusion.x);
        writer->writeDouble(220, ent->m_extrusion.y);
        writer->writeDouble(230, ent->m_extrusion.z);
    }
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeOle2Frame(DRW_Ole2Frame *ent) {
    if (!preflightEntity(ent))
        return false;
    // DXF OLE2FRAME (AcDbOle2Frame). Field order/codes per ACadSharp + dwgread:
    // 70 version, 3 client, 10/11 frame corners, 71 type, 72 mode, 73 lock
    // aspect, 90 length, 310 binary (hex chunks), 1 "OLE" trailer. pt1/pt2
    // were decoded from the OLE payload header on read; the payload is replayed
    // verbatim.
    if (ent->m_payloadTooLarge || ent->m_payloadTruncated
        || ent->m_payloadBytes.size() > DRW_Ole2Frame::kMaxOlePayloadBytes
        || (ent->m_payloadPresent
            && ent->m_declaredPayloadLength != ent->m_payloadBytes.size())) {
        m_writeError = true;
        return false;
    }
    EntityRecordScope scope(*this, ent);
    writer->writeString(0, "OLE2FRAME");
    if (!writeEntity(ent))
        return false;
    if (version > DRW::AC1009)
        writer->writeString(100, "AcDbOle2Frame");
    writer->writeInt16(70, static_cast<int>(ent->m_oleVersion));
    writer->writeUtf8String(3, ent->m_oleClient);
    writer->writeDouble(10, ent->m_pt1.x);
    writer->writeDouble(20, ent->m_pt1.y);
    writer->writeDouble(30, ent->m_pt1.z);
    writer->writeDouble(11, ent->m_pt2.x);
    writer->writeDouble(21, ent->m_pt2.y);
    writer->writeDouble(31, ent->m_pt2.z);
    writer->writeInt16(71, static_cast<int>(ent->m_flags));  // OLE object type
    writer->writeInt16(72, static_cast<int>(ent->m_mode));   // tile/paper-space mode
    writer->writeInt16(73, ent->m_lockAspect);                // lock aspect ratio
    writer->writeInt32(90, static_cast<int>(ent->m_payloadBytes.size()));
    // group 310: payload as hex, 127 bytes (254 hex chars) per record (AutoCAD/
    // dwgread convention; the binary-DXF writer hex-decodes and re-chunks).
    static const char hexd[] = "0123456789ABCDEF";
    const std::vector<std::uint8_t>& data = ent->m_payloadBytes;
    char chunk[254];
    for (std::size_t off = 0; off < data.size(); off += 127) {
        const std::size_t n = std::min<std::size_t>(127, data.size() - off);
        for (std::size_t i = 0; i < n; ++i) {
            const std::uint8_t b = data[off + i];
            chunk[2u * i] = hexd[b >> 4];
            chunk[2u * i + 1u] = hexd[b & 0x0F];
        }
        writer->writeString(310, std::string_view(chunk, n * 2u));
    }
    writer->writeString(1, "OLE");
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeOleFrame(DRW_OleFrame *ent) {
    if (!preflightEntity(ent))
        return false;
    // Legacy OLEFRAME has no OLE2 frame rectangle or DXF mode field. Its
    // interoperable DXF payload is the bounded 70/90/310 contract, followed
    // by the historical OLE trailer.
    if (ent->m_payloadTooLarge || ent->m_payloadTruncated
        || ent->m_payloadBytes.size() > DRW_OleFrame::kMaxOlePayloadBytes
        || (ent->m_payloadPresent
            && ent->m_declaredPayloadLength != ent->m_payloadBytes.size())) {
        m_writeError = true;
        return false;
    }
    EntityRecordScope scope(*this, ent);
    writer->writeString(0, "OLEFRAME");
    if (!writeEntity(ent))
        return false;
    if (version > DRW::AC1009)
        writer->writeString(100, "AcDbOleFrame");
    writer->writeInt16(70, static_cast<int>(ent->m_flags));
    writer->writeInt32(90, static_cast<int>(ent->m_payloadBytes.size()));
    static const char hexd[] = "0123456789ABCDEF";
    const std::vector<std::uint8_t>& data = ent->m_payloadBytes;
    char chunk[254];
    for (std::size_t off = 0; off < data.size(); off += 127) {
        const std::size_t n = std::min<std::size_t>(127, data.size() - off);
        for (std::size_t i = 0; i < n; ++i) {
            const std::uint8_t b = data[off + i];
            chunk[2u * i] = hexd[b >> 4];
            chunk[2u * i + 1u] = hexd[b & 0x0F];
        }
        writer->writeString(310, std::string_view(chunk, n * 2u));
    }
    writer->writeString(1, "OLE");
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeViewport(DRW_Viewport *ent) {
    if (!preflightDxfWrite())
        return false;
    // The typed DXF facade has no graph context. Only references whose target
    // was registered by a validating adapter are safe to emit; direct codec
    // callers remain fail-closed by default.
    if (ent == nullptr || writer == nullptr || !ent->validatePayloadFields()
        || (ent->backgroundHandle != 0
            && std::find(m_resolvedBackgroundHandles.begin(),
                         m_resolvedBackgroundHandles.end(),
                         ent->backgroundHandle)
                == m_resolvedBackgroundHandles.end())
        || (ent->m_sunHandle != 0
            && (version < DRW::AC1021
                || std::find(m_resolvedSunHandles.begin(),
                             m_resolvedSunHandles.end(), ent->m_sunHandle)
                    == m_resolvedSunHandles.end()))) {
        m_writeError = true;
        return false;
    }
    EntityRecordScope scope(*this, ent);
    if (!writer->writeString(0, "VIEWPORT")) {
        m_writeError = true;
        return false;
    }
    if (!writeEntity(ent))
        return false;
    bool result = true;
    if (version > DRW::AC1009) {
        writer->writeString(100, "AcDbViewport");
    }
    writer->writeDouble(10, ent->basePoint.x);
    writer->writeDouble(20, ent->basePoint.y);
    if (ent->basePoint.z != 0.0)
        writer->writeDouble(30, ent->basePoint.z);
    writer->writeDouble(40, ent->pswidth);
    writer->writeDouble(41, ent->psheight);
    writer->writeInt16(68, ent->vpstatus);
    writer->writeInt16(69, ent->vpID);
    writer->writeDouble(12, ent->centerPX);
    writer->writeDouble(22, ent->centerPY);
    if (version > DRW::AC1009) {
        writer->writeDouble(13, ent->snapPX);
        writer->writeDouble(23, ent->snapPY);
        writer->writeDouble(14, ent->snapSpPX);
        writer->writeDouble(24, ent->snapSpPY);
        writer->writeDouble(15, ent->gridSpX);
        writer->writeDouble(25, ent->gridSpY);
        writer->writeDouble(16, ent->viewDir.x);
        writer->writeDouble(26, ent->viewDir.y);
        writer->writeDouble(36, ent->viewDir.z);
        writer->writeDouble(17, ent->viewTarget.x);
        writer->writeDouble(27, ent->viewTarget.y);
        writer->writeDouble(37, ent->viewTarget.z);
        writer->writeDouble(42, ent->viewLength);
        writer->writeDouble(43, ent->frontClip);
        writer->writeDouble(44, ent->backClip);
        writer->writeDouble(45, ent->viewHeight);
        writer->writeDouble(50, ent->snapAngle);
        writer->writeDouble(51, ent->twistAngle);
        writer->writeInt16(72, static_cast<int>(ent->circleZoom));
        if (version > DRW::AC1018)
            writer->writeInt16(61, ent->majorGridLines);
        writer->writeInt32(90, ent->statusFlags);
        writer->writeUtf8String(1, ent->styleSheet);
        writer->writeInt16(281, ent->renderMode);
        writer->writeInt16(71, ent->ucsPerViewport ? 1 : 0);
        writer->writeInt16(74, ent->ucsAtOrigin ? 1 : 0);
        writer->writeDouble(110, ent->ucsOrigin.x);
        writer->writeDouble(120, ent->ucsOrigin.y);
        writer->writeDouble(130, ent->ucsOrigin.z);
        writer->writeDouble(111, ent->ucsXAxis.x);
        writer->writeDouble(121, ent->ucsXAxis.y);
        writer->writeDouble(131, ent->ucsXAxis.z);
        writer->writeDouble(112, ent->ucsYAxis.x);
        writer->writeDouble(122, ent->ucsYAxis.y);
        writer->writeDouble(132, ent->ucsYAxis.z);
        writer->writeDouble(146, ent->ucsElevation);
        writer->writeInt16(79, ent->ucsOrthographicType);
        for (const std::uint32_t ref : ent->frozenLayerHandles) {
            if (ref != 0)
                writer->writeString(331, toHexStr(remapObjectHandle(ref)));
        }
    }
    if (version > DRW::AC1015)
        writer->writeInt16(170, ent->shadePlotMode);
    if (version > DRW::AC1018) {
        writer->writeBool(292, ent->useDefaultLighting);
        writer->writeInt16(282, ent->defaultLightingType);
        writer->writeDouble(141, ent->brightness);
        writer->writeDouble(142, ent->contrast);
        writer->writeInt16(63, static_cast<int>(ent->ambientColor));
        if (ent->ambientColorRgb >= 0)
            writer->writeInt32(421, ent->ambientColorRgb);
        if (!ent->ambientColorName.empty())
            writer->writeUtf8String(431, ent->ambientColorName);
        if (ent->backgroundHandle != 0)
            writer->writeString(332, toHexStr(
                remapObjectHandle(ent->backgroundHandle)));
        if (ent->shadePlotHandle != 0)
            writer->writeString(333, toHexStr(
                remapObjectHandle(ent->shadePlotHandle)));
    }
    if (version > DRW::AC1014) {
        if (ent->clipBoundaryHandle != 0)
            writer->writeString(340, toHexStr(
                remapObjectHandle(ent->clipBoundaryHandle)));
        if (ent->namedUcsHandle != 0)
            writer->writeString(345, toHexStr(
                remapObjectHandle(ent->namedUcsHandle)));
        if (ent->baseUcsHandle != 0)
            writer->writeString(346, toHexStr(
                remapObjectHandle(ent->baseUcsHandle)));
    }
    if (version > DRW::AC1018) {
        if (ent->visualStyleHandle != 0)
            writer->writeString(348, toHexStr(
                remapObjectHandle(ent->visualStyleHandle)));
        if (ent->m_sunHandle != 0)
            writer->writeString(361, toHexStr(
                remapObjectHandle(ent->m_sunHandle)));
    }
    if (!ent->extData.empty())
        result = writeExtData(ent->extData) && result;
    if (!result || writer->hasWriteError())
        m_writeError = true;
    return result && !writer->hasWriteError();
}

DRW_ImageDef* dxfRW::writeImage(DRW_Image *ent, std::string name) {
    return writeImageRecord(ent, std::move(name), nullptr);
}

DRW_ImageDef* dxfRW::writeImage(
        DRW_Image *ent, std::string name, std::uint64_t importGeneration,
        std::uint32_t sourceDefinitionHandle) {
    if (!preflightDxfWrite())
        return nullptr;
    const auto planned = m_plannedImageDefinitions.find(
        {importGeneration, sourceDefinitionHandle});
    if (sourceDefinitionHandle == 0
        || sourceDefinitionHandle == DRW::NoHandle
        || planned == m_plannedImageDefinitions.end()) {
        m_writeError = true;
        return nullptr;
    }
    return writeImageRecord(ent, std::move(name), planned->second);
}

DRW_ImageDef* dxfRW::writeImageRecord(
        DRW_Image *ent, std::string name,
        DRW_ImageDef *plannedDefinition) {
    if (version <= DRW::AC1009) {
        rejectUnsupportedDxfWrite("IMAGE");
        return nullptr; // IMAGE is not available in ACAD R12 / earlier.
    }
    if (!preflightEntity(ent))
        return nullptr;
    if (ent == nullptr || writer == nullptr || !ent->validatePayloadFields()
        || !isValidDxfRasterAdjustments(*ent)) {
        m_writeError = true;
        return nullptr;
    }
    EntityRecordScope scope(*this, ent);
    // A DXF image definition is a named dictionary entry. Normalize an
    // unnamed source before lookup so repeated direct calls cannot create
    // duplicate empty or fallback names.
    if (plannedDefinition == nullptr && name.empty()) {
        if (ent->handle != 0) {
            name = std::string("librecad_image_") + toHexStr(ent->handle);
        } else {
            name = "librecad_image";
            const auto hasImageDefinition = [this](const std::string &candidate) {
                return std::any_of(
                    imageDef.cbegin(), imageDef.cend(),
                    [&candidate](const DRW_ImageDef *definition) {
                        return definition != nullptr
                               && definition->name == candidate;
                    });
            };
            for (std::size_t suffix = 1; hasImageDefinition(name); ++suffix)
                name = "librecad_image_" + std::to_string(suffix);
        }
    }
    //search if exist imagedef with this mane (image inserted more than 1 time)
    //RLZ: imagedef_reactor seem needed to read in acad
    DRW_ImageDef *id = plannedDefinition;
    std::unique_ptr<DRW_ImageDef> newId;
    if (id == nullptr) {
        for (unsigned int i=0; i<imageDef.size(); i++) {
            if (imageDef.at(i)->name == name ) {
                id = imageDef.at(i);
                continue;
            }
        }
    }
    if (id == NULL) {
        newId = std::make_unique<DRW_ImageDef>();
        id = newId.get();
        if (!allocateDxfHandle(id->handle))
            return nullptr;
    }
    if (plannedDefinition == nullptr)
        id->name = name;
    std::uint32_t reactorHandle = 0;
    const DRW_ImageDefinitionReactor* sourceReactor = nullptr;
    const auto sourcePlan = m_imagePlanReactorSources.find(plannedDefinition);
    if (sourcePlan != m_imagePlanReactorSources.end()) {
        const auto candidate = sourcePlan->second.find(ent->m_imageDefReactorHandle);
        if (candidate != sourcePlan->second.end()) {
            sourceReactor = candidate->second;
            if (sourceReactor->parentHandle != ent->handle) return failDxfWrite(), nullptr;
        }
    }
    const auto plannedReactor = sourceReactor == nullptr ? m_plannedImageSourceHandles.end()
        : m_plannedImageSourceHandles.find(sourceReactor->handle);
    if (plannedReactor != m_plannedImageSourceHandles.end()) {
        reactorHandle = plannedReactor->second;
        if (reactorHandle == 0u || isDxfFixedOutputHandle(reactorHandle))
            return failDxfWrite(), nullptr;
    } else if (!allocateDxfHandle(reactorHandle)) return nullptr;
    const std::string idReactor = toHexStr(reactorHandle);

    writer->writeString(0, "IMAGE");
    if (!writeEntity(ent)) {
        m_writeError = true;
        return nullptr;
    }
    writer->writeString(100, "AcDbRasterImage");
    writer->writeInt32(90, ent->m_classVersion);
    writer->writeDouble(10, ent->basePoint.x);
    writer->writeDouble(20, ent->basePoint.y);
    writer->writeDouble(30, ent->basePoint.z);
    writer->writeDouble(11, ent->secPoint.x);
    writer->writeDouble(21, ent->secPoint.y);
    writer->writeDouble(31, ent->secPoint.z);
    writer->writeDouble(12, ent->vVector.x);
    writer->writeDouble(22, ent->vVector.y);
    writer->writeDouble(32, ent->vVector.z);
    writer->writeDouble(13, ent->sizeu);
    writer->writeDouble(23, ent->sizev);
    writer->writeString(340, toHexStr(id->handle));
    writer->writeInt16(70, ent->m_displayProps);
    writer->writeInt16(280, ent->clip);
    writer->writeInt16(281, ent->brightness);
    writer->writeInt16(282, ent->contrast);
    writer->writeInt16(283, ent->fade);
    writer->writeString(360, idReactor);
    // Clip boundary (ezdxf acdb_raster_image order): type 71, count 91,
    // then 14/24 vertices. A polygonal path (>=3 pts) is type 2; otherwise
    // emit the rectangular default (type 1, two opposite corners in
    // image-pixel coords) so consumers never see count=0.
    if (ent->clipPath.size() == 2) {
        writer->writeInt16(71, 1);
        writer->writeInt32(91, 2);
        for (const DRW_Coord& v : ent->clipPath) {
            writer->writeDouble(14, v.x);
            writer->writeDouble(24, v.y);
        }
    } else if (ent->clipPath.size() >= 3) {
        writer->writeInt16(71, 2);
        writer->writeInt32(91, static_cast<std::int32_t>(ent->clipPath.size()));
        for (const DRW_Coord& v : ent->clipPath) {
            writer->writeDouble(14, v.x);
            writer->writeDouble(24, v.y);
        }
    } else {
        writer->writeInt16(71, 1);
        writer->writeInt32(91, 2);
        writer->writeDouble(14, -0.5);
        writer->writeDouble(24, -0.5);
        writer->writeDouble(14, ent->sizeu - 0.5);
        writer->writeDouble(24, ent->sizev - 0.5);
    }
    if (version >= DRW::AC1024) {
        writer->writeBool(290, ent->clipMode);  // R2010+ clip mode
    }
    if (!ent->extData.empty() && !writeExtData(ent->extData)) {
        return nullptr;
    }
    if (writer->hasWriteError()) {
        m_writeError = true;
        return nullptr;
    }
    try {
        if (newId) {
            // Transfer ownership only after vector insertion succeeds;
            // otherwise a bad_alloc would leak the definition.
            imageDef.push_back(newId.get());
            newId.release();
        }
        if (id->reactors.find(idReactor) != id->reactors.end()) {
            m_writeError = true;
            return nullptr;
        }
        if (m_recordStateScopeDepth != 0) {
            DxfWriteMutation mutation;
            mutation.kind = DxfWriteMutationKind::ImageReactorInsert;
            mutation.key = idReactor;
            mutation.imageDef = id;
            m_dxfWriteMutations.push_back(std::move(mutation));
        }
        const auto inserted = id->reactors.emplace(
            idReactor, toHexStr(ent->handle));
        if (!inserted.second) {
            m_writeError = true;
            return nullptr;
        }
        if (plannedDefinition != nullptr && ent->m_imageDefReactorHandle != 0u) {
            const auto replacements = m_regeneratedImageSourceReactors.find(id);
            if (replacements != m_regeneratedImageSourceReactors.end()
                && replacements->second.count(ent->m_imageDefReactorHandle) != 0u) {
                m_writeError = true; return nullptr;
            }
            if (m_recordStateScopeDepth != 0) {
                DxfWriteMutation mutation;
                mutation.kind = DxfWriteMutationKind::ImageSourceReactorInsert;
                mutation.imageDef = id; mutation.handle = ent->m_imageDefReactorHandle;
                m_dxfWriteMutations.push_back(std::move(mutation));
            }
            m_regeneratedImageSourceReactors[id].emplace(ent->m_imageDefReactorHandle, reactorHandle);
        }
    } catch (...) {
        m_writeError = true;
        return nullptr;
    }
    if (!scope.commit())
        return nullptr;
    return id;
}

// MULTILEADER DXF write. Mirrors the entity-level field set captured by
// DRW_MLeader::parseCode and emits the nested CONTEXT_DATA{} leader/root
// structure, including break geometry, content transforms, and hard-pointer
// handles. Unsupported pre-R2010 array variants remain outside this bounded
// modern-context route and are retained by the raw carrier when present.
bool dxfRW::writeMultiLeader(DRW_MLeader *ent){
    if (!preflightEntity(ent) || !ent->validateDxf()) {
        m_writeError = true;
        return false;
    }
    if (version < DRW::AC1021)
        return rejectUnsupportedDxfWrite("MULTILEADER");
    // The model has no typed TOLERANCE-content payload for a MULTILEADER.
    // Refuse that and unknown future content types instead of publishing a
    // content-type tag whose corresponding semantics cannot be serialized.
    if (ent->styleContentType > 2u)
        return failDxfWrite();
    // Autodesk's class-specific MLEADER DXF tables define scalar color
    // indices for these nested fields, but do not define per-field truecolor,
    // color-name, or color-book extensions.  Do not silently project DWG CMC
    // metadata into the scalar groups below.
    const auto hasUnrepresentedColor = [](
            int scalar, std::int32_t rgb24, const UTF8STRING& name,
            const UTF8STRING& bookName, std::uint8_t sourceMethod,
            std::uint8_t flags, std::uint16_t reservedIndex) {
        if (rgb24 != -1 || !name.empty() || !bookName.empty()
            || flags != 0u || reservedIndex != 0u)
            return true;
        if (sourceMethod == 0xFFu)
            return false;
        if (scalar < 0 || scalar > 256)
            return true;
        const std::uint8_t scalarMethod = scalar == 256 ? 0xC0u
            : scalar == 0 ? 0xC1u
            : scalar <= 255 ? 0xC3u : 0xFFu;
        return sourceMethod != scalarMethod;
    };
    bool hasUnrepresentedCmc =
        hasUnrepresentedColor(ent->leaderColor, ent->leaderColorRgb,
                              ent->leaderColorName, ent->leaderColorBookName,
                              ent->leaderColorDwgMethod,
                              ent->leaderColorDwgFlags,
                              ent->leaderColorDwgIndex)
        || hasUnrepresentedColor(ent->styleTextColor,
                                 ent->styleTextColorRgb,
                                 ent->styleTextColorName,
                                 ent->styleTextColorBookName,
                                 ent->styleTextColorDwgMethod,
                                 ent->styleTextColorDwgFlags,
                                 ent->styleTextColorDwgIndex)
        || hasUnrepresentedColor(ent->styleBlockColor,
                                 ent->styleBlockColorRgb,
                                 ent->styleBlockColorName,
                                 ent->styleBlockColorBookName,
                                 ent->styleBlockColorDwgMethod,
                                 ent->styleBlockColorDwgFlags,
                                 ent->styleBlockColorDwgIndex)
        || hasUnrepresentedColor(ent->context.textColor,
                                 ent->context.textColorRgb,
                                 ent->context.textColorName,
                                 ent->context.textColorBookName,
                                 ent->context.textColorDwgMethod,
                                 ent->context.textColorDwgFlags,
                                 ent->context.textColorDwgIndex)
        || hasUnrepresentedColor(ent->context.bgFillColor,
                                 ent->context.bgFillColorRgb,
                                 ent->context.bgFillColorName,
                                 ent->context.bgFillColorBookName,
                                 ent->context.bgFillColorDwgMethod,
                                 ent->context.bgFillColorDwgFlags,
                                 ent->context.bgFillColorDwgIndex)
        || hasUnrepresentedColor(ent->context.blockColor,
                                 ent->context.blockColorRgb,
                                 ent->context.blockColorName,
                                 ent->context.blockColorBookName,
                                 ent->context.blockColorDwgMethod,
                                 ent->context.blockColorDwgFlags,
                                 ent->context.blockColorDwgIndex);
    for (const DRW_MLeaderRoot& root : ent->context.roots) {
        for (const DRW_MLeaderLeaderLine& line : root.leaderLines) {
            hasUnrepresentedCmc = hasUnrepresentedCmc
                || hasUnrepresentedColor(line.color, line.colorRgb,
                                         line.colorName, line.colorBookName,
                                         line.colorDwgMethod,
                                         line.colorDwgFlags,
                                         line.colorDwgIndex);
        }
    }
    if (hasUnrepresentedCmc) {
        recordOperationDiagnostic(
            DRW::OperationPhase::Entities,
            DRW::OperationCause::ValidationFailure,
            "unrepresentable-mleader-dxf-cmc-color",
            "MLEADER DXF class fields serialize scalar colors only; RGB, color-name, and color-book CMC data cannot be preserved",
            0, false, ent->handle, ent->handle != DRW::NoHandle);
        return failDxfWrite();
    }
    if (!ent->arrowHeads.empty()
        && (version > DRW::AC1021
            || std::any_of(ent->arrowHeads.begin(), ent->arrowHeads.end(),
                [](const DRW_MLeader::ArrowHeadEntry& entry) {
                    return !entry.hasDxfIndex;
                }))) {
        recordOperationDiagnostic(
            DRW::OperationPhase::Entities,
            DRW::OperationCause::ValidationFailure,
            "unrepresentable-mleader-arrowhead-index",
            version > DRW::AC1021
                ? "legacy MULTILEADER arrowhead entries have no modern DXF representation"
                : "DWG default flags cannot be converted to DXF arrowhead indices",
            0, false, ent->handle, ent->handle != DRW::NoHandle);
        m_writeError = true;
        return false;
    }
    const auto remappedReference = [this](const dwgHandle& reference) {
        return reference.ref == 0
            ? std::uint32_t{0} : remapObjectHandle(reference.ref);
    };
    const auto referenceCanBeWritten = [&remappedReference](
            const dwgHandle& reference) {
        return reference.ref == 0 || remappedReference(reference) != 0;
    };
    if (!referenceCanBeWritten(ent->styleHandle)
        || !referenceCanBeWritten(ent->leaderLineTypeHandle)
        || !referenceCanBeWritten(ent->arrowHeadHandle)
        || !referenceCanBeWritten(ent->styleTextStyleHandle)
        || !referenceCanBeWritten(ent->styleBlockHandle)
        || !referenceCanBeWritten(ent->context.textStyleHandle)
        || !referenceCanBeWritten(ent->context.blockTableRecordHandle))
        return failDxfWrite();
    for (const DRW_MLeaderRoot& root : ent->context.roots) {
        for (const DRW_MLeaderLeaderLine& line : root.leaderLines) {
            if (!referenceCanBeWritten(line.lineTypeHandle)
                || !referenceCanBeWritten(line.arrowHandle))
                return failDxfWrite();
        }
    }
    if (version <= DRW::AC1021) {
        for (const DRW_MLeader::ArrowHeadEntry& entry : ent->arrowHeads) {
            if (!referenceCanBeWritten(entry.handle))
                return failDxfWrite();
        }
        for (const DRW_MLeader::BlockLabelEntry& entry : ent->blockLabels) {
            if (!referenceCanBeWritten(entry.attDefHandle))
                return failDxfWrite();
        }
    }
    EntityRecordScope scope(*this, ent);
    writer->writeString(0, "MULTILEADER");
    if (!writeEntity(ent))
        return false;
    writer->writeString(100, "AcDbMLeader");

    const DRW_MLeaderAnnotContext &ctx = ent->context;
    const bool hasContext =
        ctx.hasTextContents || ctx.hasContentsBlock || !ctx.roots.empty()
        || ctx.flowDirection != 0;
    auto writeCoord = [&](int xCode, const DRW_Coord &coord) {
        writer->writeDouble(xCode, coord.x);
        writer->writeDouble(xCode + 10, coord.y);
        writer->writeDouble(xCode + 20, coord.z);
    };
    if (hasContext) {
        writer->writeString(300, "CONTEXT_DATA{");
        writer->writeDouble(40, ctx.overallScale);
        writeCoord(10, ctx.contentBasePoint);
        writer->writeDouble(41, ctx.textHeight);
        writer->writeDouble(140, ctx.arrowHeadSize);
        writer->writeDouble(145, ctx.landingGap);
        writer->writeInt16(174, ctx.styleLeftAttach);
        writer->writeInt16(175, ctx.styleRightAttach);
        writer->writeInt16(176, ctx.textAlignType);
        writer->writeInt16(177, ctx.attachmentType);
        writer->writeBool(290, ctx.hasTextContents);
        // Text flow direction is independently represented in CONTEXT_DATA.
        // Keep its established position for the MTEXT branch, but do not drop
        // a parsed non-default value merely because hasTextContents is false.
        if (!ctx.hasTextContents)
            writer->writeInt16(172, ctx.flowDirection);
        if (ctx.hasTextContents) {
            writer->writeUtf8String(304, ctx.textLabel);
            writeCoord(11, ctx.textNormal);
            if (ctx.textStyleHandle.ref != 0)
                writer->writeString(340, toHexStr(
                    remappedReference(ctx.textStyleHandle)));
            writeCoord(12, ctx.textLocation);
            writeCoord(13, ctx.textDirection);
            writer->writeDouble(42, ctx.textRotation);
            writer->writeDouble(43, ctx.boundaryWidth);
            writer->writeDouble(44, ctx.boundaryHeight);
            writer->writeDouble(45, ctx.lineSpacingFactor);
            writer->writeInt16(170, ctx.lineSpacingStyle);
            writer->writeInt32(90, ctx.textColor);
            writer->writeInt16(171, ctx.alignment);
            writer->writeInt16(172, ctx.flowDirection);
            writer->writeInt32(91, ctx.bgFillColor);
            writer->writeDouble(141, ctx.bgScaleFactor);
            writer->writeInt32(92, ctx.bgTransparency);
            writer->writeBool(291, ctx.bgFillEnabled);
            writer->writeBool(292, ctx.bgMaskFillOn);
            writer->writeInt16(173, ctx.columnType);
            writer->writeBool(293, ctx.textHeightAuto);
            writer->writeDouble(142, ctx.columnWidth);
            writer->writeDouble(143, ctx.columnGutter);
            writer->writeBool(294, ctx.columnFlowReversed);
            for (double columnSize : ctx.columnSizes)
                writer->writeDouble(144, columnSize);
            writer->writeBool(295, ctx.wordBreak);
        }
        writer->writeBool(296, ctx.hasContentsBlock);
        if (ctx.hasContentsBlock) {
            writeCoord(14, ctx.blockNormal);
            writeCoord(15, ctx.blockLocation);
            writeCoord(16, ctx.blockScale);
            writer->writeDouble(46, ctx.blockRotation);
            writer->writeInt32(93, ctx.blockColor);
            if (ctx.blockTableRecordHandle.ref != 0)
                writer->writeString(341,
                                    toHexStr(remappedReference(
                                        ctx.blockTableRecordHandle)));
            for (double value : ctx.blockTransform)
                writer->writeDouble(47, value);
        }

        for (const DRW_MLeaderRoot &root : ctx.roots) {
            writer->writeString(302, "LEADER{");
            writer->writeBool(290, root.isContentValid);
            writer->writeBool(291, root.unknown291);
            writeCoord(10, root.connectionPoint);
            writeCoord(11, root.direction);
            writer->writeInt32(90, root.leaderIndex);
            writer->writeDouble(40, root.landingDistance);
            for (const auto &breakPair : root.breaks) {
                writeCoord(12, breakPair.first);
                writeCoord(13, breakPair.second);
            }
            for (const DRW_MLeaderLeaderLine &line : root.leaderLines) {
                writer->writeString(304, "LEADER_LINE{");
                for (const DRW_Coord &point : line.points)
                    writeCoord(10, point);
                for (const auto &breakPair : line.breaks) {
                    writeCoord(11, breakPair.first);
                    writeCoord(12, breakPair.second);
                }
                writer->writeInt32(90, line.segmentIndex);
                writer->writeInt32(91, line.leaderLineIndex);
                writer->writeInt32(93, line.overrideFlags);
                writer->writeInt16(170, line.leaderType);
                writer->writeInt32(92, line.color);
                writer->writeInt16(171, line.lineWeight);
                writer->writeDouble(40, line.arrowSize);
                if (line.lineTypeHandle.ref != 0)
                    writer->writeString(340,
                                        toHexStr(remappedReference(
                                            line.lineTypeHandle)));
                if (line.arrowHandle.ref != 0)
                    writer->writeString(341, toHexStr(
                        remappedReference(line.arrowHandle)));
                writer->writeString(305, "}");
            }
            writer->writeInt16(271, root.attachmentDirection);
            writer->writeString(303, "}");
        }

        writeCoord(110, ctx.basePoint);
        writeCoord(111, ctx.baseDirection);
        writeCoord(112, ctx.baseVertical);
        writer->writeBool(297, ctx.isNormalReversed);
        writer->writeInt16(273, ctx.styleTopAttach);
        writer->writeInt16(272, ctx.styleBottomAttach);
        writer->writeString(301, "}");
    }

    writer->writeInt32(90, ent->overrideFlags);
    writer->writeInt16(170, ent->leaderType);
    writer->writeInt32(91, ent->leaderColor);
    writer->writeInt16(171, ent->leaderLineWeight);
    writer->writeBool(290, ent->landingEnabled);
    writer->writeBool(291, ent->doglegEnabled);
    writer->writeDouble(41, ent->landingDistance);
    writer->writeDouble(42, ent->defaultArrowHeadSize);
    writer->writeInt16(172, ent->styleContentType);
    if (ent->styleHandle.ref != 0)
        writer->writeString(340, toHexStr(remappedReference(ent->styleHandle)));
    if (ent->leaderLineTypeHandle.ref != 0)
        writer->writeString(341, toHexStr(
            remappedReference(ent->leaderLineTypeHandle)));
    if (ent->arrowHeadHandle.ref != 0)
        writer->writeString(342, toHexStr(remappedReference(ent->arrowHeadHandle)));
    if (ent->styleTextStyleHandle.ref != 0)
        writer->writeString(343, toHexStr(
            remappedReference(ent->styleTextStyleHandle)));
    if (ent->styleBlockHandle.ref != 0)
        writer->writeString(344, toHexStr(remappedReference(ent->styleBlockHandle)));
    writer->writeInt16(173, ent->styleLeftAttach);
    writer->writeInt32(95, ent->styleRightAttach);
    writer->writeInt16(174, ent->styleTextAngleType);
    writer->writeInt16(175, ent->unknown175);
    writer->writeInt32(92, ent->styleTextColor);
    writer->writeBool(292, ent->styleTextFrameEnabled);
    writer->writeInt32(93, ent->styleBlockColor);
    if (ent->styleContentType == 1 || ent->styleBlockScale.x != 1.0 ||
        ent->styleBlockScale.y != 1.0 || ent->styleBlockScale.z != 1.0) {
        writer->writeDouble(10, ent->styleBlockScale.x);
        writer->writeDouble(20, ent->styleBlockScale.y);
        writer->writeDouble(30, ent->styleBlockScale.z);
    }
    writer->writeDouble(43, ent->styleBlockRotation);
    writer->writeInt16(176, ent->styleAttachmentType);
    writer->writeBool(293, ent->isAnnotative);
    writer->writeBool(294, ent->isTextDirectionNegative);
    writer->writeInt16(178, ent->ipeAlign);
    writer->writeInt16(179, ent->justification);
    writer->writeDouble(45, ent->scaleFactor);
    writer->writeInt16(271, ent->attachmentDirection);
    writer->writeInt16(273, ent->styleTopAttach);
    writer->writeInt16(272, ent->styleBottomAttach);
    writer->writeBool(295, ent->leaderExtendedToText);
    if (version >= DRW::AC1024)
        writer->writeInt16(270, ent->classVersion);
    if (version <= DRW::AC1021) {
        for (const DRW_MLeader::ArrowHeadEntry &entry : ent->arrowHeads) {
            writer->writeInt32(94, entry.dxfIndex);
            if (entry.handle.ref != 0)
                writer->writeString(345, toHexStr(
                    remappedReference(entry.handle)));
        }
        for (const DRW_MLeader::BlockLabelEntry &entry : ent->blockLabels) {
            if (entry.attDefHandle.ref != 0)
                writer->writeString(330, toHexStr(
                    remappedReference(entry.attDefHandle)));
            writer->writeUtf8String(302, entry.labelText);
            writer->writeInt16(177, entry.uiIndex);
            writer->writeDouble(44, entry.width);
        }
    }
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeWipeout(DRW_Wipeout *ent) {
    if (!preflightDxfWrite())
        return false;
    // WIPEOUT has one complete raster payload, not a second subclass at the
    // clipping boundary. Autodesk's DXF table names AcDbRasterImage; the
    // interoperable writer layout used here follows the independent writers'
    // AcDbWipeout marker. The reader still tolerates either and old split input.
    // No AcDbRasterImageDef is written: WIPEOUT carries no actual raster.
    if (version <= DRW::AC1009)
        return rejectUnsupportedDxfWrite("WIPEOUT");
    if (ent == nullptr || writer == nullptr || !ent->validatePayloadFields()
        || !isValidDxfRasterAdjustments(*ent) || !ent->hasValidBoundary()) {
        m_writeError = true;
        return false;
    }
    // Our pre-R2010 output layout does not emit the inversion flag. Reject
    // rather than silently change the masking area: an output-support policy.
    if (ent->clipMode && version <= DRW::AC1021)
        return rejectUnsupportedDxfWrite("WIPEOUT");
    EntityRecordScope scope(*this, ent);
    writer->writeString(0, "WIPEOUT");
    if (!writeEntity(ent))
        return false;
    writer->writeString(100, "AcDbWipeout");
    writer->writeInt32(90, 0);             // existing class-version policy
    writer->writeDouble(10, ent->basePoint.x);
    writer->writeDouble(20, ent->basePoint.y);
    writer->writeDouble(30, ent->basePoint.z);
    writer->writeDouble(11, ent->secPoint.x);
    writer->writeDouble(21, ent->secPoint.y);
    writer->writeDouble(31, ent->secPoint.z);
    writer->writeDouble(12, ent->vVector.x);
    writer->writeDouble(22, ent->vVector.y);
    writer->writeDouble(32, ent->vVector.z);
    writer->writeDouble(13, ent->sizeu);
    writer->writeDouble(23, ent->sizev);
    writer->writeString(340, toHexStr(ent->ref));
    writer->writeInt16(70, ent->m_displayProps);
    writer->writeInt16(280, ent->clip);    // 1 = clipping enabled
    writer->writeInt16(281, ent->brightness);
    writer->writeInt16(282, ent->contrast);
    writer->writeInt16(283, ent->fade);
    writer->writeString(360, toHexStr(ent->m_imageDefReactorHandle));
    writer->writeInt16(71, ent->m_clipBoundaryType);
    writer->writeInt32(91, static_cast<std::int32_t>(ent->clipPath.size()));
    for (const DRW_Coord& v : ent->clipPath) {
        writer->writeDouble(14, v.x);
        writer->writeDouble(24, v.y);
    }
    // Group 290 is the R2010+ Clip mode (0 = mask outside, 1 = mask inside);
    // this is shared with IMAGE and is NOT a frame-display flag.  WIPEOUTFRAME
    // (whether the polygon outline is drawn) is global, in WIPEOUTVARIABLES.
    if (version > DRW::AC1021)
        writer->writeBool(290, ent->clipMode);
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writePointCloud(DRW_PointCloud *ent){
    if (!preflightEntity(ent))
        return false;
    const auto finite = [](const DRW_Coord& point) {
        return std::isfinite(point.x) && std::isfinite(point.y)
            && std::isfinite(point.z);
    };
    if (ent == nullptr || version <= DRW::AC1018
        || ent->classVersion > std::numeric_limits<std::uint16_t>::max()
        || ent->sourceFileCount < 0
        || ent->sourceFileCount > static_cast<int>(DRW_PointCloud::kMaxItems)
        || ent->sourceFiles.size() != static_cast<std::size_t>(ent->sourceFileCount)
        || ent->pointCount > static_cast<std::uint64_t>(
               std::numeric_limits<std::int32_t>::max())
        || ent->showIntensity || ent->showClipping
        || ent->clippingCount != 0 || !ent->clippings.empty()) {
        m_writeError = true;
        return false;
    }
    if (!finite(ent->origin) || !finite(ent->extentsMin)
        || !finite(ent->extentsMax) || !finite(ent->ucsOrigin)
        || !finite(ent->ucsXDirection) || !finite(ent->ucsYDirection)
        || !finite(ent->ucsZDirection)
        || !std::isfinite(ent->intensityStyle.minIntensity)
        || !std::isfinite(ent->intensityStyle.maxIntensity)
        || !std::isfinite(ent->intensityStyle.lowThreshold)
        || !std::isfinite(ent->intensityStyle.highThreshold)
        || ent->intensityScheme < 0
        || ent->intensityScheme > std::numeric_limits<std::uint16_t>::max()) {
        m_writeError = true;
        return false;
    }
    EntityRecordScope scope(*this, ent);
    writer->writeString(0, "POINTCLOUD");
    if (!writeEntity(ent))
        return false;
    writer->writeString(100, "AcDbEntity");
    writer->writeString(100, "AcDbPointCloud");
    writer->writeInt16(70, ent->classVersion);
    writer->writeDouble(10, ent->origin.x);
    writer->writeDouble(20, ent->origin.y);
    writer->writeDouble(30, ent->origin.z);
    writer->writeUtf8String(1, ent->savedFilename);
    writer->writeInt32(90, ent->sourceFileCount);
    for (const UTF8STRING& srcFile : ent->sourceFiles) {
        writer->writeUtf8String(2, srcFile);
    }
    // DXF carries the geometry/reference fields for both source-file forms.
    // The source-count conditional applies to the DWG bit stream only.
    writer->writeDouble(11, ent->extentsMin.x);
    writer->writeDouble(21, ent->extentsMin.y);
    writer->writeDouble(31, ent->extentsMin.z);
    writer->writeDouble(12, ent->extentsMax.x);
    writer->writeDouble(22, ent->extentsMax.y);
    writer->writeDouble(32, ent->extentsMax.z);
    writer->writeInt32(92, static_cast<int>(ent->pointCount));
    writer->writeUtf8String(3, ent->ucsName);
    writer->writeDouble(13, ent->ucsOrigin.x);
    writer->writeDouble(23, ent->ucsOrigin.y);
    writer->writeDouble(33, ent->ucsOrigin.z);
    writer->writeDouble(210, ent->ucsXDirection.x);
    writer->writeDouble(220, ent->ucsXDirection.y);
    writer->writeDouble(230, ent->ucsXDirection.z);
    writer->writeDouble(211, ent->ucsYDirection.x);
    writer->writeDouble(221, ent->ucsYDirection.y);
    writer->writeDouble(231, ent->ucsYDirection.z);
    writer->writeDouble(212, ent->ucsZDirection.x);
    writer->writeDouble(222, ent->ucsZDirection.y);
    writer->writeDouble(232, ent->ucsZDirection.z);
    if (version > DRW::AC1024) {
        writer->writeString(330, toHexStr(ent->definitionHandle));
        writer->writeString(360, toHexStr(ent->reactorHandle));
        writer->writeInt16(71, ent->intensityScheme);
        writer->writeDouble(40, ent->intensityStyle.minIntensity);
        writer->writeDouble(41, ent->intensityStyle.maxIntensity);
        writer->writeDouble(42, ent->intensityStyle.lowThreshold);
        writer->writeDouble(43, ent->intensityStyle.highThreshold);
    }
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writePointCloudEx(DRW_PointCloudEx *ent){
    if (!preflightEntity(ent))
        return false;
    const auto finite = [](const DRW_Coord& point) {
        return std::isfinite(point.x) && std::isfinite(point.y)
            && std::isfinite(point.z);
    };
    const auto fitsUint16 = [](int value) {
        return value >= 0
            && value <= std::numeric_limits<std::uint16_t>::max();
    };
    const auto integral32 = [](double value) {
        return std::isfinite(value)
            && value >= static_cast<double>(std::numeric_limits<std::int32_t>::min())
            && value <= static_cast<double>(std::numeric_limits<std::int32_t>::max())
            && std::floor(value) == value;
    };
    if (ent == nullptr || version <= DRW::AC1024
        || ent->classVersion > std::numeric_limits<std::uint16_t>::max()
        || ent->croppingCount < 0
        || ent->croppingCount > static_cast<int>(DRW_PointCloudEx::kMaxItems)
        || ent->croppings.size() != static_cast<std::size_t>(ent->croppingCount)) {
        m_writeError = true;
        return false;
    }
    if (!finite(ent->extentsMin) || !finite(ent->extentsMax)
        || !finite(ent->ucsOrigin) || !finite(ent->ucsXDirection)
        || !finite(ent->ucsYDirection) || !finite(ent->ucsZDirection)
        || !std::isfinite(ent->elevationMin)
        || !std::isfinite(ent->elevationMax)
        || !integral32(ent->intensityMin) || !integral32(ent->intensityMax)
        || !fitsUint16(ent->stylizationType)
        || !fitsUint16(ent->intensityOutOfRangeBehavior)
        || !fitsUint16(ent->elevationOutOfRangeBehavior)) {
        m_writeError = true;
        return false;
    }
    for (const DRW_PointCloudExCropping& cropping : ent->croppings) {
        if (cropping.type < 0 || cropping.type > 0xffff
            || cropping.pointCount < 0
            || cropping.pointCount > static_cast<int>(DRW_PointCloudEx::kMaxItems)
            || cropping.points.size() != static_cast<std::size_t>(cropping.pointCount)
            || !finite(cropping.cropPlane)
            || !finite(cropping.cropXDirection)
            || !finite(cropping.cropYDirection)) {
            m_writeError = true;
            return false;
        }
        for (const DRW_Coord& point : cropping.points) {
            if (!finite(point)) {
                m_writeError = true;
                return false;
            }
        }
    }
    EntityRecordScope scope(*this, ent);
    writer->writeString(0, "POINTCLOUDEX");
    if (!writeEntity(ent))
        return false;
    writer->writeString(100, "AcDbEntity");
    writer->writeString(100, "AcDbPointCloud");
    writer->writeInt16(70, ent->classVersion);
    writer->writeDouble(10, ent->extentsMin.x);
    writer->writeDouble(20, ent->extentsMin.y);
    writer->writeDouble(30, ent->extentsMin.z);
    writer->writeDouble(11, ent->extentsMax.x);
    writer->writeDouble(21, ent->extentsMax.y);
    writer->writeDouble(31, ent->extentsMax.z);
    writer->writeDouble(12, ent->ucsOrigin.x);
    writer->writeDouble(22, ent->ucsOrigin.y);
    writer->writeDouble(32, ent->ucsOrigin.z);
    writer->writeDouble(210, ent->ucsXDirection.x);
    writer->writeDouble(220, ent->ucsXDirection.y);
    writer->writeDouble(230, ent->ucsXDirection.z);
    writer->writeDouble(211, ent->ucsYDirection.x);
    writer->writeDouble(221, ent->ucsYDirection.y);
    writer->writeDouble(231, ent->ucsYDirection.z);
    writer->writeDouble(212, ent->ucsZDirection.x);
    writer->writeDouble(222, ent->ucsZDirection.y);
    writer->writeDouble(232, ent->ucsZDirection.z);
    writer->writeBool(290, ent->isLocked);
    writer->writeString(330, toHexStr(ent->definitionHandle));
    writer->writeString(360, toHexStr(ent->reactorHandle));
    writer->writeUtf8String(1, ent->name);
    writer->writeBool(291, ent->showIntensity);
    writer->writeInt16(71, ent->stylizationType);
    writer->writeUtf8String(1, ent->intensityColorScheme);
    writer->writeUtf8String(1, ent->currentColorScheme);
    writer->writeUtf8String(1, ent->classificationColorScheme);
    writer->writeDouble(40, ent->elevationMin);
    writer->writeDouble(41, ent->elevationMax);
    writer->writeInt32(90, static_cast<std::int32_t>(ent->intensityMin));
    writer->writeInt32(91, static_cast<std::int32_t>(ent->intensityMax));
    writer->writeInt16(71, ent->intensityOutOfRangeBehavior);
    writer->writeInt16(72, ent->elevationOutOfRangeBehavior);
    writer->writeBool(292, ent->elevationApplyToFixedRange);
    writer->writeBool(293, ent->intensityAsGradient);
    writer->writeBool(294, ent->elevationAsGradient);
    writer->writeBool(295, ent->showCropping);
    writer->writeInt32(92, ent->croppingCount);
    if (ent->croppingCount == 0) {
        writer->writeInt32(93, ent->unknownInt0);
    writer->writeInt32(93, ent->unknownInt1);
    }
    for (const DRW_PointCloudExCropping& cropping : ent->croppings) {
        writer->writeInt16(280, cropping.type);
        writer->writeBool(290, cropping.isInside);
        writer->writeBool(290, cropping.isInverted);
        writer->writeDouble(13, cropping.cropPlane.x);
        writer->writeDouble(23, cropping.cropPlane.y);
        writer->writeDouble(33, cropping.cropPlane.z);
        writer->writeDouble(213, cropping.cropXDirection.x);
        writer->writeDouble(223, cropping.cropXDirection.y);
        writer->writeDouble(233, cropping.cropXDirection.z);
        writer->writeDouble(213, cropping.cropYDirection.x);
        writer->writeDouble(223, cropping.cropYDirection.y);
        writer->writeDouble(233, cropping.cropYDirection.z);
        writer->writeInt32(93, cropping.pointCount);
        for (const DRW_Coord& point : cropping.points) {
            writer->writeDouble(13, point.x);
            writer->writeDouble(23, point.y);
            writer->writeDouble(33, point.z);
        }
    }
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writePointCloudDef(DRW_PointCloudDef *ent) {
    if (!preflightTableEntry(ent))
        return false;
    if (version <= DRW::AC1009)
        return rejectUnsupportedDxfWrite("POINTCLOUDDEFINITION");

    const char *recordName = "POINTCLOUDDEFINITION";
    const char *subclassName = "AcDbPointCloudDef";
    switch (ent->m_kind) {
    case DRW_PointCloudDef::Definition:
        break;
    case DRW_PointCloudDef::DefinitionEx:
        recordName = "POINTCLOUDDEFINITIONEX";
        subclassName = "AcDbPointCloudDefEx";
        break;
    case DRW_PointCloudDef::Reactor:
        recordName = "POINTCLOUDDEFREACTOR";
        subclassName = "AcDbPointCloudDefReactor";
        break;
    case DRW_PointCloudDef::ReactorEx:
        recordName = "POINTCLOUDDEFREACTOREX";
        subclassName = "AcDbPointCloudDefReactorEx";
        break;
    default:
        m_writeError = true;
        return false;
    }
    if (ent->m_classVersion < 0
        || ent->m_classVersion > DRW_PointCloudDef::kMaxClassVersion
        || ent->m_pointCount > DRW_PointCloudDef::kMaxPointCount) {
        m_writeError = true;
        return false;
    }

    EntityRecordScope scope(*this, ent);
    writer->writeString(0, recordName);
    writer->writeString(5, toHexStr(ent->handle));
    if (!writeTableEntryAppData(*ent))
        return false;
    writeObjectOwner(static_cast<std::uint32_t>(ent->parentHandle));
    writer->writeString(100, subclassName);
    writer->writeInt32(90, ent->m_classVersion);
    if (ent->m_kind == DRW_PointCloudDef::Definition
        || ent->m_kind == DRW_PointCloudDef::DefinitionEx) {
        writer->writeUtf8String(1, ent->m_sourceFilename);
        writer->writeInt16(280, ent->m_isLoaded ? 1 : 0);
        writer->writeInt64(160, static_cast<std::int64_t>(ent->m_pointCount));
        writer->writeDouble(10, ent->m_extentsMin.x);
        writer->writeDouble(20, ent->m_extentsMin.y);
        writer->writeDouble(30, ent->m_extentsMin.z);
        writer->writeDouble(11, ent->m_extentsMax.x);
        writer->writeDouble(21, ent->m_extentsMax.y);
        writer->writeDouble(31, ent->m_extentsMax.z);
    }
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeNavisworksModelDef(DRW_NavisworksModelDef *ent) {
    if (!preflightTableEntry(ent))
        return false;
    if (version <= DRW::AC1009)
        return rejectUnsupportedDxfWrite("NAVISWORKSMODELDEF");
    if (ent->m_flags < 0 || ent->m_flags > DRW_NavisworksModelDef::kMaxFlags
        || ent->m_path.size() > DRW_NavisworksModelDef::kMaxPathLength) {
        m_writeError = true;
        return false;
    }
    EntityRecordScope scope(*this, ent);
    writer->writeString(0, "NAVISWORKSMODELDEF");
    writer->writeString(5, toHexStr(ent->handle));
    if (!writeTableEntryAppData(*ent))
        return false;
    writeObjectOwner(static_cast<std::uint32_t>(ent->parentHandle));
    writer->writeString(100, "AcDbNavisworksModelDef");
    writer->writeInt16(70, static_cast<std::int16_t>(ent->m_flags));
    writer->writeUtf8String(1, ent->m_path);
    writer->writeBool(290, ent->m_status);
    writer->writeDouble(10, ent->m_minExtent.x);
    writer->writeDouble(20, ent->m_minExtent.y);
    writer->writeDouble(30, ent->m_minExtent.z);
    writer->writeDouble(11, ent->m_maxExtent.x);
    writer->writeDouble(21, ent->m_maxExtent.y);
    writer->writeDouble(31, ent->m_maxExtent.z);
    writer->writeBool(291, ent->m_hostDrawingVisibility);
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writePointCloudColorMap(DRW_PointCloudColorMap *ent) {
    if (!preflightTableEntry(ent))
        return false;
    if (version <= DRW::AC1009)
        return rejectUnsupportedDxfWrite("POINTCLOUDCOLORMAP");
    if (ent->m_classVersion < 0
        || ent->m_classVersion > DRW_PointCloudColorMap::kMaxClassVersion
        || ent->m_colorRamps.size() > DRW_PointCloudColorMap::kMaxRamps
        || ent->m_classificationColorRamps.size() > DRW_PointCloudColorMap::kMaxRamps
        || ent->m_colorRampCount != ent->m_colorRamps.size()
        || ent->m_classificationColorRampCount
               != ent->m_classificationColorRamps.size())
    {
        m_writeError = true;
        return false;
    }
    const auto validScheme = [](const UTF8STRING& scheme) {
        return scheme.size() <= DRW_PointCloudColorMap::kMaxColorSchemeLength;
    };
    if (!validScheme(ent->m_defaultIntensityColorScheme)
        || !validScheme(ent->m_defaultElevationColorScheme)
        || !validScheme(ent->m_defaultClassificationColorScheme)) {
        m_writeError = true;
        return false;
    }

    EntityRecordScope scope(*this, ent);
    writer->writeString(0, "POINTCLOUDCOLORMAP");
    writer->writeString(5, toHexStr(ent->handle));
    if (!writeTableEntryAppData(*ent))
        return false;
    writeObjectOwner(static_cast<std::uint32_t>(ent->parentHandle));
    writer->writeString(100, "AcDbPointCloudColorMap");
    writer->writeInt32(90, ent->m_classVersion);
    writer->writeUtf8String(1, ent->m_defaultIntensityColorScheme);
    writer->writeUtf8String(1, ent->m_defaultElevationColorScheme);
    writer->writeUtf8String(1, ent->m_defaultClassificationColorScheme);
    const auto writeRamps = [&](const std::vector<DRW_PointCloudColorMapRamp>& ramps) {
        for (const auto& ramp : ramps) {
            if (ramp.m_classVersion < 0
                || ramp.m_classVersion > DRW_PointCloudColorMap::kMaxClassVersion
                || ramp.m_rampCount < ramp.m_colorSchemes.size()
                || ramp.m_rampCount > DRW_PointCloudColorMap::kMaxColorsPerRamp)
            {
                m_writeError = true;
                return false;
            }
            writer->writeInt32(91, static_cast<std::int32_t>(ramp.m_rampCount));
            writer->writeInt32(90, ramp.m_classVersion);
            for (const UTF8STRING& scheme : ramp.m_colorSchemes) {
                if (!validScheme(scheme)) {
                    m_writeError = true;
                    return false;
                }
                writer->writeUtf8String(1, scheme);
            }
        }
        return true;
    };
    if (!writeRamps(ent->m_colorRamps))
        return false;
    if (!ent->m_classificationColorRamps.empty()) {
        writer->writeInt16(70, 1);
        if (!writeRamps(ent->m_classificationColorRamps))
            return false;
    }
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeNavisworksModel(DRW_NavisworksModel *ent) {
    if (!preflightEntity(ent))
        return false;
    if (version < DRW::AC1015)
        return rejectUnsupportedDxfWrite("NAVISWORKSMODEL");
    if (!std::isfinite(ent->unitFactor)
        || !std::all_of(ent->transform.begin(), ent->transform.end(),
                        [](double value) { return std::isfinite(value); })) {
        m_writeError = true;
        return false;
    }
    EntityRecordScope scope(*this, ent);
    writer->writeString(0, "NAVISWORKSMODEL");
    if (!writeEntity(ent))
        return false;
    writer->writeString(100, "AcDbNavisworksModel");
    writer->writeInt16(70, ent->flags);
    if (ent->definitionHandle != 0)
        writer->writeString(340, toHexStr(ent->definitionHandle));
    for (double value : ent->transform)
        writer->writeDouble(40, value);
    writer->writeDouble(40, ent->unitFactor);
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeSurface(DRW_Surface *ent){
    if (ent == nullptr) {
        m_writeError = true;
        return false;
    }
    if (version <= DRW::AC1018)
        return rejectUnsupportedDxfWrite("SURFACE");
    if (!preflightEntity(ent)
        || ent->modelerFormatVersion < 0
        || ent->modelerFormatVersion > std::numeric_limits<std::int16_t>::max()
        || ent->uIsolines < 0
        || ent->uIsolines > std::numeric_limits<std::int16_t>::max()
        || ent->vIsolines < 0
        || ent->vIsolines > std::numeric_limits<std::int16_t>::max())
        return false;
    const auto fail = [this]() {
        m_writeError = true;
        return false;
    };
    if (ent->hasRawDwgBody || ent->rawDwgBodyBitSize != 0
        || ent->dwgPayloadDecoded || ent->dwgClassNum != 0
        || ent->hasDataStorageBinaryData() || ent->hasDataStorageRecord
        || !ent->dataStorageData.empty()
        || (!ent->rawAcisData.empty()
            && (version > DRW::AC1024
                || !hasDxfTextPayloadChunks(ent->rawAcisData,
                                            ent->dxfPayloadChunks))))
        return fail();
    std::string entType;
    const char *subclassType = nullptr;
    switch (ent->eType) {
    case DRW::PLANESURFACE: entType = "PLANESURFACE"; break;
    case DRW::EXTRUDEDSURFACE:
        entType = "EXTRUDEDSURFACE";
        subclassType = "AcDbExtrudedSurface";
        break;
    case DRW::REVOLVEDSURFACE:
        entType = "REVOLVEDSURFACE";
        subclassType = "AcDbRevolvedSurface";
        break;
    case DRW::SWEPTSURFACE:
        entType = "SWEPTSURFACE";
        subclassType = "AcDbSweptSurface";
        break;
    case DRW::LOFTEDSURFACE:
        entType = "LOFTEDSURFACE";
        subclassType = "AcDbLoftedSurface";
        break;
    case DRW::NURBSURFACE:
        entType = "NURBSSURFACE";
        subclassType = "AcDbNurbSurface";
        break;
    default: return fail();
    }
    EntityRecordScope scope(*this, ent);
    writer->writeString(0, entType);
    if (!writeEntity(ent))
        return false;
    writer->writeString(100, "AcDbEntity");
    writer->writeString(100, "AcDbModelerGeometry");
    if (!ent->rawAcisData.empty())
        writeDxfTextChunks(writer.get(), ent->rawAcisData);
    writer->writeInt16(70, ent->modelerFormatVersion);
    writer->writeString(100, "AcDbSurface");
    writer->writeInt16(71, ent->uIsolines);
    writer->writeInt16(72, ent->vIsolines);
    if (subclassType != nullptr)
        writer->writeString(100, subclassType);
    if (ent->eType == DRW::REVOLVEDSURFACE) {
        const auto *revolved = dynamic_cast<const DRW_RevolvedSurface *>(ent);
        if (revolved == nullptr
            || revolved->id >
                   static_cast<std::uint32_t>(std::numeric_limits<std::int32_t>::max())
            || revolved->dxfBinaryData.size() >
                   DRW::kMaxDxfBinaryPayloadBytes
            || !std::isfinite(revolved->axisPoint.x)
            || !std::isfinite(revolved->axisPoint.y)
            || !std::isfinite(revolved->axisPoint.z)
            || !std::isfinite(revolved->axisVector.x)
            || !std::isfinite(revolved->axisVector.y)
            || !std::isfinite(revolved->axisVector.z)
            || !std::isfinite(revolved->revolveAngle)
            || !std::isfinite(revolved->startAngle)
            || !std::isfinite(revolved->draftAngle)
            || !std::isfinite(revolved->draftStartDistance)
            || !std::isfinite(revolved->draftEndDistance)
            || !std::isfinite(revolved->twistAngle)
            || !std::all_of(revolved->transform.begin(), revolved->transform.end(),
                            [](double value) { return std::isfinite(value); })) {
            return fail();
        }
        writer->writeInt32(90, static_cast<std::int32_t>(revolved->id));
        writer->writeInt32(90,
                           static_cast<std::int32_t>(revolved->dxfBinaryData.size()));
        if (!revolved->dxfBinaryData.empty())
            writeDxfBinaryChunks(writer.get(), revolved->dxfBinaryData);
        writer->writeDouble(10, revolved->axisPoint.x);
        writer->writeDouble(20, revolved->axisPoint.y);
        writer->writeDouble(30, revolved->axisPoint.z);
        writer->writeDouble(11, revolved->axisVector.x);
        writer->writeDouble(21, revolved->axisVector.y);
        writer->writeDouble(31, revolved->axisVector.z);
        writer->writeDouble(40, revolved->revolveAngle);
        writer->writeDouble(41, revolved->startAngle);
        for (double value : revolved->transform)
            writer->writeDouble(42, value);
        writer->writeDouble(43, revolved->draftAngle);
        writer->writeDouble(44, revolved->draftStartDistance);
        writer->writeDouble(45, revolved->draftEndDistance);
        writer->writeDouble(46, revolved->twistAngle);
        writer->writeBool(290, revolved->solid);
        writer->writeBool(291, revolved->closeToAxis);
    } else if (ent->eType == DRW::EXTRUDEDSURFACE) {
        const auto *extruded = dynamic_cast<const DRW_ExtrudedSurface *>(ent);
        const auto finiteCoord = [](const DRW_Coord& value) {
            return std::isfinite(value.x) && std::isfinite(value.y)
                && std::isfinite(value.z);
        };
        const auto validPathFlags = [](std::int32_t value) {
            return value >= 0 && value <=
                static_cast<std::int32_t>(std::numeric_limits<std::int16_t>::max());
        };
        if (extruded == nullptr
            || extruded->classId >
                   static_cast<std::uint32_t>(std::numeric_limits<std::int32_t>::max())
            || extruded->dxfBinaryData.size() >
                   DRW::kMaxDxfBinaryPayloadBytes
            || !finiteCoord(extruded->sweepVector)
            || !finiteCoord(extruded->referenceVector)
            || extruded->sweepAlignmentFlags < 0
            || extruded->sweepAlignmentFlags > 3
            || !validPathFlags(extruded->pathFlags)
            || !std::all_of(extruded->extrudedTransform.begin(),
                            extruded->extrudedTransform.end(),
                            [](double value) { return std::isfinite(value); })
            || !std::all_of(extruded->sweepEntityTransform.begin(),
                            extruded->sweepEntityTransform.end(),
                            [](double value) { return std::isfinite(value); })
            || !std::all_of(extruded->pathEntityTransform.begin(),
                            extruded->pathEntityTransform.end(),
                            [](double value) { return std::isfinite(value); })
            || !std::isfinite(extruded->draftAngle)
            || !std::isfinite(extruded->draftStartDistance)
            || !std::isfinite(extruded->draftEndDistance)
            || !std::isfinite(extruded->twistAngle)
            || !std::isfinite(extruded->scaleFactor)
            || !std::isfinite(extruded->alignAngle)) {
            return fail();
        }
        writer->writeInt32(90, static_cast<std::int32_t>(extruded->classId));
        writer->writeInt32(90,
                           static_cast<std::int32_t>(extruded->dxfBinaryData.size()));
        if (!extruded->dxfBinaryData.empty())
            writeDxfBinaryChunks(writer.get(), extruded->dxfBinaryData);
        writer->writeDouble(10, extruded->sweepVector.x);
        writer->writeDouble(20, extruded->sweepVector.y);
        writer->writeDouble(30, extruded->sweepVector.z);
        for (double value : extruded->extrudedTransform)
            writer->writeDouble(40, value);
        writer->writeDouble(42, extruded->draftAngle);
        writer->writeDouble(43, extruded->draftStartDistance);
        writer->writeDouble(44, extruded->draftEndDistance);
        writer->writeDouble(45, extruded->twistAngle);
        writer->writeDouble(48, extruded->scaleFactor);
        writer->writeDouble(49, extruded->alignAngle);
        for (double value : extruded->sweepEntityTransform)
            writer->writeDouble(46, value);
        for (double value : extruded->pathEntityTransform)
            writer->writeDouble(47, value);
        writer->writeBool(290, extruded->solid);
        writer->writeInt16(70, extruded->sweepAlignmentFlags);
        writer->writeInt16(71, extruded->pathFlags);
        writer->writeBool(292, extruded->alignStart);
        writer->writeBool(293, extruded->bank);
        writer->writeBool(294, extruded->basePointSet);
        writer->writeBool(295, extruded->sweepEntityTransformComputed);
        writer->writeBool(296, extruded->pathEntityTransformComputed);
        writer->writeDouble(11, extruded->referenceVector.x);
        writer->writeDouble(21, extruded->referenceVector.y);
        writer->writeDouble(31, extruded->referenceVector.z);
    } else if (ent->eType == DRW::SWEPTSURFACE) {
        const auto *swept = dynamic_cast<const DRW_SweptSurface *>(ent);
        const auto finiteCoord = [](const DRW_Coord& value) {
            return std::isfinite(value.x) && std::isfinite(value.y)
                && std::isfinite(value.z);
        };
        const auto validPathFlags = [](std::int32_t value) {
            return value >= 0 && value <=
                static_cast<std::int32_t>(std::numeric_limits<std::int16_t>::max());
        };
        const auto finiteMatrix = [](const auto& matrix) {
            return std::all_of(matrix.begin(), matrix.end(),
                               [](double value) { return std::isfinite(value); });
        };
        if (swept == nullptr
            || swept->sweepEntityId >
                   static_cast<std::uint32_t>(std::numeric_limits<std::int32_t>::max())
            || swept->pathEntityId >
                   static_cast<std::uint32_t>(std::numeric_limits<std::int32_t>::max())
            || swept->sweepData.size() > DRW::kMaxDxfBinaryPayloadBytes
            || swept->pathData.size() > DRW::kMaxDxfBinaryPayloadBytes
            || !finiteCoord(swept->referenceVector)
            || swept->sweepAlignmentFlags < 0
            || swept->sweepAlignmentFlags > 3
            || !validPathFlags(swept->pathFlags)
            || !finiteMatrix(swept->sweepEntityTransformed)
            || !finiteMatrix(swept->pathEntityTransformed)
            || !finiteMatrix(swept->sweepEntityTransform)
            || !finiteMatrix(swept->pathEntityTransform)
            || !std::isfinite(swept->draftAngle)
            || !std::isfinite(swept->draftStartDistance)
            || !std::isfinite(swept->draftEndDistance)
            || !std::isfinite(swept->twistAngle)
            || !std::isfinite(swept->scaleFactor)
            || !std::isfinite(swept->alignAngle)) {
            return fail();
        }
        writer->writeInt32(90, static_cast<std::int32_t>(swept->sweepEntityId));
        writer->writeInt32(90,
                           static_cast<std::int32_t>(swept->sweepData.size()));
        if (!swept->sweepData.empty())
            writeDxfBinaryChunks(writer.get(), swept->sweepData);
        writer->writeInt32(90, static_cast<std::int32_t>(swept->pathEntityId));
        writer->writeInt32(90,
                           static_cast<std::int32_t>(swept->pathData.size()));
        if (!swept->pathData.empty())
            writeDxfBinaryChunks(writer.get(), swept->pathData);
        for (double value : swept->sweepEntityTransformed)
            writer->writeDouble(40, value);
        for (double value : swept->pathEntityTransformed)
            writer->writeDouble(41, value);
        writer->writeDouble(42, swept->draftAngle);
        writer->writeDouble(43, swept->draftStartDistance);
        writer->writeDouble(44, swept->draftEndDistance);
        writer->writeDouble(45, swept->twistAngle);
        writer->writeDouble(48, swept->scaleFactor);
        writer->writeDouble(49, swept->alignAngle);
        for (double value : swept->sweepEntityTransform)
            writer->writeDouble(46, value);
        for (double value : swept->pathEntityTransform)
            writer->writeDouble(47, value);
        writer->writeBool(290, swept->solid);
        writer->writeInt16(70, swept->sweepAlignmentFlags);
        writer->writeInt16(71, swept->pathFlags);
        writer->writeBool(292, swept->alignStart);
        writer->writeBool(293, swept->bank);
        writer->writeBool(294, swept->basePointSet);
        writer->writeBool(295, swept->sweepEntityTransformComputed);
        writer->writeBool(296, swept->pathEntityTransformComputed);
        writer->writeDouble(11, swept->referenceVector.x);
        writer->writeDouble(21, swept->referenceVector.y);
        writer->writeDouble(31, swept->referenceVector.z);
    } else if (ent->eType == DRW::LOFTEDSURFACE) {
        const auto *lofted = dynamic_cast<const DRW_LoftedSurface *>(ent);
        const auto finiteMatrix = [](const auto& matrix) {
            return std::all_of(matrix.begin(), matrix.end(),
                               [](double value) { return std::isfinite(value); });
        };
        if (lofted == nullptr
            || lofted->numCrossSections < 0
            || lofted->numGuideCurves < 0
            || lofted->numCrossSections >
                   static_cast<std::int32_t>(DRW_LoftedSurface::kMaxReferenceTokenCount)
            || lofted->numGuideCurves >
                   static_cast<std::int32_t>(DRW_LoftedSurface::kMaxReferenceTokenCount)
            || lofted->planeNormalLoftingType < 0
            || lofted->planeNormalLoftingType >
                   std::numeric_limits<std::int16_t>::max()
            || lofted->dxfReferenceData.size() >
                   DRW_LoftedSurface::kMaxReferenceTokenCount
            || !finiteMatrix(lofted->loftEntityTransform)
            || !std::isfinite(lofted->startDraftAngle)
            || !std::isfinite(lofted->endDraftAngle)
            || !std::isfinite(lofted->startDraftMagnitude)
            || !std::isfinite(lofted->endDraftMagnitude)) {
            return fail();
        }
        std::size_t referenceDataSize = 0;
        for (const DRW_Variant& value : lofted->dxfReferenceData) {
            if (value.code() == 90 && value.type() == DRW_Variant::INTEGER) {
                if (value.i_val() < 0
                    || value.i_val() > static_cast<std::int32_t>(
                           DRW_LoftedSurface::kMaxReferenceTokenCount)) {
                    return fail();
                }
            } else if (value.code() == 310
                       && value.type() == DRW_Variant::BINARY) {
                const auto *bytes = value.binary();
                if (bytes == nullptr
                    || bytes->size() > DRW_LoftedSurface::kMaxReferenceDataSize
                    || referenceDataSize >
                           DRW_LoftedSurface::kMaxReferenceDataSize - bytes->size()) {
                    return fail();
                }
                referenceDataSize += bytes->size();
            } else {
                return fail();
            }
        }
        for (double value : lofted->loftEntityTransform)
            writer->writeDouble(40, value);
        for (const DRW_Variant& value : lofted->dxfReferenceData) {
            if (value.code() == 90)
                writer->writeInt32(90, value.i_val());
            else
                writeDxfBinaryChunks(writer.get(), *value.binary());
        }
        writer->writeInt16(70, lofted->planeNormalLoftingType);
        writer->writeDouble(41, lofted->startDraftAngle);
        writer->writeDouble(42, lofted->endDraftAngle);
        writer->writeDouble(43, lofted->startDraftMagnitude);
        writer->writeDouble(44, lofted->endDraftMagnitude);
        writer->writeBool(290, lofted->arcLengthParameterization);
        writer->writeBool(291, lofted->noTwist);
        writer->writeBool(292, lofted->alignDirection);
        writer->writeBool(293, lofted->simpleSurfaces);
        writer->writeBool(294, lofted->closedSurfaces);
        writer->writeBool(295, lofted->solid);
        writer->writeBool(296, lofted->ruledSurface);
        writer->writeBool(297, lofted->virtualGuide);
        if (lofted->pathCurveHandle != 0)
            writer->writeString(5, toHexStr(lofted->pathCurveHandle));
    } else if (ent->eType == DRW::NURBSURFACE) {
        const auto *nurbs = dynamic_cast<const DRW_NurbsSurface *>(ent);
        const auto finiteCoord = [](const DRW_Coord& value) {
            return std::isfinite(value.x) && std::isfinite(value.y)
                && std::isfinite(value.z);
        };
        if (nurbs == nullptr
            || nurbs->short170 >
                   static_cast<std::uint16_t>(std::numeric_limits<std::int16_t>::max())
            || !finiteCoord(nurbs->uvec1) || !finiteCoord(nurbs->vvec1)
            || !finiteCoord(nurbs->uvec2) || !finiteCoord(nurbs->vvec2)) {
            return fail();
        }
        if (version >= DRW::AC1027) {
            writer->writeInt16(170, nurbs->short170);
            writer->writeBool(290, nurbs->cvHullDisplay);
            writer->writeDouble(10, nurbs->uvec1.x);
            writer->writeDouble(20, nurbs->uvec1.y);
            writer->writeDouble(30, nurbs->uvec1.z);
            writer->writeDouble(11, nurbs->vvec1.x);
            writer->writeDouble(21, nurbs->vvec1.y);
            writer->writeDouble(31, nurbs->vvec1.z);
            writer->writeDouble(12, nurbs->uvec2.x);
            writer->writeDouble(22, nurbs->uvec2.y);
            writer->writeDouble(32, nurbs->uvec2.z);
            writer->writeDouble(13, nurbs->vvec2.x);
            writer->writeDouble(23, nurbs->vvec2.y);
            writer->writeDouble(33, nurbs->vvec2.z);
        }
    }
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return fail();
    return !writer->hasWriteError();
}

bool dxfRW::writeModelerGeometry(DRW_ModelerGeometry *ent) {
    if (version <= DRW::AC1009) {
        recordOperationDiagnostic(writingBlock ? DRW::OperationPhase::Blocks
                                               : DRW::OperationPhase::Entities,
            DRW::OperationCause::UnsupportedVersion, "unsupported-modeler-target",
            "3DSOLID/REGION/BODY is unavailable in this DXF target", 0, false,
            ent != nullptr ? ent->handle : 0,
            ent != nullptr && ent->handle != DRW::NoHandle);
        return rejectUnsupportedDxfWrite("3DSOLID/REGION/BODY");
    }
    if (!preflightEntity(ent))
        return false;
    const bool writeAc1027Shell = version >= DRW::AC1027;
    if (!writeAc1027Shell
        && (ent->m_hasDxfModelerFlag || ent->m_hasDxfModelerUid))
        return rejectUnsupportedDxfWrite("3DSOLID/REGION/BODY");
    if (ent->m_hasDxfModelerUid
        && !isSafeDxfRecordText(ent->m_dxfModelerUid)) {
        m_writeError = true;
        return false;
    }
    const bool writeAc1015SatV1 = version == DRW::AC1015
        && hasQualifiedAc1015SatV1Payload(*ent);
    const bool writeR2013PlusSab = isAcdsDxfVersion(version)
        && hasQualifiedR2013PlusAcdsRecord(
            *ent, m_rawDxfSections, version);
    DRW_DBG("dxfRW::writeModelerGeometry R2013+ ACDSDATA SAB qualified: ");
    DRW_DBG(writeR2013PlusSab);
    DRW_DBG("\n");
    DRW_DBG("dxfRW::writeModelerGeometry AC1015 SAT v1 qualified: ");
    DRW_DBG(writeAc1015SatV1);
    DRW_DBG(" payload bytes: ");
    DRW_DBG(ent->m_dwgAcisPayload.size());
    DRW_DBG(" modeler version: ");
    DRW_DBG(ent->m_modelerVersion);
    DRW_DBG(" empty: ");
    DRW_DBG(ent->m_isEmpty);
    DRW_DBG(" has modeler data: ");
    DRW_DBG(ent->m_hasModelerData);
    DRW_DBG(" source version: ");
    DRW_DBG(static_cast<int>(ent->m_dwgSourceVersion));
    DRW_DBG(" object size: ");
    DRW_DBG(ent->m_objectSize);
    DRW_DBG(" retained raw frame bytes: ");
    DRW_DBG(ent->m_rawBytes.size());
    DRW_DBG(" ranges: ");
    DRW_DBG(ent->m_payloadRanges.size());
    DRW_DBG(" raw bytes: ");
    DRW_DBG(ent->m_rawBytes.size());
    DRW_DBG(" dxf chunks: ");
    DRW_DBG(ent->m_dxfPayloadChunks.size());
    DRW_DBG(" data-storage record: ");
    DRW_DBG(ent->hasDataStorageRecord);
    DRW_DBG(" unknown bit: ");
    DRW_DBG(ent->m_modelerDataUnknownBit);
    DRW_DBG("\n");
    const bool hasUnqualifiedDwgPayload = !writeAc1015SatV1
        && !writeR2013PlusSab
        && (ent->m_bodyBitSize != 0
        || ent->m_objectSize != 0 || ent->m_hasModelerData
        || ent->m_modelerDataUnknownBit || !ent->m_payloadRanges.empty()
        || !ent->m_dwgAcisPayload.empty()
        || ent->hasDataStorageBinaryData() || ent->hasDataStorageRecord
        || !ent->dataStorageData.empty());
    if (hasUnqualifiedDwgPayload
        || (!writeAc1015SatV1 && !writeR2013PlusSab
            && !ent->m_rawBytes.empty()
            && (version > DRW::AC1024
                || !hasDxfTextPayloadChunks(ent->m_rawBytes,
                                            ent->m_dxfPayloadChunks)))) {
        recordOperationDiagnostic(writingBlock ? DRW::OperationPhase::Blocks
                                               : DRW::OperationPhase::Entities,
            DRW::OperationCause::ValidationFailure, "unrepresentable-modeler-carrier",
            "modeler payload has no supported representation for this DXF target",
            0, false, ent->handle, ent->handle != DRW::NoHandle);
        return rejectUnsupportedDxfWrite();
    }

    const char *recordName = modelerGeometryDxfName(ent->eType);
    if (recordName == nullptr)
        return rejectUnsupportedDxfWrite();
    const bool writeSolidHistory = ent->eType == DRW::E3DSOLID
        && version >= DRW::AC1021;
    if (ent->m_historyHandle != 0 && !writeSolidHistory)
        return rejectUnsupportedDxfWrite();

    EntityRecordScope scope(*this, ent);
    writer->writeString(0, recordName);
    if (!writeEntity(ent))
        return false;
    writer->writeString(100, "AcDbModelerGeometry");
    if (writeAc1027Shell) {
        if (ent->m_hasDxfModelerFlag)
            writer->writeBool(290, ent->m_dxfModelerFlag);
        if (ent->m_hasDxfModelerUid)
            writer->writeUtf8String(2, ent->m_dxfModelerUid);
    } else {
        writer->writeInt16(70, ent->m_modelerVersion);
    }
    if (writeAc1015SatV1) {
        if (!writeDxfSatV1Text(writer.get(), ent->m_dwgAcisPayload))
            return failDxfWrite();
    } else if (!writeR2013PlusSab && !ent->m_rawBytes.empty()) {
        if (!writeDxfSatTextPayloadChunks(writer.get(), ent->m_rawBytes,
                                          ent->m_dxfPayloadChunks, binFile))
            return failDxfWrite();
    }
    // SAT belongs to AcDbModelerGeometry. Only R2007+ 3DSOLID has the
    // following subclass/history pair; REGION and BODY have no such subclass.
    if (writeSolidHistory) {
        writer->writeString(100, "AcDb3dSolid");
        writer->writeString(350, toHexStr(remapObjectHandle(ent->m_historyHandle)));
    }
    if (!ent->extData.empty() && !writeExtData(ent->extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeBlockRecord(std::string name, int insUnits) {
    return writeBlockRecord(std::move(name), insUnits, {});
}

bool dxfRW::writeBlockRecord(
    std::string name, int insUnits,
    const std::vector<std::uint8_t>& previewData) {
    return writeBlockRecord(std::move(name), insUnits, previewData, {});
}

bool dxfRW::writeBlockRecord(
    std::string name, int insUnits,
    const std::vector<std::uint8_t>& previewData,
    const std::vector<std::uint32_t>& insertHandles) {
    return writeBlockRecord(std::move(name), insUnits, previewData,
                            insertHandles, {});
}

bool dxfRW::writeBlockRecord(
    std::string name, int insUnits,
    const std::vector<std::uint8_t>& previewData,
    const std::vector<std::uint32_t>& insertHandles,
    const std::vector<DRW_Variant*>& extData) {
    if (!preflightDxfWrite())
        return false;
    if (version <= DRW::AC1009 && !extData.empty()) {
        m_writeError = true;
        return false;
    }
    if (version > DRW::AC1009
        && previewData.size() > DRW::kMaxDxfBinaryPayloadBytes) {
        m_writeError = true;
        return false;
    }
    if (version <= DRW::AC1014 && !insertHandles.empty()) {
        m_writeError = true;
        return false;
    }
    if (insertHandles.size() > DRW::kMaxDxfBlockRecordInsertHandles) {
        m_writeError = true;
        return false;
    }
    std::set<std::uint32_t> uniqueInsertHandles;
    for (const std::uint32_t insertHandle : insertHandles) {
        if (insertHandle == DRW::NoHandle
            || !uniqueInsertHandles.insert(insertHandle).second) {
            m_writeError = true;
            return false;
        }
    }
    if (!preflightDxfXdataAppIds(extData))
        return false;
    if (version > DRW::AC1009) {
        const std::string key = dxfSymbolNameKey(name);
        if (writer == nullptr || key.empty() || blockMap.count(key) != 0) {
            m_writeError = true;
            return false;
        }
        PendingDxfBlockRecord record;
        try {
            if (!allocateDxfHandle(record.handle))
                return false;
            std::uint32_t blockHandle = 0;
            std::uint32_t endBlockHandle = 0;
            if (!checkedDxfHandleOffset(record.handle, 1, blockHandle)
                || !checkedDxfHandleOffset(record.handle, 2,
                                            endBlockHandle)) {
                throw std::overflow_error("DXF block handle range exhausted");
            }
            m_handleAllocator->reserve(blockHandle);  // BLOCK
            m_handleAllocator->reserve(endBlockHandle);  // ENDBLK
        } catch (...) {
            m_writeError = true;
            return false;
        }
        record.name = std::move(name);
        record.insUnits = insUnits;
        record.previewData = previewData;
        record.insertHandles = insertHandles;
        try {
            record.extData.reserve(extData.size());
            for (const DRW_Variant* value : extData) {
                if (value == nullptr) {
                    m_writeError = true;
                    return false;
                }
                record.extData.push_back(
                    std::make_shared<DRW_Variant>(*value));
            }
        } catch (...) {
            m_writeError = true;
            return false;
        }

        if (m_collectingBlockRecords) {
            const std::uint32_t recordHandle = record.handle;
            const std::size_t mutationCheckpoint = m_dxfWriteMutations.size();
            try {
                if (m_recordStateScopeDepth != 0) {
                    m_dxfWriteMutations.push_back({
                        DxfWriteMutationKind::BlockMapInsert, key, 0, 0,
                        false});
                }
                const auto inserted = blockMap.emplace(key, record.handle);
                if (!inserted.second) {
                    m_dxfWriteMutations.resize(mutationCheckpoint);
                    m_writeError = true;
                    return false;
                }
                m_pendingBlockRecords.push_back(std::move(record));
            } catch (...) {
                blockMap.erase(key);
                if (m_pendingBlockRecords.size() > 0
                    && m_pendingBlockRecords.back().handle == recordHandle)
                    m_pendingBlockRecords.pop_back();
                m_dxfWriteMutations.resize(mutationCheckpoint);
                m_writeError = true;
                return false;
            }
            return true;
        }
        RecordStateScope state(*this);
        DxfWriterRecordScope bytes(*writer);
        const std::size_t mutationCheckpoint = m_dxfWriteMutations.size();
        try {
            m_dxfWriteMutations.push_back({
                DxfWriteMutationKind::BlockMapInsert, key, 0, 0, false});
            const auto inserted = blockMap.emplace(key, record.handle);
            if (!inserted.second) {
                m_dxfWriteMutations.resize(mutationCheckpoint);
                m_writeError = true;
                return false;
            }
        } catch (...) {
            m_writeError = true;
            return false;
        }
        if (!emitBlockRecord(record) || writer->hasWriteError())
            return false;
        if (!preflightDxfWrite() || !bytes.commit()) {
            m_writeError = true;
            return false;
        }
        state.commit();
        return true;
    }
    return true;
}

bool dxfRW::preflightDxfXdataAppIds(
        const std::vector<DRW_Variant*>& extData) {
    if (!preflightDxfWrite())
        return false;
    if (extData.empty())
        return true;

    std::vector<std::string> appIds;
    if (!validateDxfXdataGroups(
            extData, [](DRW_Variant* value) { return value; }, &appIds)) {
        recordOperationDiagnostic(
            DRW::OperationPhase::Validation,
            DRW::OperationCause::ValidationFailure,
            "xdata-group-structure",
            "XDATA must have unique APPID groups and balanced controls");
        m_writeError = true;
        return false;
    }
    try {
        for (std::string& appId : appIds)
            m_requiredDxfXdataAppIds.insert(std::move(appId));
    } catch (...) {
        m_writeError = true;
        return false;
    }
    return true;
}

bool dxfRW::validateDxfXdataAppIdRegistrations() {
    for (const std::string& appId : m_requiredDxfXdataAppIds) {
        if (m_registeredDxfXdataAppIds.count(appId) != 0)
            continue;
        recordOperationDiagnostic(
            DRW::OperationPhase::Validation,
            DRW::OperationCause::ValidationFailure,
            "xdata-appid-unregistered",
            "XDATA references an APPID not emitted in the APPID table");
        m_writeError = true;
        return false;
    }
    return true;
}

bool dxfRW::emitBlockRecord(const PendingDxfBlockRecord& record) {
    if (!preflightDxfWrite() || version <= DRW::AC1009 || record.handle == 0
        || record.name.empty()) {
        m_writeError = true;
        return false;
    }
    writer->writeString(0, "BLOCK_RECORD");
    writer->writeString(5, toHexStr(record.handle));
    if (version > DRW::AC1014)
        writer->writeString(330, "1");
    writer->writeString(100, "AcDbSymbolTableRecord");
    writer->writeString(100, "AcDbBlockTableRecord");
    writer->writeUtf8String(2, record.name);
    if (!writeSourceBlockRecordExtensionDictionary(record.handle))
        return false;
    if (version >= DRW::AC1015
        && !writeSourceBlockRecordLayoutLink(record.handle))
        return false;
    if (version > DRW::AC1018) {
        writer->writeInt16(70, record.insUnits);
        writer->writeInt16(280, 1);
        writer->writeInt16(281, 0);
    }
    if (!record.previewData.empty())
        writeDxfBinaryChunks(writer.get(), record.previewData);
    if (version > DRW::AC1014 && !record.insertHandles.empty()) {
        writer->writeString(102, "{BLKREFS");
        for (const std::uint32_t insertHandle : record.insertHandles)
            writer->writeString(331, toHexStr(insertHandle));
        writer->writeString(102, "}");
    }
    if (!record.extData.empty() && !writeExtData(record.extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::completeCurrentDxfBlockBody() {
    if (m_currentDxfBlockName.empty()) {
        m_writeError = true;
        return false;
    }
    const std::string key = dxfSymbolNameKey(m_currentDxfBlockName);
    const std::string name = m_currentDxfBlockName;
    m_currentDxfBlockName.clear();
    if (!m_requireResolvedBlockOwners || version <= DRW::AC1009
        || !m_dxfBlockSectionActive)
        return true;
    if (key.empty() || blockMap.count(key) == 0) {
        m_writeError = true;
        return false;
    }
    return recordEmittedDxfBlockBody(name);
}

bool dxfRW::writeBlockEnd(const DRW_Block *footer) {
    return writeBlockEndWithHandle(footer, 0);
}

bool dxfRW::writeBlockEndCommonFields(const DRW_Block& end) {
    if (version > DRW::AC1009) {
        if (!writeEntityReferenceGroups(&end))
            return false;
        if (version >= DRW::AC1014 && !writeAppData(end.appData))
            return false;
        writer->writeString(100, "AcDbEntity");
    }
    if (end.space == DRW::PaperSpace)
        writer->writeInt16(67, DRW::PaperSpace);
    if (version > DRW::AC1009)
        writer->writeUtf8String(8, end.layer);
    else
        writer->writeUtf8Caps(8, end.layer);
    if (version > DRW::AC1009)
        writer->writeUtf8String(6, end.lineType);
    else
        writer->writeUtf8Caps(6, end.lineType);
    writer->writeInt16(62, end.color);
    if (version > DRW::AC1015 && end.color24 >= 0)
        writer->writeInt32(420, end.color24);
    if (version > DRW::AC1015 && !end.colorName.empty())
        writer->writeUtf8String(430, end.colorName);
    if (version > DRW::AC1009 && end.ltypeScale != 1.0)
        writer->writeDouble(48, end.ltypeScale);
    if (version > DRW::AC1009 && !end.visible)
        writer->writeInt16(60, 1);
    if (version > DRW::AC1018
        && end.shadow != DRW::CastAndReceieveShadows) {
        writer->writeInt16(284, static_cast<int>(end.shadow));
    }
    if (version > DRW::AC1018 && end.material != DRW::MaterialByLayer) {
        writer->writeUtf8String(347,
                                toHexStr(remapObjectHandle(end.material)));
    }
    if (version > DRW::AC1018 && end.fullVisualStyleHandle != 0) {
        writer->writeUtf8String(
            348, toHexStr(remapObjectHandle(end.fullVisualStyleHandle)));
    }
    if (version > DRW::AC1014)
        writer->writeInt16(370, DRW_LW_Conv::lineWidth2dxfInt(end.lWeight));
    if (version > DRW::AC1018 && end.plotStyle != DRW::DefaultPlotStyle) {
        writer->writeUtf8String(
            390, toHexStr(remapObjectHandle(
                     static_cast<std::uint32_t>(end.plotStyle))));
    }
    if (version > DRW::AC1015 && end.transparency != DRW::Opaque)
        writer->writeInt32(440, end.transparency);
    if (version > DRW::AC1009)
        writer->writeString(100, "AcDbBlockEnd");
    if (!end.extData.empty() && !writeExtData(end.extData))
        return false;
    return !writer->hasWriteError();
}

bool dxfRW::writeBlockEndWithHandle(const DRW_Block *footer,
                                    std::uint32_t emittedHandle) {
    if (!preflightDxfWrite() || !writingBlock
        || (footer != nullptr
            && (!footer->getIsEnd() || !preflightEntity(footer)))) {
        m_writeError = true;
        return false;
    }

    RecordStateScope state(*this);
    DxfWriterRecordScope record(*writer);
    DRW_Block defaultFooter;
    defaultFooter.setIsEnd(true);
    const DRW_Block& end = footer != nullptr ? *footer : defaultFooter;

    if (version > DRW::AC1009) {
        if (emittedHandle == 0
            && !checkedDxfHandleOffset(currHandle, 2, emittedHandle)) {
            m_writeError = true;
            return false;
        }
        if (emittedHandle == 0) {
            m_writeError = true;
            return false;
        }
    }
    if (version > DRW::AC1009
        && !bindSourceBlockEndHandle(footer, emittedHandle))
        return false;
    if (!validateSourceBlockEndOwner(footer, currHandle))
        return false;

    writer->writeString(0, "ENDBLK");
    if (version > DRW::AC1009) {
        writer->writeString(5, toHexStr(emittedHandle));
        if (version > DRW::AC1014)
            writer->writeString(330, toHexStr(currHandle));
    }
    if (!writeBlockEndCommonFields(end)) {
        m_writeError = true;
        return false;
    }

    if (writer->hasWriteError() || !completeCurrentDxfBlockBody()) {
        m_writeError = true;
        return false;
    }
    writingBlock = false;
    if (!record.commit()) {
        m_writeError = true;
        return false;
    }
    state.commit();
    return true;
}

bool dxfRW::writeBlock(DRW_Block *bk){
    if (!preflightEntity(bk) || m_collectingBlockRecords) {
        m_writeError = true;
        return false;
    }
    if (bk->xrefUnloaded
        && (version <= DRW::AC1014 || (bk->flags & 4) == 0)) {
        m_writeError = true;
        return false;
    }

    if (writingBlock && !writeBlockEnd(nullptr))
        return false;
    const bool wasWritingBlock = writingBlock;
    const std::uint32_t previousHandle = currHandle;

    std::uint32_t blockRecordHandle = 0;
    std::uint32_t blockHandle = 0;
    if (version > DRW::AC1009) {
        const auto blockRecord = blockMap.find(dxfSymbolNameKey(bk->name));
        if (blockRecord == blockMap.end()) {
            m_writeError = true;
            return false;
        }
        blockRecordHandle = static_cast<std::uint32_t>(blockRecord->second);
        if (!checkedDxfHandleOffset(blockRecordHandle, 1, blockHandle)) {
            m_writeError = true;
            return false;
        }
    }
    RecordStateScope state(*this, bk);
    DxfWriterRecordScope record(*writer);
    if (version > DRW::AC1009
        && !bindSourceBlockBeginHandle(bk, blockHandle)) {
        return false;
    }
    writingBlock = true;
    writer->writeString(0, "BLOCK");
    if (version > DRW::AC1009) {
        currHandle = blockRecordHandle;
        writer->writeString(5, toHexStr(blockHandle));
        if (version > DRW::AC1014) {
            writer->writeString(330, toHexStr(currHandle));
        }
        if (!writeEntityReferenceGroups(bk)) {
            writingBlock = wasWritingBlock;
            currHandle = previousHandle;
            return false;
        }
        if (version >= DRW::AC1014 && !writeAppData(bk->appData)) {
            writingBlock = wasWritingBlock;
            currHandle = previousHandle;
            return false;
        }
        writer->writeString(100, "AcDbEntity");
    }
    if (version > DRW::AC1009)
        writer->writeUtf8String(8, bk->layer);
    else
        writer->writeUtf8Caps(8, bk->layer);
    if (version > DRW::AC1009)
        writer->writeUtf8String(6, bk->lineType);
    else
        writer->writeUtf8Caps(6, bk->lineType);
    writer->writeInt16(62, bk->color);
    if (version > DRW::AC1015 && bk->color24 >= 0) {
        writer->writeInt32(420, bk->color24);
    }
    if (version > DRW::AC1015 && !bk->colorName.empty())
        writer->writeUtf8String(430, bk->colorName);
    if (version > DRW::AC1009 && bk->ltypeScale != 1.0)
        writer->writeDouble(48, bk->ltypeScale);
    if (version > DRW::AC1009 && !bk->visible)
        writer->writeInt16(60, 1);
    if (version > DRW::AC1018
        && bk->shadow != DRW::CastAndReceieveShadows) {
        writer->writeInt16(284, static_cast<int>(bk->shadow));
    }
    if (version > DRW::AC1014)
        writer->writeInt16(370,
                           DRW_LW_Conv::lineWidth2dxfInt(bk->lWeight));
    if (version > DRW::AC1015 && bk->transparency != DRW::Opaque)
        writer->writeInt32(440, bk->transparency);
    if (version > DRW::AC1009) {
        writer->writeString(100, "AcDbBlockBegin");
        writer->writeUtf8String(2, bk->name);
    } else
        writer->writeUtf8Caps(2, bk->name);
    writer->writeInt16(70, bk->flags);
    if (version > DRW::AC1014 && bk->xrefUnloaded)
        writer->writeInt16(71, 1);
    writer->writeDouble(10, bk->basePoint.x);
    writer->writeDouble(20, bk->basePoint.y);
    if (bk->basePoint.z != 0.0) {
        writer->writeDouble(30, bk->basePoint.z);
    }
    if (version > DRW::AC1009)
        writer->writeUtf8String(3, bk->name);
    else
        writer->writeUtf8Caps(3, bk->name);
    writer->writeUtf8String(1, bk->xrefPath);
    if (bk->hasDescription || !bk->description.empty()) {
        if (version > DRW::AC1009)
            writer->writeUtf8String(4, bk->description);
        else
            writer->writeUtf8Caps(4, bk->description);
    }
    if (!bk->extData.empty() && !writeExtData(bk->extData)) {
        writingBlock = wasWritingBlock;
        currHandle = previousHandle;
        return false;
    }

    if (writer->hasWriteError()) {
        writingBlock = wasWritingBlock;
        currHandle = previousHandle;
        m_writeError = true;
        return false;
    }
    m_currentDxfBlockName = bk->name;
    if (!record.commit()) {
        writingBlock = wasWritingBlock;
        currHandle = previousHandle;
        m_writeError = true;
        return false;
    }
    state.commit();
    return true;
}

bool dxfRW::writeTables() {
    if (!preflightDxfWrite()) {
        m_writeError = true;
        return false;
    }
    RecordStateScope state(*this);
    DxfWriterRecordScope record(*writer);
    DxfTableRowCounterScope tableRows(m_dxfTableRowCount,
                                      m_dxfTableRowCountActive);
    const auto hasWriteFailure = [this]() {
        return m_writeError || writer == nullptr || writer->hasWriteError();
    };
    const auto writeCapacityPlaceholder = [this](std::streampos& offset) {
        if (writer == nullptr
            || !writeDxfTableCapacityPlaceholder(*writer, offset)) {
            m_writeError = true;
            return false;
        }
        return true;
    };
    const auto patchCapacity = [this, &tableRows](std::streampos offset) {
        if (writer == nullptr
            || !backpatchDxfTableCapacity(
                *writer, offset, tableRows.value(), binFile,
                binFile && version <= DRW::AC1009)) {
            m_writeError = true;
            return false;
        }
        return true;
    };
    const auto writeEndTable = [&]() {
        writer->writeString(0, "ENDTAB");
        return !hasWriteFailure();
    };

    writer->writeString(0, "TABLE");
    writer->writeString(2, "VPORT");
    if (version > DRW::AC1009) {
        writer->writeString(5, "8");
        if (version > DRW::AC1014) {
            writer->writeString(330, "0");
        }
        writer->writeString(100, "AcDbSymbolTable");
    }
    std::streampos vportCountOffset;
    tableRows.reset();
    if (!writeCapacityPlaceholder(vportCountOffset))
        return false;
/*** VPORT ***/
    if (hasWriteFailure())
        return false;
    dimstyleStd =false;
    iface->writeVports();
    if (hasWriteFailure())
        return false;
    if (!dimstyleStd) {
        DRW_Vport portact;
        portact.name = "*ACTIVE";
        if (!writeVport(&portact))
            return false;
    }
    if (hasWriteFailure() || !patchCapacity(vportCountOffset))
        return false;
    if (!writeEndTable())
        return false;
/*** LTYPE ***/
    std::map<std::string, const DRW_LType*> mandatoryLinetypes;
    const auto mandatoryHandle = [](const std::string& name) {
        const std::string key = dxfSymbolNameKey(name);
        if (key == "BYBLOCK")
            return 0x14u;
        if (key == "BYLAYER")
            return 0x15u;
        if (key == "CONTINUOUS")
            return 0x16u;
        return 0u;
    };
    for (const DRW_LType& lineType : m_canonicalLineTypeMetadata) {
        const std::uint32_t fixedHandle = mandatoryHandle(lineType.name);
        if (fixedHandle == 0)
            continue;
        const std::string key = dxfSymbolNameKey(lineType.name);
        if (!mandatoryLinetypes.emplace(key, &lineType).second
            || (lineType.handle != 0
                && !bindSourceEntityHandle(lineType.handle, fixedHandle))) {
            m_writeError = true;
            return false;
        }
    }
    const auto writeMandatoryMetadata = [this, &mandatoryLinetypes](
        const char* name) {
        const auto found = mandatoryLinetypes.find(name);
        if (found == mandatoryLinetypes.end())
            return true;
        return writeTableEntryAppData(*found->second);
    };
    const auto writeMandatoryExtData = [this, &mandatoryLinetypes](
        const char* name) {
        const auto found = mandatoryLinetypes.find(name);
        return found == mandatoryLinetypes.end()
            || found->second->extData.empty()
            || writeExtData(found->second->extData);
    };
    writer->writeString(0, "TABLE");
    writer->writeString(2, "LTYPE");
    if (version > DRW::AC1009) {
        writer->writeString(5, "5");
        if (version >= DRW::AC1014) {
            writer->writeString(330, "0");
        }
        writer->writeString(100, "AcDbSymbolTable");
    }
    std::streampos lineTypeCountOffset;
    tableRows.reset();
    if (!writeCapacityPlaceholder(lineTypeCountOffset))
        return false;
//Mandatory linetypes
    writer->writeString(0, "LTYPE");
    if (version > DRW::AC1009) {
        writer->writeString(5, "14");
    }
    if (!writeMandatoryMetadata("BYBLOCK"))
        return false;
    if (version > DRW::AC1009) {
        if (version >= DRW::AC1014) {
            writer->writeString(330, "5");
        }
        writer->writeString(100, "AcDbSymbolTableRecord");
        writer->writeString(100, "AcDbLinetypeTableRecord");
        writer->writeString(2, "ByBlock");
    } else
        writer->writeString(2, "BYBLOCK");
    writer->writeInt16(70, 0);
    writer->writeString(3, "");
    writer->writeInt16(72, 65);
    writer->writeInt16(73, 0);
    writer->writeDouble(40, 0.0);
    if (!writeMandatoryExtData("BYBLOCK"))
        return false;
    if (!recordDxfTableRow())
        return false;

    writer->writeString(0, "LTYPE");
    if (version > DRW::AC1009) {
        writer->writeString(5, "15");
    }
    if (!writeMandatoryMetadata("BYLAYER"))
        return false;
    if (version > DRW::AC1009) {
        if (version >= DRW::AC1014) {
            writer->writeString(330, "5");
}
        writer->writeString(100, "AcDbSymbolTableRecord");
        writer->writeString(100, "AcDbLinetypeTableRecord");
        writer->writeString(2, "ByLayer");
    } else
        writer->writeString(2, "BYLAYER");
    writer->writeInt16(70, 0);
    writer->writeString(3, "");
    writer->writeInt16(72, 65);
    writer->writeInt16(73, 0);
    writer->writeDouble(40, 0.0);
    if (!writeMandatoryExtData("BYLAYER"))
        return false;
    if (!recordDxfTableRow())
        return false;

    writer->writeString(0, "LTYPE");
    if (version > DRW::AC1009) {
        writer->writeString(5, "16");
    }
    if (!writeMandatoryMetadata("CONTINUOUS"))
        return false;
    if (version > DRW::AC1009) {
        if (version >= DRW::AC1014) {
            writer->writeString(330, "5");
        }
        writer->writeString(100, "AcDbSymbolTableRecord");
        writer->writeString(100, "AcDbLinetypeTableRecord");
        writer->writeString(2, "Continuous");
    } else {
        writer->writeString(2, "CONTINUOUS");
    }
    writer->writeInt16(70, 0);
    writer->writeString(3, "Solid line");
    writer->writeInt16(72, 65);
    writer->writeInt16(73, 0);
    writer->writeDouble(40, 0.0);
    if (!writeMandatoryExtData("CONTINUOUS"))
        return false;
    if (!recordDxfTableRow())
        return false;
//Application linetypes
    if (hasWriteFailure())
        return false;
    iface->writeLTypes();
    if (hasWriteFailure() || !patchCapacity(lineTypeCountOffset))
        return false;
    if (!writeEndTable())
        return false;
/*** LAYER ***/
    writer->writeString(0, "TABLE");
    writer->writeString(2, "LAYER");
    if (version > DRW::AC1009) {
        writer->writeString(5, "2");
        if (version > DRW::AC1014) {
            writer->writeString(330, "0");
        }
        writer->writeString(100, "AcDbSymbolTable");
    }
    std::streampos layerCountOffset;
    tableRows.reset();
    if (!writeCapacityPlaceholder(layerCountOffset))
        return false;
    if (hasWriteFailure())
        return false;
    wlayer0 = false;
    iface->writeLayers();
    if (hasWriteFailure())
        return false;
    if (!wlayer0) {
        DRW_Layer lay0;
        lay0.name = "0";
        if (!writeLayer(&lay0))
            return false;
    }
    if (hasWriteFailure() || !patchCapacity(layerCountOffset))
        return false;
    if (!writeEndTable())
        return false;
/*** STYLE ***/
    writer->writeString(0, "TABLE");
    writer->writeString(2, "STYLE");
    if (version > DRW::AC1009) {
        writer->writeString(5, "3");
        if (version > DRW::AC1014) {
            writer->writeString(330, "0");
}
        writer->writeString(100, "AcDbSymbolTable");
}
    std::streampos styleCountOffset;
    tableRows.reset();
    if (!writeCapacityPlaceholder(styleCountOffset))
        return false;
    if (hasWriteFailure())
        return false;
    dimstyleStd =false;
    iface->writeTextstyles();
    if (hasWriteFailure())
        return false;
    if (!dimstyleStd) {
        DRW_Textstyle tsty;
        tsty.name = "Standard";
        if (!writeTextstyle(&tsty))
            return false;
    }
    if (hasWriteFailure() || !patchCapacity(styleCountOffset))
        return false;
    if (!writeEndTable())
        return false;

    writer->writeString(0, "TABLE");
    writer->writeString(2, "VIEW");
    if (version > DRW::AC1009) {
        writer->writeString(5, "6");
        if (version > DRW::AC1014) {
            writer->writeString(330, "0");
}
        writer->writeString(100, "AcDbSymbolTable");
    }
    std::streampos viewCountOffset;
    tableRows.reset();
    if (!writeCapacityPlaceholder(viewCountOffset))
        return false;
    if (hasWriteFailure())
        return false;
    iface->writeViews();
    if (hasWriteFailure() || !patchCapacity(viewCountOffset))
        return false;
    if (!writeEndTable())
        return false;

    writer->writeString(0, "TABLE");
    writer->writeString(2, "UCS");
    if (version > DRW::AC1009) {
        writer->writeString(5, "7");
        if (version > DRW::AC1014) {
            writer->writeString(330, "0");
        }
        writer->writeString(100, "AcDbSymbolTable");
    }
    std::streampos ucsCountOffset;
    tableRows.reset();
    if (!writeCapacityPlaceholder(ucsCountOffset))
        return false;
    if (hasWriteFailure())
        return false;
    iface->writeUCSs();
    if (hasWriteFailure() || !patchCapacity(ucsCountOffset))
        return false;
    if (!writeEndTable())
        return false;

    writer->writeString(0, "TABLE");
    writer->writeString(2, "APPID");
    if (version > DRW::AC1009) {
        writer->writeString(5, "9");
        if (version > DRW::AC1014) {
            writer->writeString(330, "0");
        }
        writer->writeString(100, "AcDbSymbolTable");
        }
    std::streampos appIdCountOffset;
    tableRows.reset();
    if (!writeCapacityPlaceholder(appIdCountOffset))
        return false;
    writer->writeString(0, "APPID");
    if (version > DRW::AC1009) {
        writer->writeString(5, "12");
        if (version > DRW::AC1014) {
            writer->writeString(330, "9");
    }
        writer->writeString(100, "AcDbSymbolTableRecord");
        writer->writeString(100, "AcDbRegAppTableRecord");
    }
    writer->writeString(2, "ACAD");
    writer->writeInt16(70, 0);
    if (!recordDxfTableRow())
        return false;
    m_registeredDxfXdataAppIds.insert("ACAD");
    if (hasWriteFailure())
        return false;
    iface->writeAppId();
    if (hasWriteFailure() || !validateDxfXdataAppIdRegistrations()
        || !patchCapacity(appIdCountOffset))
        return false;
    if (!writeEndTable())
        return false;

    writer->writeString(0, "TABLE");
    writer->writeString(2, "DIMSTYLE");
    if (version > DRW::AC1009) {
        writer->writeString(5, "A");
        if (version > DRW::AC1014) {
            writer->writeString(330, "0");
        }
        writer->writeString(100, "AcDbSymbolTable");
        }
    std::streampos dimStyleCountOffset;
    tableRows.reset();
    if (!writeCapacityPlaceholder(dimStyleCountOffset))
        return false;
    if (version > DRW::AC1014) {
        writer->writeString(100, "AcDbDimStyleTable");
        if (version != DRW::AC1024)
            writer->writeInt16(71, 1); // legacy table-definition marker
        }
    if (hasWriteFailure())
        return false;
    dimstyleStd =false;
    if (version == DRW::AC1024) {
        std::vector<std::uint32_t> dimstyleHandles;
        std::string stagedDimstyleRows;
        {
            DxfWriterStreamCaptureScope rowCapture(*writer);
            if (!rowCapture.valid()) {
                m_writeError = true;
                return false;
            }
            DxfDimstyleHeaderHandleSink sink{
                this, &dimstyleHandles, activeDxfDimstyleHeaderHandleSink};
            PointerRestoreScope<DxfDimstyleHeaderHandleSink> handleSink(
                activeDxfDimstyleHeaderHandleSink, &sink);
            iface->writeDimstyles();
            if (hasWriteFailure())
                return false;
            if (!dimstyleStd) {
                DRW_Dimstyle dsty;
                dsty.name = "Standard";
                if (!writeDimstyle(&dsty))
                    return false;
            }
            if (hasWriteFailure()
                || dimstyleHandles.size() != tableRows.value()
                || dimstyleHandles.size()
                    > static_cast<std::size_t>(
                        std::numeric_limits<std::int16_t>::max())) {
                m_writeError = true;
                return false;
            }
            stagedDimstyleRows = rowCapture.bytes();
        }
        writer->writeInt16(71, static_cast<int>(dimstyleHandles.size()));
        for (std::uint32_t handle : dimstyleHandles)
            writer->writeString(340, toHexStr(handle));
        if (hasWriteFailure()
            || !appendDxfWriterBytes(*writer, stagedDimstyleRows)) {
            m_writeError = true;
            return false;
        }
    } else {
        iface->writeDimstyles();
        if (hasWriteFailure())
            return false;
        if (!dimstyleStd) {
            DRW_Dimstyle dsty;
            dsty.name = "Standard";
            if (!writeDimstyle(&dsty))
                return false;
        }
    }
    if (hasWriteFailure() || !patchCapacity(dimStyleCountOffset))
        return false;
    if (!writeEndTable())
        return false;

    if (version > DRW::AC1009) {
        writer->writeString(0, "TABLE");
        writer->writeString(2, "BLOCK_RECORD");
        writer->writeString(5, "1");
        if (version > DRW::AC1014) {
            writer->writeString(330, "0");
        }
        writer->writeString(100, "AcDbSymbolTable");
        writer->writeInt16(
            70, static_cast<int>(2 + m_pendingBlockRecords.size()));
        writer->writeString(0, "BLOCK_RECORD");
        writer->writeString(5, "1F");
        if (version > DRW::AC1014) {
            writer->writeString(330, "1");
        }
        writer->writeString(100, "AcDbSymbolTableRecord");
        writer->writeString(100, "AcDbBlockTableRecord");
        writer->writeString(2, "*Model_Space");
        if (!writeSourceBlockRecordExtensionDictionary(
                DRW::DxfModelSpaceBlockRecordHandle))
            return false;
        if (version >= DRW::AC1015
            && !writeSourceBlockRecordLayoutLink(
                DRW::DxfModelSpaceBlockRecordHandle))
            return false;
        if (version > DRW::AC1018) {
            //    writer->writeInt16(340, 22);
            writer->writeInt16(70, 0);
            writer->writeInt16(280, 1);
            writer->writeInt16(281, 0);
        }
        writer->writeString(0, "BLOCK_RECORD");
        writer->writeString(5, "1E");
        if (version > DRW::AC1014) {
            writer->writeString(330, "1");
        }
        writer->writeString(100, "AcDbSymbolTableRecord");
        writer->writeString(100, "AcDbBlockTableRecord");
        writer->writeString(2, "*Paper_Space");
        if (!writeSourceBlockRecordExtensionDictionary(
                DRW::DxfPaperSpaceBlockRecordHandle))
            return false;
        if (version >= DRW::AC1015
            && !writeSourceBlockRecordLayoutLink(
                DRW::DxfPaperSpaceBlockRecordHandle))
            return false;
        if (version > DRW::AC1018) {
            //    writer->writeInt16(340, 22);
            writer->writeInt16(70, 0);
            writer->writeInt16(280, 1);
            writer->writeInt16(281, 0);
        }
    }
    if (hasWriteFailure())
        return false;
    for (const PendingDxfBlockRecord& record : m_pendingBlockRecords) {
        if (!emitBlockRecord(record))
            return false;
    }
    if (version > DRW::AC1009) {
        writer->writeString(0, "ENDTAB");
    } else {
        // R12 has no BLOCK_RECORD table or record handles. Preserve the
        // historical callback order without unnecessary pre-collection.
        iface->writeBlockRecords();
        if (hasWriteFailure())
            return false;
    }
    if (hasWriteFailure() || !record.commit([this](std::string_view bytes) {
            return inspectDxfWriteSection(m_dxfTablesWriteInspector, bytes);
        })) {
        m_writeError = true;
        return false;
    }
    state.commit();
    return true;
}

bool dxfRW::writeBlocks() {
    if (!preflightDxfWrite())
        return false;
    RecordStateScope state(*this);
    DxfWriterRecordScope record(*writer);
    const bool trackPictureBodies = m_requireResolvedBlockOwners
        && version > DRW::AC1009;
    if (trackPictureBodies
        && (m_dxfBlockSectionActive || m_dxfBlockSectionComplete
            || !m_currentDxfBlockName.empty()
            || !m_emittedDxfBlockBodyNames.empty()
            || !m_pendingDxfDimensionPictureBlocks.empty()
            || !m_pendingDxfInsertBodyTargets.empty())) {
        m_writeError = true;
        return false;
    }
    m_dxfBlockSectionActive = trackPictureBodies;
    m_dxfBlockSectionComplete = false;
    writer->writeString(0, "BLOCK");
    if (version > DRW::AC1009) {
        if (m_fixedModelSpaceBlockBegin != nullptr
            && !bindSourceBlockBeginHandle(
                m_fixedModelSpaceBlockBegin.get(),
                DRW::DxfModelSpaceBlockRecordHandle + 1u))
            return false;
        writer->writeString(5, "20");
        if (version > DRW::AC1014) {
            writer->writeString(330, "1F");
        }
        if (m_fixedModelSpaceBlockBegin != nullptr
            && (!writeEntityReferenceGroups(
                    m_fixedModelSpaceBlockBegin.get())
                || (version >= DRW::AC1014
                    && !writeAppData(
                        m_fixedModelSpaceBlockBegin->appData)))) {
            m_writeError = true;
            return false;
        }
        writer->writeString(100, "AcDbEntity");
    }
    writer->writeString(8, "0");
    if (version > DRW::AC1009) {
        writer->writeString(100, "AcDbBlockBegin");
        writer->writeString(2, "*Model_Space");
    } else
        writer->writeString(2, "$MODEL_SPACE");
    writer->writeInt16(70, 0);
    writer->writeDouble(10, 0.0);
    writer->writeDouble(20, 0.0);
    writer->writeDouble(30, 0.0);
    if (version > DRW::AC1009)
        writer->writeString(3, "*Model_Space");
    else
        writer->writeString(3, "$MODEL_SPACE");
    writer->writeString(1, "");
    if (m_fixedModelSpaceBlockEnd != nullptr) {
        if (version > DRW::AC1009
            && !bindSourceBlockEndHandle(
                m_fixedModelSpaceBlockEnd.get(),
                DRW::DxfModelSpaceBlockRecordHandle + 2u))
            return false;
        if (!validateSourceBlockEndOwner(
                m_fixedModelSpaceBlockEnd.get(),
                DRW::DxfModelSpaceBlockRecordHandle))
            return false;
        writer->writeString(0, "ENDBLK");
        if (version > DRW::AC1009) {
            writer->writeString(5, "21");
            if (version > DRW::AC1014)
                writer->writeString(330, "1F");
        }
        if (!writeBlockEndCommonFields(*m_fixedModelSpaceBlockEnd)) {
            m_writeError = true;
            return false;
        }
    } else {
        writer->writeString(0, "ENDBLK");
        if (version > DRW::AC1009) {
            writer->writeString(5, "21");
            if (version > DRW::AC1014) {
                writer->writeString(330, "1F");
            }
            writer->writeString(100, "AcDbEntity");
        }
        writer->writeString(8, "0");
        if (version > DRW::AC1009)
            writer->writeString(100, "AcDbBlockEnd");
    }

    writer->writeString(0, "BLOCK");
    if (version > DRW::AC1009) {
        if (m_fixedPaperSpaceBlockBegin != nullptr
            && !bindSourceBlockBeginHandle(
                m_fixedPaperSpaceBlockBegin.get(),
                DRW::DxfPaperSpaceBlockRecordHandle - 2u))
            return false;
        writer->writeString(5, "1C");
        if (version > DRW::AC1014) {
            // Paper_Space BLOCK (handle 1C) is owned by the Paper_Space
            // BLOCK_RECORD (1E, reserved above), not the nonexistent handle 1B.
            writer->writeString(330, "1E");
        }
        if (m_fixedPaperSpaceBlockBegin != nullptr
            && (!writeEntityReferenceGroups(
                    m_fixedPaperSpaceBlockBegin.get())
                || (version >= DRW::AC1014
                    && !writeAppData(
                        m_fixedPaperSpaceBlockBegin->appData)))) {
            m_writeError = true;
            return false;
        }
        writer->writeString(100, "AcDbEntity");
    }
    writer->writeString(8, "0");
    if (version > DRW::AC1009) {
        writer->writeString(100, "AcDbBlockBegin");
        writer->writeString(2, "*Paper_Space");
    } else
        writer->writeString(2, "$PAPER_SPACE");
    writer->writeInt16(70, 0);
    writer->writeDouble(10, 0.0);
    writer->writeDouble(20, 0.0);
    writer->writeDouble(30, 0.0);
    if (version > DRW::AC1009)
        writer->writeString(3, "*Paper_Space");
    else
        writer->writeString(3, "$PAPER_SPACE");
    writer->writeString(1, "");
    if (m_fixedPaperSpaceBlockEnd != nullptr) {
        if (version > DRW::AC1009
            && !bindSourceBlockEndHandle(
                m_fixedPaperSpaceBlockEnd.get(),
                DRW::DxfPaperSpaceBlockRecordHandle - 1u))
            return false;
        if (!validateSourceBlockEndOwner(
                m_fixedPaperSpaceBlockEnd.get(),
                DRW::DxfPaperSpaceBlockRecordHandle))
            return false;
        writer->writeString(0, "ENDBLK");
        if (version > DRW::AC1009) {
            writer->writeString(5, "1D");
            if (version > DRW::AC1014) {
                // Paper_Space ENDBLK belongs to BLOCK_RECORD 1E.
                writer->writeString(330, "1E");
            }
        }
        if (!writeBlockEndCommonFields(*m_fixedPaperSpaceBlockEnd)) {
            m_writeError = true;
            return false;
        }
    } else {
        writer->writeString(0, "ENDBLK");
        if (version > DRW::AC1009) {
            writer->writeString(5, "1D");
            if (version > DRW::AC1014) {
                // Paper_Space ENDBLK (handle 1D) is owned by the Paper_Space
                // BLOCK_RECORD (1E), not the Model_Space BLOCK_RECORD (1F).
                writer->writeString(330, "1E");
            }
            writer->writeString(100, "AcDbEntity");
        }
        writer->writeString(8, "0");
        if (version > DRW::AC1009)
            writer->writeString(100, "AcDbBlockEnd");
    }

    if (m_writeError || writer->hasWriteError()) {
        m_writeError = true;
        return false;
    }
    if (trackPictureBodies
        && (!recordEmittedDxfBlockBody("*Model_Space")
            || !recordEmittedDxfBlockBody("*Paper_Space"))) {
        m_writeError = true;
        return false;
    }
    writingBlock = false;
    {
        struct BlockRemapPhaseScope final {
            explicit BlockRemapPhaseScope(bool& phase) noexcept
                : active(phase), previous(phase) {
                active = true;
            }
            ~BlockRemapPhaseScope() noexcept { active = previous; }
            bool& active;
            bool previous;
        } remapPhase(m_dxfWriteBlockRemapPhase);
        iface->writeBlocks();
    }
    if (m_writeError || writer->hasWriteError())
        return false;
    if (writingBlock && !writeBlockEnd(nullptr))
        return false;
    if (trackPictureBodies) {
        for (const auto& pending : m_pendingDxfDimensionPictureBlocks) {
            if (m_emittedDxfBlockBodyNames.count(pending.first) != 0)
                continue;
            recordOperationDiagnostic(DRW::OperationPhase::Blocks,
                DRW::OperationCause::ValidationFailure,
                "incomplete-dimension-picture-block",
                "DIMENSION picture BLOCK_RECORD has no emitted BLOCK body",
                0, false, pending.second,
                pending.second != DRW::NoHandle);
            m_writeError = true;
            return false;
        }
        for (const auto& pending : m_pendingDxfInsertBodyTargets) {
            if (m_emittedDxfBlockBodyNames.count(pending.first) != 0)
                continue;
            recordOperationDiagnostic(DRW::OperationPhase::Blocks,
                DRW::OperationCause::ValidationFailure,
                "incomplete-insert-target-block",
                "nested INSERT BLOCK_RECORD has no emitted BLOCK body",
                0, false, pending.second,
                pending.second != DRW::NoHandle);
            m_writeError = true;
            return false;
        }
        for (const auto& pending : m_pendingDxfDimstyleBlockResources) {
            if (m_emittedDxfBlockBodyNames.count(pending.first) != 0)
                continue;
            recordOperationDiagnostic(DRW::OperationPhase::Blocks,
                DRW::OperationCause::ValidationFailure,
                "incomplete-dimstyle-arrow-block",
                "DIMSTYLE arrow BLOCK_RECORD has no emitted BLOCK body",
                0, false, pending.second,
                pending.second != DRW::NoHandle);
            m_writeError = true;
            return false;
        }
    }
    m_dxfBlockSectionActive = false;
    m_dxfBlockSectionComplete = trackPictureBodies;
    const auto inspect = [this](std::string_view bytes) {
        if (!m_dxfEntitySectionsWriteInspector) return true;
        return inspectDxfWriteSection([this](const auto& view) {
            return m_dxfEntitySectionsWriteInspector(view, "BLOCKS");
        }, bytes);
    };
    if (m_writeError || writer->hasWriteError() || !record.commit(inspect)) {
        m_writeError = true;
        return false;
    }
    state.commit();
    return true;
}

bool dxfRW::planDxfGroupHandles() {
    if (!preflightDxfWrite())
        return false;
    if (m_generatedGroupDictionarySource
        && m_generatedGroupDictionarySource->m_entries.size() != m_groups.size())
        return failDxfWrite();
    if (m_dxfGroupPlanFrozen)
        return m_plannedDxfGroupHandles.size() == m_groups.size()
            || failDxfWrite();
    if (m_groups.empty()) {
        m_dxfGroupPlanFrozen = true;
        return true;
    }
    try {
        std::set<std::string> names;
        std::size_t sourceNameBytes = DRW::kMaxDxfBinaryPayloadBytes;
        std::set<std::uint32_t> namedDestinations;
        // Index only GROUP destinations, not the potentially much larger
        // complete remap graph. Saturate at two: only uniqueness matters.
        std::map<std::uint32_t, unsigned char> remapDestinationCounts;
        for (const auto& group : m_groups) {
            const auto mapping = m_handleRemap.find(group.handle);
            if (group.handle != 0 && mapping != m_handleRemap.end())
                remapDestinationCounts.emplace(mapping->second, 0u);
        }
        for (const auto& mapping : m_handleRemap) {
            const auto count = remapDestinationCounts.find(mapping.second);
            if (count != remapDestinationCounts.end() && count->second < 2u)
                ++count->second;
        }
        // Named dictionaries are known before allocation; a future verbatim
        // dictionary must not collide with an early planned GROUP destination.
        if (!m_groups.empty()) {
            for (const auto& dictionary : m_namedDictObjects) {
                const auto target = remapObjectHandle(dictionary.handle);
                namedDestinations.insert(target);
                m_handleAllocator->reserveForWrite(target);
            }
        }
        std::vector<std::uint32_t> handles;
        std::map<std::uint32_t, std::uint32_t> sources;
        handles.reserve(m_groups.size());
        for (const auto& group : m_groups) {
            if (group.name.empty()
                || group.m_entityHandles.size() > DRW_Group::kMaxEntityHandles)
                return failDxfWrite();
            if (m_generatedGroupDictionarySource) {
                if (group.name.size() > sourceNameBytes)
                    return failDxfWrite();
                sourceNameBytes -= group.name.size();
            }
            std::string name = group.name;
            for (char& character : name)
                character = static_cast<char>(dxfAsciiUpper(
                    static_cast<unsigned char>(character)));
            if (!names.insert(std::move(name)).second)
                return failDxfWrite();
            std::unordered_set<std::uint32_t> members;
            members.reserve(group.m_entityHandles.size());
            for (const auto member : group.m_entityHandles) {
                if (member == 0 || member == DRW::NoHandle
                    || !members.insert(member).second)
                    return failDxfWrite();
            }
            if (group.handle != 0
                && (sources.count(group.handle) != 0
                    || group.handle == m_generatedNodSourceHandle
                    || group.handle == m_generatedGroupDictionarySourceHandle
                    || m_sourceBlockRecordHandles.count(group.handle) != 0
                    || m_writingContext.sourceHandleToWrittenTableMap.count(group.handle) != 0
                    || m_writingContext.sourceHandleToMintedMap.count(group.handle) != 0))
                return failDxfWrite();
            std::uint32_t target = 0;
            const auto explicitTarget = m_handleRemap.find(group.handle);
            if (group.handle != 0 && explicitTarget != m_handleRemap.end()) {
                target = explicitTarget->second;
                if (target == 0 || isDxfFixedOutputHandle(target)
                    || namedDestinations.count(target) != 0
                    || remapDestinationCounts.at(target) != 1u)
                    return failDxfWrite();
                m_handleAllocator->reserveForWrite(target);
            } else if (!allocateDxfHandle(target)) {
                return false;
            }
            if (group.handle != 0)
                sources.emplace(group.handle, target);
            handles.push_back(target);
        }
        m_plannedDxfGroupHandles.swap(handles);
        m_plannedDxfGroupSourceHandles.swap(sources);
        m_dxfGroupPlanFrozen = true;
    } catch (...) {
        return failDxfWrite();
    }
    return true;
}

bool dxfRW::writeObjects() {
    if (!preflightDxfWrite())
        return false;
    if (!planDxfGroupHandles())
        return false;
    for (const auto& group : m_plannedDxfGroupSourceHandles) {
        // A callback cannot redirect an already-used forward reference by
        // replacing caller remaps after GROUP planning.
        if (remapObjectHandle(group.first) != group.second)
            return failDxfWrite();
    }
    if ((m_generatedNodSourceHandle != 0u
            && remapObjectHandle(m_generatedNodSourceHandle) != 0xCu)
        || (m_generatedGroupDictionarySourceHandle != 0u
            && remapObjectHandle(m_generatedGroupDictionarySourceHandle) != 0xDu))
        return failDxfWrite();
    // Validate registered authored dictionaries before allocating generated
    // image/GROUP identities or entering the OBJECTS record transaction.
    try {
        DxfDictionaryEntryAdmission root;
        std::size_t sourceNameBytes = DRW::kMaxDxfBinaryPayloadBytes;
        root.accept("ACAD_GROUP", 0xDu);
        if (!imageDef.empty())
            root.accept("ACAD_IMAGE_DICT", 0);
        for (const auto& entry : m_rootDictEntries) {
            if (m_generatedNodSource) {
                if (entry.first.size() > sourceNameBytes)
                    return failDxfWrite();
                sourceNameBytes -= entry.first.size();
            }
            std::uint64_t target = 0;
            if (!parseRawDxfHandleLexeme(entry.second, target)
                || !root.accept(entry.first, target)) {
                m_writeError = true;
                return false;
            }
        }
        for (const auto& dictionary : m_namedDictObjects) {
            if (dictionary.handle == 0
                || dictionary.hardOwner < 0 || dictionary.hardOwner > 1
                || dictionary.cloning < 0
                || dictionary.cloning > std::numeric_limits<std::int16_t>::max()
                || !dictionary.hasCompleteDxfEntries()) {
                m_writeError = true;
                return false;
            }
            DxfDictionaryEntryAdmission entries;
            for (const auto& entry : dictionary.m_entries) {
                const auto target = remapObjectHandle(entry.m_handle);
                if (target == 0 || !isSafeDxfRecordText(entry.m_name)
                    || !entries.accept(entry.m_name, target)) {
                    m_writeError = true;
                    return false;
                }
            }
        }
    } catch (...) {
        m_writeError = true;
        return false;
    }
    RecordStateScope state(*this);
    DxfWriterRecordScope record(*writer);
    std::string imgDictH;
    std::uint32_t imageDictionaryHandle = 0;
    const auto& groupHandles = m_plannedDxfGroupHandles;
    std::vector<std::string> imageDictionaryKeys;
    std::vector<DxfDictionaryOutputEntry> imageDictionaryEntries;
    try {
        if (!imageDef.empty()) {
            imageDictionaryHandle = m_plannedImageDictionaryHandle;
            if (imageDictionaryHandle == 0u && !allocateDxfHandle(imageDictionaryHandle))
                return false;
            imgDictH = toHexStr(imageDictionaryHandle);
            imageDictionaryKeys.reserve(imageDef.size());
            std::set<std::string> normalizedKeys;
            if (m_generatedImageDictionarySource) {
                for (const auto& entry : m_generatedImageDictionarySource->m_entries) {
                    if (m_plannedImageDefinitions.count({m_generatedImageDictionaryGeneration, entry.m_handle}) != 0u)
                        normalizedKeys.insert(dxfSymbolNameKey(entry.m_name));
                }
            }
            for (const DRW_ImageDef* definition : imageDef) {
                const std::string& imageName = definition->name;
                const std::size_t separator = imageName.find_last_of("/\\");
                const std::size_t basenameStart = separator == std::string::npos
                    ? 0 : separator + 1;
                const std::size_t extension = imageName.find_last_of('.');
                const std::size_t basenameEnd = extension == std::string::npos
                        || extension < basenameStart
                    ? imageName.size() : extension;
                std::string base = imageName.substr(
                    basenameStart, basenameEnd - basenameStart);
                if (base.empty())
                    base = "image";
                const auto normalize = [](std::string value) {
                    for (char& character : value) {
                        if (character >= 'a' && character <= 'z')
                            character = static_cast<char>(character - 'a' + 'A');
                    }
                    return value;
                };
                std::string key = base;
                for (std::size_t suffix = 2;
                     !normalizedKeys.insert(normalize(key)).second;
                     ++suffix) {
                    key = base + "_" + std::to_string(suffix);
                }
                imageDictionaryKeys.push_back(std::move(key));
            }
            if (m_generatedImageDictionarySource) {
                std::map<std::uint32_t, std::size_t> indices;
                for (std::size_t index = 0; index < imageDef.size(); ++index)
                    if (!indices.emplace(imageDef[index]->handle, index).second) return failDxfWrite();
                std::vector<bool> selected(imageDef.size(), false);
                imageDictionaryEntries.reserve(imageDef.size());
                for (const auto& entry : m_generatedImageDictionarySource->m_entries) {
                    const auto definition = m_plannedImageDefinitions.find(
                        {m_generatedImageDictionaryGeneration, entry.m_handle});
                    if (definition == m_plannedImageDefinitions.end()) continue; // Existing selected-definition projection.
                    const auto index = indices.find(definition->second->handle);
                    if (index == indices.end() || selected[index->second]) return failDxfWrite();
                    selected[index->second] = true;
                    imageDictionaryEntries.push_back({entry.m_name, definition->second->handle,
                        dictionaryEntryCode(entry, m_generatedImageDictionarySource->hardOwner == 1 ? 360 : 350)});
                }
                for (std::size_t index = 0; index < imageDef.size(); ++index)
                    if (!selected[index]) imageDictionaryEntries.push_back(
                        {imageDictionaryKeys[index], imageDef[index]->handle, 350});
            }
        }
    } catch (...) {
        m_writeError = true;
        return false;
    }
    if (m_generatedNodSource) {
        std::vector<DxfDictionaryOutputEntry> selected;
        std::vector<DxfDictionaryOutputEntry> ordered;
        std::map<std::string, std::size_t> selectedKeys;
        std::vector<bool> used;
        try {
            const auto select = [&](std::string_view key, std::uint32_t target) {
                if (selected.size() >= DRW_Dictionary::kMaxEntries
                    || !selectedKeys.emplace(dxfSymbolNameKey(key), selected.size()).second)
                    return false;
                selected.push_back({key, target, 350});
                return true;
            };
            if (!select("ACAD_GROUP", 0xDu)
                || (!imageDef.empty() && !select("ACAD_IMAGE_DICT", imageDictionaryHandle)))
                return failDxfWrite();
            for (const auto& entry : m_rootDictEntries) {
                std::uint64_t target = 0;
                if (!parseRawDxfHandleLexeme(entry.second, target)
                    || target > std::numeric_limits<std::uint32_t>::max()
                    || !select(entry.first, static_cast<std::uint32_t>(target)))
                    return failDxfWrite();
            }
            used.resize(selected.size(), false);
            ordered.reserve(selected.size());
            for (const auto& entry : m_generatedNodSource->m_entries) {
                const auto key = dxfSymbolNameKey(entry.m_name);
                const auto target = selectedKeys.find(key);
                if (target == selectedKeys.end())
                    continue; // Existing export projection, not source-completeness proof.
                const auto& projection = selected[target->second];
                if ((key != "ACAD_IMAGE_DICT" || imageDef.empty() || m_generatedImageDictionarySource)
                    && remapObjectHandle(entry.m_handle) != projection.target)
                    return failDxfWrite();
                ordered.push_back({entry.m_name, projection.target,
                    dictionaryEntryCode(entry, m_generatedNodSource->hardOwner == 1 ? 360 : 350)});
                used[target->second] = true;
            }
            for (std::size_t index = 0; index < selected.size(); ++index) {
                if (!used[index])
                    ordered.push_back(selected[index]); // Explicitly generated/authored entry.
            }
        } catch (...) {
            return failDxfWrite();
        }
        if (!writeDictionaryRecord(*m_generatedNodSource, 0xCu, 0u, true, &ordered))
            return false;
    } else {
    writer->writeString(0, "DICTIONARY");
    writer->writeString(5, "C");
    if (version > DRW::AC1014) {
        writer->writeString(330, "0");
    }
    writer->writeString(100, "AcDbDictionary");
    writer->writeInt16(281, 1);
    writer->writeString(3, "ACAD_GROUP");
    writer->writeString(350, "D");
    if (imageDef.size() != 0) {
        writer->writeString(3, "ACAD_IMAGE_DICT");
        writer->writeString(350, imgDictH);
    }
    //Slice (spine-dicts): re-attach raw-net-routed named dictionaries to the
    //regenerated root NamedObjectsDictionary so they are reachable (not pruned as
    //orphans). The filter populates (name, hex-handle) from the source root dict;
    //each handle matches the verbatim code-5 of a dictionary re-emitted later in
    //this OBJECTS section. ACAD_GROUP / root / C-D collisions are excluded there.
    for (const std::pair<std::string, std::string> &entry : m_rootDictEntries) {
        writer->writeUtf8String(3, entry.first);
        writer->writeString(350, entry.second);
    }
    }
    if (!preflightDxfWrite()
        || (m_generatedNodSourceHandle != 0u
            && !bindDxfWriteSourceObjectHandle(m_generatedNodSourceHandle, 0xCu)))
        return false;
    // GROUP identities were planned before dependent emission. Preserve the
    // source dictionary's independent entry order and per-key ownership role.
    if (m_generatedGroupDictionarySource) {
        std::vector<DxfDictionaryOutputEntry> entries;
        try {
            if (m_generatedGroupDictionarySource->m_entries.size() != m_groups.size())
                return failDxfWrite();
            std::map<std::uint32_t, const DRW_Group*> groups;
            for (const auto& group : m_groups) {
                if (group.handle == 0 || !groups.emplace(group.handle, &group).second)
                    return failDxfWrite();
            }
            entries.reserve(groups.size());
            for (const auto& entry : m_generatedGroupDictionarySource->m_entries) {
                const auto group = groups.find(entry.m_handle);
                const auto emitted = m_plannedDxfGroupSourceHandles.find(entry.m_handle);
                if (group == groups.end() || group->second->name != entry.m_name
                    || emitted == m_plannedDxfGroupSourceHandles.end())
                    return failDxfWrite();
                entries.push_back({entry.m_name, emitted->second,
                    dictionaryEntryCode(entry, m_generatedGroupDictionarySource->hardOwner == 1 ? 360 : 350)});
            }
        } catch (...) {
            return failDxfWrite();
        }
        if (!writeDictionaryRecord(*m_generatedGroupDictionarySource, 0xDu, 0xCu, true, &entries))
            return false;
    } else {
    writer->writeString(0, "DICTIONARY");
    writer->writeString(5, "D");
    writer->writeString(330, "C");
    writer->writeString(100, "AcDbDictionary");
    writer->writeInt16(281, 1);
    for (std::size_t i = 0; i < m_groups.size(); ++i) {
        //Unnamed groups carry a generated "*An" name; named groups carry their
        //real name. The D-dict entry name mirrors the GROUP's name field.
        writer->writeUtf8String(3, m_groups[i].name);
        writer->writeString(350, toHexStr(groupHandles[i]));
    }
    }
    if (!preflightDxfWrite()
        || (m_generatedGroupDictionarySourceHandle != 0u
            && !bindDxfWriteSourceObjectHandle(m_generatedGroupDictionarySourceHandle, 0xDu)))
        return false;
//write IMAGEDEF_REACTOR
    for (const auto& planned : m_plannedImageDefinitions) {
        const auto source = m_imagePlanSources.find(planned.second);
        if (source == m_imagePlanSources.end()) return failDxfWrite();
        const auto replacements = m_regeneratedImageSourceReactors.find(planned.second);
        for (const auto& reactor : source->second->selectedReactors)
            if (replacements == m_regeneratedImageSourceReactors.end()
                || replacements->second.count(reactor.handle) != 1u) return failDxfWrite();
    }
    for (unsigned int i=0; i<imageDef.size(); i++) {
        DRW_ImageDef *id = imageDef.at(i);
        std::map<std::string, const DRW_ImageDefinitionReactor*> selected;
        const auto plan = m_imagePlanSources.find(id);
        const auto replacements = m_regeneratedImageSourceReactors.find(id);
        if (plan != m_imagePlanSources.end() && replacements != m_regeneratedImageSourceReactors.end())
            for (const auto& candidate : plan->second->selectedReactors) {
                const auto replacement = replacements->second.find(candidate.handle);
                if (replacement != replacements->second.end()) selected.emplace(toHexStr(replacement->second), &candidate);
            }
        for (auto it=id->reactors.begin() ; it != id->reactors.end(); ++it ) {
            const auto found = selected.find(it->first);
            const DRW_ImageDefinitionReactor* source = found == selected.end() ? nullptr : found->second;
            writer->writeString(0, "IMAGEDEF_REACTOR");
            writer->writeString(5, (*it).first);
            writer->writeString(330, (*it).second);
            if (source != nullptr && !writeTableEntryAppData(*source)) return false;
            writer->writeString(100, "AcDbRasterImageDefReactor");
            writer->writeInt32(90, 2); //version 2=R14 to v2010
            writer->writeString(330, (*it).second);
            if (source != nullptr && !source->extData.empty() && !writeExtData(source->extData)) return false;
        }
    }
    if (imageDef.size() != 0) {
        if (m_generatedImageDictionarySource) {
            if (!writeDictionaryRecord(*m_generatedImageDictionarySource,
                    imageDictionaryHandle, 0xCu, true, &imageDictionaryEntries)
                || !preflightDxfWrite()
                || !bindDxfWriteSourceObjectHandle(m_generatedImageDictionarySource->handle,
                                                   imageDictionaryHandle)) return false;
        } else {
        writer->writeString(0, "DICTIONARY");
        writer->writeString(5, imgDictH);
        writer->writeString(330, "C");
        writer->writeString(100, "AcDbDictionary");
        writer->writeInt16(281, 1);
        for (unsigned int i=0; i<imageDef.size(); i++) {
            writer->writeUtf8String(3, imageDictionaryKeys.at(i));
            writer->writeString(350, toHexStr(imageDef.at(i)->handle) );
        }
        }
    }
    for (unsigned int i=0; i<imageDef.size(); i++) {
        DRW_ImageDef *id = imageDef.at(i);
        writer->writeString(0, "IMAGEDEF");
        writer->writeString(5, toHexStr(id->handle) );
        // Owner 330 = the AcDbRasterImageDef dictionary (imgDictH). A missing
        // owner triggers an INVALID_OWNER_HANDLE audit/repair in ezdxf/AutoCAD.
        // imgDictH is non-empty whenever imageDef is non-empty (set above).
        if (version > DRW::AC1014 && !imgDictH.empty()) {
            id->parentHandle = imageDictionaryHandle;
            writer->writeString(330, imgDictH);
        }
        if (!writeTableEntryAppData(*id, false))
            return false;
        std::vector<std::uint32_t> emittedReactors;
        const auto replacements = m_regeneratedImageSourceReactors.find(id);
        for (const auto source : id->reactorHandles) {
            if (replacements != m_regeneratedImageSourceReactors.end()
                && replacements->second.count(source) != 0u) continue;
            const auto emitted = m_referenceResolver ? resolveReference(source) : remapObjectHandle(source);
            if (source != 0u && m_referenceResolver && emitted == 0u) continue;
            if (source == 0u || emitted == 0u)
                return failDxfWrite();
            emittedReactors.push_back(emitted);
        }
        if (version < DRW::AC1014 && !emittedReactors.empty()) return failDxfWrite();
        // Minted reactor identities are final output IDs: never source-remap
        // them, even when an unrelated source has the same integer handle.
        for (const auto& reactor : id->reactors) {
            std::uint32_t emitted = 0u;
            const auto parsed = std::from_chars(reactor.first.data(),
                reactor.first.data() + reactor.first.size(), emitted, 16);
            if (parsed.ec != std::errc{} || parsed.ptr != reactor.first.data() + reactor.first.size()
                || emitted == 0u) return failDxfWrite();
            emittedReactors.push_back(emitted);
        }
        // Check collisions without reordering the retained source links or
        // charging a tree node for every reactor in a large valid record.
        auto uniqueReactors = emittedReactors;
        std::sort(uniqueReactors.begin(), uniqueReactors.end());
        if (std::adjacent_find(uniqueReactors.begin(), uniqueReactors.end()) != uniqueReactors.end())
            return failDxfWrite();
        writer->writeString(102, "{ACAD_REACTORS");
        for (const auto reactor : emittedReactors) {
            writer->writeString(330, toHexStr(reactor));
        }
        writer->writeString(102, "}");
        writer->writeString(100, "AcDbRasterImageDef");
        writer->writeInt32(90, id->imgVersion);
        writer->writeUtf8String(1, id->name);
        writer->writeDouble(10, id->u);
        writer->writeDouble(20, id->v);
        writer->writeDouble(11, id->up);
        // IMAGEDEF's DXF V pixel-size scalar is group 12 (not a point Y code).
        writer->writeDouble(12, id->vp);
        writer->writeInt16(280, id->loaded);
        writer->writeInt16(281, id->resolution);
        if (!id->extData.empty() && !writeExtData(id->extData))
            return false;
    }
    for (const auto& source : m_plannedImageSourceHandles) {
        if (m_generatedImageDictionarySource && source.first == m_generatedImageDictionarySource->handle) continue;
        if (!preflightDxfWrite() || !bindDxfWriteSourceObjectHandle(source.first, source.second)) return false;
    }
    //F4-followup: emit the named-dictionary OBJECTS the filter routed via
    //setNamedDictObjects (DWG->DXF). The root C dict already references these by
    //handle (setRootDictEntries spliced their (name, handle) into C above); this
    //makes them exist as reachable objects with a valid owner, clearing the
    //INVALID_OWNER_HANDLE fixes ezdxf otherwise applies to the dangling 350s.
    for (const DRW_Dictionary &dict : m_namedDictObjects) {
        if (m_writingContext.sourceHandleToWrittenTableMap.count(
                dict.handle) != 0)
            return failDxfWrite();
        const std::uint32_t dictionaryHandle =
            remapObjectHandle(dict.handle);
        if (dictionaryHandle == 0
            || isDxfFixedOutputHandle(dictionaryHandle)
            || !reserveHandle(dictionaryHandle)) {
            m_writeError = true;
            return false;
        }
        if (!writeDictionaryRecord(dict, dictionaryHandle,
                dict.parentHandle ? remapObjectHandle(dict.parentHandle) : 0xCu,
                version > DRW::AC1014, nullptr, DxfDictionaryRecordPhase::Emit))
            return false;
        if (!preflightDxfWrite()
            || !bindDxfWriteSourceObjectHandle(dict.handle, dictionaryHandle))
            return false;
    }

    //F3: emit each GROUP object, owned by the ACAD_GROUP D dict (which already
    //lists it as a (name, minted-handle) entry above). Every source member must
    //resolve through the writeEntity source->minted map; silently omitting one
    //would publish a structurally valid but semantically incomplete group.
    const auto &srcToMinted = m_writingContext.sourceHandleToMintedMap;
    for (std::size_t i = 0; i < m_groups.size(); ++i) {
        const DRW_Group &grp = m_groups[i];
        writer->writeString(0, "GROUP");
        writer->writeString(5, toHexStr(groupHandles[i]));
        if (!writeTableEntryAppData(grp))
            return false;
        writer->writeString(330, "D");
        writer->writeString(100, "AcDbGroup");
        writer->writeUtf8String(300, grp.m_description);
        writer->writeInt16(70, grp.m_isUnnamed ? 1 : 0);
        writer->writeInt16(71, grp.m_selectable ? 1 : 0);
        for (std::uint32_t memberSrc : grp.m_entityHandles) {
            auto it = srcToMinted.find(memberSrc);
            if (it == srcToMinted.end())
                return failDxfWrite();
            writer->writeString(340, toHexStr(it->second));
        }
        if (!grp.extData.empty() && !writeExtData(grp.extData))
            return false;
        // An authored GROUP may have no source identity. A supplied source
        // handle must bind to the record serialized, not its allocation alone.
        // A later failure rolls back the enclosing OBJECTS state and bytes.
        if (!preflightDxfWrite()
            || (grp.handle != DRW::NoHandle
                && !bindDxfWriteSourceObjectHandle(grp.handle, groupHandles[i])))
            return false;
    }

    if (m_writeError || writer->hasWriteError()) {
        m_writeError = true;
        return false;
    }
    iface->writeObjects();
    if (m_writeError || writer->hasWriteError())
        return false;
    const auto inspect = [this](std::string_view bytes) {
        return inspectDxfWriteSection(m_dxfObjectsWriteInspector, bytes);
    };
    if (!preflightDxfWrite() || !record.commit(inspect)) {
        m_writeError = true;
        return false;
    }
    state.commit();

    // IMAGEDEF pointers are owned by this write session. Keep them alive until
    // every OBJECTS byte has committed; resetDxfWriteSession discards carriers
    // from a failed attempt before the next callback traversal.
    for (DRW_ImageDef *id : imageDef)
        delete id;
    imageDef.clear();
    return true;
}

bool dxfRW::writeExtData(
    const std::vector<std::shared_ptr<DRW_Variant>> &ed) {
    if (!preflightDxfWrite())
        return false;
    // Keep the shared owners in place; materializing a second pointer array
    // does not add ownership or validation strength.
    return writeExtDataRange(ed, [](const std::shared_ptr<DRW_Variant>& value) {
        return value.get();
    });
}

bool dxfRW::writeExtData(const std::vector<DRW_Variant*> &ed){
    return writeExtDataRange(ed, [](DRW_Variant* value) { return value; });
}

template <typename Range, typename GetPointer>
bool dxfRW::writeExtDataRange(const Range& ed, GetPointer getPointer) {
    if (!preflightDxfWrite()) {
        m_writeError = true;
        return false;
    }

    // Validate the complete EED vector before emitting its first group.  EED
    // is appended to an already-open record, so validating as we write can
    // leave a syntactically incomplete record when a later variant is bad.
    const auto isValid = [](const DRW_Variant* value) {
        if (value == nullptr)
            return false;

        switch (value->code()) {
        case 1000:
        case 1001:
        case 1002:
        case 1003:
        case 1005:
            return value->type() == DRW_Variant::STRING
                && value->content.s != nullptr;
        case 1004:
            if (value->type() == DRW_Variant::BINARY) {
                return value->content.b != nullptr
                    && value->content.b->size()
                        <= DRW::kMaxDxfBinaryPayloadBytes;
            }
            return value->type() == DRW_Variant::STRING
                && value->content.s != nullptr
                && isDxfHexText(*value->content.s)
                && value->content.s->size() / 2u
                    <= DRW::kMaxDxfBinaryPayloadBytes;
        case 1010:
        case 1011:
        case 1012:
        case 1013:
            return value->type() == DRW_Variant::COORD
                && value->content.v != nullptr
                && std::isfinite(value->content.v->x)
                && std::isfinite(value->content.v->y)
                && std::isfinite(value->content.v->z);
        case 1040:
        case 1041:
        case 1042:
            return value->type() == DRW_Variant::DOUBLE
                && std::isfinite(value->content.d);
        case 1070:
            return value->type() == DRW_Variant::INTEGER;
        case 1071:
            if (value->type() == DRW_Variant::INTEGER)
                return true;
            return value->type() == DRW_Variant::INTEGER64
                && value->content.i64
                    >= std::numeric_limits<std::int32_t>::min()
                && value->content.i64
                    <= std::numeric_limits<std::int32_t>::max();
        default:
            return false;
        }
    };
    for (const auto& storedValue : ed) {
        const DRW_Variant* value = getPointer(storedValue);
        if (!isValid(value)) {
            m_writeError = true;
            return false;
        }
    }

    try {
        std::vector<std::string> applicationIds;
        if (!validateDxfXdataGroups(ed, getPointer, &applicationIds)) {
            recordOperationDiagnostic(
                DRW::OperationPhase::Validation,
                DRW::OperationCause::ValidationFailure,
                "xdata-group-structure",
                "XDATA must have unique APPID groups and balanced controls");
            m_writeError = true;
            return false;
        }
        for (std::string& appId : applicationIds)
            m_requiredDxfXdataAppIds.insert(std::move(appId));
    } catch (...) {
        m_writeError = true;
        return false;
    }

    // The public typed XDATA strings are semantic UTF-8, not source bytes.
    // Validate the selected encoded representation before the first group is
    // emitted: source-codepage bytes and lossy supplementary fallbacks cannot
    // be silently published as successful text conversion. Tolerant reading
    // and opaque raw replay remain separate contracts.
    try {
        DRW_TextCodec verification;
        verification.setVersion(version, true);
        verification.setCodePage(writer->getCodePage(), true);
        for (const auto& storedValue : ed) {
            const DRW_Variant* value = getPointer(storedValue);
            const int code = value->code();
            if (code != 1000 && code != 1001 && code != 1003)
                continue;
            const std::string& text = *value->content.s;
            if (!isUtf8ScalarText(text) || !isSafeDxfRecordText(text)) {
                recordOperationDiagnostic(DRW::OperationPhase::Validation,
                    DRW::OperationCause::ValidationFailure, "xdata-text-encoding",
                    "typed XDATA text must contain valid UTF-8 scalar values");
                m_writeError = true;
                return false;
            }
            std::string encodedStorage;
            std::string_view encoded(text.data(), text.size());
            if (!writer->usesCompatibleModernDxfUtf8() || !binFile) {
                encodedStorage = writer->fromUtf8String(text);
                encoded = std::string_view(encodedStorage.data(),
                                           encodedStorage.size());
            }
            if ((code == 1000 && encoded.size() > 255u)
                || (code == 1001 && encoded.size() > 31u)) {
                recordOperationDiagnostic(DRW::OperationPhase::Validation,
                    DRW::OperationCause::ValidationFailure, "xdata-text-length",
                    "encoded XDATA text exceeds its group byte limit");
                m_writeError = true;
                return false;
            }
            if (verification.toUtf8(encoded, !binFile) != text) {
                recordOperationDiagnostic(DRW::OperationPhase::Validation,
                    DRW::OperationCause::ValidationFailure, "xdata-text-encoding",
                    "typed XDATA text cannot be represented losslessly by the target codec");
                m_writeError = true;
                return false;
            }
        }
    } catch (...) {
        m_writeError = true;
        return false;
    }

    bool success = true;
    const auto recordResult = [&success, this](bool result) {
        if (!result) {
            success = false;
            m_writeError = true;
        }
    };
    const auto writeBinaryHex = [this](std::string_view hex) {
        if (!isDxfHexText(hex)
            || hex.size() / 2u > DRW::kMaxDxfBinaryPayloadBytes)
            return false;
        if (hex.empty())
            return writer->writeString(1004, std::string_view{});
        constexpr std::size_t kHexChunkLength = 2u * 127u;
        for (std::size_t offset = 0; offset < hex.size();
             offset += kHexChunkLength) {
            const std::size_t count = std::min(kHexChunkLength,
                                               hex.size() - offset);
            if (!writer->writeString(1004, hex.substr(offset, count)))
                return false;
        }
        return true;
    };
    const auto writeBinaryBytes = [this](
            const std::vector<std::uint8_t>& bytes) {
        if (bytes.size() > DRW::kMaxDxfBinaryPayloadBytes)
            return false;
        if (bytes.empty())
            return writer->writeString(1004, std::string_view{});
        static constexpr char hexDigits[] = "0123456789ABCDEF";
        constexpr std::size_t kChunkBytes = 127u;
        char encoded[kChunkBytes * 2u];
        for (std::size_t offset = 0; offset < bytes.size();
             offset += kChunkBytes) {
            const std::size_t count = std::min(kChunkBytes,
                                               bytes.size() - offset);
            for (std::size_t i = 0; i < count; ++i) {
                const std::uint8_t byte = bytes[offset + i];
                encoded[2u * i] = hexDigits[byte >> 4u];
                encoded[2u * i + 1u] = hexDigits[byte & 0x0Fu];
            }
            if (!writer->writeString(
                    1004, std::string_view(encoded, count * 2u)))
                return false;
        }
        return true;
    };

    try {
        for (const auto& storedValue : ed) {
            const DRW_Variant* it = getPointer(storedValue);
            if (it == nullptr) {
                recordResult(false);
                continue;
            }
            switch (it->code()) {
                case 1000:
                case 1001:
                case 1003: {
                    const int cc = it->code();
                    if (it->type() != DRW_Variant::STRING
                        || it->content.s == nullptr) {
                        recordResult(false);
                        break;
                    }
                    recordResult(writer->writeUtf8String(
                        cc, *it->content.s));
                    break;
                }
                case 1002:
                    recordResult(writer->writeString(1002, *it->content.s));
                    break;
                case 1005: {
                    if (it->type() != DRW_Variant::STRING
                        || it->content.s == nullptr) {
                        recordResult(false);
                        break;
                    }
                    const std::string& text = *it->content.s;
                    std::uint64_t sourceHandle = 0;
                    const char* begin = text.data();
                    const char* end = begin + text.size();
                    const auto parsed = std::from_chars(
                        begin, end, sourceHandle, 16);
                    if (m_referenceResolver) {
                        if (parsed.ec == std::errc{} && parsed.ptr == end
                            && sourceHandle != 0
                            && sourceHandle
                                <= std::numeric_limits<std::uint32_t>::max()) {
                            const std::uint32_t emitted = resolveReference(
                                static_cast<std::uint32_t>(sourceHandle));
                            recordResult(writer->writeString(
                                1005, toHexStr(emitted)));
                        } else {
                            // A literal zero is not an absent optional edge;
                            // malformed legacy spellings are opaque data.
                            // Match the bundled facade's resolver contract.
                            recordResult(writer->writeString(1005, text));
                        }
                        break;
                    }
                    if (parsed.ec != std::errc{} || parsed.ptr != end
                        || sourceHandle
                            > std::numeric_limits<std::uint32_t>::max()) {
                        recordResult(false);
                        break;
                    }
                    const std::string outputHandle = toHexStr(
                        remapObjectHandle(
                            static_cast<std::uint32_t>(sourceHandle)));
                    recordResult(writer->writeString(1005, outputHandle));
                    break;
                }
                case 1004:
                    // DXF code 1004 is binary chunk data; emitted as a
                    // hex-encoded string. Both BINARY (from DWG path) and
                    // STRING (from a DXF round-trip that already hex-encoded
                    // the bytes) variants are accepted.
                    if (it->type() == DRW_Variant::BINARY) {
                        const std::vector<std::uint8_t>* bytes =
                            it->content.b;
                        if (bytes == nullptr
                            || bytes->size() > DRW::kMaxDxfBinaryPayloadBytes) {
                            recordResult(false);
                            break;
                        }
                        recordResult(writeBinaryBytes(*bytes));
                    } else if (it->type() == DRW_Variant::STRING
                               && it->content.s != nullptr
                               && isDxfHexText(*it->content.s)) {
                        recordResult(writeBinaryHex(*it->content.s));
                    } else {
                        recordResult(false);
                    }
                    break;
                case 1010:
                case 1011:
                case 1012:
                case 1013:
                    if (it->type() != DRW_Variant::COORD
                        || it->content.v == nullptr
                        || !std::isfinite(it->content.v->x)
                        || !std::isfinite(it->content.v->y)
                        || !std::isfinite(it->content.v->z)) {
                        recordResult(false);
                        break;
                    }
                    recordResult(writer->writeDouble(
                        it->code(), it->content.v->x));
                    recordResult(writer->writeDouble(
                        it->code()+10, it->content.v->y));
                    recordResult(writer->writeDouble(
                        it->code()+20, it->content.v->z));
                    break;
                case 1040:
                case 1041:
                case 1042:
                    recordResult(it->type() == DRW_Variant::DOUBLE
                        && std::isfinite(it->content.d)
                        && writer->writeDouble(it->code(), it->content.d));
                    break;
                case 1070:
                    recordResult(it->type() == DRW_Variant::INTEGER
                        && writer->writeInt16(it->code(), it->content.i));
                    break;
                case 1071:
                    if (it->type() == DRW_Variant::INTEGER) {
                        recordResult(writer->writeInt32(
                            it->code(), it->content.i));
                    } else if (it->type() == DRW_Variant::INTEGER64) {
                        const std::int64_t value = it->content.i64;
                        recordResult(
                            value >= std::numeric_limits<std::int32_t>::min()
                            && value <= std::numeric_limits<std::int32_t>::max()
                            && writer->writeInt32(
                                it->code(), static_cast<std::int32_t>(value)));
                    } else {
                        recordResult(false);
                    }
                    break;
                default:
                    break;
            }
        }
    } catch (...) {
        m_writeError = true;
        return false;
    }
    return success && !writer->hasWriteError();
}

/********* Reader Process *********/

bool dxfRW::processDxf() {
    DRW_DBG("dxfRW::processDxf() start processing dxf\n");
    int code {-1};
    bool inSection {false};

    reader->setIgnoreComments( false);
    while (reader->readRec(&code)) {
        DRW_DBG(code); DRW_DBG(" code\n");
        /* at this level we should only get:
         999 - Comment
         0 - SECTION or EOF
         2 - section name
         everything else between "2 - section name" and "0 - ENDSEC" is handled in process() methods
        */
        switch (code) {
        case 999: // when DXF was created by libdxfrw, first record is a comment with dxfrw version info
            if (!appendDxfReadHeaderComment(reader->getRawValue()))
                return false;
            continue;

            case 0:
                // DXF comment policy: retain 999 records before the first SECTION
                // in DRW_Header; comments inside sections are deliberately skipped
                // by dxfReader and are not part of typed or raw-record replay.
                reader->setIgnoreComments(true);
                if (inSection)
                    return setError(DRW::BAD_READ_SECTION);
                {
                const std::string_view sectionstr = reader->getStringView();

                    if (dxfKeywordEquals(sectionstr, "SECTION")) {
                        DRW_DBG(sectionstr.data());
                        DRW_DBG(" new section\n");
                        inSection = true;
                        continue;
                    }
                    if (dxfKeywordEquals(sectionstr, "EOF")) {
                        return true; //found EOF terminate
                    }
                }
                return setError(DRW::BAD_READ_SECTION);

        case 2:
                if (!inSection)
                    return setError(DRW::BAD_READ_SECTION);
                {
                bool processed{false};
                const std::string_view sectionName = reader->getStringView();

                    DRW_DBG(sectionName.data());
                    DRW_DBG(" process section\n");
                    if (dxfKeywordEquals(sectionName, "HEADER")) {
                        processed = processHeader();
                    }
                else if (dxfKeywordEquals(sectionName, "CLASSES")) {
                    processed = processClasses();
                    }
                    else if (dxfKeywordEquals(sectionName, "TABLES")) {
                        processed = processTables();
                    }
                    else if (dxfKeywordEquals(sectionName, "BLOCKS")) {
                        processed = processBlocks();
                    }
                    else if (dxfKeywordEquals(sectionName, "ENTITIES")) {
                        processed = processEntities(false);
                        if (processed
                            && !dxfKeywordEquals(nextentity, "ENDSEC")) {
                            processed = setError(DRW::BAD_READ_ENTITIES);
                        }
                    }
                    else if (dxfKeywordEquals(sectionName, "OBJECTS")) {
                        processed = processObjects();
                    }
                    else {
                        DRW_DBG(" section unknown or not supported\n");
                        processed = processRawDxfSection(sectionName);
                        if (!processed)
                            return false;
                    }

                    if (!processed) {
                        DRW_DBG("  failed\n");
                        if (failDxfReadBudget())
                            return false;
                        // Keep the specific section error (for example
                        // BAD_READ_TABLES from a malformed table entry)
                        // instead of replacing it with the generic section
                        // failure.
                        return error == DRW::BAD_NONE
                            ? setError(DRW::BAD_READ_SECTION)
                            : false;
                    }

                    inSection = false;
                }
                continue;

            default:
                // The outer stream contains only section framing. A record
                // body outside a SECTION must not be skipped as a successful
                // read, since table/object state may be required by ENTITIES.
                return setError(DRW::BAD_READ_SECTION);
        }
    }

    if (failDxfReadBudget())
        return false;

    if (0 == code && reader->getStringView() == "EOF") {
        // in case the final EOF has no newline we end up here!
        // this is caused by filestr->good() which is false for missing newline on EOF
        return true;
    }

    return setError(DRW::BAD_UNKNOWN);
}

bool dxfRW::processRawDxfSection(std::string_view sectionName) {
    if (sectionName.empty())
        return setError(DRW::BAD_READ_SECTION);

    DRW_RawDxfSection section;
    const auto& retainedBudget = reader->retainedByteBudget();
    if (retainedBudget != nullptr) {
        section.m_retainedTextLease =
            std::make_shared<DxfReadRetainedLease>(retainedBudget);
        if (!section.m_retainedTextLease->add(sectionName.size()))
            return failDxfReadRetainedBudget();
    }
    section.m_name.assign(sectionName.data(), sectionName.size());
    section.m_hasRawValues = !binFile;
    DxfRawHandleLexemeScope handleLexemes(*reader);
    int applicationDepth = 0;
    int code = 0;
    std::size_t pairCount = 0;
    while (reader->readRec(&code)) {
        if (++pairCount > DRW::kMaxDxfApplicationGroupPairs)
            return setError(DRW::BAD_CODE_PARSED);
        if (code == 0
            && dxfKeywordEquals(reader->getStringView(), "ENDSEC")) {
            if (applicationDepth != 0)
                return setError(DRW::BAD_CODE_PARSED);
            section.m_version = reader->getSourceVersion();
            iface->addRawDxfSection(section);
            return true;
        }

        DRW_RawDxfObject group;
        group.m_retainedTextLease = section.m_retainedTextLease;
        if (!captureRawGroup(group, code, /*validateHandles=*/true)) {
            recordInvalidRawHandleDiagnostic();
            return setError(DRW::BAD_CODE_PARSED);
        }
        if (group.groups.empty()
            || !updateRawDxfApplicationDepth(group.groups.back(),
                                               applicationDepth))
            return setError(DRW::BAD_CODE_PARSED);
        try {
            section.m_groups.push_back(std::move(group.groups.back()));
            section.m_rawValues.push_back(std::move(group.rawValues.back()));
        } catch (...) {
            return setError(DRW::BAD_CODE_PARSED);
        }
    }
    recordInvalidRawHandleDiagnostic();
    return setError(DRW::BAD_READ_SECTION);
}

/********* Header Section *********/

bool dxfRW::processHeader() {
    DRW_DBG("dxfRW::processHeader\n");
    int code;
    std::string_view sectionstr;
    while (reader->readRec(&code)) {
        DRW_DBG(code); DRW_DBG(" processHeader\n");
        if (code == 0) {
            sectionstr = reader->getStringView();
            DRW_DBG(sectionstr.data()); DRW_DBG(" processHeader\n\n");
            if (dxfKeywordEquals(sectionstr, "ENDSEC")) {
                if (!header.finalizeDxfHeader(reader))
                    return setError(DRW::BAD_CODE_PARSED);
                // Naming diagnostics must observe the original declaration,
                // not the canonical spelling reapplied during finalization.
                // R2007+ DXF uses UTF8, so legacy metadata selects no byte
                // decoder there. These bounded advisories are nonfatal.
                if (!reader->hasSourceVersion()
                    || reader->getSourceVersion() < DRW::AC1021) {
                    const auto selection = reader->declaredCodePageSelection();
                    const char* diagnosticCode = nullptr;
                    const char* diagnosticMessage = nullptr;
                    if (selection.kind == DRW_CodePageKind::CompatibilityAlias) {
                        diagnosticCode = "compatibility-codepage-alias";
                        diagnosticMessage = reader->dxfCodePagePolicy() == DRW::DxfCodePagePolicy::ExactNamed
                            ? "declared name is a historical compatibility alias; explicit exact input selection is separate"
                            : "legacy codepage alias uses a historical compatibility decoder; byte equivalence is not assured";
                    } else if (selection.kind == DRW_CodePageKind::Unavailable) {
                        diagnosticCode = "unavailable-codepage";
                        diagnosticMessage = reader->dxfCodePagePolicy() == DRW::DxfCodePagePolicy::ExactNamed
                            ? "declared spelling lacks a historical selection route; explicit exact input selection is separate"
                            : "recognized codepage has no implemented selection route; compatibility fallback retained";
                    } else if (selection.kind == DRW_CodePageKind::Unknown) {
                        diagnosticCode = "unknown-codepage";
                        diagnosticMessage = reader->dxfCodePagePolicy() == DRW::DxfCodePagePolicy::ExactNamed
                            ? "unrecognized declaration is ineligible for exact named decoding"
                            : "unrecognized codepage uses the compatibility fallback";
                    } else if (selection.selectedName != nullptr
                               && std::string_view(selection.selectedName) != reader->getCodePage()) {
                        diagnosticCode = "reapplied-codepage";
                        diagnosticMessage = "legacy codepage metadata was normalized and reapplied by compatibility policy";
                    }
                    if (diagnosticCode != nullptr)
                        recordOperationDiagnostic(DRW::OperationPhase::Header,
                            DRW::OperationCause::ValidationFailure,
                            diagnosticCode, diagnosticMessage, 0, false, 0, false, true);
                }
                iface->addHeader(&header);
                return true;  //found ENDSEC terminate
            }

            DRW_DBG("unexpected 0 code in header!\n");
            return setError(DRW::BAD_READ_HEADER);
        }

        if (!header.parseCodeImpl(code, reader, !header.m_dxfHeaderFinalized)) {
            // An unrecognised $ACADVER no longer fails here, so a failure at
            // this point is a malformed record rather than a version problem
            // and must not be reported as BAD_VERSION: the source version is
            // UNKNOWNV for every such file, and classifying on it would label
            // any unrelated header parse failure a version failure.
            return setError(DRW::BAD_CODE_PARSED);
        }
    }
    return setError(DRW::BAD_READ_HEADER);
}

/********* Classes Section *********/

bool dxfRW::processClasses() {
    DRW_DBG("dxfRW::processClasses\n");
    int code = 0;
    bool reading = false;
    DRW_Class cls;
    std::vector<DRW_Class> pendingClasses;
    DxfReadRetainedReservation classTextReservation(
        reader->retainedByteBudget(), 0u);
    std::size_t classTextBytes = 0u;
    bool hasRecName = false;
    bool hasClassName = false;
    bool hasAppName = false;
    bool hasProxyFlag = false;
    bool hasInstanceCount = false;
    bool hasWasaProxyFlag = false;
    bool hasEntityFlag = false;

    auto retainClassText = [&](std::string value,
                               std::string& destination) -> bool {
        const std::size_t maxSize =
            (std::numeric_limits<std::size_t>::max)();
        if (value.size() > maxSize - classTextBytes)
            return failDxfReadRetainedBudget();
        const std::size_t nextBytes = classTextBytes + value.size();
        if (!classTextReservation.resize(nextBytes))
            return failDxfReadRetainedBudget();
        classTextBytes = nextBytes;
        destination = std::move(value);
        return true;
    };

    auto finishClass = [&]() -> bool {
        if (!reading)
            return true;
        // Every CLASS group defined by the DXF reference is mandatory. An
        // internal proxy class may have an empty record name, but it must still
        // carry code 1; otherwise default-initialized metadata would be
        // published as a plausible class. Group 91 was introduced with the
        // R2004 class-instance trailer and is absent from older records.
        if (!hasRecName || !hasClassName || !hasAppName || !hasProxyFlag
            || !hasWasaProxyFlag || !hasEntityFlag
            || (reader->getSourceVersion() > DRW::AC1015
                && !hasInstanceCount)) {
            DRW_DBG("malformed CLASS record: missing required group\n");
            return false;
        }
        if (pendingClasses.size() >= DRW::kMaxDxfClasses)
            return false;
        // Transfer the current row into the section batch. Copying here would
        // temporarily duplicate its three retained strings without charging
        // those bytes to the aggregate retained-text budget.
        pendingClasses.push_back(std::move(cls));
        cls = DRW_Class{};
        return true;
    };

    while (reader->readRec(&code)) {
        DRW_DBG(code); DRW_DBG(" processClasses\n");
        if (code == 0) {
            if (!finishClass())
                return setError(DRW::BAD_CODE_PARSED);
            const std::string_view sectionstr = reader->getStringView();
            DRW_DBG(sectionstr.data()); DRW_DBG(" processClasses\n\n");
            if (dxfKeywordEquals(sectionstr, "CLASS")) {
                reading = true;
                cls = DRW_Class{};
                hasRecName = false;
                hasClassName = false;
                hasAppName = false;
                hasProxyFlag = false;
                hasInstanceCount = false;
                hasWasaProxyFlag = false;
                hasEntityFlag = false;
                continue;
            }
            if (dxfKeywordEquals(sectionstr, "ENDSEC")) {
                for (const DRW_Class &pendingClass : pendingClasses)
                    iface->addDxfClass(pendingClass);
                return true;
            }

            DRW_DBG("unexpected 0 code in classes section!\n");
            return setError(DRW::BAD_READ_HEADER);
        }

        if (!reading)
            return setError(DRW::BAD_CODE_PARSED);

        switch (code) {
        case 1:
            if (hasRecName)
                return setError(DRW::BAD_CODE_PARSED);
            hasRecName = true;
            if (!retainClassText(reader->getUtf8String(), cls.recName))
                return false;
            break;
        case 2:
            if (hasClassName)
                return setError(DRW::BAD_CODE_PARSED);
            hasClassName = true;
            if (!retainClassText(reader->getUtf8String(), cls.className))
                return false;
            break;
        case 3:
            if (hasAppName)
                return setError(DRW::BAD_CODE_PARSED);
            hasAppName = true;
            if (!retainClassText(reader->getUtf8String(), cls.appName))
                return false;
            break;
        case 90:
            if (hasProxyFlag)
                return setError(DRW::BAD_CODE_PARSED);
            hasProxyFlag = true;
            cls.proxyFlag = reader->getInt32();
            // LibreDWG sets the upper 16 bits even though this is a 16-bit mask.
            if ((static_cast<std::uint32_t>(cls.proxyFlag) >> 16) == 0xFFFFu)
                cls.proxyFlag &= 0xFFFF;
            if (cls.proxyFlag < 0)
                return setError(DRW::BAD_CODE_PARSED);
            break;
        case 91:
            if (hasInstanceCount)
                return setError(DRW::BAD_CODE_PARSED);
            hasInstanceCount = true;
            cls.instanceCount = reader->getInt32();
            if (cls.instanceCount < 0)
                return setError(DRW::BAD_CODE_PARSED);
            break;
        case 280:
            if (hasWasaProxyFlag)
                return setError(DRW::BAD_CODE_PARSED);
            hasWasaProxyFlag = true;
            cls.wasaProxyFlag = reader->getInt32();
            if (cls.wasaProxyFlag < 0 || cls.wasaProxyFlag > 1)
                return setError(DRW::BAD_CODE_PARSED);
            break;
        case 281:
            if (hasEntityFlag)
                return setError(DRW::BAD_CODE_PARSED);
            cls.entityFlag = reader->getInt32();
            if (cls.entityFlag < 0 || cls.entityFlag > 1)
                return setError(DRW::BAD_CODE_PARSED);
            hasEntityFlag = true;
            break;
        default:
            break;
        }
    }

    return setError(DRW::BAD_READ_HEADER);
}

/********* Tables Section *********/

bool dxfRW::processTables() {
    DRW_DBG("dxfRW::processTables\n");
    int code;
    std::string_view sectionstr;
    bool more = true;
    std::uint64_t skippedUnknownTableCount = 0;
    std::vector<std::string> skippedUnknownTableNames;
    std::size_t skippedUnknownTableNameBytes = 0u;
    DxfReadRetainedReservation skippedUnknownTableReservation(
        reader->retainedByteBudget(), 0u);
    const auto recordSkippedUnknownTables = [this, &skippedUnknownTableCount,
            &skippedUnknownTableNames, &skippedUnknownTableNameBytes,
            &skippedUnknownTableReservation]() {
        if (skippedUnknownTableCount == 0)
            return true;

        const std::string countText =
            std::to_string(skippedUnknownTableCount);
        const std::string omittedText = skippedUnknownTableCount
                > skippedUnknownTableNames.size()
            ? std::to_string(skippedUnknownTableCount
                             - skippedUnknownTableNames.size())
            : std::string{};
        const auto addSize = [](std::size_t& total, std::size_t amount) {
            const std::size_t maxSize =
                (std::numeric_limits<std::size_t>::max)();
            if (amount > maxSize - total)
                return false;
            total += amount;
            return true;
        };
        std::size_t messageBytes = sizeof("skipped ") - 1u;
        if (!addSize(messageBytes, countText.size())
            || !addSize(messageBytes,
                        sizeof(" unsupported nested TABLE(s); names: ") - 1u))
            return failDxfReadRetainedBudget();
        for (std::size_t index = 0;
             index < skippedUnknownTableNames.size(); ++index) {
            if ((index != 0u && !addSize(messageBytes, 2u))
                || !addSize(messageBytes,
                            skippedUnknownTableNames[index].size()))
                return failDxfReadRetainedBudget();
        }
        if (!omittedText.empty()
            && (!addSize(messageBytes, sizeof("; ") - 1u)
                || !addSize(messageBytes, omittedText.size())
                || !addSize(messageBytes,
                            sizeof(" additional name(s) omitted") - 1u)))
            return failDxfReadRetainedBudget();

        const bool canAppendSecondary =
            m_lastDiagnostic.secondary.size()
                < DRW::OperationDiagnostic::MaxSecondaryEntries;
        auto replaceable = m_lastDiagnostic.secondary.rend();
        if (!canAppendSecondary) {
            replaceable = std::find_if(
                m_lastDiagnostic.secondary.rbegin(),
                m_lastDiagnostic.secondary.rend(),
                [](const DRW::OperationDiagnosticEntry& existing) {
                    return existing.cause == DRW::OperationCause::None;
                });
        }
        const bool recordAsPrimary = !canAppendSecondary
            && replaceable == m_lastDiagnostic.secondary.rend()
            && !m_lastDiagnostic.failed();
        std::size_t peakBytes = skippedUnknownTableNameBytes;
        if (!addSize(peakBytes, messageBytes)
            || (recordAsPrimary && !addSize(peakBytes, messageBytes)))
            return failDxfReadRetainedBudget();
        if (!skippedUnknownTableReservation.resize(peakBytes))
            return failDxfReadRetainedBudget();

        std::string message;
        message.reserve(messageBytes);
        message.append("skipped ");
        message.append(countText);
        message.append(" unsupported nested TABLE(s); names: ");
        for (std::size_t index = 0;
             index < skippedUnknownTableNames.size(); ++index) {
            if (index != 0u)
                message.append(", ");
            message.append(skippedUnknownTableNames[index]);
        }
        if (!omittedText.empty()) {
            message.append("; ");
            message.append(omittedText);
            message.append(" additional name(s) omitted");
        }

        DRW::OperationDiagnosticEntry entry;
        entry.phase = DRW::OperationPhase::Tables;
        entry.code = "unsupported-table-skipped";
        entry.message = std::move(message);
        if (m_lastDiagnostic.secondary.size()
            < DRW::OperationDiagnostic::MaxSecondaryEntries) {
            m_lastDiagnostic.secondary.push_back(std::move(entry));
        } else if (replaceable != m_lastDiagnostic.secondary.rend()) {
            // Keep the loss visible when unrelated advisory details have
            // filled the bounded secondary list. Prefer replacing a
            // non-failure advisory; if every slot contains failure evidence,
            // preserve those failures.
            *replaceable = std::move(entry);
        } else if (!m_lastDiagnostic.failed()) {
            recordOperationDiagnostic(
                DRW::OperationPhase::Tables, DRW::OperationCause::None,
                "unsupported-table-skipped", entry.message.c_str());
        }
        const bool messageRetained = canAppendSecondary
            || replaceable != m_lastDiagnostic.secondary.rend()
            || recordAsPrimary;
        entry.message.clear();
        skippedUnknownTableNames.clear();
        skippedUnknownTableNameBytes = 0u;
        if (messageRetained) {
            if (!skippedUnknownTableReservation.resize(messageBytes))
                return failDxfReadRetainedBudget();
            skippedUnknownTableReservation.transfer();
        } else if (!skippedUnknownTableReservation.resize(0u)) {
            return failDxfReadRetainedBudget();
        }
        return true;
    };
    while (reader->readRec(&code)) {
        DRW_DBG(code); DRW_DBG("\n");
        if (code == 0) {
            sectionstr = reader->getStringView();
            DRW_DBG(sectionstr.data()); DRW_DBG(" processHeader\n\n");
            if (dxfKeywordEquals(sectionstr, "TABLE")) {
                more = reader->readRec(&code);
                DRW_DBG(code); DRW_DBG("\n");
                if (!more || code != 2) {
                    if (!recordSkippedUnknownTables())
                        return false;
                    return setError(DRW::BAD_READ_TABLES); //wrong dxf file
                }
                sectionstr = reader->getStringView();
                DRW_DBG(sectionstr.data()); DRW_DBG(" processHeader\n\n");
                //found section, process it
                bool processed = true;
                if (dxfKeywordEquals(sectionstr, "LTYPE")) {
                    processed = processLType();
                } else if (dxfKeywordEquals(sectionstr, "LAYER")) {
                    processed = processLayer();
                } else if (dxfKeywordEquals(sectionstr, "STYLE")) {
                    processed = processTextStyle();
                } else if (dxfKeywordEquals(sectionstr, "VPORT")) {
                    processed = processVports();
                } else if (dxfKeywordEquals(sectionstr, "VIEW")) {
                    processed = processView();
                } else if (dxfKeywordEquals(sectionstr, "UCS")) {
                    processed = processUCS();
                } else if (dxfKeywordEquals(sectionstr, "APPID")) {
                    processed = processAppId();
                } else if (dxfKeywordEquals(sectionstr, "DIMSTYLE")) {
                    processed = processDimStyle();
                } else if (dxfKeywordEquals(sectionstr, "BLOCK_RECORD")) {
                    processed = processBlockRecord();
                } else {
                    // Unknown tables are allowed, but their terminator still
                    // belongs to the section grammar.  Consume the table as
                    // an opaque stream and reject ENDSEC before ENDTAB so a
                    // malformed table cannot be mistaken for a valid one.
                    constexpr std::size_t MaxTableNameBytes = 64;
                    const bool retainUnknownTableName =
                        skippedUnknownTableNames.size() < 8u;
                    std::string skippedTableName;
                    if (retainUnknownTableName) {
                        const std::size_t nameBytes = std::min(
                            sectionstr.size(), MaxTableNameBytes);
                        if (nameBytes > (std::numeric_limits<std::size_t>::max)()
                                            - skippedUnknownTableNameBytes
                            || !skippedUnknownTableReservation.resize(
                                skippedUnknownTableNameBytes + nameBytes))
                            return failDxfReadRetainedBudget();
                        skippedUnknownTableNameBytes += nameBytes;
                        skippedTableName.assign(sectionstr.data(), nameBytes);
                    }
                    bool ended = false;
                    while (reader->readRec(&code)) {
                        if (code != 0)
                            continue;
                        const std::string_view tableRecord =
                            reader->getStringView();
                        if (dxfKeywordEquals(tableRecord, "ENDTAB")) {
                            ended = true;
                            break;
                        }
                        if (dxfKeywordEquals(tableRecord, "ENDSEC")) {
                            if (!recordSkippedUnknownTables())
                                return false;
                            return setError(DRW::BAD_READ_TABLES);
                        }
                    }
                    if (!ended) {
                        if (!recordSkippedUnknownTables())
                            return false;
                        return setError(DRW::BAD_READ_TABLES);
                    }
                    if (skippedUnknownTableCount
                        != std::numeric_limits<std::uint64_t>::max())
                        ++skippedUnknownTableCount;
                    if (retainUnknownTableName)
                        skippedUnknownTableNames.push_back(
                            std::move(skippedTableName));
                }
                if (!processed) {
                    if (!recordSkippedUnknownTables())
                        return false;
                    return false;
                }
            } else if (dxfKeywordEquals(sectionstr, "ENDSEC")) {
                if (!recordSkippedUnknownTables())
                    return false;
                return true;  //found ENDSEC terminate
            }
        }
    }

    if (!recordSkippedUnknownTables())
        return false;
    return setError(DRW::BAD_READ_TABLES);
}

bool dxfRW::processBlockRecord() {
    DRW_DBG("dxfRW::processBlockRecord\n");
    int code = 0;
    bool reading = false;
    bool readingBlkRefs = false;
    bool readingXDictionary = false;
    bool xDictionarySeen = false;
    int ignoredApplicationDepth = 0;
    std::uint32_t handle = DRW::NoHandle;
    DRW_Block_Record publicRecord;
    std::unordered_set<std::uint32_t> recordInsertHandles;
    std::vector<DRW_Block_Record> pendingPublicBlockRecords;
    std::size_t activeInsertIndexBytes = 0u;
    std::size_t activeInsertOwnerBytes = 0u;
    std::size_t activePreviewOwnerBytes = 0u;
    DxfReadRetainedReservation activeInsertIndexReservation(
        reader->retainedByteBudget(), 0u);
    auto growRetainedBytes = [this](DxfReadRetainedReservation& reservation,
                                    std::size_t& currentBytes,
                                    std::size_t addedBytes) {
        const std::size_t maxSize =
            (std::numeric_limits<std::size_t>::max)();
        if (addedBytes > maxSize - currentBytes)
            return failDxfReadRetainedBudget();
        const std::size_t nextBytes = currentBytes + addedBytes;
        if (!reservation.resize(nextBytes))
            return failDxfReadRetainedBudget();
        currentBytes = nextBytes;
        return true;
    };

    auto finishRecord = [&]() -> bool {
        if (!reading)
            return true;
        if (readingBlkRefs || readingXDictionary
            || ignoredApplicationDepth != 0)
            return false;
        const DRW::Version sourceVersion = reader->getSourceVersion();
        if (publicRecord.name.empty()
            || (sourceVersion != DRW::UNKNOWNV
                && sourceVersion > DRW::AC1009
                && handle == DRW::NoHandle))
            return false;
        // Keep the full table entry, including XDATA, available to consumers
        // without folding it into the BLOCK entity.  The latter is a distinct
        // DXF record and must retain its own entity-level metadata. This move
        // is the only staged public owner; the internal context projection is
        // copied once, under its own retained-byte reservation at publication.
        publicRecord.handle = handle;
        pendingPublicBlockRecords.push_back(std::move(publicRecord));
        if (!activeInsertIndexReservation.resize(0u))
            return failDxfReadRetainedBudget();
        activeInsertIndexBytes = 0u;
        activeInsertOwnerBytes = 0u;
        activePreviewOwnerBytes = 0u;
        return true;
    };
    const auto publishBlockRecords = [&]() -> bool {
        std::size_t contextRecordCount = 0u;
        std::size_t contextCopyBytes = 0u;
        const std::size_t maxSize =
            (std::numeric_limits<std::size_t>::max)();
        const auto addContextCopyBytes = [&contextCopyBytes](
                std::size_t bytes) {
            if (bytes > maxSize - contextCopyBytes)
                return false;
            contextCopyBytes += bytes;
            return true;
        };
        for (const DRW_Block_Record& entry : pendingPublicBlockRecords) {
            if (entry.handle == DRW::NoHandle)
                continue;
            if (m_readingContext.blockRecordMap.find(entry.handle)
                    != m_readingContext.blockRecordMap.end())
                return false;
            if (entry.insertHandles.size() > maxSize / sizeof(std::uint32_t)
                || !addContextCopyBytes(entry.name.size())
                || !addContextCopyBytes(entry.previewData.size())
                || !addContextCopyBytes(
                    entry.insertHandles.size() * sizeof(std::uint32_t)))
                return failDxfReadRetainedBudget();
            ++contextRecordCount;
        }

        DxfReadRetainedReservation contextCopyReservation(
            reader->retainedByteBudget(), contextCopyBytes);
        if (!contextCopyReservation.reserved())
            return failDxfReadRetainedBudget();

        auto& contextRecords = m_readingContext.blockRecordMap;
        if (contextRecordCount > contextRecords.max_size() - contextRecords.size())
            return failDxfReadRetainedBudget();
        std::unordered_map<std::uint32_t,
                           DRW_ParsingContext::BlockRecordInfo>
            stagedContextRecords;
        stagedContextRecords.reserve(contextRecordCount);
        for (const DRW_Block_Record& entry : pendingPublicBlockRecords) {
            if (entry.handle == DRW::NoHandle)
                continue;
            DRW_ParsingContext::BlockRecordInfo contextEntry;
            contextEntry.name = entry.name;
            contextEntry.insUnits = entry.insUnits;
            contextEntry.canExplode = entry.canExplode;
            contextEntry.blockScaling = entry.blockScaling;
            contextEntry.layoutHandle = entry.layoutHandle;
            contextEntry.previewData = entry.previewData;
            contextEntry.insertHandles = entry.insertHandles;
            const auto inserted = stagedContextRecords.emplace(
                entry.handle, std::move(contextEntry));
            if (!inserted.second)
                return false;
        }
        if (contextRecordCount > contextRecords.max_size() - contextRecords.size())
            return failDxfReadRetainedBudget();
        contextRecords.reserve(contextRecords.size() + contextRecordCount);
        for (auto& entry : stagedContextRecords) {
            const auto inserted = contextRecords.emplace(
                entry.first, std::move(entry.second));
            if (!inserted.second)
                return false;
        }
        stagedContextRecords.clear();
        contextCopyReservation.transfer();

        for (const DRW_Block_Record &entry : pendingPublicBlockRecords)
            iface->addBlockRecord(entry);
        return true;
    };

    while (reader->readRec(&code)) {
        DRW_DBG(code); DRW_DBG("\n");
        if (code == 0) {
            if (!finishRecord())
                return setError(DRW::BAD_CODE_PARSED);
            const std::string_view sectionstr = reader->getStringView();
            DRW_DBG(sectionstr.data()); DRW_DBG("\n");
            if (dxfKeywordEquals(sectionstr, "BLOCK_RECORD")) {
                reading = true;
                readingBlkRefs = false;
                readingXDictionary = false;
                xDictionarySeen = false;
                ignoredApplicationDepth = 0;
                handle = DRW::NoHandle;
                publicRecord.reset();
                recordInsertHandles.clear();
            } else if (dxfKeywordEquals(sectionstr, "ENDTAB")) {
                if (!publishBlockRecords())
                    return setError(DRW::BAD_CODE_PARSED);
                return true;
            } else {
                return setError(DRW::BAD_READ_TABLES);
            }
        } else if (reading) {
            switch (code) {
            case 102: {
                const std::string_view control = reader->getStringView();
                if (readingBlkRefs) {
                    if (control != "}")
                        return setError(DRW::BAD_CODE_PARSED);
                    readingBlkRefs = false;
                } else if (readingXDictionary) {
                    if (control != "}" || !xDictionarySeen)
                        return setError(DRW::BAD_CODE_PARSED);
                    readingXDictionary = false;
                } else if (ignoredApplicationDepth != 0) {
                    if (control == "}") {
                        --ignoredApplicationDepth;
                    } else if (!control.empty() && control.front() == '{') {
                        if (ignoredApplicationDepth ==
                                DRW::kMaxDxfApplicationGroupNesting)
                            return setError(DRW::BAD_CODE_PARSED);
                        ++ignoredApplicationDepth;
                    } else {
                        return setError(DRW::BAD_CODE_PARSED);
                    }
                } else {
                    if (control == "{BLKREFS") {
                        if (reader->getSourceVersion() != DRW::UNKNOWNV
                            && reader->getSourceVersion() <= DRW::AC1014)
                            return setError(DRW::BAD_CODE_PARSED);
                        readingBlkRefs = true;
                    } else if (control == "{ACAD_XDICTIONARY") {
                        readingXDictionary = true;
                        xDictionarySeen = false;
                    } else if (!control.empty() && control.front() == '{') {
                        ignoredApplicationDepth = 1;
                    } else if (control == "}") {
                        return setError(DRW::BAD_CODE_PARSED);
                    }
                }
                break;
            }
            case 331:
                if (ignoredApplicationDepth != 0)
                    break;
                if (!readingBlkRefs || !reader->isValidHandleString())
                    return setError(DRW::BAD_CODE_PARSED);
                if (recordInsertHandles.size()
                        >= DRW::kMaxDxfBlockRecordInsertHandles)
                    return setError(DRW::BAD_CODE_PARSED);
                {
                    const std::uint32_t insertHandle =
                        reader->getHandleString();
                    if (insertHandle == DRW::NoHandle)
                        break;
                    if (recordInsertHandles.find(insertHandle)
                        != recordInsertHandles.end())
                        return setError(DRW::BAD_CODE_PARSED);
                    if (!growRetainedBytes(
                            activeInsertIndexReservation,
                            activeInsertIndexBytes,
                            sizeof(std::uint32_t)))
                        return false;
                    if (!publicRecord.retainDxfRetainedStringBytes(
                            reader, activeInsertOwnerBytes,
                            sizeof(std::uint32_t)))
                        return failDxfReadRetainedBudget();
                    recordInsertHandles.insert(insertHandle);
                    publicRecord.insertHandles.push_back(insertHandle);
                }
                break;
            case 360:
                if (ignoredApplicationDepth != 0)
                    break;
                if (!readingXDictionary || xDictionarySeen
                    || !reader->isValidHandleString())
                    return setError(DRW::BAD_CODE_PARSED);
                publicRecord.xDictHandle = reader->getHandleString();
                if (publicRecord.xDictHandle == 0
                    || publicRecord.xDictHandle == DRW::NoHandle)
                    return setError(DRW::BAD_CODE_PARSED);
                xDictionarySeen = true;
                break;
            case 340:
                if (!reader->isValidHandleString())
                    return setError(DRW::BAD_CODE_PARSED);
                publicRecord.layoutHandle = reader->getHandleString();
                break;
            case 330:
                if (!reader->isValidHandleString())
                    return setError(DRW::BAD_CODE_PARSED);
                publicRecord.parentHandle = reader->getHandleString();
                break;
            case 2:
                if (!publicRecord.parseCode(code, reader))
                    return setError(DRW::BAD_CODE_PARSED);
                break;
            case 5:
                if (!reader->isValidHandleString())
                    return setError(DRW::BAD_CODE_PARSED);
                handle = reader->getHandleString();
                publicRecord.handle = handle;
                break;
            case 70:
                publicRecord.insUnits = reader->getInt32();
                publicRecord.flags = publicRecord.insUnits;
                break;
            case 280: {
                const std::int32_t canExplode = reader->getInt32();
                if (canExplode < 0 || canExplode > 1)
                    return setError(DRW::BAD_CODE_PARSED);
                publicRecord.canExplode = canExplode != 0;
                break;
            }
            case 281: {
                const std::int32_t blockScaling = reader->getInt32();
                if (blockScaling < 0 || blockScaling > 1)
                    return setError(DRW::BAD_CODE_PARSED);
                publicRecord.blockScaling = static_cast<std::uint8_t>(blockScaling);
                break;
            }
            case 310: {
                const std::string_view chunk = reader->getStringView();
                if ((chunk.size() & 1u) != 0u)
                    return setError(DRW::BAD_CODE_PARSED);
                const std::size_t decodedBytes = chunk.size() / 2u;
                if (!publicRecord.retainDxfRetainedStringBytes(
                        reader, activePreviewOwnerBytes, decodedBytes))
                    return failDxfReadRetainedBudget();
                if (!appendDxfHexChunk(chunk, publicRecord.previewData))
                    return setError(DRW::BAD_CODE_PARSED);
                break;
            }
            case 1000:
            case 1001:
            case 1002:
            case 1003:
            case 1004:
            case 1005:
            case 1010:
            case 1011:
            case 1012:
            case 1013:
            case 1020:
            case 1021:
            case 1022:
            case 1023:
            case 1030:
            case 1031:
            case 1032:
            case 1033:
            case 1040:
            case 1041:
            case 1042:
            case 1070:
            case 1071:
                if (!publicRecord.parseCode(code, reader))
                    return setError(DRW::BAD_CODE_PARSED);
                break;
            default:
                break;
            }
        }
    }

    return setError(DRW::BAD_READ_TABLES);
}

bool dxfRW::processLType() {
    DRW_DBG("dxfRW::processLType\n");
    int code;
    std::string_view sectionstr;
    bool reading = false;
    DRW_LType ltype;
    std::vector<DRW_LType> pendingLTypes;
    std::set<std::uint32_t> pendingLineTypeHandles;
    std::size_t pendingLineTypeNameBytes = 0u;
    DxfReadRetainedReservation pendingLineTypeNameMapReservation(
        reader->retainedByteBudget(), 0u);
    auto finishLType = [&]() -> bool {
        if (!reading)
            return true;
        if (!dxfTableEntryComplete(ltype, reader->getSourceVersion()))
            return false;
        if (!ltype.update() || !ltype.validateDxf())
            return false;
        if (ltype.handle != 0 && !ltype.name.empty()) {
            if (!pendingLineTypeHandles.insert(ltype.handle).second
                || m_readingContext.lineTypeNameMap.find(ltype.handle)
                    != m_readingContext.lineTypeNameMap.end())
                return false;
            const std::size_t maxSize =
                (std::numeric_limits<std::size_t>::max)();
            if (ltype.name.size() > maxSize - pendingLineTypeNameBytes)
                return failDxfReadRetainedBudget();
            pendingLineTypeNameBytes += ltype.name.size();
        }
        // This object remains staged until ENDTAB. Moving it avoids an
        // uncharged duplicate of its retained strings and shared lease.
        pendingLTypes.push_back(std::move(ltype));
        return true;
    };
    const auto publishLTypes = [&]() -> bool {
        for (const DRW_LType &entry : pendingLTypes) {
            if (entry.handle != 0 && !entry.name.empty()
                && m_readingContext.lineTypeNameMap.find(entry.handle)
                    != m_readingContext.lineTypeNameMap.end())
                return false;
        }

        // The parsing context keeps a second live name string after the table
        // batch is destroyed. Reserve for those parser-owned copies before
        // publishing callbacks, then transfer the charge to the read budget
        // for the lifetime of this read session.
        if (!pendingLineTypeNameMapReservation.resize(
                pendingLineTypeNameBytes))
            return failDxfReadRetainedBudget();
        for (const DRW_LType &entry : pendingLTypes)
            iface->addLType(entry);
        for (const DRW_LType &entry : pendingLTypes) {
            if (entry.handle != 0 && !entry.name.empty()) {
                const auto inserted = m_readingContext.lineTypeNameMap.emplace(
                    entry.handle, entry.name);
                if (!inserted.second)
                    return false;
            }
        }
        pendingLineTypeNameMapReservation.transfer();
        return true;
    };
    while (reader->readRec(&code)) {
        DRW_DBG(code); DRW_DBG("\n");
        if (code == 0) {
            if (!finishLType())
                return setError(DRW::BAD_CODE_PARSED);
            sectionstr = reader->getStringView();
            DRW_DBG(sectionstr.data()); DRW_DBG("\n");
            if (dxfKeywordEquals(sectionstr, "LTYPE")) {
                reading = true;
                ltype.reset();
            } else if (dxfKeywordEquals(sectionstr, "ENDTAB")) {
                if (!publishLTypes())
                    return setError(DRW::BAD_CODE_PARSED);
                return true;  //found ENDTAB terminate
            } else {
                return setError(DRW::BAD_READ_TABLES);
            }
        } else if (reading) {
            if (!ltype.parseCode(code, reader)) {
                return setError( DRW::BAD_CODE_PARSED);
            }
        }
    }

    return setError(DRW::BAD_READ_TABLES);
}

bool dxfRW::processLayer() {
    DRW_DBG("dxfRW::processLayer\n");
    int code;
    std::string_view sectionstr;
    bool reading = false;
    DRW_Layer layer;
    std::vector<DRW_Layer> pendingLayers;
    std::set<std::uint32_t> seenHandles;
    const auto publishLayer = [&]() -> bool {
        if (!dxfTableEntryComplete(layer, reader->getSourceVersion())
            || !layer.validatePayloadFields())
            return false;
        if (layer.handle != DRW::NoHandle
            && !seenHandles.insert(layer.handle).second)
            return false;
        if (!layer.validateDxf())
            recordOperationDiagnostic(
                DRW::OperationPhase::Validation,
                DRW::OperationCause::None,
                "dxf-layer-value-preserved",
                "invalid LAYER semantic value preserved on read; structured output requires explicit repair",
                0, false, layer.handle, layer.handle != DRW::NoHandle, true);
        pendingLayers.push_back(std::move(layer));
        return true;
    };
    while (reader->readRec(&code)) {
        DRW_DBG(code); DRW_DBG("\n");
        if (code == 0) {
            if (reading && !publishLayer())
                return setError(DRW::BAD_CODE_PARSED);
            sectionstr = reader->getStringView();
            DRW_DBG(sectionstr.data()); DRW_DBG("\n");
            if (dxfKeywordEquals(sectionstr, "LAYER")) {
                reading = true;
                layer.reset();
            } else if (dxfKeywordEquals(sectionstr, "ENDTAB")) {
                for (const DRW_Layer &entry : pendingLayers)
                    iface->addLayer(entry);
                return true;  //found ENDTAB terminate
            } else {
                return setError(DRW::BAD_READ_TABLES);
            }
        } else if (reading) {
            if (!layer.parseCode(code, reader)) {
                return setError( DRW::BAD_CODE_PARSED);
            }
        }
}

    return setError(DRW::BAD_READ_TABLES);
}

bool dxfRW::processDimStyle() {
    DRW_DBG("dxfRW::processDimStyle");
    struct DimstyleNameScope {
        dxfReader& reader;
        explicit DimstyleNameScope(dxfReader& r) : reader(r) {
            reader.setAllowDimstyleNames(true);
        }
        ~DimstyleNameScope() { reader.setAllowDimstyleNames(false); }
    } dimstyleNames(*reader);
    int code;
    std::string_view sectionstr;
    bool reading = false;
    DRW_Dimstyle dimSty;
    std::vector<DRW_Dimstyle> pendingDimStyles;
    std::set<std::uint32_t> seenHandles;
    const auto publishDimStyle = [&]() -> bool {
        if (!dxfTableEntryComplete(dimSty, reader->getSourceVersion()))
            return false;
        if (dimSty.handle != DRW::NoHandle
            && !seenHandles.insert(dimSty.handle).second)
            return false;
        dimSty.finalizeDxfDimensionVariables(reader->getSourceVersion());
        if (!dimSty.syncStructToVarsForDxfRead(*reader))
            return false;
        pendingDimStyles.push_back(std::move(dimSty));
        return true;
    };
    while (reader->readRec(&code)) {
        DRW_DBG(code); DRW_DBG("\n");
        if (code == 0) {
            if (reading) {
                // Phase 3A.0: populate the vars map from the parsed struct so
                // the LibreCAD createDimStyle consumer (reads $DIM* keys) gets
                // the imported values, not reset() defaults. Copy-free (called
                // on dimSty before it is reset() for the next record).
                if (!publishDimStyle())
                    return setError(DRW::BAD_CODE_PARSED);
            }
            sectionstr = reader->getStringView();
            DRW_DBG(sectionstr.data()); DRW_DBG("\n");
            if (dxfKeywordEquals(sectionstr, "DIMSTYLE")) {
                reading = true;
                // Start from a pristine record. reset() leaves the $DIM
                // override map and the optional string codes populated, and
                // syncStructToVars() keeps whatever the map already holds, so
                // reusing it imports every style with the first one's values.
                dimSty = DRW_Dimstyle{};
            } else if (dxfKeywordEquals(sectionstr, "ENDTAB")) {
                for (const DRW_Dimstyle &entry : pendingDimStyles)
                    iface->addDimStyle(entry);
                return true;  //found ENDTAB terminate
            } else {
                return setError(DRW::BAD_READ_TABLES);
            }
        } else if (reading) {
            if (!dimSty.parseCode(code, reader)) {
                return setError( DRW::BAD_CODE_PARSED);
            }
        }
    }
    return setError(DRW::BAD_READ_TABLES);
}

bool dxfRW::processTextStyle(){
    DRW_DBG("dxfRW::processTextStyle");
    int code;
    std::string_view sectionstr;
    bool reading = false;
    DRW_Textstyle TxtSty;
    std::vector<DRW_Textstyle> pendingTextStyles;
    std::set<std::uint32_t> seenHandles;
    const auto publishTextStyle = [&]() -> bool {
        const bool shapeFile = (TxtSty.flags & 0x01) != 0;
        if (!dxfTableEntryComplete(TxtSty, reader->getSourceVersion(), shapeFile)
            || !TxtSty.validateDxf())
            return false;
        if (TxtSty.handle != DRW::NoHandle
            && !seenHandles.insert(TxtSty.handle).second)
            return false;
        pendingTextStyles.push_back(std::move(TxtSty));
        return true;
    };
    while (reader->readRec(&code)) {
        DRW_DBG(code); DRW_DBG("\n");
        if (code == 0) {
            if (reading && !publishTextStyle())
                return setError(DRW::BAD_CODE_PARSED);
            sectionstr = reader->getStringView();
            DRW_DBG(sectionstr.data()); DRW_DBG("\n");
            if (dxfKeywordEquals(sectionstr, "STYLE")) {
                reading = true;
                TxtSty.reset();
            } else if (dxfKeywordEquals(sectionstr, "ENDTAB")) {
                for (const DRW_Textstyle &entry : pendingTextStyles)
                    iface->addTextStyle(entry);
                return true;  //found ENDTAB terminate
            } else {
                return setError(DRW::BAD_READ_TABLES);
            }
        } else if (reading) {
            if (!TxtSty.parseCode(code, reader)) {
                return setError( DRW::BAD_CODE_PARSED);
            }
        }
    }

    return setError(DRW::BAD_READ_TABLES);
}

