// TVDEVICEPROPERTIES is a producer-specific OBJECTS record rather than a
// standard DXF class.  Decode the positional fields used by dwgTs while
// retaining every group, so the source record remains authoritative on replay.
bool dxfRW::processTvDeviceProperties() {
    DRW_DBG("dxfRW::processTvDeviceProperties");
    int code;
    DRW_TvDeviceProperties data;
    DRW_RawDxfObject raw;
    if (!copyRawDxfCarrierName(raw, nextentity))
        return setError(DRW::BAD_CODE_PARSED);

    int seen90 = 0;
    int seen70 = 0;
    int seenBll = 0;
    int seen40 = 0;
    while (reader->readRec(&code)) {
        if (code == 0) {
            if (!acceptObjectBoundary(code))
                return setError(DRW::BAD_READ_OBJECTS);
            if (!validateCapturedRawDxfObject(raw, binFile, reader->classifierProfile()))
                return setError(DRW::BAD_CODE_PARSED);
            data.handle = raw.handle;
            data.parentHandle = raw.parentHandle;
            iface->addTvDeviceProperties(data);
            iface->addRawDxfObject(raw);
            return true;
        }
        if (code == 102) {
            if (!captureRawDxfApplicationGroup(raw, data))
                return setError(DRW::BAD_CODE_PARSED);
            continue;
        }

        if (!captureRawGroup(raw, code, /*validateHandles=*/true))
            return setError(DRW::BAD_CODE_PARSED);
        switch (code) {
        case 90:
            if (seen90 == 0)
                data.flags = reader->getInt32();
            else if (seen90 == 1)
                data.useLutPalette = reader->getInt32();
            else if (seen90 == 2)
                data.blendingMode = reader->getInt32();
            ++seen90;
            break;
        case 70:
            if (seen70++ == 0)
                data.maxRegenThreads = reader->getInt32();
            break;
        case 160: case 161: case 162: case 163: case 164:
        case 165: case 166: case 167: case 168: case 169:
            if (seenBll == 0)
                data.alternateHighlight = reader->getInt64();
            else if (seenBll == 1)
                data.alternateHighlightColor = reader->getInt64();
            else if (seenBll == 2)
                data.geometryShaderUsage = reader->getInt64();
            ++seenBll;
            break;
        case 40:
            if (seen40 == 0)
                data.antialiasingLevel = reader->getDouble();
            else if (seen40 == 1)
                data.valueBd2 = reader->getDouble();
            ++seen40;
            break;
        default:
            break;
        }
    }

    return setError(DRW::BAD_READ_OBJECTS);
}

// CSACDOCUMENTOPTIONS has only two documented DXF body fields. Keep the
// complete source record in the raw carrier while decoding those fields.
bool dxfRW::processCsacDocumentOptions() {
    DRW_DBG("dxfRW::processCsacDocumentOptions");
    int code;
    DRW_CsacDocumentOptions data;
    DRW_RawDxfObject raw;
    if (!copyRawDxfCarrierName(raw, nextentity))
        return setError(DRW::BAD_CODE_PARSED);

    int seen90 = 0;
    while (reader->readRec(&code)) {
        if (code == 0) {
            if (!acceptObjectBoundary(code))
                return setError(DRW::BAD_READ_OBJECTS);
            if (!validateCapturedRawDxfObject(raw, binFile, reader->classifierProfile()))
                return setError(DRW::BAD_CODE_PARSED);
            data.handle = raw.handle;
            data.parentHandle = raw.parentHandle;
            iface->addCsacDocumentOptions(data);
            iface->addRawDxfObject(raw);
            return true;
        }
        if (code == 102) {
            if (!captureRawDxfApplicationGroup(raw, data))
                return setError(DRW::BAD_CODE_PARSED);
            continue;
        }

        if (!captureRawGroup(raw, code, /*validateHandles=*/true))
            return setError(DRW::BAD_CODE_PARSED);
        if (code == 90) {
            if (seen90 == 0)
                data.classVersion = static_cast<std::uint32_t>(
                    reader->getInt32());
            else if (seen90 == 1)
                data.flags = static_cast<std::uint32_t>(reader->getInt32());
            ++seen90;
        }
    }

    return setError(DRW::BAD_READ_OBJECTS);
}

//Slice A1: lossless passthrough for an OBJECTS-section object libdxfrw does not
//model as a typed DXF object. Captures each group with its decoded typed value
//and, for ASCII input, the original value spelling so the object can be
//re-emitted without numeric normalization once the object-write spine (A2)
//consumes it.
namespace {
enum class RawValType { Str, Int16, Int32, Int64, Dbl, Bool };
//Mirror dxfReader::readRec's code->reader dispatch (intern/dxfreader.cpp) so a
//raw-captured group value is taken from the matching typed getter. readRec parses
//numeric codes into the typed members (intData/int64/doubleData) and leaves
//strData STALE, so getString() is wrong for them. The reader's public `type` is
//ALSO unreliable here: each numeric reader sets `type` then calls readString(&t)
//which resets it to STRING — hence we classify by code range, not reader->type.
RawValType classifyDxfCode(int code,
                           DxfClassifierProfile profile =
                               DxfClassifierProfile::StandaloneSafe) {
    switch (dxfValueKindForCode(code, profile)) {
    case DxfValueKind::Dbl: return RawValType::Dbl;
    case DxfValueKind::I16: return RawValType::Int16;
    case DxfValueKind::I32: return RawValType::Int32;
    case DxfValueKind::I64: return RawValType::Int64;
    case DxfValueKind::Bln: return RawValType::Bool;
    case DxfValueKind::Bin:
    case DxfValueKind::Str:
    case DxfValueKind::Unknown:
    default: return RawValType::Str;
    }
}

bool isDxfHandleReferenceCode(int code) {
    return isDxfHandleCode(code);
}

bool parseRawDxfHandleLexeme(std::string_view text, std::uint64_t& value) {
    if (text.empty() || text.size() > 16)
        return false;
    const char* begin = text.data();
    const char* end = begin + text.size();
    const std::from_chars_result result = std::from_chars(begin, end, value, 16);
    return result.ec == std::errc{} && result.ptr == end;
}

// Group 5 is a self identity in a record header, but an opaque numeric sort
// key in the SORTENTSTABLE body. Keep this exception record/subclass scoped;
// changing the global group-code role would break ordinary identity remaps.
class RawSortEntsScope {
public:
    explicit RawSortEntsScope(bool sortRecord) : m_sortRecord(sortRecord) {}

    bool accept(const DRW_Variant& value) {
        m_sortKey = false;
        m_blockOwner = false;
        m_entityReference = false;
        const int code = value.code();
        if (code == 0) {
            if (!complete() || value.type() != DRW_Variant::STRING)
                return false;
            *this = RawSortEntsScope(
                dxfKeywordEquals(value.c_str(), "SORTENTSTABLE"));
            return true;
        }
        if (!m_sortRecord)
            return true;
        if (code == 102 && value.type() == DRW_Variant::STRING) {
            const char* const rawText = value.c_str();
            if (rawText == nullptr)
                return false;
            const std::string_view text(rawText);
            if (!text.empty() && text.front() == '{')
                ++m_appDepth;
            else if (text == "}" && m_appDepth != 0)
                --m_appDepth;
            return true;
        }
        if (m_appDepth != 0)
            return true;
        if (code == 100 && value.type() == DRW_Variant::STRING) {
            const char* const rawText = value.c_str();
            if (rawText == nullptr)
                return false;
            if (std::string_view(rawText) == "AcDbSortentsTable") {
                if (m_bodySeen)
                    return false;
                m_body = true;
                m_bodySeen = true;
            } else if (m_body) {
                if (!m_owner || m_pendingEntity)
                    return false;
                m_body = false;
                m_otherSubclass = true;
            }
            return true;
        }
        if (!m_body || (code != 330 && code != 331 && code != 5))
            return true;
        std::uint64_t handle = 0;
        if (value.type() != DRW_Variant::STRING
            || !parseRawDxfHandleLexeme(value.c_str(), handle))
            return false;
        if (code == 330) {
            if (m_owner || m_pendingEntity || m_entries != 0 || handle == 0)
                return false;
            m_owner = true;
            m_blockOwner = true;
        } else if (code == 331) {
            if (!m_owner || m_pendingEntity
                || m_entries >= DRW_SortEntsTable::kMaxEntries)
                return false;
            m_pendingEntity = true;
            m_entityReference = true;
        } else {
            if (!m_pendingEntity)
                return false;
            m_sortKey = true;
            m_pendingEntity = false;
            ++m_entries;
        }
        return true;
    }

    bool complete() const noexcept {
        return !m_sortRecord
            || (m_bodySeen && m_owner && !m_pendingEntity && m_appDepth == 0);
    }
    bool isSortKey() const noexcept { return m_sortKey; }
    bool isBlockOwner() const noexcept { return m_blockOwner; }
    bool isEntityReference() const noexcept { return m_entityReference; }
    bool isOpaqueHandleReference() const noexcept {
        return m_sortRecord && (m_appDepth != 0 || m_otherSubclass);
    }

private:
    bool m_sortRecord{false}, m_body{false}, m_bodySeen{false}, m_owner{false};
    bool m_pendingEntity{false}, m_sortKey{false}, m_otherSubclass{false};
    bool m_blockOwner{false}, m_entityReference{false};
    std::size_t m_entries{0}, m_appDepth{0};
};

// ASCII source spellings must describe the same known SORTENTSTABLE carrier
// that preflight classifies. Unknown records retain their existing raw policy.
bool hasRawSortEntsAgreement(const std::vector<DRW_Variant>& groups,
                            const std::vector<UTF8STRING>& rawValues,
                            bool sortRecord) {
    for (std::size_t index = 0; index < groups.size(); ++index) {
        const DRW_Variant& group = groups[index];
        const int code = group.code();
        if (code == 0) {
            const bool decodedSort = dxfKeywordEquals(group.c_str(), "SORTENTSTABLE");
            const bool rawSort = dxfKeywordEquals(rawValues[index], "SORTENTSTABLE");
            if ((sortRecord || decodedSort || rawSort)
                && rawValues[index] != group.c_str())
                return false;
            sortRecord = decodedSort || rawSort;
            continue;
        }
        if (!sortRecord)
            continue;
        if (code == 100 || code == 102) {
            if (rawValues[index] != group.c_str())
                return false;
        } else if (code == 5 || code == 330 || code == 331) {
            std::uint64_t decoded = 0, raw = 0;
            if (!parseRawDxfHandleLexeme(group.c_str(), decoded)
                || !parseRawDxfHandleLexeme(rawValues[index], raw)
                || decoded != raw)
                return false;
        }
    }
    return true;
}

bool requiresDxfSelfHandle(DRW::Version sourceVersion) {
    return sourceVersion != DRW::UNKNOWNV && sourceVersion > DRW::AC1009;
}

bool requiresDxfSelfHandle(const dxfReader& reader) {
    return requiresDxfSelfHandle(reader.getSourceVersion());
}

// Proxy graphics are decoded with a bit layout chosen by the drawing's
// revision -- DRW_ProxyGraphicDecoder reads two extra fields per polyline from
// AC1024 on -- so an unrecognised revision is not a strictness question but a
// layout one, and there is nothing to fall back on.  Decoding UNKNOWNV as if it
// were pre-AC1024 misaligns the stream and emits the misread bits through the
// ordinary entity callbacks as real geometry, which is worse than emitting
// nothing: the caller cannot tell.  The bytes are still delivered verbatim in
// proxyGraphics and through the raw carrier, so declining to decode loses only
// the guess.
bool canDecodeProxyGraphics(const dxfReader& reader) {
    return reader.getSourceVersion() != DRW::UNKNOWNV;
}

bool updateRawDxfApplicationDepth(const DRW_Variant& value, int& depth) {
    if (value.code() != 102)
        return true;
    if (value.type() != DRW_Variant::STRING || value.c_str() == nullptr)
        return false;

    const std::string_view marker(value.c_str());
    if (marker.size() > 1 && marker.front() == '{') {
        if (++depth > DRW::kMaxDxfApplicationGroupNesting)
            return false;
    } else if (marker == "}") {
        if (depth == 0)
            return false;
        --depth;
    } else {
        return false;
    }
    return true;
}

bool isDxfBinaryChunkCode(int code) {
    return (code >= 310 && code <= 319) || code == 1004;
}

bool isDxfHexString(std::string_view text) {
    if ((text.size() & 1u) != 0u || text.size() / 2u > 127u)
        return false;
    return std::all_of(text.begin(), text.end(), [](unsigned char ch) {
        return std::isxdigit(ch) != 0;
    });
}

bool isValidDxfHandleString(std::string_view text) {
    std::uint64_t value = 0;
    return parseRawDxfHandleLexeme(text, value);
}

bool hasRawDxfSelfHandle(const DRW_RawDxfObject& object) {
    const bool sortRecord = dxfKeywordEquals(object.name, "SORTENTSTABLE");
    std::size_t appDepth = 0;
    for (const DRW_Variant& group : object.groups) {
        if (sortRecord) {
            if (group.code() == 102 && group.type() == DRW_Variant::STRING
                && group.c_str() != nullptr) {
                const std::string_view text(group.c_str());
                if (!text.empty() && text.front() == '{')
                    ++appDepth;
                else if (text == "}" && appDepth != 0)
                    --appDepth;
                continue;
            }
            if (appDepth != 0)
                continue;
            if (group.code() == 100)
                break; // A body sort key cannot supply the record's identity.
        }
        if (group.code() != 5 || group.type() != DRW_Variant::STRING
            || group.c_str() == nullptr) {
            continue;
        }
        std::uint64_t value = 0;
        if (parseRawDxfHandleLexeme(group.c_str(), value) && value != 0)
            return true;
        if (sortRecord)
            return false;
    }
    return false;
}

bool parseDxfIntegerString(const std::string& text, std::int64_t minimum,
                           std::int64_t maximum) {
    const char* begin = text.data();
    const char* end = begin + text.size();
    while (begin != end && DxfNumeric::isSpace(*begin))
        ++begin;
    while (end != begin && DxfNumeric::isSpace(end[-1]))
        --end;
    if (begin == end)
        return false;
    if (*begin == '+') {
        if (++begin == end)
            return false;
    }

    std::int64_t value = 0;
    const std::from_chars_result result = std::from_chars(begin, end, value);
    return result.ec == std::errc{} && result.ptr == end
        && value >= minimum && value <= maximum;
}

bool isValidDxfDoubleString(const std::string& text) {
    char* end = nullptr;
    errno = 0;
    const double value = DxfNumeric::strtodC(text.c_str(), &end);
    while (end != nullptr && *end != '\0'
           && DxfNumeric::isSpace(*end)) {
        ++end;
    }
    // Match typed ASCII DXF parsing: finite underflow (including zero) is
    // admitted, while overflow remains rejected by the finite-value check.
    // The original raw spelling is emitted unchanged, so no lexical detail is
    // lost by the validation conversion.
    return end != text.c_str() && end != nullptr && end == text.c_str() + text.size()
        && std::isfinite(value);
}

bool isValidRawDxfNumericString(RawValType type, const std::string& text) {
    switch (type) {
    case RawValType::Int16:
        return parseDxfIntegerString(
            text, std::numeric_limits<std::int16_t>::min(),
            std::numeric_limits<std::uint16_t>::max());
    case RawValType::Int32:
    case RawValType::Bool:
        return parseDxfIntegerString(
            text, std::numeric_limits<std::int32_t>::min(),
            std::numeric_limits<std::int32_t>::max());
    case RawValType::Int64:
        return parseDxfIntegerString(
            text, std::numeric_limits<std::int64_t>::min(),
            std::numeric_limits<std::int64_t>::max());
    case RawValType::Dbl:
        return isValidDxfDoubleString(text);
    case RawValType::Str:
        return false;
    }
    return false;
}

bool isSafeAsciiDxfLexeme(const std::string& text) {
    return text.find_first_of("\r\n") == std::string::npos
        && text.find('\0') == std::string::npos;
}

int dxfSignedInt32BitPattern(std::uint32_t value) noexcept {
    static_assert(sizeof(int) == sizeof(std::uint32_t),
                  "DXF binary writer requires 32-bit int");
    const std::uint32_t signedMax = static_cast<std::uint32_t>(
        std::numeric_limits<int>::max());
    return value <= signedMax
        ? static_cast<int>(value)
        : -1 - static_cast<int>(
            (std::numeric_limits<std::uint32_t>::max)() - value);
}

bool isValidRawDxfUInt32Lexeme(const std::string& text) {
    if (!isSafeAsciiDxfLexeme(text))
        return false;
    std::size_t begin = 0u;
    std::size_t end = text.size();
    while (begin < end && DxfNumeric::isSpace(text[begin]))
        ++begin;
    while (begin < end && DxfNumeric::isSpace(text[end - 1u]))
        --end;
    if (begin == end)
        return false;
    std::uint32_t value = 0u;
    const char* first = text.data() + begin;
    const char* last = text.data() + end;
    const auto parsed = std::from_chars(first, last, value, 10);
    return parsed.ec == std::errc{} && parsed.ptr == last;
}

bool isValidRawDxfLexeme(int code, RawValType type,
                         const std::string& text) {
    if (!isSafeAsciiDxfLexeme(text))
        return false;
    if (isDxfBinaryChunkCode(code))
        return isDxfHexString(text);
    if (isDxfHandleReferenceCode(code))
        return isValidDxfHandleString(text);
    return type == RawValType::Str || isValidRawDxfNumericString(type, text);
}

bool validateRawDxfGroups(const std::vector<DRW_Variant>& groups,
                          const std::vector<UTF8STRING>& rawValues,
                          bool hasRawValues,
                          bool binaryOutput,
                          bool allowRecordBoundaries,
                          DxfClassifierProfile profile =
                              DxfClassifierProfile::StandaloneSafe,
                          bool allowMaterialUnsignedColorValues = false) {
    if (groups.size() > DRW::kMaxDxfRawRecordGroups
        || (hasRawValues && rawValues.size() != groups.size())) {
        return false;
    }

    const bool writesRawValues = hasRawValues && !binaryOutput;
    int applicationDepth = 0;
    bool xrecordData = false;
    for (std::size_t groupIndex = 0; groupIndex < groups.size(); ++groupIndex) {
        const DRW_Variant& group = groups[groupIndex];
        const int code = group.code();
        if (code < 0 || code > 1071
            || (!allowRecordBoundaries && code == 0)) {
            return false;
        }

        const RawValType type = classifyDxfCode(code, profile);
        const bool materialUnsignedColor =
            allowMaterialUnsignedColorValues
            && (code == 90 || code == 91 || code == 92)
            && group.type() == DRW_Variant::INTEGER64;
        if (writesRawValues
            && !(materialUnsignedColor
                     ? isValidRawDxfUInt32Lexeme(rawValues[groupIndex])
                     : isValidRawDxfLexeme(code, type,
                                           rawValues[groupIndex]))) {
            return false;
        }

        switch (type) {
        case RawValType::Str: {
            if (group.type() != DRW_Variant::STRING || group.c_str() == nullptr)
                return false;
            const std::string_view value(group.c_str());
            if ((isDxfBinaryChunkCode(code) && !isDxfHexString(value))
                || (isDxfHandleReferenceCode(code)
                    && !isValidDxfHandleString(value))) {
                return false;
            }
            break;
        }
        case RawValType::Int16:
            if (group.type() == DRW_Variant::STRING && !binaryOutput
                && isValidRawDxfNumericString(
                    RawValType::Int16, group.c_str())) {
                break;
            }
            if (group.type() != DRW_Variant::INTEGER
                || group.i_val() < std::numeric_limits<std::int16_t>::min()
                || group.i_val() > std::numeric_limits<std::uint16_t>::max()) {
                return false;
            }
            break;
        case RawValType::Int32:
        case RawValType::Bool:
            if (materialUnsignedColor
                && group.i64_val() >= 0
                && static_cast<std::uint64_t>(group.i64_val())
                    <= std::numeric_limits<std::uint32_t>::max())
                break;
            if (group.type() == DRW_Variant::STRING && !binaryOutput
                && isValidRawDxfNumericString(classifyDxfCode(code, profile),
                                               group.c_str())) {
                break;
            }
            if (group.type() != DRW_Variant::INTEGER)
                return false;
            break;
        case RawValType::Int64:
            if (group.type() == DRW_Variant::STRING && !binaryOutput
                && isValidRawDxfNumericString(
                    RawValType::Int64, group.c_str())) {
                break;
            }
            if (group.type() != DRW_Variant::INTEGER64)
                return false;
            break;
        case RawValType::Dbl:
            if (group.type() == DRW_Variant::STRING && !binaryOutput
                && isValidRawDxfNumericString(
                    RawValType::Dbl, group.c_str())) {
                break;
            }
            if (group.type() != DRW_Variant::DOUBLE
                || !std::isfinite(group.d_val())) {
                return false;
            }
            break;
        }

        if (code == 0 || (code == 100 && applicationDepth == 0))
            xrecordData = code == 100
                && std::string_view(group.c_str()) == "AcDbXrecord";
        if (code == 102 && xrecordData)
            continue;
        if (code == 102 && writesRawValues) {
            const DRW_Variant rawMarker(code, rawValues[groupIndex]);
            if (!updateRawDxfApplicationDepth(rawMarker, applicationDepth))
                return false;
        } else if (!updateRawDxfApplicationDepth(group, applicationDepth)) {
            return false;
        }
    }
    return applicationDepth == 0;
}

bool validateCapturedRawDxfObject(const DRW_RawDxfObject& object,
                                  bool binaryOutput,
                                  DxfClassifierProfile profile) {
    return validateRawDxfGroups(object.groups, object.rawValues,
                                object.hasRawValues, binaryOutput,
                                /*allowRecordBoundaries=*/false, profile);
}

enum class DxfProxyPayloadSlot { Primary, Body, Unknown };

struct DxfProxyCapture {
    DxfProxyPayloadSlot slot = DxfProxyPayloadSlot::Primary;
    bool inProxyRecord = false;
    // Which 100 subclass the following groups belong to.  A proxy record may
    // carry additional subclasses -- ODA writes an inline AcDbEvalGraph for
    // dynamic blocks -- whose group codes collide with the proxy payload codes
    // (92/93/96 in particular).  Only the proxy subclass's own groups may be
    // interpreted as payload; the rest are kept verbatim by the raw carrier.
    bool inProxySubclass = true;
    int applicationDepth = 0;
    std::vector<std::string> applicationGroups;
    bool hasOwner = false;
    std::uint32_t ownerHandle = 0;
    std::vector<std::uint32_t> reactorHandles;
    std::uint32_t xDictHandle = 0;
    bool hasProxyClassId = false;
    std::int32_t proxyClassId = 0;
    bool hasProxyCarrierId = false;
    std::int32_t proxyCarrierId = 0;
    bool hasProxyDrawingFormat = false;
    std::uint32_t proxyDrawingFormat = 0;
    bool hasFromDxf = false;
    bool fromDxf = false;
    bool hasPrimaryByteSize = false;
    std::uint64_t primaryByteSize = 0;
    bool hasBodyBitSize = false;
    std::uint32_t bodyBitSize = 0;
    bool proxyObjectIdSectionTerminated = false;
    bool hasUnknownByteSize = false;
    std::uint64_t unknownByteSize = 0;
    bool unknownSizeIs162 = false;
    std::vector<std::uint8_t> primary;
    std::vector<std::uint8_t> body;
    std::vector<std::uint8_t> unknown;
    std::vector<DRW_ProxyObjectIdRef> objectIdRefs;
    // The typed proxy payload vectors duplicate source groups across physical
    // records. Keep their decoded bytes charged until ownership transfers to
    // the published proxy entity/object.
    std::shared_ptr<DxfReadRetainedLease> retainedPayloadLease;
};

bool proxyDxfInteger(const DRW_Variant& value, std::int64_t& result) {
    if (value.type() == DRW_Variant::INTEGER) {
        result = value.i_val();
        return true;
    }
    if (value.type() == DRW_Variant::INTEGER64) {
        result = value.i64_val();
        return true;
    }
    return false;
}

bool proxyDxfInt32(const DRW_Variant& value, std::int32_t& result) {
    std::int64_t integer = 0;
    if (!proxyDxfInteger(value, integer)
        || integer < std::numeric_limits<std::int32_t>::min()
        || integer > std::numeric_limits<std::int32_t>::max()) {
        return false;
    }
    result = static_cast<std::int32_t>(integer);
    return true;
}

bool proxyDxfHandle(const DRW_Variant& value, std::uint64_t& result) {
    if (value.type() != DRW_Variant::STRING || value.c_str() == nullptr)
        return false;
    const std::string_view text(value.c_str());
    if (text.empty())
        return false;

    result = 0;
    for (char ch : text) {
        unsigned digit = 0;
        if (ch >= '0' && ch <= '9')
            digit = static_cast<unsigned>(ch - '0');
        else if (ch >= 'a' && ch <= 'f')
            digit = static_cast<unsigned>(ch - 'a' + 10);
        else if (ch >= 'A' && ch <= 'F')
            digit = static_cast<unsigned>(ch - 'A' + 10);
        else
            return false;
        if (result > (std::numeric_limits<std::uint64_t>::max() - digit) / 16u)
            return false;
        result = result * 16u + digit;
    }
    return true;
}

bool appendProxyDxfBytes(
    const DRW_Variant& value, std::vector<std::uint8_t>& target,
    std::shared_ptr<DxfReadRetainedLease>& retainedLease,
    const std::shared_ptr<DxfReadRetainedBudget>& budget) {
    if (target.size() > DRW::kMaxDxfBinaryPayloadBytes)
        return false;

    DxfReadRetainedLeaseCheckpoint retainedCheckpoint(retainedLease);
    if (value.type() == DRW_Variant::BINARY) {
        const auto* bytes = value.binary();
        if (bytes == nullptr || bytes->size() >
                                  DRW::kMaxDxfBinaryPayloadBytes - target.size())
            return false;
        const std::size_t newSize = target.size() + bytes->size();
        if (newSize > static_cast<std::size_t>(std::numeric_limits<int>::max())
            || !retainDxfReadBytes(retainedLease, budget, bytes->size())
            || !DRW::reserve(target, static_cast<int>(newSize)))
            return false;
        try {
            target.insert(target.end(), bytes->begin(), bytes->end());
        } catch (...) {
            return false;
        }
        retainedCheckpoint.commit();
        return true;
    }
    if (value.type() != DRW_Variant::STRING || value.c_str() == nullptr)
        return false;

    const char* const rawHex = value.c_str();
    const std::size_t rawHexBytes =
        std::char_traits<char>::length(rawHex);
    const std::string_view text(rawHex, rawHexBytes);
    if ((text.size() & 1u) != 0u)
        return false;
    const std::size_t decodedBytes = text.size() / 2u;
    if (decodedBytes > DRW::kMaxDxfBinaryPayloadBytes - target.size()
        || !retainDxfReadBytes(retainedLease, budget, decodedBytes)
        || !appendDxfHexChunk(text, target))
        return false;
    retainedCheckpoint.commit();
    return true;
}

bool validateProxyDxfPayloads(const DxfProxyCapture& capture) {
    const auto byteCountMatches = [](const std::vector<std::uint8_t>& data,
                                      bool declared,
                                      std::uint64_t expected) {
        return !declared || (expected <= DRW::kMaxDxfBinaryPayloadBytes
                             && data.size() == expected);
    };
    const auto bitCountMatches = [](const std::vector<std::uint8_t>& data,
                                    bool declared,
                                    std::uint64_t expected) {
        if (!declared)
            return true;
        if (expected > DRW::kMaxDxfBinaryPayloadBytes * 8u)
            return false;
        return (expected + 7u) / 8u == data.size();
    };

    return byteCountMatches(capture.primary, capture.hasPrimaryByteSize,
                            capture.primaryByteSize)
        && bitCountMatches(capture.body, capture.hasBodyBitSize,
                           capture.bodyBitSize)
        && (byteCountMatches(capture.unknown, capture.hasUnknownByteSize,
                             capture.unknownByteSize)
            || bitCountMatches(capture.unknown, capture.hasUnknownByteSize,
                               capture.unknownByteSize));
}

int proxyDxfHandleCode(int code) {
    // Inverse of the DWG typed-handle/DXF group-code mapping (ODA §2.13;
    // Autodesk DXF handle groups). DXF has absolute handles only, so code 4
    // is the canonical soft-pointer representation on readback.
    switch (code) {
    case 330: return 4;
    case 340: return 5;
    case 350: return 2;
    case 360: return 3;
    default: return 0;
    }
}

bool collectProxyDxfGroup(DxfProxyCapture& capture,
                          const DRW_Variant& value, bool entity,
                          const std::shared_ptr<DxfReadRetainedBudget>& budget) {
    const int code = value.code();
    if (code == 102) {
        if (value.type() != DRW_Variant::STRING || value.c_str() == nullptr)
            return false;
        const std::string_view marker(value.c_str());
        if (marker.size() > 1 && marker.front() == '{') {
            if (++capture.applicationDepth > DRW::kMaxDxfApplicationGroupNesting)
                return false;
            capture.applicationGroups.emplace_back(marker.data() + 1,
                                                    marker.size() - 1u);
        } else if (marker == "}") {
            if (capture.applicationDepth == 0
                || capture.applicationGroups.empty())
                return false;
            --capture.applicationDepth;
            capture.applicationGroups.pop_back();
        } else {
            return false;
        }
        return true;
    }

    if (code == 100) {
        if (value.type() != DRW_Variant::STRING || value.c_str() == nullptr)
            return false;
        // A 100 is a subclass marker only at record level.  Inside a 102
        // application group it is opaque application data that happens to use
        // the same code, and letting it move the subclass state would either
        // disarm the payload interpretation for the rest of the record or
        // re-arm it inside somebody else's group.  captureRawGroup has already
        // kept it verbatim either way.
        if (capture.applicationDepth != 0)
            return true;
        const std::string_view subclass(value.c_str());
        capture.inProxySubclass =
            dxfKeywordEquals(subclass, "AcDbProxyEntity")
            || dxfKeywordEquals(subclass, "AcDbProxyObject")
            || dxfKeywordEquals(subclass, "AcDbZombieEntity")
            || dxfKeywordEquals(subclass, "AcDbZombieObject");
        return true;
    }

    // Outside the proxy subclass every code below is somebody else's field.
    // Accept it without interpreting it; captureRawGroup has already kept it.
    // 102 and 100 have already returned above, so this cannot swallow a
    // group marker.
    if (!capture.inProxySubclass)
        return true;

    if (code == 330 || code == 340 || code == 350 || code == 360) {
        std::uint64_t handle = 0;
        if (!proxyDxfHandle(value, handle))
            return false;
        if (capture.applicationDepth != 0) {
            const std::string& group = capture.applicationGroups.back();
            if (capture.applicationDepth == 1
                && dxfKeywordEquals(group, "ACAD_REACTORS")
                && code == 330) {
                if (handle != 0
                    && handle <= std::numeric_limits<std::uint32_t>::max()) {
                    capture.reactorHandles.push_back(
                        static_cast<std::uint32_t>(handle));
                }
            } else if (capture.applicationDepth == 1
                       && dxfKeywordEquals(group, "ACAD_XDICTIONARY")
                       && (code == 360 || code == 361 || code == 362)
                       && capture.xDictHandle == 0
                       && handle != 0
                       && handle <= std::numeric_limits<std::uint32_t>::max()) {
                capture.xDictHandle = static_cast<std::uint32_t>(handle);
            }
            return true;
        }
        if (capture.inProxyRecord) {
            // Group 94 terminates the proxy object-ID list.  A later handle
            // group in this same proxy subclass is not part of that list and
            // cannot be safely exposed as a typed reference.  Other
            // subclasses and 102 application groups are kept opaque above.
            if (capture.proxyObjectIdSectionTerminated)
                return false;
            DRW_ProxyObjectIdRef ref;
            ref.m_dxfCode = code;
            ref.m_handleCode = static_cast<std::uint8_t>(proxyDxfHandleCode(code));
            ref.m_handle = handle;
            ref.m_rawHandle = handle;
            capture.objectIdRefs.push_back(ref);
        } else if (code == 330 && !capture.hasOwner) {
            if (handle > std::numeric_limits<std::uint32_t>::max())
                return false;
            capture.hasOwner = true;
            capture.ownerHandle = static_cast<std::uint32_t>(handle);
        }
        return true;
    }

    std::int64_t integer = 0;
    std::int32_t integer32 = 0;
    switch (code) {
    case 5:
        // The self handle is consumed by the common raw carrier. No proxy
        // payload state is changed here.
        return true;
    case 90:
        if (!proxyDxfInt32(value, integer32)) return false;
        capture.inProxyRecord = true;
        capture.hasProxyCarrierId = true;
        capture.proxyCarrierId = integer32;
        return true;
    case 91:
        if (!proxyDxfInt32(value, integer32)) return false;
        capture.inProxyRecord = true;
        capture.hasProxyClassId = true;
        capture.proxyClassId = integer32;
        return true;
    case 92:
        // ACAD_PROXY_OBJECT has no graphics payload and does not use group
        // 92. Do not reinterpret an entity-only graphics length as object
        // data; retain the raw record only when its recognized grammar is
        // valid.
        if (!entity)
            return false;
        if (capture.hasPrimaryByteSize
            || !proxyDxfInteger(value, integer)
            || integer < 0
            || static_cast<std::uint64_t>(integer)
                   > DRW::kMaxDxfBinaryPayloadBytes)
            return false;
        capture.inProxyRecord = true;
        capture.hasPrimaryByteSize = true;
        capture.primaryByteSize = static_cast<std::uint64_t>(integer);
        capture.slot = DxfProxyPayloadSlot::Primary;
        return true;
    case 160:
        if (capture.hasPrimaryByteSize
            || !proxyDxfInteger(value, integer)
            || integer < 0
            || static_cast<std::uint64_t>(integer)
                   > DRW::kMaxDxfBinaryPayloadBytes)
            return false;
        capture.inProxyRecord = true;
        capture.hasPrimaryByteSize = true;
        capture.primaryByteSize = static_cast<std::uint64_t>(integer);
        capture.slot = DxfProxyPayloadSlot::Primary;
        return true;
    case 93:
    case 161:
        if (!proxyDxfInteger(value, integer) || integer < 0
            || capture.hasBodyBitSize
            || static_cast<std::uint64_t>(integer)
                   > DRW::kMaxDxfBinaryPayloadBytes * 8u)
            return false;
        capture.inProxyRecord = true;
        capture.hasBodyBitSize = true;
        capture.bodyBitSize = static_cast<std::uint32_t>(integer);
        capture.slot = DxfProxyPayloadSlot::Body;
        return true;
    case 94:
        if (!proxyDxfInteger(value, integer) || integer != 0
            || capture.proxyObjectIdSectionTerminated)
            return false;
        capture.inProxyRecord = true;
        capture.proxyObjectIdSectionTerminated = true;
        return true;
    case 95:
        if (!proxyDxfInteger(value, integer)
            || integer < 0
            || static_cast<std::uint64_t>(integer)
                   > std::numeric_limits<std::uint32_t>::max())
            return false;
        capture.inProxyRecord = true;
        capture.hasProxyDrawingFormat = true;
        capture.proxyDrawingFormat = static_cast<std::uint32_t>(integer);
        return true;
    case 96:
    case 162:
        if (capture.hasUnknownByteSize
            || !proxyDxfInteger(value, integer)
            || integer < 0
            || static_cast<std::uint64_t>(integer)
                   > DRW::kMaxDxfBinaryPayloadBytes)
            return false;
        capture.inProxyRecord = true;
        capture.hasUnknownByteSize = true;
        capture.unknownByteSize = static_cast<std::uint64_t>(integer);
        capture.unknownSizeIs162 = code == 162;
        capture.slot = DxfProxyPayloadSlot::Unknown;
        return true;
    case 70:
        if (!proxyDxfInteger(value, integer)) return false;
        capture.inProxyRecord = true;
        capture.hasFromDxf = true;
        capture.fromDxf = integer != 0;
        return true;
    case 71:
    case 97:
        capture.inProxyRecord = true;
        return true;
    case 310: {
        capture.inProxyRecord = true;
        auto* target = &capture.primary;
        if (capture.slot == DxfProxyPayloadSlot::Body)
            target = &capture.body;
        else if (capture.slot == DxfProxyPayloadSlot::Unknown)
            target = &capture.unknown;
        return appendProxyDxfBytes(value, *target,
                                   capture.retainedPayloadLease, budget);
    }
    case 311:
        capture.inProxyRecord = true;
        return appendProxyDxfBytes(value,
                                   entity || capture.unknownSizeIs162
                                       ? capture.unknown : capture.body,
                                   capture.retainedPayloadLease, budget);
    default:
        return true;
    }
}

void applyProxyDxfCommon(DRW_ProxyEntity& entity,
                         const DRW_Variant& value) {
    switch (value.code()) {
    case 5:
        if (value.type() == DRW_Variant::STRING) {
            std::uint64_t handle = 0;
            if (proxyDxfHandle(value, handle))
                entity.handle = static_cast<std::uint32_t>(handle);
        }
        break;
    case 8:
        if (value.type() == DRW_Variant::STRING)
            entity.layer = value.c_str();
        break;
    case 6:
        if (value.type() == DRW_Variant::STRING)
            entity.lineType = value.c_str();
        break;
    case 62:
        if (value.type() == DRW_Variant::INTEGER)
            entity.color = value.i_val();
        break;
    case 370:
        if (value.type() == DRW_Variant::INTEGER)
            entity.lWeight = DRW_LW_Conv::dxfInt2lineWidth(value.i_val());
        break;
    case 48:
        if (value.type() == DRW_Variant::DOUBLE)
            entity.ltypeScale = value.d_val();
        break;
    case 60:
        if (value.type() == DRW_Variant::INTEGER)
            entity.visible = (value.i_val() & 1) == 0;
        break;
    case 67:
        if (value.type() == DRW_Variant::INTEGER)
            entity.space = static_cast<DRW::Space>(value.i_val());
        break;
    case 347:
        if (value.type() == DRW_Variant::STRING) {
            std::uint64_t handle = 0;
            if (proxyDxfHandle(value, handle))
                entity.material = static_cast<std::uint32_t>(handle);
        }
        break;
    case 390:
        if (value.type() == DRW_Variant::STRING) {
            std::uint64_t handle = 0;
            if (proxyDxfHandle(value, handle))
                entity.plotStyle = static_cast<std::uint32_t>(handle);
        }
        break;
    case 420:
        if (value.type() == DRW_Variant::INTEGER)
            entity.color24 = value.i_val();
        break;
    case 430:
        if (value.type() == DRW_Variant::STRING)
            entity.colorName = value.c_str();
        break;
    case 440:
        if (value.type() == DRW_Variant::INTEGER)
            entity.transparency = value.i_val();
        break;
    default:
        break;
    }
}

bool applyProxyDxfCapture(DRW_ProxyEntity& entity,
                          DxfProxyCapture&& capture) {
    const std::size_t primarySize = capture.primary.size();
    entity.m_hasProxyClassId = capture.hasProxyClassId;
    entity.m_proxyClassId = capture.proxyClassId;
    entity.m_hasProxyCarrierId = capture.hasProxyCarrierId;
    entity.m_proxyCarrierId = capture.proxyCarrierId;
    entity.m_hasProxyDrawingFormat = capture.hasProxyDrawingFormat;
    entity.m_proxyDrawingFormat = capture.proxyDrawingFormat;
    entity.m_proxyDwgVersion = static_cast<std::uint16_t>(
        capture.proxyDrawingFormat & 0xFFFFu);
    entity.m_proxyMaintenanceVersion = static_cast<std::uint16_t>(
        capture.proxyDrawingFormat >> 16u);
    entity.m_hasFromDxf = capture.hasFromDxf;
    entity.m_fromDxf = capture.fromDxf;
    entity.m_hasProxyGraphicsByteSize = capture.hasPrimaryByteSize;
    entity.m_proxyGraphicsByteSize = capture.primaryByteSize;
    entity.m_hasEntityDataBitSize = capture.hasBodyBitSize;
    entity.m_entityDataBitSize = capture.bodyBitSize;
    entity.m_hasUnknownDataByteSize = capture.hasUnknownByteSize;
    entity.m_unknownDataByteSize = capture.unknownByteSize;
    entity.m_entityData = std::move(capture.body);
    entity.m_unknownData = std::move(capture.unknown);
    entity.proxyGraphics.clear();
    if (!capture.primary.empty()) {
        const auto& budget = capture.retainedPayloadLease != nullptr
            ? capture.retainedPayloadLease->budget()
            : std::shared_ptr<DxfReadRetainedBudget>{};
        DxfReadRetainedReservation proxyGraphicsCopy(
            budget, capture.primary.size());
        if (budget != nullptr && !proxyGraphicsCopy.reserved())
            return false;
        if (capture.primary.size()
                > static_cast<std::size_t>(std::numeric_limits<int>::max())
            || !DRW::reserve(entity.proxyGraphics,
                             static_cast<int>(capture.primary.size())))
            return false;
        try {
            entity.proxyGraphics.assign(
                reinterpret_cast<const char*>(capture.primary.data()),
                capture.primary.size());
        } catch (...) {
            return false;
        }
        // The capture vector's charge now accounts for this published string;
        // release the temporary source allocation before the separate-copy
        // reservation expires.
        std::vector<std::uint8_t>().swap(capture.primary);
    }
    entity.numProxyGraph = primarySize >
                                   static_cast<std::size_t>(std::numeric_limits<int>::max())
        ? std::numeric_limits<int>::max()
        : static_cast<int>(primarySize);
    entity.reactorHandles = std::move(capture.reactorHandles);
    entity.xDictHandle = capture.xDictHandle;
    entity.m_objectIdRefs = std::move(capture.objectIdRefs);
    return true;
}

void applyProxyDxfCapture(DRW_ProxyObject& object,
                          DxfProxyCapture&& capture) {
    object.m_hasProxyClassId = capture.hasProxyClassId;
    object.m_proxyClassId = capture.proxyClassId;
    object.m_hasProxyCarrierId = capture.hasProxyCarrierId;
    object.m_proxyCarrierId = capture.proxyCarrierId;
    object.m_hasProxyDrawingFormat = capture.hasProxyDrawingFormat;
    object.m_proxyDrawingFormat = capture.proxyDrawingFormat;
    object.m_proxyDwgVersion = static_cast<std::uint16_t>(
        capture.proxyDrawingFormat & 0xFFFFu);
    object.m_proxyMaintenanceVersion = static_cast<std::uint16_t>(
        capture.proxyDrawingFormat >> 16u);
    object.m_hasFromDxf = capture.hasFromDxf;
    object.m_fromDxf = capture.fromDxf;
    object.m_hasProxyGraphicsByteSize = capture.hasPrimaryByteSize;
    object.m_proxyGraphicsByteSize = capture.primaryByteSize;
    object.m_hasObjectDataBitSize = capture.hasBodyBitSize;
    object.m_objectDataBitSize = capture.bodyBitSize;
    object.m_hasUnknownDataByteSize = capture.hasUnknownByteSize;
    object.m_unknownDataByteSize = capture.unknownByteSize;
    object.m_binaryData = std::move(capture.primary);
    object.m_objectData = std::move(capture.body);
    object.m_unknownData = std::move(capture.unknown);
    object.reactorHandles = std::move(capture.reactorHandles);
    object.xDictHandle = capture.xDictHandle;
    object.m_objectIdRefs = std::move(capture.objectIdRefs);
}
}  // namespace

//Capture the current DXF record into a raw-passthrough carrier as a correctly
//TYPED DRW_Variant (see classifyDxfCode above for why getString()/reader->type
//cannot be trusted for numeric codes — that was the A1/A4 capture bug). The write
//side (writeRawDxfObject) re-emits binary values from their matching variant
//type and uses rawValues only for ASCII source spellings. Also latches code 5
//-> handle and code 330 -> parentHandle.
bool dxfRW::captureRawGroup(DRW_RawDxfObject &obj, int code,
                            bool validateHandles, bool selfHandle) {
    if (obj.groups.size() >= DRW::kMaxDxfRawRecordGroups)
        return false;
    if (obj.m_version == DRW::UNKNOWNV)
        obj.m_version = reader->getSourceVersion();
    obj.hasRawValues = !binFile;
    const auto& retainedBudget = reader->retainedByteBudget();
    if (retainedBudget != nullptr) {
        if (!obj.m_retainedTextLease) {
            obj.m_retainedTextLease =
                std::make_shared<DxfReadRetainedLease>(retainedBudget);
            // Object names were copied from nextentity before the first data
            // pair. Attach their already-bounded token length to the carrier
            // owner before adding any further retained string destinations.
            if (!obj.m_retainedTextLease->add(obj.name.size()))
                return false;
        } else if (obj.m_retainedTextLease->budget() != retainedBudget
                   && !obj.m_retainedTextLease->bind(
                       retainedBudget, obj.m_retainedTextLease->bytes())) {
            return false;
        }
    }
    if (validateHandles && isDxfHandleReferenceCode(code)) {
        const bool validHandle = reader->allowsWideHandleLexemes()
            ? reader->isValidHandleLexeme()
            : reader->isValidHandleString();
        if (!validHandle) {
            recordOperationDiagnostic(
                DRW::OperationPhase::Validation,
                DRW::OperationCause::ValidationFailure,
                "invalid-handle",
                code == DRW::dxfCode::HANDLE
                    ? "a DXF raw record contains an invalid self handle"
                    : "a DXF raw record contains an invalid handle reference");
            return false;
        }
    }
    if (code == DRW::dxfCode::HANDLE && selfHandle) {
        std::uint64_t rawHandle = 0;
        if (!parseRawDxfHandleLexeme(reader->getStringView(), rawHandle)) {
            recordOperationDiagnostic(
                DRW::OperationPhase::Validation,
                DRW::OperationCause::ValidationFailure,
                "invalid-handle",
                "a DXF raw record contains an invalid self handle");
            return false;
        }
        if (rawHandle != 0 && m_readRawHandles.count(rawHandle) != 0) {
            const bool hasDiagnosticHandle =
                rawHandle <= std::numeric_limits<std::uint32_t>::max();
            recordOperationDiagnostic(
                DRW::OperationPhase::Validation,
                DRW::OperationCause::ValidationFailure,
                "duplicate-handle",
                "a DXF raw record reuses a previously seen self handle", 0,
                false, hasDiagnosticHandle
                    ? static_cast<std::uint32_t>(rawHandle)
                    : 0,
                hasDiagnosticHandle);
            return false;
        }
        if (!reader->registerSelfHandle())
            return false;
        if (rawHandle != 0)
            m_readRawHandles.insert(rawHandle);
    }
    const std::string& rawValue = reader->getRawValue();
    const RawValType valueType =
        classifyDxfCode(code, reader->classifierProfile());
    std::size_t retainedCopyBytes =
        valueType == RawValType::Str ? rawValue.size() : 0u;
    if (!binFile) {
        const std::size_t maxSize =
            (std::numeric_limits<std::size_t>::max)();
        if (rawValue.size() > maxSize - retainedCopyBytes) {
            if (retainedBudget != nullptr)
                retainedBudget->reject();
            return false;
        }
        retainedCopyBytes += rawValue.size();
    }
    const std::size_t previousRetainedBytes =
        obj.m_retainedTextLease != nullptr
            ? obj.m_retainedTextLease->bytes() : 0u;
    if (obj.m_retainedTextLease != nullptr
        && !obj.m_retainedTextLease->add(retainedCopyBytes))
        return false;
    if (!reader->chargeTypedVariantNode()) {
        if (obj.m_retainedTextLease != nullptr)
            (void)obj.m_retainedTextLease->resizeTo(previousRetainedBytes);
        return false;
    }
    try {
        switch (valueType) {
        case RawValType::Int16:
        case RawValType::Int32:
        case RawValType::Bool:
            if (dxfKeywordEquals(obj.name, "MATERIAL")
                && (code == 90 || code == 91 || code == 92)) {
                obj.groups.emplace_back(
                    code, static_cast<std::uint64_t>(reader->getUInt32()));
            } else {
                obj.groups.emplace_back(code,
                                        static_cast<std::int32_t>(
                                            reader->getInt32()));
            }
            break;
        case RawValType::Int64:
            obj.groups.emplace_back(code,
                                    static_cast<std::int64_t>(
                                        reader->getInt64()));
            break;
        case RawValType::Dbl:
            obj.groups.emplace_back(code, reader->getDouble());
            break;
        case RawValType::Str:
        default:
            // Raw carrier strings are source bytes, including XDATA text.
            // Typed parseCode gets semantic UTF-8 separately; using getString
            // here would decode only selected group codes and corrupt binary
            // or cross-encoding raw replay without a matching encode step.
            obj.groups.emplace_back(code, reader->getRawValue());
            break;
        }
        obj.rawValues.emplace_back(binFile ? std::string{}
                                            : reader->getRawValue());
    } catch (...) {
        if (obj.m_retainedTextLease != nullptr)
            (void)obj.m_retainedTextLease->resizeTo(previousRetainedBytes);
        return false;
    }
    if (5 == code && obj.handle == 0) {
        // The raw group string remains authoritative when the handle does not
        // fit this legacy 32-bit convenience field.
        obj.handle = reader->getHandleString();
    } else if (330 == code) {
        // Latch the OWNER 330 only — the one OUTSIDE any 102 {ACAD_REACTORS/
        // ACAD_XDICTIONARY} control group. Reactor 330s live at 102-group depth
        // >= 1; the prior code latched the LAST 330 unconditionally, so an object
        // whose only 330s are reactors (no owner 330) took a reactor handle as
        // its owner. Compute the depth from the groups captured so far (the
        // current 330 is the last element) and latch only at depth 0.
        int depth = 0;
        for (std::size_t i = 0; i + 1 < obj.groups.size(); ++i) {
            if (obj.groups[i].code() == 102
                && obj.groups[i].type() == DRW_Variant::STRING) {
                const char *v = obj.groups[i].c_str();
                if (v && v[0] == '{' && v[1] != '\0') ++depth;
                else if (v && v[0] == '}') --depth;
            }
        }
        if (depth == 0 && obj.parentHandle == 0)
        obj.parentHandle = reader->getHandleString();
    }
    return true;
}

bool dxfRW::captureRawDxfApplicationGroup(DRW_RawDxfObject &obj,
                                          std::list<std::list<DRW_Variant>> &appData,
                                          std::vector<std::uint32_t> &reactorHandles,
                                          std::uint32_t &xDictHandle,
                                          std::shared_ptr<DxfReadRetainedLease> &typedLease) {
    DxfReadRetainedLeaseCheckpoint typedCheckpoint(typedLease);
    if (!captureRawGroup(obj, 102, /*validateHandles=*/true)
        || obj.groups.empty()
        || appData.size() >= DRW::kMaxDxfApplicationGroups) {
        return false;
    }

    const DRW_Variant &openingGroup = obj.groups.back();
    if (openingGroup.type() != DRW_Variant::STRING
        || openingGroup.content.s == nullptr) {
        return false;
    }
    const std::string& openingText = *openingGroup.content.s;
    if (openingText.size() <= 1 || openingText.front() != '{')
        return false;

    const bool isReactors = openingText == "{ACAD_REACTORS";
    const bool isXDictionary = openingText == "{ACAD_XDICTIONARY";
    std::list<DRW_Variant> applicationGroup;
    std::vector<std::uint32_t> reactors;
    std::uint32_t xDictionary = 0;
    int depth = 0;
    std::size_t pairCount = 1;

    try {
        const std::size_t openerBytes = openingText.size() - 1u;
        if (openerBytes > (std::numeric_limits<std::size_t>::max)() / 2u
            || !retainDxfReadBytes(typedLease,
                                   reader->retainedByteBudget(),
                                   openerBytes * 2u))
            return false;
        if (!reader->chargeTypedVariantNode())
            return false;
        DRW_Variant opener;
        std::string openerText = openingText.substr(1);
        opener.addString(102, std::move(openerText));
        applicationGroup.push_back(std::move(opener));
        if (typedLease != nullptr
            && !typedLease->resizeTo(typedLease->bytes() - openerBytes))
            return false;
        if (!updateRawDxfApplicationDepth(openingGroup, depth))
            return false;

        int code = 0;
        while (depth > 0 && reader->readRec(&code)) {
            if (code == 0 || pairCount >= DRW::kMaxDxfApplicationGroupPairs
                || !captureRawGroup(obj, code, /*validateHandles=*/true)
                || obj.groups.empty()) {
                return false;
            }
            ++pairCount;

            const DRW_Variant &group = obj.groups.back();
            const bool topLevelGroup = depth == 1;
            if (!updateRawDxfApplicationDepth(group, depth))
                return false;
            if (!reader->chargeTypedVariantNode())
                return false;
            if (group.type() == DRW_Variant::STRING
                && group.content.s != nullptr
                && !retainDxfReadBytes(typedLease,
                                       reader->retainedByteBudget(),
                                       group.content.s->size()))
                return false;
            applicationGroup.push_back(group);

            if (topLevelGroup && isReactors && code == 330) {
                const std::uint32_t handle = reader->getHandleString();
                if (handle != 0) {
                    if (reactors.size() >= dwgSafety::MaxReactorCount)
                        return false;
                    reactors.push_back(handle);
                }
            } else if (topLevelGroup && isXDictionary && code == 360
                       && xDictionary == 0) {
                xDictionary = reader->getHandleString();
            }
        }
    } catch (...) {
        return false;
    }

    if (depth != 0)
        return false;
    try {
        appData.push_back(std::move(applicationGroup));
        if (isReactors)
            reactorHandles = std::move(reactors);
        if (isXDictionary && xDictionary != 0)
            xDictHandle = xDictionary;
    } catch (...) {
        return false;
    }
    typedCheckpoint.commit();
    return true;
}

bool dxfRW::captureRawDxfApplicationGroup(DRW_RawDxfObject &obj,
                                          DRW_TableEntry &entry) {
    return captureRawDxfApplicationGroup(obj, entry.appData,
                                         entry.reactorHandles,
                                         entry.xDictHandle,
                                         entry.m_dxfRetainedStringLease);
}

bool dxfRW::captureRawDxfApplicationGroup(DRW_RawDxfObject &obj,
                                          DRW_Entity &entity) {
    return captureRawDxfApplicationGroup(obj, entity.appData,
                                         entity.reactorHandles,
                                         entity.xDictHandle,
                                         entity.m_dxfRetainedStringLease);
}

bool dxfRW::captureAndParseRawDxfGroup(DRW_RawDxfObject &obj, int code,
                                       DRW_TableEntry &entry) {
    if (code == 102)
        return captureRawDxfApplicationGroup(obj, entry);
    return captureRawGroup(obj, code, /*validateHandles=*/true)
        && entry.parseCode(code, reader);
}

bool dxfRW::captureAndParseRawDxfGroup(DRW_RawDxfObject &obj, int code,
                                       DRW_Entity &entity) {
    if (code == 102)
        return captureRawDxfApplicationGroup(obj, entity);
    return captureRawGroup(obj, code, /*validateHandles=*/true)
        && entity.parseCode(code, reader);
}

bool dxfRW::copyRawDxfCarrierName(DRW_RawDxfObject& obj,
                                  const std::string& name) {
    if (reader == nullptr || reader->retainedByteBudget() == nullptr) {
        obj.name = name;
        return true;
    }

    // The generic raw fallback can publish an empty record without ever
    // calling captureRawGroup(). Reserve the callback-owned name before making
    // its copy so the no-group path obeys the same retained-byte ceiling as
    // carriers whose first group initializes the lease.
    auto lease = std::make_shared<DxfReadRetainedLease>(
        reader->retainedByteBudget());
    if (!lease->add(name.size()))
        return false;
    obj.name = name;
    obj.m_retainedTextLease = std::move(lease);
    return true;
}

bool dxfRW::processRawObject(bool reportUnmodeled) {
    DRW_DBG("dxfRW::processRawObject");
    int code;
    DRW_RawDxfObject obj;
    if (!copyRawDxfCarrierName(obj, nextentity))
        return setError(DRW::BAD_CODE_PARSED);
    DxfRawHandleLexemeScope handleLexemes(*reader);
    int applicationDepth = 0;
    std::size_t pairCount = 0;
    while (reader->readRec(&code)) {
        DRW_DBG(code); DRW_DBG("\n");
        if (0 == code) {
            const DxfEntityBoundary boundary = setEntityBoundary(code);
            if (boundary == DxfEntityBoundary::Error
                || boundary == DxfEntityBoundary::EndBlock
                || applicationDepth != 0)
                return setError(DRW::BAD_READ_OBJECTS);
            if (requiresDxfSelfHandle(*reader) && !hasRawDxfSelfHandle(obj))
                return setError(DRW::BAD_READ_OBJECTS);
            if (reportUnmodeled) {
                auto* handler =
                    dynamic_cast<DRW_UnmodeledDxfObjectHandler*>(iface);
                if (handler != nullptr)
                    handler->addUnmodeledDxfObject(obj);
            }
            iface->addRawDxfObject(obj);
            return true;  //found new entity or ENDSEC, terminate
        }
        if (++pairCount > DRW::kMaxDxfApplicationGroupPairs)
            return setError(DRW::BAD_CODE_PARSED);
        if (!captureRawGroup(obj, code, /*validateHandles=*/true))
            return setError(DRW::BAD_CODE_PARSED);
        if (obj.groups.empty()
            || !updateRawDxfApplicationDepth(obj.groups.back(),
                                             applicationDepth))
            return setError(DRW::BAD_CODE_PARSED);
    }

    recordInvalidRawHandleDiagnostic();
    return setError(DRW::BAD_READ_OBJECTS);
}

//Slice A4: lossless passthrough for an unmodeled entity in the ENTITIES section
//or inside a BLOCK. Same verbatim capture as
//processRawObject but reports via addRawDxfEntity / the entities error code.
bool dxfRW::processRawEntity() {
    DRW_DBG("dxfRW::processRawEntity");
    int code;
    DRW_RawDxfObject ent;
    if (!copyRawDxfCarrierName(ent, nextentity))
        return setError(DRW::BAD_CODE_PARSED);
    DxfRawHandleLexemeScope handleLexemes(*reader);
    // Accumulate any cached proxy graphics (codes 92/160 + 310) via the common
    // entity parser so we can decode it into render primitives — same path as
    // the DWG reader.  proxyHost is a throwaway carrier; the raw object is still
    // delivered verbatim for round-trip.
    DRW_Point proxyHost;
    int applicationDepth = 0;
    std::size_t pairCount = 0;
    while (reader->readRec(&code)) {
        DRW_DBG(code); DRW_DBG("\n");
        if (0 == code) {
            const DxfEntityBoundary boundary = setEntityBoundary(code);
            if (boundary == DxfEntityBoundary::Error
                || !acceptEntityCallbackBoundary()
                || applicationDepth != 0)
                return setError(DRW::BAD_READ_ENTITIES);
            if (requiresDxfSelfHandle(*reader) && !hasRawDxfSelfHandle(ent))
                return setError(DRW::BAD_READ_ENTITIES);
            if (proxyHost.proxyGraphics.size() >= 16
                && canDecodeProxyGraphics(*reader))
                DRW_ProxyGraphicDecoder::decode(
                    proxyHost.proxyGraphics, reader->getSourceVersion(),
                    *iface, proxyHost);
            iface->addRawDxfEntity(ent);
            return true;  //found new entity, ENDSEC or ENDBLK, terminate
        }
        if (++pairCount > DRW::kMaxDxfApplicationGroupPairs)
            return setError(DRW::BAD_CODE_PARSED);
        // Keep raw capture authoritative. Parsing every group through a typed
        // entity parser is unsafe here: code 102 recursively consumes its
        // child records, so the raw stream would lose nested groups. Only
        // parse the common fields needed by the proxy decoder's draw state.
        switch (code) {
        case DRW::dxfCode::HANDLE:
            // Code 5 is identity metadata for the raw carrier. Do not route
            // it through the proxy host: DRW_Entity::parseCode registers the
            // handle and would reject a later raw entity before captureRawGroup
            // can provide the duplicate-handle diagnostic.
            break;
        case DRW::dxfCode::LAYER:
        case 6:
        case DRW::dxfCode::COLOR:
        case DRW::dxfCode::LINEWEIGHT:
        case 67:
        case 92:
        case 160:
        case 310:
            if (!proxyHost.parseCode(code, reader))
                return setError(DRW::BAD_CODE_PARSED);
            break;
        default:
            break;
        }
        if (!captureRawGroup(ent, code, /*validateHandles=*/true))
            return setError(DRW::BAD_CODE_PARSED);
        if (ent.groups.empty()
            || !updateRawDxfApplicationDepth(ent.groups.back(),
                                             applicationDepth))
            return setError(DRW::BAD_CODE_PARSED);
    }

    recordInvalidRawHandleDiagnostic();
    return setError(DRW::BAD_READ_ENTITIES);
}

// ACAD_PROXY_ENTITY carries typed metadata around two independent binary
// payloads.  Keep the complete raw group stream alongside the typed view so
// DXF->DXF replay never depends on a guessed proxy writer.
bool dxfRW::processProxyEntity() {
    DRW_DBG("dxfRW::processProxyEntity\n");
    int code;
    DRW_ProxyEntity entity;
    DRW_RawDxfObject raw;
    DxfProxyCapture capture;
    if (!copyRawDxfCarrierName(raw, nextentity))
        return setError(DRW::BAD_CODE_PARSED);
    // Proxy records are retained as raw carriers. Keep DWG-width code-5
    // lexemes lossless even when the typed convenience handle is uint32_t.
    DxfRawHandleLexemeScope handleLexemes(*reader);
    std::size_t pairCount = 0;

    while (reader->readRec(&code)) {
        if (code == 0) {
            const DxfEntityBoundary boundary = setEntityBoundary(code);
            if (boundary == DxfEntityBoundary::Error
                || !acceptEntityCallbackBoundary())
                return setError(DRW::BAD_READ_ENTITIES);
            if (capture.applicationDepth != 0)
                return setError(DRW::BAD_CODE_PARSED);
            if (!validateProxyDxfPayloads(capture))
                return setError(DRW::BAD_CODE_PARSED);
            if (requiresDxfSelfHandle(*reader) && !hasRawDxfSelfHandle(raw))
                return setError(DRW::BAD_READ_ENTITIES);

            entity.handle = raw.handle;
            entity.parentHandle = capture.hasOwner ? capture.ownerHandle
                                                   : static_cast<std::uint32_t>(DRW::NoHandle);
            raw.parentHandle = entity.parentHandle;
            if (!applyProxyDxfCapture(entity, std::move(capture)))
                return setError(DRW::BAD_READ_ENTITIES);
            entity.m_dxfRetainedStringLease = capture.retainedPayloadLease;
            if (entity.proxyGraphics.size() >= 16
                && canDecodeProxyGraphics(*reader))
                DRW_ProxyGraphicDecoder::decode(
                    entity.proxyGraphics, reader->getSourceVersion(),
                    *iface, entity);
            iface->addProxyEntity(entity);
            iface->addRawDxfEntity(raw);
            return true;
        }
        if (++pairCount > DRW::kMaxDxfApplicationGroupPairs)
            return setError(DRW::BAD_CODE_PARSED);

        if (!captureRawGroup(raw, code, /*validateHandles=*/true))
            return setError(DRW::BAD_CODE_PARSED);
        if (raw.groups.empty()
            || !collectProxyDxfGroup(
                capture, raw.groups.back(), true,
                reader->retainedByteBudget())) {
            return setError(DRW::BAD_CODE_PARSED);
        }
        applyProxyDxfCommon(entity, raw.groups.back());
    }
    return setError(DRW::BAD_READ_ENTITIES);
}

// ACAD_PROXY_OBJECT follows the same DXF proxy-data policy as the entity, but
// code 311 belongs to object data rather than the entity's unknown slot.
bool dxfRW::processProxyObject() {
    DRW_DBG("dxfRW::processProxyObject\n");
    int code;
    DRW_ProxyObject object;
    DRW_RawDxfObject raw;
    DxfProxyCapture capture;
    if (!copyRawDxfCarrierName(raw, nextentity))
        return setError(DRW::BAD_CODE_PARSED);
    // Proxy records are retained as raw carriers. Keep DWG-width code-5
    // lexemes lossless even when the typed convenience handle is uint32_t.
    DxfRawHandleLexemeScope handleLexemes(*reader);
    std::size_t pairCount = 0;

    while (reader->readRec(&code)) {
        if (code == 0) {
            const DxfEntityBoundary boundary = setEntityBoundary(code);
            if (boundary == DxfEntityBoundary::Error
                || boundary == DxfEntityBoundary::EndBlock)
                return setError(DRW::BAD_READ_OBJECTS);
            if (capture.applicationDepth != 0)
                return setError(DRW::BAD_CODE_PARSED);
            if (!validateProxyDxfPayloads(capture))
                return setError(DRW::BAD_CODE_PARSED);
            if (requiresDxfSelfHandle(*reader) && !hasRawDxfSelfHandle(raw))
                return setError(DRW::BAD_READ_OBJECTS);

            object.handle = raw.handle;
            object.parentHandle = capture.hasOwner ? capture.ownerHandle
                                                   : static_cast<std::uint32_t>(DRW::NoHandle);
            raw.parentHandle = object.parentHandle;
            applyProxyDxfCapture(object, std::move(capture));
            object.m_dxfRetainedStringLease = capture.retainedPayloadLease;
            iface->addProxyObject(object);
            iface->addRawDxfObject(raw);
            return true;
        }
        if (++pairCount > DRW::kMaxDxfApplicationGroupPairs)
            return setError(DRW::BAD_CODE_PARSED);

        if (!captureRawGroup(raw, code, /*validateHandles=*/true))
            return setError(DRW::BAD_CODE_PARSED);
        if (raw.groups.empty()
            || !collectProxyDxfGroup(
                capture, raw.groups.back(), false,
                reader->retainedByteBudget())) {
            return setError(DRW::BAD_CODE_PARSED);
        }
    }
    return setError(DRW::BAD_READ_OBJECTS);
}

bool dxfRW::writeRawDxfGroups(
    const std::vector<DRW_Variant>& groups,
    const std::vector<UTF8STRING>& rawValues,
    bool hasRawValues,
    DRW::Version sourceVersion,
    bool remapSourceHandles,
    bool useLegacyClassifier,
    bool sortEntsTableRecord,
    const std::vector<std::pair<std::size_t, std::string>>* stringOverrides,
    bool allowMaterialUnsignedColorValues,
    const std::vector<std::pair<std::size_t, std::int32_t>>*
        int32Overrides) {
    return writeRawDxfEntityGroups(
        groups, rawValues, hasRawValues, sourceVersion, remapSourceHandles,
        useLegacyClassifier, sortEntsTableRecord, -1, DRW::NoHandle, false,
        stringOverrides, allowMaterialUnsignedColorValues, int32Overrides);
}

bool dxfRW::writeRawDxfEntityGroups(
    const std::vector<DRW_Variant> &groups,
    const std::vector<UTF8STRING> &rawValues,
    bool hasRawValues,
    DRW::Version sourceVersion,
    bool remapSourceHandles,
    bool useLegacyClassifier,
    bool sortEntsTableRecord,
    int ownerOverrideGroupIndex,
    std::uint32_t emittedOwnerOverride,
    bool remapEntityXdataHandleReferences,
    const std::vector<std::pair<std::size_t, std::string>>* stringOverrides,
    bool allowMaterialUnsignedColorValues,
    const std::vector<std::pair<std::size_t, std::int32_t>>*
        int32Overrides) {
    if (!preflightDxfWrite()
        || (sourceVersion != DRW::UNKNOWNV && sourceVersion != version)) {
        m_writeError = true;
        return false;
    }
    const DxfClassifierProfile profile = useLegacyClassifier
        ? DxfClassifierProfile::LibreCadMasterLegacy
        : DxfClassifierProfile::StandaloneSafe;
    if (!validateRawDxfGroups(groups, rawValues, hasRawValues, binFile,
                              /*allowRecordBoundaries=*/true, profile,
                              allowMaterialUnsignedColorValues)) {
        m_writeError = true;
        return false;
    }
    if (!binFile && hasRawValues
        && !hasRawSortEntsAgreement(groups, rawValues, sortEntsTableRecord))
        return failDxfWrite();
    if (stringOverrides != nullptr) {
        std::size_t previousIndex = 0u;
        bool hasPreviousIndex = false;
        for (const auto& override : *stringOverrides) {
            std::uint64_t parsedHandle = 0u;
            if (override.first >= groups.size()
                || (hasPreviousIndex && override.first <= previousIndex)
                || groups[override.first].type() != DRW_Variant::STRING
                || (groups[override.first].code() == 320
                    ? !parseRawDxfHandleLexeme(override.second, parsedHandle)
                    : groups[override.first].code() != 3
                        && groups[override.first].code() != 300))
                return failDxfWrite();
            previousIndex = override.first;
            hasPreviousIndex = true;
        }
    }
    if (int32Overrides != nullptr) {
        std::size_t previousIndex = 0u;
        bool hasPreviousIndex = false;
        for (const auto& override : *int32Overrides) {
            if (override.first >= groups.size()
                || (hasPreviousIndex && override.first <= previousIndex)
                || groups[override.first].type() != DRW_Variant::INTEGER
                || classifyDxfCode(groups[override.first].code(), profile)
                    != RawValType::Int32)
                return failDxfWrite();
            previousIndex = override.first;
            hasPreviousIndex = true;
        }
    }
    const auto resolveSortReference = [this, remapSourceHandles](
        const RawSortEntsScope& scope, const DRW_Variant& group,
        std::uint64_t& resolved) {
        if (!scope.isBlockOwner() && !scope.isEntityReference())
            return true;
        std::uint64_t source = 0;
        if (!parseRawDxfHandleLexeme(group.c_str(), source))
            return false;
        resolved = source;
        if (!remapSourceHandles)
            return true; // Preserve the existing raw-section namespace policy.
        // With no active entity namespace, raw 331 values (including wide or
        // unresolved values) remain transport, not evidence of graph closure.
        if (scope.isEntityReference()
            && !m_writingContext.sourceHandleToMintedMap.empty()) {
            // Active entity identity planning is 32-bit. Raw wide keys remain
            // opaque; wide references are transport-only without this map.
            if (source > std::numeric_limits<std::uint32_t>::max())
                return false;
            std::uint32_t entity = 0;
            if (!resolveSortEntsEntityHandle(static_cast<std::uint32_t>(source), entity))
                return false;
            resolved = entity;
        } else if (scope.isBlockOwner()
                   && source <= std::numeric_limits<std::uint32_t>::max()) {
            const auto block = m_sourceBlockRecordHandles.find(
                static_cast<std::uint32_t>(source));
            resolved = block != m_sourceBlockRecordHandles.end()
                ? block->second : remapObjectHandle(static_cast<std::uint32_t>(source));
            if (resolved == 0)
                return false;
        }
        return true;
    };
    RawSortEntsScope preflightScope(sortEntsTableRecord);
    for (const DRW_Variant& group : groups) {
        std::uint64_t resolved = 0;
        if (!preflightScope.accept(group)
            || !resolveSortReference(preflightScope, group, resolved))
            return failDxfWrite();
    }
    if (!preflightScope.complete())
        return failDxfWrite();

    auto writeString = [this, sourceVersion, profile](int code,
                                                      std::string_view value) {
        const bool textKind = dxfValueKindForCode(code, profile) == DxfValueKind::Str
            || dxfValueKindForCode(code, profile) == DxfValueKind::Unknown;
        const bool knownUtf8 = sourceVersion >= DRW::AC1021 && version >= DRW::AC1021;
        if ((textKind && !isDxfHandleCode(code) && !writer->preflightOpaqueText(value, knownUtf8))
            || !writer->writeRawString(code, value)) {
            m_writeError = true;
            return false;
        }
        return true;
    };
    auto writeInt16 = [this](int code, int value) {
        if (!writer->writeInt16(code, value)) {
            m_writeError = true;
            return false;
        }
        return true;
    };
    auto writeInt32 = [this](int code, int value) {
        if (!writer->writeInt32(code, value)) {
            m_writeError = true;
            return false;
        }
        return true;
    };
    auto writeBool = [this](int code, bool value) {
        if (!writer->writeBool(code, value)) {
            m_writeError = true;
            return false;
        }
        return true;
    };
    auto writeInt64 = [this](int code, std::int64_t value) {
        if (!writer->writeInt64(code, value)) {
            m_writeError = true;
            return false;
        }
        return true;
    };
    auto writeDouble = [this](int code, double value) {
        if (!writer->writeDouble(code, value)) {
            m_writeError = true;
            return false;
        }
        return true;
    };

    RawSortEntsScope groupScope(sortEntsTableRecord);
    int entityApplicationDepth = 0;
    bool entityXdata = false;
    std::size_t stringOverrideIndex = 0u;
    std::size_t int32OverrideIndex = 0u;
    for (std::size_t groupIndex = 0; groupIndex < groups.size();
         ++groupIndex) {
        const DRW_Variant &v = groups[groupIndex];
        if (!groupScope.accept(v))
            return failDxfWrite();
        if (remapEntityXdataHandleReferences) {
            if (v.code() == 102) {
                entityXdata = false;
                if (!updateRawDxfApplicationDepth(v,
                                                  entityApplicationDepth))
                    return failDxfWrite();
            } else if (entityApplicationDepth == 0) {
                if (v.code() == 1001) {
                    entityXdata = true;
                } else if (entityXdata
                           && (v.code() < 1000 || v.code() > 1071)) {
                    entityXdata = false;
                }
            }
        }
        if (ownerOverrideGroupIndex >= 0
            && groupIndex
                == static_cast<std::size_t>(ownerOverrideGroupIndex)) {
            if (v.code() != 330 || emittedOwnerOverride == 0
                || emittedOwnerOverride == DRW::NoHandle
                || !writeString(
                    330, std::string_view(toHexStr(emittedOwnerOverride))))
                return failDxfWrite();
            continue;
        }
        if (stringOverrides != nullptr
            && stringOverrideIndex < stringOverrides->size()
            && groupIndex
                == (*stringOverrides)[stringOverrideIndex].first) {
            const std::string& replacement =
                (*stringOverrides)[stringOverrideIndex].second;
            const bool written = v.code() == 3 || v.code() == 300
                ? writer->writeUtf8String(
                    v.code(), std::string_view(replacement.data(),
                                               replacement.size()))
                : writeString(v.code(),
                    std::string_view(replacement.data(), replacement.size()));
            if (!written) {
                m_writeError = true;
                return failDxfWrite();
            }
            ++stringOverrideIndex;
            continue;
        }
        if (int32Overrides != nullptr
            && int32OverrideIndex < int32Overrides->size()
            && groupIndex
                == (*int32Overrides)[int32OverrideIndex].first) {
            if (!writeInt32(v.code(),
                    (*int32Overrides)[int32OverrideIndex].second))
                return failDxfWrite();
            ++int32OverrideIndex;
            continue;
        }
        if (remapEntityXdataHandleReferences && entityApplicationDepth == 0
            && entityXdata && v.code() == 1005) {
            std::uint64_t source = 0;
            if (v.type() != DRW_Variant::STRING || v.c_str() == nullptr
                || !parseRawDxfHandleLexeme(v.c_str(), source)
                || source > std::numeric_limits<std::uint32_t>::max())
                return failDxfWrite();
            std::uint32_t emitted = static_cast<std::uint32_t>(source);
            if (source != 0) {
                emitted = m_referenceResolver
                    ? resolveReference(static_cast<std::uint32_t>(source))
                    : remapObjectHandle(static_cast<std::uint32_t>(source));
                if (emitted == 0 || emitted == DRW::NoHandle
                    || writer->recordHandleCount(emitted) != 1u)
                    return failDxfWrite();
            }
            if (source == 0 || emitted == source) {
                const std::string_view value =
                    hasRawValues && groupIndex < rawValues.size()
                        ? std::string_view(rawValues[groupIndex].data(),
                                           rawValues[groupIndex].size())
                        : std::string_view(v.c_str());
                if (!writeString(1005, value))
                    return failDxfWrite();
            } else {
                const std::string replacement = toHexStr(emitted);
                if (!writeString(1005, replacement))
                    return failDxfWrite();
            }
            continue;
        }
        if (groupScope.isBlockOwner() || groupScope.isEntityReference()) {
            std::uint64_t source = 0;
            std::uint64_t resolved = 0;
            if (!parseRawDxfHandleLexeme(v.c_str(), source)
                || !resolveSortReference(groupScope, v, resolved))
                return failDxfWrite();
            if (resolved != source) {
                if (!writeString(
                        v.code(), std::string_view(
                            DxfNumeric::formatHex(resolved))))
                    return false;
                continue;
            }
        }
        // Apply the structural-collision handle remap to handle-reference codes.
        // The value is a hex handle string; if it names a remapped handle, emit
        // the replacement so this object (and every reference to a remapped
        // object) stays internally consistent.
        const bool opaqueSortReference =
            (v.code() == 330 || v.code() == 331)
            && groupScope.isOpaqueHandleReference()
            && !groupScope.isBlockOwner()
            && !groupScope.isEntityReference();
        if (v.type() == DRW_Variant::STRING
            && isDxfTranslatedHandleCode(v.code()) && !groupScope.isSortKey()
            && !opaqueSortReference) {
            const std::string_view s(v.c_str());
            std::uint32_t parsed = 0;
            const char* begin = s.data();
            const char* end = begin + s.size();
            const std::from_chars_result result =
                std::from_chars(begin, end, parsed, 16);
            if (result.ec == std::errc{} && result.ptr == end) {
                std::uint32_t remapped = parsed;
                bool hasStructuralRemap = false;
                const auto structural = m_handleRemap.find(parsed);
                if (structural != m_handleRemap.end()) {
                    remapped = structural->second;
                    hasStructuralRemap = true;
                } else {
                    const auto sourceBlockRecord =
                        m_sourceBlockRecordHandles.find(parsed);
                    if (sourceBlockRecord != m_sourceBlockRecordHandles.end()) {
                        remapped = sourceBlockRecord->second;
                        hasStructuralRemap = true;
                    }
                }
                if (!hasStructuralRemap) {
                    const auto blockRecord =
                        m_dxfWriteHandleRemap.find(parsed);
                    if (blockRecord != m_dxfWriteHandleRemap.end()) {
                        remapped = blockRecord->second;
                        hasStructuralRemap = true;
                    }
                }
                if (!hasStructuralRemap && remapSourceHandles) {
                    // Use the same final namespace as typed references,
                    // including planned GROUPs and already-emitted objects.
                    // Raw sections with remapSourceHandles=false keep their
                    // existing structural-only transport policy.
                    remapped = remapObjectHandle(parsed);
                }
                if (remapped != parsed) {
                    if (!writeString(
                            v.code(),
                            std::string_view(toHexStr(remapped))))
                        return false;
                    continue;
                }
            }
        }
        bool written = false;
        if (!binFile && hasRawValues && groupIndex < rawValues.size()) {
            const std::string& rawValue = rawValues[groupIndex];
            written = writeString(
                v.code(), std::string_view(rawValue.data(), rawValue.size()));
        }
        if (written)
            continue;
        switch (v.type()) {
        case DRW_Variant::STRING:
            written = writeString(v.code(), std::string_view(v.c_str()));
            break;
        case DRW_Variant::INTEGER: {
            switch (classifyDxfCode(v.code(), profile)) {
            case RawValType::Int16:
                written = writeInt16(v.code(), v.i_val());
                break;
            case RawValType::Int32:
                written = writeInt32(v.code(), v.i_val());
                break;
            case RawValType::Bool:
                written = writeBool(v.code(), v.i_val() != 0);
                break;
            default:
                m_writeError = true;
                break;
            }
            break;
        }
        case DRW_Variant::INTEGER64:
            if (allowMaterialUnsignedColorValues
                && (v.code() == 90 || v.code() == 91 || v.code() == 92)
                && v.i64_val() >= 0
                && static_cast<std::uint64_t>(v.i64_val())
                    <= std::numeric_limits<std::uint32_t>::max()) {
                const std::uint32_t color =
                    static_cast<std::uint32_t>(v.i64_val());
                if (binFile) {
                    written = writeInt32(
                        v.code(), dxfSignedInt32BitPattern(color));
                } else {
                    const std::string decimal = std::to_string(color);
                    written = writeString(
                        v.code(), std::string_view(decimal.data(),
                                                   decimal.size()));
                }
            } else if (classifyDxfCode(v.code(), profile)
                       == RawValType::Int64) {
                written = writeInt64(v.code(), v.i64_val());
            } else {
                m_writeError = true;
            }
            break;
        case DRW_Variant::DOUBLE:
            if (classifyDxfCode(v.code(), profile) == RawValType::Dbl)
                written = writeDouble(v.code(), v.d_val());
            else
                m_writeError = true;
            break;
        default:
            m_writeError = true;
            break;
        }
        if (!written)
            return false;
    }
    return (stringOverrides == nullptr
            || stringOverrideIndex == stringOverrides->size())
        && (int32Overrides == nullptr
            || int32OverrideIndex == int32Overrides->size());
}

// Slice A2: re-emit a raw-captured object (from processRawObject) verbatim.
// The capture stores decoded typed values and, for ASCII input, parallel source
// spellings; the shared group writer also serves unknown DXF sections.
bool dxfRW::writeRawDxfObject(DRW_RawDxfObject *obj) {
    return writeRawDxfObjectInternal(obj, DRW::NoHandle, nullptr);
}

bool dxfRW::writeRawDxfObject(DRW_RawDxfObject *obj,
                              std::uint32_t ownerOverride) {
    return writeRawDxfObjectInternal(obj, ownerOverride, nullptr);
}

bool dxfRW::writeRawDxfObjectWithStringOverrides(
        DRW_RawDxfObject *obj,
        const std::vector<std::pair<std::size_t, std::string>>& overrides) {
    return writeRawDxfObjectInternal(obj, DRW::NoHandle, &overrides);
}

bool dxfRW::writeRawDxfObjectWithStringAndInt32Overrides(
        DRW_RawDxfObject *obj,
        const std::vector<std::pair<std::size_t, std::string>>& stringOverrides,
        const std::vector<std::pair<std::size_t, std::int32_t>>& int32Overrides) {
    return writeRawDxfObjectInternal(obj, DRW::NoHandle, &stringOverrides,
                                     &int32Overrides);
}

bool dxfRW::writeRawDxfObjectInternal(
        DRW_RawDxfObject *obj, std::uint32_t ownerOverride,
        const std::vector<std::pair<std::size_t, std::string>>*
            stringOverrides,
        const std::vector<std::pair<std::size_t, std::int32_t>>*
            int32Overrides) {
    if (!preflightDxfWrite() || obj == nullptr
        || (obj->m_version != DRW::UNKNOWNV && obj->m_version != version)) {
        m_writeError = true;
        return false;
    }
    const DxfClassifierProfile profile = m_useTargetLegacyClassifier
        ? DxfClassifierProfile::LibreCadMasterLegacy
        : DxfClassifierProfile::StandaloneSafe;
    const bool allowMaterialUnsignedColorValues =
        dxfKeywordEquals(obj->name, "MATERIAL");
    if (obj->name.empty()
        || !validateRawDxfGroups(obj->groups, obj->rawValues,
                                 obj->hasRawValues, binFile,
                                 /*allowRecordBoundaries=*/false, profile,
                                 allowMaterialUnsignedColorValues)
        || (requiresDxfSelfHandle(version) && !hasRawDxfSelfHandle(*obj))) {
        m_writeError = true;
        return false;
    }
    std::size_t ownerGroupIndex = obj->groups.size();
    std::size_t ownerGroupCount = 0;
    std::uint64_t sourceOwner = 0;
    const bool isSunCarrier = dxfKeywordEquals(obj->name, "SUN")
        || dxfKeywordEquals(obj->name, "ACDBSUN");
    if (isSunCarrier && ownerOverride == DRW::NoHandle) {
        m_writeError = true;
        return false;
    }
    if (ownerOverride != DRW::NoHandle) {
        const bool sunWasResolved = std::find(
            m_resolvedSunHandles.begin(), m_resolvedSunHandles.end(),
            obj->handle) != m_resolvedSunHandles.end();
        const bool ownerWasEmitted =
            m_writingContext.sourceHandleToWrittenTableMap.count(
                ownerOverride) != 0
            || m_writingContext.sourceHandleToMintedMap.count(
                ownerOverride) != 0;
        if (!isSunCarrier || !sunWasResolved || !ownerWasEmitted) {
            m_writeError = true;
            return false;
        }
        for (std::size_t index = 0; index < obj->groups.size(); ++index) {
            const DRW_Variant& group = obj->groups[index];
            if (group.code() != 330)
                continue;
            ++ownerGroupCount;
            ownerGroupIndex = index;
            if (group.type() != DRW_Variant::STRING
                || group.c_str() == nullptr
                || !parseRawDxfHandleLexeme(group.c_str(), sourceOwner)) {
                m_writeError = true;
                return false;
            }
        }
        if (ownerOverride == 0 || ownerOverride == DRW::NoHandle
            || ownerOverride != obj->parentHandle || ownerGroupCount != 1u
            || sourceOwner != ownerOverride) {
            m_writeError = true;
            return false;
        }
    }
    auto writeString = [this](int code, const std::string &value) {
        if (!writer->writeString(code, value)) {
            m_writeError = true;
            return false;
        }
        return true;
    };
    DxfWriterRecordScope record(*writer);
    if (!writer->preflightOpaqueText(obj->name,
            obj->m_version >= DRW::AC1021 && version >= DRW::AC1021)
        || !writeString(0, obj->name))
        return false;
    const std::uint32_t emittedOwner = ownerOverride == DRW::NoHandle
        ? DRW::NoHandle : remapObjectHandle(ownerOverride);
    if (ownerOverride != DRW::NoHandle
        && (emittedOwner == 0 || emittedOwner == DRW::NoHandle)) {
        m_writeError = true;
        return false;
    }
    const bool wroteGroups = ownerOverride == DRW::NoHandle
        ? writeRawDxfGroups(
              obj->groups, obj->rawValues, obj->hasRawValues,
              obj->m_version, /*remapSourceHandles=*/true,
              m_useTargetLegacyClassifier,
              dxfKeywordEquals(obj->name, "SORTENTSTABLE"), stringOverrides,
              allowMaterialUnsignedColorValues, int32Overrides)
        : writeRawDxfEntityGroups(
              obj->groups, obj->rawValues, obj->hasRawValues,
              obj->m_version, /*remapSourceHandles=*/true,
              m_useTargetLegacyClassifier,
              dxfKeywordEquals(obj->name, "SORTENTSTABLE"),
              static_cast<int>(ownerGroupIndex), emittedOwner,
              /*remapEntityXdataHandleReferences=*/false,
              stringOverrides,
              /*allowMaterialUnsignedColorValues=*/false, int32Overrides);
    if (!wroteGroups)
        return false;
    if (!preflightDxfWrite() || !record.commit()) {
        m_writeError = true;
        return false;
    }
    return true;
}

bool dxfRW::writeRawDxfEntity(DRW_RawDxfObject *entity,
                              std::uint32_t ownerOverride) {
    const auto rejectRawEntity = [this](const char* detail) {
        recordOperationDiagnostic(
            DRW::OperationPhase::Validation,
            DRW::OperationCause::ValidationFailure,
            "raw-entity-replay-profile", detail);
        return failDxfWrite();
    };
    if (!preflightDxfWrite() || entity == nullptr
        || (entity->m_version != DRW::UNKNOWNV
            && entity->m_version != version))
        return rejectRawEntity(
            "raw entity is null or its source DXF version differs from target");
    const DxfClassifierProfile profile = m_useTargetLegacyClassifier
        ? DxfClassifierProfile::LibreCadMasterLegacy
        : DxfClassifierProfile::StandaloneSafe;
    if (entity->name.empty() || entity->handle == 0
        || !validateRawDxfGroups(entity->groups, entity->rawValues,
                                 entity->hasRawValues, binFile,
                                 /*allowRecordBoundaries=*/false, profile)
        || !hasRawDxfSelfHandle(*entity))
        return rejectRawEntity(
            "raw entity has invalid identity, name, or group encoding");

    std::size_t ownerGroupIndex = entity->groups.size();
    std::size_t selfHandleIndex = entity->groups.size();
    std::size_t ownerGroupCount = 0;
    std::size_t selfHandleCount = 0;
    std::uint64_t sourceOwner = 0;
    std::uint64_t sourceSelf = 0;
    int applicationDepth = 0;
    bool inXdata = false;
    for (std::size_t index = 0; index < entity->groups.size(); ++index) {
        const DRW_Variant& group = entity->groups[index];
        if (group.code() == 102) {
            inXdata = false;
            const char* marker = group.type() == DRW_Variant::STRING
                ? group.c_str() : nullptr;
            if (marker == nullptr)
                return rejectRawEntity(
                    "raw entity application-group marker is not text");
            if (marker[0] == '}' && applicationDepth > 0)
                --applicationDepth;
            else if (marker[0] == '{' && marker[1] != '\0')
                ++applicationDepth;
            else
                return rejectRawEntity(
                    "raw entity application-group delimiters are unbalanced");
            continue;
        }
        // Unknown 102 application groups may assign meanings to handle-like
        // codes that differ from the standard DXF pointer roles. Do not
        // rewrite such data without a parsed application-specific contract.
        if (applicationDepth != 0
            && isDxfTranslatedHandleCode(group.code()))
            return rejectRawEntity(
                "raw entity has an unqualified handle inside application data");
        if (applicationDepth != 0)
            continue;
        if (group.code() == 1001) {
            inXdata = true;
            continue;
        }
        if (inXdata && group.code() >= 1000 && group.code() <= 1071) {
            if (group.code() == 1005) {
                std::uint64_t source = 0;
                if (group.type() != DRW_Variant::STRING
                    || group.c_str() == nullptr
                    || !parseRawDxfHandleLexeme(group.c_str(), source)
                    || source > std::numeric_limits<std::uint32_t>::max())
                    return rejectRawEntity(
                        "raw entity XDATA has an invalid 1005 handle");
                if (source != 0) {
                    const std::uint32_t sourceHandle =
                        static_cast<std::uint32_t>(source);
                    if (m_writingContext.ambiguousSourceHandles.count(
                            sourceHandle) != 0)
                        return rejectRawEntity(
                            "raw entity XDATA 1005 target is ambiguous");
                    const std::uint32_t emitted = m_referenceResolver
                        ? resolveReference(sourceHandle)
                        : remapObjectHandle(sourceHandle);
                    if (emitted == 0 || emitted == DRW::NoHandle
                        || writer->recordHandleCount(emitted) != 1u)
                        return rejectRawEntity(
                            "raw entity XDATA 1005 target is not uniquely emitted yet");
                }
            }
            continue;
        }
        inXdata = false;
        if (group.code() == 5) {
            ++selfHandleCount;
            selfHandleIndex = index;
            if (group.type() != DRW_Variant::STRING || group.c_str() == nullptr
                || !parseRawDxfHandleLexeme(group.c_str(), sourceSelf))
                return rejectRawEntity(
                    "raw entity has an invalid self-handle group");
        } else if (group.code() == 330) {
            ++ownerGroupCount;
            ownerGroupIndex = index;
            if (group.type() != DRW_Variant::STRING || group.c_str() == nullptr
                || !parseRawDxfHandleLexeme(group.c_str(), sourceOwner))
                return rejectRawEntity(
                    "raw entity has an invalid owner-handle group");
        }
    }
    if (selfHandleCount != 1u || selfHandleIndex == entity->groups.size()
        || sourceSelf != entity->handle || sourceOwner != entity->parentHandle
        || ownerGroupCount > 1u)
        return rejectRawEntity(
            "raw entity self/owner identity is ambiguous or inconsistent");
    const bool requiresEntityOwner = version > DRW::AC1014;
    const bool hasOwnerOverride = ownerOverride != DRW::NoHandle;
    if ((requiresEntityOwner
         && (ownerGroupCount != 1u || !hasOwnerOverride))
        || (hasOwnerOverride && ownerGroupCount != 1u)) {
        return rejectRawEntity(
            (std::string("raw entity owner is missing or cannot be resolved: groups=")
             + std::to_string(ownerGroupCount) + " source="
             + std::to_string(entity->parentHandle) + " output="
             + std::to_string(ownerOverride)).c_str());
    }
    // This narrow raw-entity writer only replays identities and the logical
    // owner. Other pointer-like references need a closed source-to-emitted
    // graph, which the adapter has not qualified for arbitrary custom records.
    int referenceApplicationDepth = 0;
    bool referenceInXdata = false;
    for (std::size_t index = 0; index < entity->groups.size(); ++index) {
        const DRW_Variant& group = entity->groups[index];
        if (group.code() == 102) {
            referenceInXdata = false;
            if (!updateRawDxfApplicationDepth(
                    group, referenceApplicationDepth))
                return rejectRawEntity(
                    "raw entity application-group delimiters are invalid");
            continue;
        }
        if (referenceApplicationDepth != 0) {
            if (isDxfTranslatedHandleCode(group.code()))
                return rejectRawEntity(
                    "raw entity has an unqualified handle inside application data");
            continue;
        }
        if (group.code() == 1001)
            referenceInXdata = true;
        else if (referenceInXdata
                 && (group.code() < 1000 || group.code() > 1071))
            referenceInXdata = false;
        if (index != selfHandleIndex && index != ownerGroupIndex
            && isDxfTranslatedHandleCode(group.code())
            && !(referenceInXdata && group.code() == 1005))
            return rejectRawEntity(
                "raw entity contains a handle reference without qualified graph closure");
    }

    const std::uint32_t sourceHandle = entity->handle;
    if (m_writingContext.ambiguousSourceHandles.count(sourceHandle) != 0
        || m_writingContext.writtenSourceEntityHandles.count(sourceHandle) != 0)
        return rejectRawEntity(
            "raw entity source handle is ambiguous or already emitted");
    std::uint32_t emittedHandle = remapObjectHandle(sourceHandle);
    const auto existing = m_writingContext.sourceHandleToMintedMap.find(
        sourceHandle);
    if (existing != m_writingContext.sourceHandleToMintedMap.end())
        emittedHandle = existing->second;
    if (emittedHandle == 0 || emittedHandle == DRW::NoHandle)
        return rejectRawEntity("raw entity output handle is invalid");
    if (isDxfFixedOutputHandle(emittedHandle))
        return rejectRawEntity(
            "raw entity output handle collides with a fixed DXF record");

    RecordStateScope state(*this);
    DxfWriterRecordScope record(*writer);
    if (!bindSourceEntityHandle(sourceHandle, emittedHandle))
        return rejectRawEntity(
            "raw entity source/output identity binding is ambiguous");
    const std::size_t mutationCheckpoint = m_dxfWriteMutations.size();
    if (m_recordStateScopeDepth != 0) {
        m_dxfWriteMutations.push_back({
            DxfWriteMutationKind::WrittenSourceEntityHandleInsert,
            {}, sourceHandle, 0, false});
    }
    try {
        const auto inserted =
            m_writingContext.writtenSourceEntityHandles.insert(sourceHandle);
        if (!inserted.second) {
            m_dxfWriteMutations.resize(mutationCheckpoint);
            return rejectRawEntity(
                "raw entity source identity was already recorded as written");
        }
    } catch (...) {
        m_dxfWriteMutations.resize(mutationCheckpoint);
        throw;
    }
    if (!writer->preflightOpaqueText(entity->name,
            entity->m_version >= DRW::AC1021 && version >= DRW::AC1021)
        || !writer->writeString(0, entity->name)
        || !writeRawDxfEntityGroups(
            entity->groups, entity->rawValues, entity->hasRawValues,
            entity->m_version, /*remapSourceHandles=*/true,
            m_useTargetLegacyClassifier, /*sortEntsTableRecord=*/false,
            hasOwnerOverride ? static_cast<int>(ownerGroupIndex) : -1,
            ownerOverride, /*remapEntityXdataHandleReferences=*/true,
            /*stringOverrides=*/nullptr,
            /*allowMaterialUnsignedColorValues=*/false)
        || !preflightDxfWrite() || !record.commit())
        return rejectRawEntity(
            "raw entity groups could not be committed to the DXF stream");
    state.commit();
    return true;
}

bool dxfRW::collectAcdsAsmDataOwnerHandleOverrides(
    const DRW_RawDxfSection& section,
    std::vector<std::pair<std::size_t, std::string>>& overrides) {
    overrides.clear();
    if (!dxfKeywordEquals(section.m_name, "ACDSDATA"))
        return true;

    const std::vector<DRW_Variant>& groups = section.m_groups;
    for (std::size_t recordStart = 0; recordStart < groups.size();) {
        if (groups[recordStart].code() != 0
            || groups[recordStart].type() != DRW_Variant::STRING
            || groups[recordStart].c_str() == nullptr) {
            ++recordStart;
            continue;
        }

        std::size_t recordEnd = recordStart + 1;
        while (recordEnd < groups.size()
               && groups[recordEnd].code() != 0)
            ++recordEnd;

        if (!dxfKeywordEquals(groups[recordStart].c_str(), "ACDSRECORD")) {
            recordStart = recordEnd;
            continue;
        }

        std::size_t idSectionCount = 0;
        std::size_t asmDataCount = 0;
        std::size_t ownerHandleCount = 0;
        std::size_t ownerHandleIndex = groups.size();
        std::uint64_t sourceHandle = 0;
        bool ownerHandleIsString = false;
        bool inIdSection = false;

        for (std::size_t groupIndex = recordStart + 1;
             groupIndex < recordEnd; ++groupIndex) {
            const DRW_Variant& group = groups[groupIndex];
            if (group.code() == 2) {
                if (group.type() != DRW_Variant::STRING
                    || group.c_str() == nullptr) {
                    inIdSection = false;
                    continue;
                }
                inIdSection = dxfKeywordEquals(group.c_str(), "AcDbDs::ID");
                if (inIdSection)
                    ++idSectionCount;
                if (dxfKeywordEquals(group.c_str(), "ASM_Data"))
                    ++asmDataCount;
            } else if (inIdSection && group.code() == 320) {
                ++ownerHandleCount;
                ownerHandleIndex = groupIndex;
                if (group.type() == DRW_Variant::STRING
                    && group.c_str() != nullptr) {
                    ownerHandleIsString = parseRawDxfHandleLexeme(
                        group.c_str(), sourceHandle);
                } else {
                    ownerHandleIsString = false;
                }
            }
        }

        if (asmDataCount != 0) {
            if (asmDataCount != 1 || idSectionCount != 1
                || ownerHandleCount != 1 || !ownerHandleIsString
                || sourceHandle == 0
                || sourceHandle > std::numeric_limits<std::uint32_t>::max()) {
                return failDxfWrite();
            }
            const std::uint32_t source =
                static_cast<std::uint32_t>(sourceHandle);
            if (m_writingContext.ambiguousSourceHandles.count(source) != 0)
                return failDxfWrite();
            const auto emitted =
                m_writingContext.modelerSourceHandleToMintedMap.find(source);
            if (emitted
                == m_writingContext.modelerSourceHandleToMintedMap.end())
                return failDxfWrite();
            if (section.m_hasRawValues
                && ownerHandleIndex >= section.m_rawValues.size())
                return failDxfWrite();
            overrides.emplace_back(ownerHandleIndex,
                                   toHexStr(emitted->second));
        }
        recordStart = recordEnd;
    }
    return true;
}

bool dxfRW::writeRawDxfSection(const DRW_RawDxfSection &section) {
    if (!preflightDxfWrite() || section.m_name.empty()
        || dxfKeywordEquals(section.m_name, "HEADER")
        || dxfKeywordEquals(section.m_name, "CLASSES")
        || dxfKeywordEquals(section.m_name, "TABLES")
        || dxfKeywordEquals(section.m_name, "BLOCKS")
        || dxfKeywordEquals(section.m_name, "ENTITIES")
        || dxfKeywordEquals(section.m_name, "OBJECTS")
        || (section.m_version != DRW::UNKNOWNV
            && section.m_version != version)) {
        m_writeError = true;
        return false;
    }
    const DxfClassifierProfile profile = m_useTargetLegacyClassifier
        ? DxfClassifierProfile::LibreCadMasterLegacy
        : DxfClassifierProfile::StandaloneSafe;
    // ACDSDATA owner remapping is represented as a tiny output overlay. Keep
    // the caller's potentially large typed/raw vectors const and avoid cloning
    // the complete section merely to replace one or more group-320 spellings.
    std::vector<std::pair<std::size_t, std::string>> stringOverrides;
    if (!validateRawDxfGroups(section.m_groups, section.m_rawValues,
                              section.m_hasRawValues, binFile,
                              /*allowRecordBoundaries=*/true, profile)) {
        m_writeError = true;
        return false;
    }
    if (!collectAcdsAsmDataOwnerHandleOverrides(section, stringOverrides))
        return false;
    DxfWriterRecordScope record(*writer);
    if (!writer->preflightOpaqueText(section.m_name,
            section.m_version >= DRW::AC1021 && version >= DRW::AC1021)
        || !writer->writeString(0, "SECTION")
        || !writer->writeString(2, section.m_name)
        || !writeRawDxfGroups(section.m_groups, section.m_rawValues,
                              section.m_hasRawValues,
                              section.m_version,
                              /*remapSourceHandles=*/false,
                              m_useTargetLegacyClassifier,
                              /*sortEntsTableRecord=*/false,
                              &stringOverrides)
        || !writer->writeString(0, "ENDSEC")) {
        m_writeError = true;
        return false;
    }
    if (!preflightDxfWrite() || !record.commit()) {
        m_writeError = true;
        return false;
    }
    return true;
}

//Slice A3: canonical DXF CLASS metadata for the custom-class OBJECTS the raw net
//round-trips — both the routed data-only types (SUN/SCALE/...) and common
//unmodeled OBJECTS captured verbatim (MATERIAL/VISUALSTYLE/...). Values are the
//DXF-authoritative ezdxf CLASS_DEFINITIONS tuple {className(2), appName(3),
//flags(90), wasaProxy(280), isEntity(281)}. Every entry is a NON-fixed object
//class (ezdxf lists only classes that need a CLASS), so registering one can never
//mislabel a fixed built-in (DICTIONARY/GROUP/LAYOUT/MLINESTYLE are absent here);
//emission is instance-driven, so an entry that is never present never fires.
//instanceCount (91) is left 0 for the caller to fill. entityFlag 0 = object.
//Arbitrary/proprietary objects not in this table still round-trip losslessly
//LibreCAD<->LibreCAD but get no CLASS (a heuristic proxy is a deliberate TODO,
//since distinguishing a custom class from an unmodeled fixed type is unsafe).
const char* dxfRW::dxfMeshRecordNameForVersion(
        DRW::Version targetVersion) noexcept {
    switch (targetVersion) {
    case DRW::AC1014:
    case DRW::AC1015:
    case DRW::AC1018:
    case DRW::AC1021:
    case DRW::AC1027:
    case DRW::AC1032:
        return "MESH";
    case DRW::AC1024:
        return "SUBDIVISION";
    default:
        return nullptr;
    }
}

