    for (const Entry &e : table) {
        if (recName == e.rec) {
            out.recName = e.rec;
            out.className = e.cls;
            out.appName = e.app;
            out.proxyFlag = e.flag;
            out.wasaProxyFlag = 0;
            out.entityFlag = e.isEntity;
            out.instanceCount = 0;
            return true;
        }
    }
    return false;
